	private readonly struct MeasureKey(string text, Font font, int width, StringFormat fmt) : IEquatable<MeasureKey>
	{
		public readonly string Text = text;

		public readonly Font Font = font;

		public readonly int Width = width;

		public readonly StringFormatFlags Flags = fmt.FormatFlags;

		public bool Equals(MeasureKey other)
		{
			if (Text == other.Text && Font.Equals(other.Font) && Width == other.Width)
			{
				return Flags == other.Flags;
			}
			return false;
		}

		public override bool Equals(object obj)
		{
			if (obj is MeasureKey other)
			{
				return Equals(other);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return (((17 * 31 + (Text?.GetHashCode() ?? 0)) * 31 + Font.GetHashCode()) * 31 + Width) * 31 + ((int)Flags).GetHashCode();
		}
	}

