	public int TxAttenData
	{
		get
		{
			return _tx_attenuator_data;
		}
		set
		{
			if (_updatingTxAtt)
			{
				return;
			}
			_updatingTxAtt = true;
			_tx_attenuator_data = validateTXStepAttData(value);
			if (!initializing)
			{
				setTXstepAttenuatorForBand(_tx_band, _tx_attenuator_data);
				if (m_bATTonTX)
				{
					NetworkIO.SetTxAttenData(_tx_attenuator_data);
					Display.TXAttenuatorOffset = _tx_attenuator_data;
				}
				else
				{
					NetworkIO.SetTxAttenData(0);
					Display.TXAttenuatorOffset = 0f;
				}
				udTXStepAttData.Value = _tx_attenuator_data;
				if (_mox && m_bATTonTX && HardwareSpecific.Model == HPSDRModel.REDPITAYA)
				{
					udRX1StepAttData.Value = _tx_attenuator_data;
				}
			}
			_updatingTxAtt = false;
		}
	}

