			bool flag = ((!VFOBTX || !RX2Enabled) ? (RX1DSPMode == DSPMode.CWL || RX1DSPMode == DSPMode.CWU) : (RX2DSPMode == DSPMode.CWL || RX2DSPMode == DSPMode.CWU));
			NetworkIO.SetSidetoneRun(0, (flag && _cw_sidetones && _cw_sw_sidetone) ? 1 : 0);
