	public bool RX1StepAttEnabled
	{
		get
		{
			return _rx1_step_att_enabled;
		}
		set
		{
			bool rx1_step_att_enabled = _rx1_step_att_enabled;
			_rx1_step_att_enabled = value;
			if (_rx1_step_att_enabled)
			{
				udRX1StepAttData.Value = validateRX1StepAttData(getRX1stepAttenuatorForBand(rx1_band));
				udRX1StepAttData_ValueChanged(this, EventArgs.Empty);
			}
			else
			{
				comboPreamp_SelectedIndexChanged(this, EventArgs.Empty);
				if (alexpresent)
				{
					NetworkIO.SetAlexAtten(alex_atten);
				}
			}
			updateAttNudsCombos();
			if (!_mox)
			{
				update_preamp = true;
				UpdatePreamps();
			}
			UpdateRX1DisplayOffsets();
			if (rx1_step_att_enabled != _rx1_step_att_enabled)
			{
