	public int RX1AttenuatorData
	{
		get
		{
			return _rx1_attenuator_data;
		}
		set
		{
			if (_from_attenuatordata[0])
			{
				return;
			}
			int rx1_attenuator_data = _rx1_attenuator_data;
			_rx1_attenuator_data = value;
			if (initializing)
			{
				if (rx1_attenuator_data != _rx1_attenuator_data)
				{
					AttenuatorDataChangedHandlers?.Invoke(1, rx1_attenuator_data, _rx1_attenuator_data);
				}
				return;
			}
			_from_attenuatordata[0] = true;
			if (alexpresent && HardwareSpecific.Model != HPSDRModel.ANAN10 && HardwareSpecific.Model != HPSDRModel.ANAN10E && HardwareSpecific.Model != HPSDRModel.ANAN7000D && HardwareSpecific.Model != HPSDRModel.ANAN8000D && HardwareSpecific.Model != HPSDRModel.ORIONMKII && HardwareSpecific.Model != HPSDRModel.ANAN_G2E && HardwareSpecific.Model != HPSDRModel.ANAN_G2 && HardwareSpecific.Model != HPSDRModel.ANAN_G2_1K && HardwareSpecific.Model != HPSDRModel.ANVELINAPRO3 && HardwareSpecific.Model != HPSDRModel.REDPITAYA)
			{
				udRX1StepAttData.Maximum = 61m;
			}
			else
			{
				udRX1StepAttData.Maximum = 31m;
			}
			_from_attenuatordata[0] = false;
			_rx1_attenuator_data = validateRX1StepAttData(_rx1_attenuator_data);
			int DDCrx = -1;
			int DDCrx2 = -1;
			int DDCsync = -1;
			int DDCsync2 = -1;
			int DDCpsrx = -1;
			int DDCpstx = -1;
			GetDDC(out DDCrx, out DDCrx2, out DDCsync, out DDCsync2, out DDCpsrx, out DDCpstx);
			int aDCInUse = GetADCInUse(DDCrx);
			int aDCInUse2 = GetADCInUse(DDCrx2);
			if (_rx1_step_att_enabled)
			{
				if (alexpresent && HardwareSpecific.Model != HPSDRModel.ANAN10 && HardwareSpecific.Model != HPSDRModel.ANAN10E && HardwareSpecific.Model != HPSDRModel.ANAN7000D && HardwareSpecific.Model != HPSDRModel.ANAN8000D && HardwareSpecific.Model != HPSDRModel.ORIONMKII && HardwareSpecific.Model != HPSDRModel.ANAN_G2E && HardwareSpecific.Model != HPSDRModel.ANAN_G2 && HardwareSpecific.Model != HPSDRModel.ANAN_G2_1K && HardwareSpecific.Model != HPSDRModel.ANVELINAPRO3 && HardwareSpecific.Model != HPSDRModel.REDPITAYA)
				{
					if (_rx1_attenuator_data <= 31)
					{
						NetworkIO.SetAlexAtten(0);
						switch (aDCInUse)
						{
						case 0:
							NetworkIO.SetADC1StepAttenData(_rx1_attenuator_data);
							break;
						case 1:
							NetworkIO.SetADC2StepAttenData(_rx1_attenuator_data);
							break;
						case 2:
							NetworkIO.SetADC3StepAttenData(_rx1_attenuator_data);
							break;
						}
					}
					else
					{
						NetworkIO.SetAlexAtten(3);
						switch (aDCInUse)
						{
						case 0:
							NetworkIO.SetADC1StepAttenData(_rx1_attenuator_data + 2);
							break;
						case 1:
							NetworkIO.SetADC2StepAttenData(_rx1_attenuator_data + 2);
							break;
						case 2:
							NetworkIO.SetADC3StepAttenData(_rx1_attenuator_data + 2);
							break;
						}
					}
				}
				else
				{
					NetworkIO.SetAlexAtten(0);
					switch (aDCInUse)
					{
					case 0:
						NetworkIO.SetADC1StepAttenData(_rx1_attenuator_data);
						break;
					case 1:
						NetworkIO.SetADC2StepAttenData(_rx1_attenuator_data);
						break;
					case 2:
						NetworkIO.SetADC3StepAttenData(_rx1_attenuator_data);
						break;
					}
				}
			}
			if (!_mox)
			{
				setRX1stepAttenuatorForBand(rx1_band, _rx1_attenuator_data);
			}
			_from_attenuatordata[0] = true;
			udRX1StepAttData.Value = _rx1_attenuator_data;
			_from_attenuatordata[0] = false;
			lblAttenLabel.Text = _rx1_attenuator_data + " dB";
			if (!_mox)
			{
				if (!_setFromOtherAttenuator)
				{
					bool flag = m_bDiversityAttLinkForRX1andRX2 && diversityForm != null && Diversity2 && diversityForm.EXTDIVOutput == 2;
					if (((aDCInUse == aDCInUse2) | flag) && RX2AttenuatorData != _rx1_attenuator_data)
					{
						_setFromOtherAttenuator = true;
						if (SetupForm.RX2EnableAtt != SetupForm.RX1EnableAtt)
						{
							SetupForm.RX2EnableAtt = SetupForm.RX1EnableAtt;
						}
						RX2AttenuatorData = _rx1_attenuator_data;
						_setFromOtherAttenuator = false;
					}
				}
				update_preamp = true;
				UpdatePreamps();
			}
			UpdateRX1DisplayOffsets();
			if (rx1_attenuator_data != _rx1_attenuator_data)
			{
				AttenuatorDataChangedHandlers?.Invoke(1, rx1_attenuator_data, _rx1_attenuator_data);
			}
			setATTGeneralSetting(1);
		}
	}

