	public double TXFreq
	{
		get
		{
			double result = 0.0;
			if (!rx2_enabled)
			{
				result = (chkVFOBTX.Checked ? VFOBFreq : VFOAFreq);
			}
			else if (chkVFOBTX.Checked)
			{
				result = VFOBFreq;
			}
			else if (chkVFOSplit.Checked)
			{
				result = VFOASubFreq;
			}
			else if (chkVFOATX.Checked)
			{
				result = VFOAFreq;
			}
			return result;
		}
		set
		{
			if (!rx2_enabled)
			{
				if (!chkVFOBTX.Checked)
				{
					VFOAFreq = value;
				}
				else
				{
					VFOBFreq = value;
				}
			}
			else if (chkVFOBTX.Checked)
			{
				VFOBFreq = value;
			}
			else if (chkVFOSplit.Checked)
			{
				VFOASubFreq = value;
			}
			else if (chkVFOATX.Checked)
			{
				VFOAFreq = value;
			}
		}
	}

