	public bool RECPOST
	{
		set
		{
			string error;
			if (value)
			{
				ARP.StopPlayback(out error);
				ARP.StopRecord(out error);
				RecordingDetails recordingDetails = new RecordingDetails
				{
					Band = BandStackManager.BandToString(RX1Band),
					Frequency = VFOAFreq.ToString("F6", CultureInfo.InvariantCulture),
					Mode = RX1DSPMode.ToString(),
					UtcTime = DateTime.UtcNow
				};
				int num;
				switch (ARP.BitDepthMode)
				{
				case AudioBitDepthMode.Pcm8:
					num = 8;
					break;
				case AudioBitDepthMode.Pcm16:
					num = 16;
					break;
				case AudioBitDepthMode.Pcm24:
					num = 24;
					break;
				case AudioBitDepthMode.IeeeFloat32:
				case AudioBitDepthMode.Pcm32:
					num = 32;
					break;
				default:
					num = 0;
					break;
				}
				int sampleRate = ARP.SampleRate;
				string text = DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ss.fffZ");
				string text2 = recordingDetails.Mode + "_" + recordingDetails.Frequency + "MHz_[" + num + "bits_" + sampleRate + "Hz]_" + text + ".wav";
				error = new string(Path.GetInvalidFileNameChars());
				foreach (char oldChar in error)
				{
					text2 = text2.Replace(oldChar, '_');
				}
				string full_path = Path.Combine(ARP.AudioFolder, "scheduled", text2);
				ARP.RecordToFileFromWDSP("scheduled", full_path, 0, out var _, remove_if_file_exists: true, recordingDetails, ignore_temp_changes: true);
			}
			else
			{
				ARP.StopPlayback(out error);
				ARP.StopRecord(out error);
			}
		}
	}

