	public string TXProfile
	{
		get
		{
			return _tx_profile;
		}
		set
		{
			string tx_profile = _tx_profile;
			switch (_rx1_dsp_mode)
			{
			case DSPMode.DIGU:
			case DSPMode.DIGL:
				if (comboDigTXProfile != null)
				{
					comboDigTXProfile.Text = value;
				}
				break;
			case DSPMode.FM:
				if (comboFMTXProfile != null)
				{
					comboFMTXProfile.Text = value;
				}
				break;
			case DSPMode.AM:
			case DSPMode.SAM:
				if (comboAMTXProfile != null)
				{
					comboAMTXProfile.Text = value;
				}
				break;
			default:
				if (comboTXProfile != null)
				{
					comboTXProfile.Text = value;
				}
				break;
			}
			_tx_profile = value;
			if (tx_profile != _tx_profile)
			{
				TXProfileChangedHandlers?.Invoke(tx_profile, _tx_profile);
			}
		}
	}

