	public int DefaultLowCut
	{
		get
		{
			return default_low_cut;
		}
		set
		{
			for (DSPMode dSPMode = DSPMode.LSB; dSPMode < DSPMode.LAST; dSPMode++)
			{
				for (Filter filter = Filter.F1; filter < Filter.LAST; filter++)
				{
					int low = rx1_filters[(int)dSPMode].GetLow(filter);
					int high = rx1_filters[(int)dSPMode].GetHigh(filter);
					switch (dSPMode)
					{
					case DSPMode.USB:
						if (low == default_low_cut)
						{
							rx1_filters[(int)dSPMode].SetLow(filter, value);
						}
						break;
					case DSPMode.LSB:
						if (high == -default_low_cut)
						{
							rx1_filters[(int)dSPMode].SetHigh(filter, -value);
						}
						break;
					}
				}
			}
			default_low_cut = value;
			RX1Filter = rx1_filter;
		}
	}

	public int DefaultRX2LowCut
	{
		get
		{
			return default_rx2_low_cut;
		}
		set
		{
			for (DSPMode dSPMode = DSPMode.LSB; dSPMode < DSPMode.LAST; dSPMode++)
			{
				for (Filter filter = Filter.F1; filter < Filter.LAST; filter++)
				{
					int low = rx2_filters[(int)dSPMode].GetLow(filter);
					int high = rx2_filters[(int)dSPMode].GetHigh(filter);
					switch (dSPMode)
					{
					case DSPMode.USB:
						if (low == default_rx2_low_cut)
						{
							rx2_filters[(int)dSPMode].SetLow(filter, value);
						}
						break;
					case DSPMode.LSB:
						if (high == -default_rx2_low_cut)
						{
							rx2_filters[(int)dSPMode].SetHigh(filter, -value);
						}
						break;
					}
				}
			}
			default_rx2_low_cut = value;
			RX2Filter = rx2_filter;
		}
	}

