	public bool VACAutoEnable
	{
		get
		{
			return vac_auto_enable;
		}
		set
		{
			vac_auto_enable = value;
			if (IsSetupFormNull)
			{
				return;
			}
			if (vac_auto_enable)
			{
				switch (_rx1_dsp_mode)
				{
				case DSPMode.DIGU:
				case DSPMode.DIGL:
				case DSPMode.DRM:
					SetupForm.VACEnable = true;
					break;
				default:
					SetupForm.VACEnable = false;
					break;
				}
			}
			else
			{
				SetupForm.VACEnable = false;
			}
		}
	}

	public bool VAC2AutoEnable
	{
		get
		{
			return vac2_auto_enable;
		}
		set
		{
			vac2_auto_enable = value;
			if (IsSetupFormNull)
			{
				return;
			}
			if (vac2_auto_enable)
			{
				DSPMode dSPMode = _rx1_dsp_mode;
				if (vac2_rx2)
				{
					dSPMode = _rx2_dsp_mode;
				}
				switch (dSPMode)
				{
				case DSPMode.DIGU:
				case DSPMode.DIGL:
				case DSPMode.DRM:
					SetupForm.VAC2Enable = true;
					break;
				default:
					SetupForm.VAC2Enable = false;
					break;
				}
			}
			else
			{
				SetupForm.VAC2Enable = false;
			}
		}
	}

	public bool VAC2RX2
	{
		get
		{
			return vac2_rx2;
		}
		set
		{
			vac2_rx2 = value;
			if (!IsSetupFormNull && vac2_auto_enable)
			{
				DSPMode dSPMode = _rx1_dsp_mode;
				if (vac2_rx2)
				{
					dSPMode = _rx2_dsp_mode;
				}
				switch (dSPMode)
				{
				case DSPMode.DIGU:
				case DSPMode.DIGL:
				case DSPMode.DRM:
					SetupForm.VAC2Enable = true;
					break;
				default:
					SetupForm.VAC2Enable = false;
					break;
				}
			}
		}
	}

