	public int DIGUClickTuneOffset
	{
		get
		{
			return digu_click_tune_offset;
		}
		set
		{
			if (digu_click_tune_offset != value)
			{
				int num = digu_click_tune_offset;
				digu_click_tune_offset = value;
				Filter rX1Filter = RX1Filter;
				Filter rX2Filter = RX2Filter;
				for (Filter filter = Filter.F1; filter < Filter.LAST; filter++)
				{
					int low = rx1_filters[7].GetLow(filter);
					int high = rx1_filters[7].GetHigh(filter);
					string name = rx1_filters[7].GetName(filter);
					int num2 = high - low;
					low = digu_click_tune_offset - num2 / 2;
					high = digu_click_tune_offset + num2 / 2;
					rx1_filters[7].SetFilter(filter, low, high, name);
					rx2_filters[7].SetFilter(filter, low, high, name);
				}
				RX1Filter = rX1Filter;
				RX2Filter = rX2Filter;
				if (!IsSetupFormNull && SetupForm.DigU_CT_Offset != digu_click_tune_offset)
				{
					SetupForm.DigU_CT_Offset = digu_click_tune_offset;
				}
				if (num != digu_click_tune_offset)
				{
					DIGUOffsetChangedHandlers?.Invoke(num, digu_click_tune_offset);
				}
			}
		}
	}

	public int DIGLClickTuneOffset
	{
		get
		{
			return digl_click_tune_offset;
		}
		set
		{
			if (digl_click_tune_offset != value)
			{
				int num = digl_click_tune_offset;
				digl_click_tune_offset = value;
				Filter rX1Filter = RX1Filter;
				Filter rX2Filter = RX2Filter;
				for (Filter filter = Filter.F1; filter < Filter.LAST; filter++)
				{
					int low = rx1_filters[9].GetLow(filter);
					int high = rx1_filters[9].GetHigh(filter);
					string name = rx1_filters[9].GetName(filter);
					int num2 = high - low;
					low = -digl_click_tune_offset - num2 / 2;
					high = -digl_click_tune_offset + num2 / 2;
					rx1_filters[9].SetFilter(filter, low, high, name);
					rx2_filters[9].SetFilter(filter, low, high, name);
				}
				RX1Filter = rX1Filter;
				RX2Filter = rX2Filter;
				if (!IsSetupFormNull && SetupForm.DigL_CT_Offset != digl_click_tune_offset)
				{
					SetupForm.DigL_CT_Offset = digl_click_tune_offset;
				}
				if (num != digl_click_tune_offset)
				{
					DIGLOffsetChangedHandlers?.Invoke(num, digl_click_tune_offset);
				}
			}
		}
	}

