	public BreakIn CurrentBreakInMode
	{
		get
		{
			return _current_breakin_mode;
		}
		set
		{
			_current_breakin_mode = value;
			switch (value)
			{
			case BreakIn.QSK:
				QSKEnabled = true;
				NetworkIO.SetCWBreakIn(1);
				chkQSK.Text = "QSK";
				break;
			case BreakIn.Manual:
				QSKEnabled = false;
				NetworkIO.SetCWBreakIn(0);
				chkQSK.Text = "OFF";
				break;
			case BreakIn.Semi:
				QSKEnabled = false;
				NetworkIO.SetCWBreakIn(1);
				chkQSK.Text = "SEMI";
				break;
			}
			TXAF = txaf;
		}
	}

