	public bool PennyExtCtrlEnabled
	{
		get
		{
			return penny_ext_ctrl_enabled;
		}
		set
		{
			penny_ext_ctrl_enabled = value;
			if (!initializing)
			{
				Band band = BandByFreq(XVTRForm.TranslateFreq(VFOAFreq), rx1_xvtr_index, current_region);
				Band bandb = BandByFreq(XVTRForm.TranslateFreq(VFOBFreq), rx2_xvtr_index, current_region);
				int bits = Penny.getPenny().ExtCtrlEnable(band, bandb, _mox, value, _tuning, SetupForm.TestIMD, chkExternalPA.Checked);
				if (!IsSetupFormNull)
				{
					SetupForm.UpdateOCLedStrip(_mox, bits);
				}
			}
		}
	}

	public bool AlexAntCtrlEnabled
	{
		get
		{
			return alex_ant_ctrl_enabled;
		}
		set
		{
			alex_ant_ctrl_enabled = value;
			UpdateTRXAnt();
			if (rx1_xvtr_index >= 0)
			{
				Band band = BandByFreq(XVTRForm.TranslateFreq(VFOAFreq), rx1_xvtr_index, current_region);
				Alex.getAlex().UpdateAlexAntSelection(band, _mox, alex_ant_ctrl_enabled, xvtr: true);
			}
			else
			{
				Alex.getAlex().UpdateAlexAntSelection(RX1Band, _mox, alex_ant_ctrl_enabled, xvtr: false);
			}
			UpdateTRXAnt();
			if ((RX1DSPMode == DSPMode.CWL || RX1DSPMode == DSPMode.CWU) && BreakInEnabledState == CheckState.Indeterminate)
			{
				chkQSK_CheckStateChanged(this, EventArgs.Empty);
			}
		}
	}

