	public CheckState VFOLock { get; set; }

	public bool VFOALock
	{
		get
		{
			return _vfoA_lock;
		}
		set
		{
			bool vfoA_lock = _vfoA_lock;
			_vfoA_lock = value;
			if (_vfoA_lock)
			{
				chkVFOSync.Checked = false;
				DisableAllBands();
				DisableAllModes();
			}
			else
			{
				EnableAllBands();
				EnableAllModes();
			}
			bool enabled = !_vfoA_lock;
			txtVFOAFreq.Enabled = enabled;
			btnVFOBtoA.Enabled = enabled;
			btnVFOSwap.Enabled = enabled;
			btnMemoryQuickRestore.Enabled = enabled;
			if (_vfoA_lock)
			{
				lblLockLabel.BackColor = Color.Blue;
			}
			else
			{
				lblLockLabel.BackColor = Color.Transparent;
			}
			lblLockLabel.Invalidate();
			AndromedaIndicatorCheck(EIndicatorActions.eINVFOLock, IsRX1: true, _vfoA_lock);
			chkVFOLock.Checked = _vfoA_lock;
			if (_vfoA_lock != vfoA_lock)
			{
				VfoALockChangedHandlers?.Invoke(1, vfoA_lock, _vfoA_lock);
				vfoA_lock = _vfoA_lock;
			}
			SetGeneralSetting(0, OtherButtonId.LOCK_A, chkVFOLock.Checked);
		}
	}

	public bool VFOBLock
	{
		get
		{
			return _vfoB_lock;
		}
		set
		{
			bool vfoB_lock = _vfoB_lock;
			_vfoB_lock = value;
			if (_vfoB_lock)
			{
				chkVFOSync.Checked = false;
			}
			bool enabled = !_vfoB_lock;
			txtVFOBFreq.Enabled = enabled;
			comboRX2Band.Enabled = enabled;
			btnVFOAtoB.Enabled = enabled;
			chkVFOSync.Enabled = enabled;
			radRX2ModeLSB.Enabled = enabled;
			radRX2ModeUSB.Enabled = enabled;
			radRX2ModeDSB.Enabled = enabled;
			radRX2ModeCWL.Enabled = enabled;
			radRX2ModeCWU.Enabled = enabled;
			radRX2ModeFMN.Enabled = enabled;
			radRX2ModeAM.Enabled = enabled;
			radRX2ModeSAM.Enabled = enabled;
			radRX2ModeSPEC.Enabled = enabled;
			radRX2ModeDIGL.Enabled = enabled;
			radRX2ModeDIGU.Enabled = enabled;
			radRX2ModeDRM.Enabled = enabled;
			if (_vfoB_lock)
			{
				lblRX2LockLabel.BackColor = Color.Blue;
			}
			else
			{
				lblRX2LockLabel.BackColor = Color.Transparent;
			}
			AndromedaIndicatorCheck(EIndicatorActions.eINVFOLock, !RX2Enabled, _vfoB_lock);
			chkVFOBLock.Checked = _vfoB_lock;
			if (_vfoB_lock != vfoB_lock)
			{
				VfoBLockChangedHandlers?.Invoke((!RX2Enabled) ? 1 : 2, vfoB_lock, _vfoB_lock);
				vfoB_lock = _vfoB_lock;
			}
			SetGeneralSetting(0, OtherButtonId.LOCK_B, chkVFOBLock.Checked);
		}
	}

