			{
				chkMOX.Enabled = !_tx_inhibit;
			}
			if (_tx_inhibit && chkMOX.Checked)
			{
				chkMOX.Checked = false;
			}
			toolStripStatusLabel_TXInhibit.Visible = _tx_inhibit;
