	public double MaxFreq
	{
		get
		{
			return max_freq;
		}
		set
		{
			max_freq = value;
			if (IsSetupFormNull)
			{
				return;
			}
			if (VFOAFreq > max_freq && rx1_xvtr_index < 0)
			{
				VFOAFreq = max_freq;
			}
			if (RX2Enabled)
			{
				if (VFOBFreq > max_freq && rx2_xvtr_index < 0)
				{
					VFOBFreq = max_freq;
				}
			}
			else if (VFOBFreq > max_freq && rx1_xvtr_index < 0)
			{
				VFOBFreq = max_freq;
			}
		}
	}

