	public bool WaterfallUseRX1SpectrumMinMax
	{
		get
		{
			return m_bWaterfallUseRX1SpectrumMinMax;
		}
		set
		{
			if (value && !m_bWaterfallUseRX1SpectrumMinMax)
			{
				_savedRX1WFLow = Display.WaterfallLowThreshold;
				_savedRX1WFHigh = Display.WaterfallHighThreshold;
			}
			else if (!value && m_bWaterfallUseRX1SpectrumMinMax)
			{
				if (!float.IsNaN(_savedRX1WFLow))
				{
					Display.WaterfallLowThreshold = _savedRX1WFLow;
				}
				if (!float.IsNaN(_savedRX1WFHigh))
				{
					Display.WaterfallHighThreshold = _savedRX1WFHigh;
				}
			}
			m_bWaterfallUseRX1SpectrumMinMax = value;
			Display.SpectrumBasedThresholdsRX1 = m_bWaterfallUseRX1SpectrumMinMax;
			setWaterfallGainsIfLinkedToSpectrum(1);
		}
	}

	public bool WaterfallUseRX2SpectrumMinMax
	{
		get
		{
			return m_bWaterfallUseRX2SpectrumMinMax;
		}
		set
		{
