			{
				_savedRX2WFLow = Display.RX2WaterfallLowThreshold;
				_savedRX2WFHigh = Display.RX2WaterfallHighThreshold;
			}
			else if (!value && m_bWaterfallUseRX2SpectrumMinMax)
			{
				if (!float.IsNaN(_savedRX2WFLow))
				{
					Display.RX2WaterfallLowThreshold = _savedRX2WFLow;
				}
				if (!float.IsNaN(_savedRX2WFHigh))
				{
					Display.RX2WaterfallHighThreshold = _savedRX2WFHigh;
				}
			}
			m_bWaterfallUseRX2SpectrumMinMax = value;
			Display.SpectrumBasedThresholdsRX2 = m_bWaterfallUseRX2SpectrumMinMax;
			setWaterfallGainsIfLinkedToSpectrum(2);
		}
	}

