	public int CATFilterWidth
	{
		get
		{
			int val = (ptbFilterWidth.Value + _max_filter_width) / 2;
			val = Math.Max(10, val);
			val = Math.Min(_max_filter_width, val);
			switch (RX1DSPMode)
			{
			case DSPMode.DSB:
			case DSPMode.FM:
			case DSPMode.AM:
			case DSPMode.SPEC:
			case DSPMode.SAM:
			case DSPMode.DRM:
				val *= 2;
				break;
			}
			return val;
		}
		set
		{
			int num;
			switch (RX1DSPMode)
			{
			case DSPMode.DSB:
			case DSPMode.FM:
			case DSPMode.AM:
			case DSPMode.SPEC:
			case DSPMode.SAM:
			case DSPMode.DRM:
				num = 2;
				break;
			default:
				num = 1;
				break;
			}
			int num2 = _max_filter_width * num;
			int value2 = (Math.Max(10, Math.Min(num2, value)) * 2 - num2) / num;
			FilterWidthMode filterWidthMode = current_filter_width_mode;
			current_filter_width_mode = FilterWidthMode.Linear;
			_filter_width_update_from_cat = true;
			ptbFilterWidth.Value = value2;
			ptbFilterWidth_Scroll(ptbFilterWidth, EventArgs.Empty);
			_filter_width_update_from_cat = false;
			current_filter_width_mode = filterWidthMode;
		}
	}

