	public bool CATEnabled
	{
		get
		{
			return cat_enabled;
		}
		set
		{
			try
			{
				cat_enabled = value;
				if (Siolisten != null)
				{
					if (cat_enabled)
					{
						Siolisten.enableCAT();
					}
					else
					{
						Siolisten.disableCAT();
					}
				}
			}
			catch (Exception)
			{
				MessageBox.Show("Error enabling CAT on COM" + cat_port + ".\nPlease check CAT settings and try again.", "CAT Error", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
				if (!IsSetupFormNull)
				{
					SetupForm.CATEnabled = false;
				}
			}
		}
	}

	public bool AndromedaCATEnabled
	{
		get
		{
			return andromeda_cat_enabled;
		}
		set
		{
			try
			{
				andromeda_cat_enabled = value;
				if (value)
				{
					NetworkIO.ATU_Tune(1);
				}
				else
				{
					NetworkIO.ATU_Tune(0);
				}
				if (AndromedaSiolisten != null)
				{
					if (andromeda_cat_enabled)
					{
						AndromedaSiolisten.enableCAT5();
						MakeAndromedaVersionRequestMsg();
						toolStripStatusLabelAndromedaMulti.Visible = true;
					}
					else
					{
						AndromedaSiolisten.disableCAT5();
					}
				}
			}
			catch (Exception)
			{
				MessageBox.Show("Error enabling Andromeda on COM" + cat_port + ".\nPlease check settings and try again.", "Andromeda CAT Error", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
				if (!IsSetupFormNull && !andromeda_g2_enabled)
				{
					SetupForm.AndromedaCATEnabled = false;
				}
			}
		}
	}

