		{
			_ptt_bit_bang_enabled = value;
			if (serialPTT != null)
			{
				serialPTT.Destroy();
				serialPTT = null;
			}
			if (!_ptt_bit_bang_enabled)
			{
				return;
			}
			try
			{
				serialPTT = new SerialPortPTT(cat_ptt_bit_bang_port, cat_ptt_rts, cat_ptt_dtr);
				serialPTT.Init();
			}
			catch (Exception ex)
			{
				_ptt_bit_bang_enabled = false;
				if (!IsSetupFormNull)
				{
					SetupForm.copyCATPropsToDialogVars();
				}
				MessageBox.Show("Could not initialize PTT Bit Bang control.  Exception was:\n\n " + ex.Message + "\n\nPTT Bit Bang control has been disabled.", "Error Initializing PTT control", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			}
		}
	}

