	public Band RX1Band
	{
		get
		{
			return rx1_band;
		}
		set
		{
			if (!MOX || (!VFOATX && (rx2_enabled || !VFOBTX)))
			{
				Band band = rx1_band;
				rx1_band = value;
				if (rx1_xvtr_index >= 0)
				{
					BandByFreq(XVTRForm.TranslateFreq(VFOAFreq), rx1_xvtr_index, current_region);
				}
				if (!initializing && rx1_preamp_mode > PreampMode.FIRST)
				{
					rx1_preamp_by_band[(int)band] = rx1_preamp_mode;
					setRX1stepAttenuatorForBand(band, _rx1_attenuator_data);
				}
				if (rx1_band != band || initializing)
				{
					rx1_agcm_by_band[(int)band] = (AGCMode)comboAGC.SelectedIndex;
					rx1_agct_by_band[(int)band] = ptbRF.Value;
					SetupForm.ATTOnTX = getTXstepAttenuatorForBand(_tx_band);
					RX1PreampMode = rx1_preamp_by_band[(int)rx1_band];
					RX1AttenuatorData = getRX1stepAttenuatorForBand(rx1_band);
					int rF = rx1_agct_by_band[(int)rx1_band];
					RX1AGCMode = rx1_agcm_by_band[(int)rx1_band];
					RF = rF;
				}
				DisplayAriesRXAntenna();
				if (band != rx1_band)
				{
					BandChangeHandlers?.Invoke(1, band, rx1_band);
				}
				else
				{
					BandNoChangeHandlers?.Invoke(1, rx1_band);
				}
			}
		}
	}

	public Band RX2Band
	{
		get
		{
			return rx2_band;
		}
		set
		{
			if (MOX && VFOBTX)
			{
				return;
			}
			Band band = rx2_band;
			rx2_band = value;
			string value2 = BandToString(rx2_band);
			if (comboRX2Band.Items.Contains(value2))
			{
				comboRX2Band.Text = value2;
			}
			if (rx2_xvtr_index >= 0)
			{
				BandByFreq(XVTRForm.TranslateFreq(VFOBFreq), rx2_xvtr_index, current_region);
			}
			if (!initializing && rx2_preamp_mode > PreampMode.FIRST)
			{
				rx2_preamp_by_band[(int)band] = rx2_preamp_mode;
				setRX2stepAttenuatorForBand(band, rx2_attenuator_data);
			}
			if (rx2_band != band || initializing)
			{
				rx2_agcm_by_band[(int)band] = (AGCMode)comboRX2AGC.SelectedIndex;
				rx2_agct_by_band[(int)band] = ptbRX2RF.Value;
				RX2PreampMode = rx2_preamp_by_band[(int)rx2_band];
				RX2AttenuatorData = getRX2stepAttenuatorForBand(rx2_band);
				int rX2RF = rx2_agct_by_band[(int)rx2_band];
				RX2AGCMode = rx2_agcm_by_band[(int)rx2_band];
				RX2RF = rX2RF;
				repopulateForms();
				if (band != rx2_band)
				{
					BandChangeHandlers?.Invoke(2, band, rx2_band);
				}
				else
				{
					BandNoChangeHandlers?.Invoke(2, rx2_band);
				}
			}
		}
	}

	public Band TXBand
	{
		get
		{
			return _tx_band;
		}
		set
		{
			if (MOX)
			{
				return;
			}
			Band band = _tx_band;
			if (initializing)
			{
				band = value;
			}
			_tx_band = value;
			if (tx_xvtr_index >= 0)
			{
				BandByFreq(XVTRForm.TranslateFreq(VFOAFreq), rx1_xvtr_index, current_region);
			}
			if (_tx_band != band || initializing)
			{
				int num = ptbPWR.Value;
				if (initializing)
				{
					num = power_by_band[(int)band];
				}
				power_by_band[(int)band] = num;
				ptbPWR.LimitValue = limitPower_by_band[(int)value];
				ptbTune.LimitValue = limitTunePower_by_band[(int)value];
				PWR = power_by_band[(int)value];
				TunePWR = tunePower_by_band[(int)value];
				if (!initializing)
				{
					fm_tx_offset_by_band_mhz[(int)band] = fm_tx_offset_mhz;
				}
				FMTXOffsetMHz = fm_tx_offset_by_band_mhz[(int)value];
			}
			if (band != Band.B60M && !initializing)
			{
				SetupForm.TXFilterHighSave = tx_filter_high;
				SetupForm.TXFilterLowSave = tx_filter_low;
			}
			if (_tx_band == Band.B60M)
			{
				if (tx_filter_high > 2900)
				{
					SetupForm.TXFilterHigh = 2900;
				}
				if (tx_filter_low < 100)
				{
					SetupForm.TXFilterLow = 100;
				}
			}
			if ((_tx_band != band || initializing) && band == Band.B60M)
			{
				if (tx_filter_high != SetupForm.TXFilterHighSave)
				{
					SetupForm.TXFilterHigh = SetupForm.TXFilterHighSave;
				}
				if (tx_filter_low != SetupForm.TXFilterLowSave)
				{
					SetupForm.TXFilterLow = SetupForm.TXFilterLowSave;
				}
			}
			DisplayAriesTXAntenna();
			if (_tx_band != band)
			{
				TXBandChangeHandlers?.Invoke(band, _tx_band, TXFreq);
			}
		}
	}

