	public int CWPitch
	{
		get
		{
			return cw_pitch;
		}
		set
		{
			int num = cw_pitch;
			int num2 = cw_pitch - value;
			cw_pitch = value;
			if (cw_pitch <= 0)
			{
				cw_pitch = 0;
			}
			udCWPitch.Value = cw_pitch;
			Display.CWPitch = cw_pitch;
			NetworkIO.SetCWSidetoneFreq(cw_pitch);
			for (Filter filter = Filter.F1; filter < Filter.LAST; filter++)
			{
				int low = rx1_filters[3].GetLow(filter);
				int high = rx1_filters[3].GetHigh(filter);
				string name = rx1_filters[3].GetName(filter);
				int num3 = high - low;
				low = -cw_pitch - num3 / 2;
				high = -cw_pitch + num3 / 2;
				if (high > 0)
				{
					low -= high;
					high = 0;
				}
				rx1_filters[3].SetFilter(filter, low, high, name);
				rx2_filters[3].SetFilter(filter, low, high, name);
				low = rx1_filters[4].GetLow(filter);
				high = rx1_filters[4].GetHigh(filter);
				name = rx1_filters[4].GetName(filter);
				num3 = high - low;
				low = cw_pitch - num3 / 2;
				high = cw_pitch + num3 / 2;
				if (low < 0)
				{
					high -= low;
					low = 0;
				}
				rx1_filters[4].SetFilter(filter, low, high, name);
				rx2_filters[4].SetFilter(filter, low, high, name);
			}
			switch (_rx1_dsp_mode)
			{
			case DSPMode.CWL:
				num2 = -num2;
				if (_mox)
				{
					VFOAFreq += (double)num2 / 1000000.0;
					if (chkVFOSplit.Checked)
					{
						VFOBFreq += (double)num2 / 1000000.0;
					}
				}
				else
				{
					txtVFOAFreq_LostFocus(this, EventArgs.Empty);
					txtVFOBFreq_LostFocus(this, EventArgs.Empty);
				}
				RX1Filter = rx1_filter;
				RX2Filter = rx2_filter;
				break;
			case DSPMode.CWU:
				if (_mox)
				{
					VFOAFreq += (double)num2 / 1000000.0;
					if (chkVFOSplit.Checked)
					{
						VFOBFreq += (double)num2 / 1000000.0;
					}
				}
				else
				{
					txtVFOAFreq_LostFocus(this, EventArgs.Empty);
					txtVFOBFreq_LostFocus(this, EventArgs.Empty);
				}
				RX1Filter = rx1_filter;
				RX2Filter = rx2_filter;
				break;
			}
			if (!IsSetupFormNull)
			{
				if (SetupForm.RX1APFControls)
				{
					SetupForm.RX1APFFreq = ptbCWAPFFreq.Value;
				}
				if (SetupForm.RX1subAPFControls)
				{
					SetupForm.RX1subAPFFreq = ptbCWAPFFreq.Value;
				}
				if (SetupForm.RX2APFControls)
				{
					SetupForm.RX2APFFreq = ptbCWAPFFreq.Value;
				}
			}
			if (num != cw_pitch)
			{
				CWPitchChangedHandlers?.Invoke(num, cw_pitch, Display.ShowCWZeroLine);
			}
		}
	}

