	public int APFType
	{
		get
		{
			return _apf_type;
		}
		set
		{
			if (value < 0 || value > 3 || value == _apf_type)
			{
				return;
			}
			_apf_type = value;
			SetupForm.SetAPFType(_apf_type);
			if (btnAPF_type != null)
			{
				switch (_apf_type)
				{
				case 0:
					btnAPF_type.Text = "DP";
					break;
				case 1:
					btnAPF_type.Text = "MA";
					break;
				case 2:
					btnAPF_type.Text = "GA";
					break;
				case 3:
					btnAPF_type.Text = "BI";
					break;
				}
			}
		}
	}

