			if (!value && _auto_attTX_when_not_in_ps)
			{
				return;
			}
			m_bATTonTX = value;
			updateAttNudsCombos();
			if (PowerOn)
			{
				if (m_bATTonTX)
				{
					int tXstepAttenuatorForBand = getTXstepAttenuatorForBand(_tx_band);
					NetworkIO.SetTxAttenData(tXstepAttenuatorForBand);
					Display.TXAttenuatorOffset = tXstepAttenuatorForBand;
				}
				else
				{
					NetworkIO.SetTxAttenData(0);
					Display.TXAttenuatorOffset = 0f;
				}
			}
		}
	}

