	public bool AlexPresent
	{
		get
		{
			return alexpresent;
		}
		set
		{
			bool flag = alexpresent;
			alexpresent = value;
			if (alexpresent)
			{
				if (!comboMeterTXMode.Items.Contains("Ref Pwr"))
				{
					comboMeterTXMode.Items.Insert(1, "Ref Pwr");
				}
				if (!comboMeterTXMode.Items.Contains("SWR"))
				{
					comboMeterTXMode.Items.Insert(2, "SWR");
				}
				if (comboMeterTXMode.SelectedIndex < 0)
				{
					comboMeterTXMode.SelectedIndex = 0;
				}
				setAlex1HPF(_rx1_dds_freq);
				setAlexLPF(tx_dds_freq_mhz, freqIsTX: true);
				setAlex2HPF(rx2_dds_freq_mhz);
			}
			else
			{
				string text = comboMeterTXMode.Text;
				if (!initializing)
				{
					if (comboMeterTXMode.Items.Contains("Ref Pwr"))
					{
						comboMeterTXMode.Items.Remove("Ref Pwr");
					}
					if (comboMeterTXMode.Items.Contains("SWR"))
					{
						comboMeterTXMode.Items.Remove("SWR");
					}
				}
				comboMeterTXMode.Text = text;
				if (comboMeterTXMode.SelectedIndex < 0 && comboMeterTXMode.Items.Count > 0)
				{
					comboMeterTXMode.SelectedIndex = 0;
				}
			}
			if (flag != alexpresent)
			{
				AlexPresentChangedHandlers?.Invoke(flag, alexpresent);
			}
		}
	}

