	public PreampMode RX1PreampMode
	{
		get
		{
			return rx1_preamp_mode;
		}
		set
		{
			if (_from_preampmode[0])
			{
				return;
			}
			PreampMode preampMode = rx1_preamp_mode;
			rx1_preamp_mode = value;
			if (initializing)
			{
				if (preampMode != rx1_preamp_mode)
				{
					PreampModeChangedHandlers?.Invoke(1, preampMode, rx1_preamp_mode);
				}
				return;
			}
			if (!alexpresent && (rx1_preamp_mode == PreampMode.HPSDR_MINUS10 || rx1_preamp_mode == PreampMode.HPSDR_MINUS20 || rx1_preamp_mode == PreampMode.HPSDR_MINUS30 || rx1_preamp_mode == PreampMode.HPSDR_MINUS40 || rx1_preamp_mode == PreampMode.HPSDR_MINUS50))
			{
				rx1_preamp_mode = PreampMode.HPSDR_OFF;
			}
			alex_atten = 0;
			int rX1Preamp = 0;
			int num = 0;
			switch (rx1_preamp_mode)
			{
			case PreampMode.HPSDR_ON:
				num = 0;
				rX1Preamp = 1;
				alex_atten = 0;
				break;
			case PreampMode.HPSDR_OFF:
				num = 20;
				rX1Preamp = 0;
				alex_atten = 0;
				break;
			case PreampMode.HPSDR_MINUS10:
				num = 0;
				rX1Preamp = 1;
				alex_atten = 1;
				break;
			case PreampMode.HPSDR_MINUS20:
				num = 0;
				rX1Preamp = 1;
				alex_atten = 2;
				break;
			case PreampMode.HPSDR_MINUS30:
				num = 0;
				rX1Preamp = 1;
				alex_atten = 3;
				break;
			case PreampMode.HPSDR_MINUS40:
				num = 20;
				rX1Preamp = 0;
				alex_atten = 2;
				break;
			case PreampMode.HPSDR_MINUS50:
				num = 20;
				rX1Preamp = 0;
				alex_atten = 3;
				break;
			case PreampMode.SA_MINUS10:
				num = 10;
				rX1Preamp = 0;
				alex_atten = 0;
				break;
			case PreampMode.SA_MINUS20:
				num = 20;
				rX1Preamp = 0;
				alex_atten = 0;
				break;
			case PreampMode.SA_MINUS30:
				num = 30;
				rX1Preamp = 0;
				alex_atten = 0;
				break;
			}
			int DDCrx = -1;
			int DDCrx2 = -1;
			int DDCsync = -1;
			int DDCsync2 = -1;
			int DDCpsrx = -1;
			int DDCpstx = -1;
			GetDDC(out DDCrx, out DDCrx2, out DDCsync, out DDCsync2, out DDCpsrx, out DDCpstx);
			int aDCInUse = GetADCInUse(DDCrx);
			int aDCInUse2 = GetADCInUse(DDCrx2);
			if (HardwareSpecific.Model != HPSDRModel.HPSDR)
			{
				if (!_rx1_step_att_enabled)
				{
					switch (aDCInUse)
					{
					case 0:
						NetworkIO.SetADC1StepAttenData(num);
						break;
					case 1:
						NetworkIO.SetADC2StepAttenData(num);
						break;
					case 2:
						NetworkIO.SetADC3StepAttenData(num);
						break;
					}
				}
			}
			else
			{
				NetworkIO.SetRX1Preamp(rX1Preamp);
			}
			if (_rx1_step_att_enabled)
			{
				if (alexpresent && HardwareSpecific.Model != HPSDRModel.ANAN10 && HardwareSpecific.Model != HPSDRModel.ANAN10E && HardwareSpecific.Model != HPSDRModel.ANAN7000D && HardwareSpecific.Model != HPSDRModel.ANAN8000D && HardwareSpecific.Model != HPSDRModel.ORIONMKII && HardwareSpecific.Model != HPSDRModel.ANAN_G2E && HardwareSpecific.Model != HPSDRModel.ANAN_G2 && HardwareSpecific.Model != HPSDRModel.ANAN_G2_1K && HardwareSpecific.Model != HPSDRModel.ANVELINAPRO3 && HardwareSpecific.Model != HPSDRModel.REDPITAYA)
				{
					if (_rx1_attenuator_data <= 31)
					{
						NetworkIO.SetAlexAtten(0);
					}
					else
					{
						NetworkIO.SetAlexAtten(3);
					}
				}
				else
				{
					NetworkIO.SetAlexAtten(0);
				}
			}
			else
			{
				NetworkIO.SetAlexAtten(alex_atten);
			}
			rx1_preamp_by_band[(int)rx1_band] = rx1_preamp_mode;
			_from_preampmode[0] = true;
			switch (rx1_preamp_mode)
			{
			case PreampMode.HPSDR_ON:
				comboPreamp.Text = "0dB";
				break;
			case PreampMode.HPSDR_OFF:
				comboPreamp.Text = "-20dB";
				break;
			case PreampMode.HPSDR_MINUS10:
				comboPreamp.Text = "-10db";
				break;
			case PreampMode.HPSDR_MINUS20:
				comboPreamp.Text = "-20db";
				break;
			case PreampMode.HPSDR_MINUS30:
				comboPreamp.Text = "-30db";
				break;
			case PreampMode.HPSDR_MINUS40:
				comboPreamp.Text = "-40db";
				break;
			case PreampMode.HPSDR_MINUS50:
				comboPreamp.Text = "-50db";
				break;
			case PreampMode.SA_MINUS10:
				comboPreamp.Text = "-10dB";
				break;
			case PreampMode.SA_MINUS20:
				comboPreamp.Text = "-20dB";
				break;
			case PreampMode.SA_MINUS30:
				comboPreamp.Text = "-30dB";
				break;
			}
			_from_preampmode[0] = false;
			if (!_mox && !_setFromOtherAttenuator)
			{
				bool flag = m_bDiversityAttLinkForRX1andRX2 && diversityForm != null && Diversity2 && diversityForm.EXTDIVOutput == 2;
				if (((aDCInUse == aDCInUse2) | flag) && RX2PreampMode != rx1_preamp_mode)
				{
					_setFromOtherAttenuator = true;
					if (SetupForm.RX2EnableAtt != SetupForm.RX1EnableAtt)
					{
						SetupForm.RX2EnableAtt = SetupForm.RX1EnableAtt;
					}
					RX2PreampMode = rx1_preamp_mode;
					_setFromOtherAttenuator = false;
				}
			}
			if (chkSquelch.Checked)
			{
				ptbSquelch_Scroll(this, EventArgs.Empty);
			}
			if (!_mox)
			{
				update_preamp = true;
				UpdatePreamps();
			}
			UpdateRX1DisplayOffsets();
			if (preampMode != rx1_preamp_mode)
			{
				PreampModeChangedHandlers?.Invoke(1, preampMode, rx1_preamp_mode);
			}
			setATTGeneralSetting(1);
		}
	}

	public PreampMode RX2PreampMode
	{
		get
		{
			return rx2_preamp_mode;
		}
		set
		{
			if (_from_preampmode[1])
			{
				return;
			}
			PreampMode preampMode = rx2_preamp_mode;
			rx2_preamp_mode = value;
			if (initializing)
			{
				if (preampMode != rx2_preamp_mode)
				{
					PreampModeChangedHandlers?.Invoke(2, preampMode, rx2_preamp_mode);
				}
				return;
			}
			int rX2Preamp = 0;
			int num = 0;
			_from_preampmode[1] = true;
			switch (rx2_preamp_mode)
			{
			case PreampMode.HPSDR_ON:
				num = 0;
				rX2Preamp = 1;
				comboRX2Preamp.Text = "0dB";
				break;
			case PreampMode.HPSDR_OFF:
				num = 20;
				rX2Preamp = 0;
				comboRX2Preamp.Text = "-20dB";
				break;
			case PreampMode.HPSDR_MINUS10:
				num = 10;
				rX2Preamp = 1;
				comboRX2Preamp.Text = "-10db";
				break;
			case PreampMode.HPSDR_MINUS20:
				num = 20;
				rX2Preamp = 1;
				comboRX2Preamp.Text = "-20db";
				break;
			case PreampMode.HPSDR_MINUS30:
				num = 30;
				rX2Preamp = 1;
				comboRX2Preamp.Text = "-30db";
				break;
			case PreampMode.SA_MINUS10:
				num = 10;
				rX2Preamp = 0;
				comboRX2Preamp.Text = "-10dB";
				break;
			case PreampMode.SA_MINUS20:
				num = 20;
				rX2Preamp = 0;
				comboRX2Preamp.Text = "-20dB";
				break;
			case PreampMode.SA_MINUS30:
				num = 30;
				rX2Preamp = 0;
				comboRX2Preamp.Text = "-30dB";
				break;
			}
			_from_preampmode[1] = false;
			int DDCrx = -1;
			int DDCrx2 = -1;
			int DDCsync = -1;
			int DDCsync2 = -1;
			int DDCpsrx = -1;
			int DDCpstx = -1;
			GetDDC(out DDCrx, out DDCrx2, out DDCsync, out DDCsync2, out DDCpsrx, out DDCpstx);
			int aDCInUse = GetADCInUse(DDCrx);
			int aDCInUse2 = GetADCInUse(DDCrx2);
			if (!_rx2_step_att_enabled && (HardwareSpecific.Model == HPSDRModel.ANAN100D || HardwareSpecific.Model == HPSDRModel.ANAN200D || HardwareSpecific.Model == HPSDRModel.ORIONMKII || HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ANAN_G2E || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.REDPITAYA))
			{
				switch (aDCInUse2)
				{
				case 0:
					NetworkIO.SetADC1StepAttenData(num);
					break;
				case 1:
					NetworkIO.SetADC2StepAttenData(num);
					break;
				case 2:
					NetworkIO.SetADC3StepAttenData(num);
					break;
				}
			}
			if (HardwareSpecific.Model == HPSDRModel.HPSDR)
			{
				NetworkIO.SetRX2Preamp(rX2Preamp);
			}
			rx2_preamp_by_band[(int)rx2_band] = rx2_preamp_mode;
			if (!_mox && !_setFromOtherAttenuator)
			{
				bool flag = m_bDiversityAttLinkForRX1andRX2 && diversityForm != null && Diversity2 && diversityForm.EXTDIVOutput == 2;
				if (((aDCInUse == aDCInUse2) | flag) && RX1PreampMode != rx2_preamp_mode)
				{
					_setFromOtherAttenuator = true;
					if (SetupForm.RX1EnableAtt != SetupForm.RX2EnableAtt)
					{
						SetupForm.RX1EnableAtt = SetupForm.RX2EnableAtt;
					}
					RX1PreampMode = rx2_preamp_mode;
					_setFromOtherAttenuator = false;
				}
			}
			UpdateRX2DisplayOffsets();
			if (chkRX2Squelch.Checked)
			{
				ptbRX2Squelch_Scroll(this, EventArgs.Empty);
			}
			if (preampMode != rx2_preamp_mode)
			{
				PreampModeChangedHandlers?.Invoke(2, preampMode, rx2_preamp_mode);
			}
			setATTGeneralSetting(2);
		}
	}

