	public int DisplayFPS
	{
		get
		{
			return _display_fps;
		}
		set
		{
			int display_fps = _display_fps;
			_display_fps = value;
			if (_display_fps > 640)
			{
				_display_fps = 640;
			}
			if (_display_fps < 1)
			{
				_display_fps = 1;
			}
			_display_delay = 1000f / (float)_display_fps;
			Display.CurrentFPS = _display_fps;
			Display.TargetFPS = _display_fps;
			int frameRate = (int)Math.Max(1f, (float)_display_fps * 1.1f);
			specRX.GetSpecRX(0).FrameRate = frameRate;
			specRX.GetSpecRX(1).FrameRate = frameRate;
			specRX.GetSpecRX(cmaster.inid(1, 0)).FrameRate = frameRate;
			if (display_fps != _display_fps)
			{
				FSPChangedHandlers?.Invoke(display_fps, _display_fps);
			}
		}
	}

