	public bool PAPresent
	{
		get
		{
			return pa_present;
		}
		set
		{
			bool flag = pa_present;
			pa_present = value;
			if (pa_present || alexpresent)
			{
				if (comboMeterTXMode.SelectedIndex < 0)
				{
					comboMeterTXMode.SelectedIndex = 0;
				}
			}
			else
			{
				string text = comboMeterTXMode.Text;
				comboMeterTXMode.Text = text;
				if (comboMeterTXMode.SelectedIndex < 0 && comboMeterTXMode.Items.Count > 0)
				{
					comboMeterTXMode.SelectedIndex = 0;
				}
			}
			ptbPWR_Scroll(this, EventArgs.Empty);
			if (flag != pa_present)
			{
				PAPresentChangedHandlers?.Invoke(flag, pa_present);
			}
		}
	}

