	public bool TNFActive
	{
		get
		{
			return chkTNF.Checked;
		}
		set
		{
			if (value != chkTNF.Checked)
			{
				chkTNF.Checked = value;
				return;
			}
			bool tNFActive = Display.TNFActive;
			Display.TNFActive = value;
			WDSP.RXANBPSetNotchesRun(WDSP.id(0u, 0u), value);
			WDSP.RXANBPSetNotchesRun(WDSP.id(0u, 1u), value);
			WDSP.RXANBPSetNotchesRun(WDSP.id(2u, 0u), value);
			if (tNFActive != value)
			{
				TNFChangedHandlers?.Invoke(tNFActive, value);
			}
		}
	}

