			if (value == PAstatusIndicatorState.NotUsed)
			{
				toolStripStatusLabel_PAstatus.Visible = false;
				_ganymede_pa_issue = false;
				return;
			}
			toolStripStatusLabel_PAstatus.Visible = true;
			toolStripStatusLabel_PAstatus.ToolTipText = GetPAStatusText(value);
			PAstatusIndicatorState pAstatusIndicatorState = PAstatusIndicatorState.PSUVoltage | PAstatusIndicatorState.DrainCurrent | PAstatusIndicatorState.ReversePower | PAstatusIndicatorState.HeatsinkTemperature | PAstatusIndicatorState.ForwardPower | PAstatusIndicatorState.Resettable;
			PAstatusIndicatorState pAstatusIndicatorState2 = value & pAstatusIndicatorState;
			if ((value & PAstatusIndicatorState.OK) != PAstatusIndicatorState.NotUsed || pAstatusIndicatorState2 == PAstatusIndicatorState.NotUsed)
			{
				toolStripStatusLabel_PAstatus.Width = Resources.paok.Width;
				toolStripStatusLabel_PAstatus.Image = Resources.paok;
			}
			else
			{
				toolStripStatusLabel_PAstatus.Width = Resources.paflt.Width;
				toolStripStatusLabel_PAstatus.Image = Resources.paflt;
			}
		}
	}

