	private void SetAriesTXFrequency(double NewFrequency)
	{
		double num = Math.Truncate(NewFrequency * 100.0);
		if (Math.Abs(num - AriesReportedFrequency_10KHz) == 0.0)
		{
			return;
		}
		AriesReportedFrequency_10KHz = num;
		AriesTuneState = false;
		string text = (num / 100.0).ToString("f6");
		string text2 = "ZZFT" + text.Replace(separator, "").PadLeft(11, '0') + ";";
		if (AriesPresent)
		{
			if (AriesCATEnabled)
			{
				try
				{
					AriesSiolisten.SIO6.put(text2);
				}
				catch
				{
				}
			}
			else
			{
				SendAriesMsgViaTCPIPcat(text2);
			}
		}
		CheckAriesEnabled();
		UpdateAriesDisplayLabel();
	}

	public void SetAriesTXAntenna(int Antenna, Band band)
