	public Band AntennaBandFromFreq(bool IsTX)
	{
		double freq = 0.0;
		freq = ((RX1XVTRIndex < 0) ? VFOAFreq : XVTRForm.TranslateFreq(freq));
		if (freq >= 12.075)
		{
			if (freq >= 23.17)
			{
				if (freq >= 26.465)
				{
					return (freq >= 39.85) ? Band.B6M : Band.B10M;
				}
				return Band.B12M;
			}
			if (freq >= 16.209)
			{
				return (freq >= 19.584) ? Band.B15M : Band.B17M;
			}
			return Band.B20M;
		}
		if (freq >= 6.20175)
		{
			return (freq >= 8.7) ? Band.B30M : Band.B40M;
		}
		if (freq >= 4.66525)
		{
			return Band.B60M;
		}
		return (!(freq >= 2.75)) ? Band.B160M : Band.B80M;
	}

	private void DisplayAriesTXAntenna()
	{
		Band band = TXBand;
		if (band < Band.B160M || band > Band.B6M)
		{
			band = AntennaBandFromFreq(IsTX: true);
		}
		int num = (int)(band - 1);
		if (num < 12 && num >= 0)
		{
			int num2 = AntennaArrayByBand[num];
			if (num2 != TXAntennaSent)
			{
				toolStripStatusLabelTXAnt.Text = "Tx Ant " + num2;
				TXAntennaSent = num2;
			}
		}
	}

	private void SendAriesRXAntennaMsg()
	{
		if (chkRxAnt.Checked)
		{
			Band band = TXBand;
			if (band < Band.B160M || band > Band.B6M)
			{
				band = AntennaBandFromFreq(IsTX: true);
			}
			int num = (int)(band - 1);
			if (num < 12 && num >= 0)
			{
				int ant = AntennaArrayByBand[num];
				MakeAriesRXAntennaChangeMsg(ant);
			}
		}
		else
		{
			Band band = RX1Band;
			if (band < Band.B160M || band > Band.B6M)
			{
				band = AntennaBandFromFreq(IsTX: false);
			}
			int num2 = (int)(band - 1);
			if (num2 < 12 && num2 >= 0)
			{
				int ant = RXAntennaArrayByBand[num2];
				MakeAriesRXAntennaChangeMsg(ant);
			}
		}
	}

	private void DisplayAriesRXAntenna()
	{
		string text = "RX";
		Band band = RX1Band;
		if (band < Band.B160M || band > Band.B6M)
		{
			band = AntennaBandFromFreq(IsTX: false);
		}
		int num = (int)(band - 1);
		if (num >= 12 || num < 0)
		{
			return;
		}
		int num2 = RXAntennaArrayByBand[num];
		SendAriesRXAntennaMsg();
		if (RXAuxAntennaArrayByBand[num])
		{
			switch (RXAntennaNameArrayByBand[num])
			{
			case "RX1":
				text = "X1";
				break;
			case "RX2":
				text = "X2";
				break;
			case "XVTR":
				text = "XV";
				break;
			case "EXT1":
				text = "X1";
				break;
			case "EXT2":
				text = "X2";
				break;
			case "BYPS":
				text = "BP";
				break;
			}
		}
		else
		{
			text = "Rx Ant " + num2;
		}
		if (text != RXAntennaSentString)
		{
			toolStripStatusLabelRXAnt.Text = text;
			RXAntennaSentString = text;
		}
	}

	private void TXAntennaStep()
	{
		if (TXBand != RX1Band)
		{
			return;
		}
		int num = (int)(TXBand - 1);
		if (num >= 12 || num < 0)
		{
			return;
		}
		int num2 = AntennaArrayByBand[num];
		int num3 = num2;
		switch (num2)
		{
		case 1:
			if (!AlexANT2RXOnly)
			{
				num3 = 2;
			}
			else if (!AlexANT3RXOnly)
			{
				num3 = 3;
			}
			break;
		case 2:
			num3 = (AlexANT3RXOnly ? 1 : 3);
			break;
		default:
			num3 = 1;
			break;
		}
		if (SetupForm != null && num3 != num2)
		{
			SetupForm.SetRXAntenna(num3, TXBand);
			SetupForm.SetTXAntenna(num3, TXBand);
		}
	}

