	private void CheckAriesEnabled()
	{
		int num = 0;
		bool flag = false;
		if (TXBand <= Band.B6M && TXBand >= Band.B160M)
		{
			int num2 = (int)(TXBand - 1);
			num = AntennaArrayByBand[num2];
			switch (num)
			{
			case 0:
				flag = false;
				break;
			case 1:
				flag = aries_ant1_enabled;
				break;
			case 2:
				flag = aries_ant2_enabled;
				break;
			case 3:
				flag = aries_ant3_enabled;
				break;
			}
		}
		if (flag != AriesEnabled)
		{
			MakeAriesATUEnableRequestMsg(flag);
			AndromedaIndicatorCheck(EIndicatorActions.eINATUReady, IsRX1: false, AriesEnabled);
		}
		if (num != AriesAntenna)
		{
			MakeAriesAntennaChangeMsg(num);
		}
		SendAriesRXAntennaMsg();
	}

	private void SetAriesAlexMode(bool state)
	{
		Alex.getAlex().SetAntennasTo1(state);
		if (rx1_xvtr_index >= 0)
		{
			Band band = BandByFreq(XVTRForm.TranslateFreq(VFOAFreq), rx1_xvtr_index, current_region);
			Alex.getAlex().UpdateAlexAntSelection(band, _mox, alex_ant_ctrl_enabled, xvtr: true);
		}
		else
		{
			Alex.getAlex().UpdateAlexAntSelection(RX1Band, _mox, alex_ant_ctrl_enabled, xvtr: false);
		}
	}

	private void InitialiseAries()
	{
		AriesEnabled = false;
		AriesAntenna = 0;
		AriesTuneState = false;
		MakeAriesVersionRequestMsg();
		CheckAriesEnabled();
		MakeAriesATUEnableRequestMsg(AriesEnabled);
		MakeAriesQuickTuneRequestMsg(AriesQuickTuneEnabled);
		UpdateAriesDisplayLabel();
		SetAriesAlexMode(aries_standalone);
	}

	private void TweakAriesCapacitance(int Steps)
	{
		MakeAriesATUTuneTweakMsg(IsInductance: false, Steps);
	}

	private void TweakAriesInductance(int Steps)
	{
		MakeAriesATUTuneTweakMsg(IsInductance: true, Steps);
	}

	private void MakeAriesATUTuneTweakMsg(bool IsInductance, int TweakSteps)
	{
		string text = "ZZZE";
		int num;
		if (TweakSteps >= 0)
		{
			num = 10;
		}
		else
		{
			num = 510;
			TweakSteps = -TweakSteps;
		}
		if (!IsInductance)
		{
			num += 10;
		}
		if (TweakSteps <= 9)
		{
			num += TweakSteps;
		}
		text += num.ToString("D3");
		text += ";";
		if (!AriesPresent)
		{
			return;
		}
		if (AriesCATEnabled)
		{
			try
			{
				AriesSiolisten.SIO6.put(text);
				return;
			}
			catch
			{
				return;
			}
		}
		SendAriesMsgViaTCPIPcat(text);
	}

	private void SendGanymedeMsgViaTCPIPcat(string message)
	{
		if (m_tcpCATServer != null)
		{
