	}

	public static string GetPAStatusText(PAstatusIndicatorState state)
	{
		if (state == PAstatusIndicatorState.NotUsed)
		{
			return "Not Used";
		}
		if ((state & PAstatusIndicatorState.OK) != PAstatusIndicatorState.NotUsed)
		{
			return "Normal operation";
		}
		PAstatusIndicatorState pAstatusIndicatorState = PAstatusIndicatorState.PSUVoltage | PAstatusIndicatorState.DrainCurrent | PAstatusIndicatorState.ReversePower | PAstatusIndicatorState.HeatsinkTemperature | PAstatusIndicatorState.ForwardPower | PAstatusIndicatorState.Resettable;
		PAstatusIndicatorState pAstatusIndicatorState2 = state & pAstatusIndicatorState;
		if (pAstatusIndicatorState2 == PAstatusIndicatorState.NotUsed)
		{
			return "Normal operation";
		}
		StringBuilder stringBuilder = new StringBuilder(64);
		stringBuilder.Append("TRIP Excess: ");
		if ((pAstatusIndicatorState2 & PAstatusIndicatorState.ReversePower) != PAstatusIndicatorState.NotUsed)
		{
			stringBuilder.Append("Reverse Power ");
		}
		if ((pAstatusIndicatorState2 & PAstatusIndicatorState.DrainCurrent) != PAstatusIndicatorState.NotUsed)
		{
			stringBuilder.Append("Drain Current ");
		}
		if ((pAstatusIndicatorState2 & PAstatusIndicatorState.PSUVoltage) != PAstatusIndicatorState.NotUsed)
		{
			stringBuilder.Append("PSU Voltage ");
		}
		if ((pAstatusIndicatorState2 & PAstatusIndicatorState.HeatsinkTemperature) != PAstatusIndicatorState.NotUsed)
		{
			stringBuilder.Append("Heatsink Temperature ");
		}
		if ((pAstatusIndicatorState2 & PAstatusIndicatorState.ForwardPower) != PAstatusIndicatorState.NotUsed)
		{
			stringBuilder.Append("Forward Power ");
		}
		if ((pAstatusIndicatorState2 & PAstatusIndicatorState.Resettable) != PAstatusIndicatorState.NotUsed)
		{
			stringBuilder.Append("\n Awaiting RESET ");
		}
		string text = stringBuilder.ToString();
		if (text.StartsWith("\n "))
		{
			text = text.Substring(2);
		}
		return text.TrimEnd(' ');
	}

	public void CATHandleAmplifierTripMessage(int TripState)
	{
		GanymedePresent = true;
		_ganymede_pa_issue = TripState != 0;
		if (_ganymede_pa_issue && MOX)
		{
			MOX = false;
		}
		switch (TripState)
		{
		case 0:
			PAStatusIndicator = PAstatusIndicatorState.OK;
			break;
		case 1:
			PAStatusIndicator = PAstatusIndicatorState.ReversePower;
			break;
		case 2:
			PAStatusIndicator = PAstatusIndicatorState.DrainCurrent;
			break;
		case 4:
			PAStatusIndicator = PAstatusIndicatorState.PSUVoltage;
			break;
		case 8:
			PAStatusIndicator = PAstatusIndicatorState.HeatsinkTemperature;
			break;
		case 16:
			PAStatusIndicator = PAstatusIndicatorState.ForwardPower;
			break;
		case 64:
			PAStatusIndicator = PAstatusIndicatorState.Resettable;
			break;
		}
		SetupForm.GanymedeStatus = GetPAStatusText(PAStatusIndicator);
	}

	public void GanymedeResetPressed()
	{
		string text = "ZZZA32;";
		if (!GanymedePresent)
		{
			return;
		}
		if (GanymedeCATEnabled)
		{
			try
			{
				GanymedeSiolisten.SIO7.put(text);
				return;
			}
			catch
			{
				return;
			}
		}
		SendGanymedeMsgViaTCPIPcat(text);
	}

