	private void SaveAndromedaDataset()
	{
		string fileName = AppDataPath + "andromedadata.xml";
		AndromedaSet.WriteXml(fileName, XmlWriteMode.WriteSchema);
		InitialiseAndromedaIndicators(InitialiseAll: true);
		currentButtonBarMenu = 0;
		UpdateButtonBarButtons();
	}

	public void ResetAndromedaDataset()
	{
		AndromedaSet.Tables.Clear();
		MakeNewAndromedaDataset();
		SaveAndromedaDataset();
		InitialiseAndromedaIndicators(InitialiseAll: true);
	}

	public void ResetG2PanelDataset()
	{
		AndromedaSet.Tables.Clear();
		MakeNewG2PanelDataset();
		SaveAndromedaDataset();
		InitialiseAndromedaIndicators(InitialiseAll: true);
	}

	private void AndromedaIndicatorCheck(EIndicatorActions IndicatorType, bool IsRX1, bool State)
	{
		if (!AndromedaCATEnabled && !G2V2PanelPresent)
		{
			return;
		}
		bool flag = true;
		DataTable dataTable = AndromedaSet.Tables["Indicators"];
		int count = dataTable.Rows.Count;
		for (int i = 0; i < count; i++)
		{
			if ((EIndicatorActions)dataTable.Rows[i]["Indicator Action"] == IndicatorType)
			{
				switch ((int)dataTable.Rows[i]["Indicator RX Selector"])
				{
				case 1:
					flag = show_rx1 == IsRX1;
					break;
				case 2:
					flag = IsRX1;
					break;
				case 3:
					flag = !IsRX1;
					break;
				}
				if (flag)
				{
					MakeIndicatorCATMsg(i + 1, State);
				}
			}
		}
	}

	private void MakeAndromedaVersionRequestMsg()
	{
		string s = "ZZZS;";
		if (AndromedaCATEnabled)
		{
			try
			{
				AndromedaSiolisten.SIO5.put(s);
			}
			catch
			{
			}
		}
	}

	private void MakeIndicatorCATMsg(int IndicatorNumber, bool State)
	{
		string text = "ZZZI";
		text += IndicatorNumber.ToString("D2");
		text = ((!State) ? (text + "0;") : (text + "1;"));
		if (AndromedaCATEnabled)
		{
			try
			{
				AndromedaSiolisten.SIO5.put(text);
				return;
			}
			catch
			{
				return;
			}
		}
		if (G2V2PanelPresent)
		{
			SendG2V2PanelMsgViaTCPIPcat(text);
		}
	}

	private void InitialiseAndromedaIndicators(bool InitialiseAll)
	{
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		if (!AndromedaCATEnabled && !G2V2PanelPresent)
		{
			return;
		}
		DataTable dataTable = AndromedaSet.Tables["Indicators"];
		int count = dataTable.Rows.Count;
		for (int i = 0; i < count; i++)
		{
			flag3 = false;
			EIndicatorActions eIndicatorActions = (EIndicatorActions)dataTable.Rows[i]["Indicator Action"];
			switch ((int)dataTable.Rows[i]["Indicator RX Selector"])
			{
			case 1:
				flag = show_rx1;
				flag3 = true;
				break;
			case 2:
				flag = true;
				break;
			case 3:
				flag = false;
				break;
			}
			switch (eIndicatorActions)
			{
			case EIndicatorActions.eINNone:
				flag2 = false;
				break;
			case EIndicatorActions.eINMOX:
				flag2 = chkMOX.Checked;
				break;
			case EIndicatorActions.eINTune:
				flag2 = chkTUN.Checked;
				break;
			case EIndicatorActions.eINRIT:
				flag2 = chkRIT.Checked;
				break;
			case EIndicatorActions.eINXIT:
				flag2 = chkXIT.Checked;
				break;
			case EIndicatorActions.eINSplit:
				flag2 = chkVFOSplit.Checked;
				break;
			case EIndicatorActions.eINCTune:
				flag2 = ((!flag) ? chkX2TR.Checked : chkFWCATU.Checked);
				break;
			case EIndicatorActions.eINVFOSync:
				flag2 = chkVFOSync.Checked;
				break;
			case EIndicatorActions.eINVFOAB:
				flag2 = show_rx1;
				break;
			case EIndicatorActions.eINVFOLock:
				flag2 = ((!flag) ? chkVFOBLock.Checked : chkVFOLock.Checked);
				break;
			case EIndicatorActions.eINNB:
				flag2 = ((!flag) ? chkRX2NB.Checked : chkNB.Checked);
				break;
			case EIndicatorActions.eINNR:
				flag2 = ((!flag) ? (_nr_selected[1] > 0) : (_nr_selected[0] > 0));
				break;
			case EIndicatorActions.eINSNB:
				flag2 = ((!flag) ? chkRX2NB2.Checked : chkDSPNB2.Checked);
				break;
			case EIndicatorActions.eINANF:
				flag2 = ((!flag) ? chkRX2ANF.Checked : chkANF.Checked);
				break;
			case EIndicatorActions.eINSquelch:
				flag2 = ((!flag) ? chkRX2Squelch.Checked : chkSquelch.Checked);
				break;
			case EIndicatorActions.eINCompanderEnabled:
				flag2 = chkCPDR.Checked;
				break;
			case EIndicatorActions.eINPuresignalEnabled:
				flag2 = chkFWCATUBypass.Checked;
				break;
			case EIndicatorActions.eINDiversityEnabled:
				flag2 = Diversity2;
				break;
			case EIndicatorActions.eINATUReady:
				flag2 = AriesEnabled;
				break;
			case EIndicatorActions.eINShiftEnabled:
				flag2 = AndromedaBandButtonsEnabled;
				break;
			}
			if ((InitialiseAll | flag3) && eIndicatorActions != EIndicatorActions.eINNone)
			{
				MakeIndicatorCATMsg(i + 1, flag2);
			}
		}
	}

