	public void HandleFrontPanelEncoderStep(int Encoder, int Steps)
	{
		int num = 0;
		bool flag = false;
		EEncoderActions eEncoderActions = EEncoderActions.eENNoAction;
		DataTable dataTable = AndromedaSet.Tables["Encoders"];
		int count = dataTable.Rows.Count;
		if (!AndromedaCATEnabled && !AndromedaG2Enabled)
		{
			return;
		}
		if (andromedaEditorForm != null && andromedaEditorForm.AndromedaEditorVisible)
		{
			andromedaEditorForm.SetEncoderNumber(Encoder);
			flag = true;
		}
		if (Encoder < 0 || Encoder >= count || flag)
		{
			return;
		}
		eEncoderActions = (EEncoderActions)dataTable.Rows[Encoder]["Encoder Action"];
		num = (int)dataTable.Rows[Encoder]["Encoder RX Selector"];
		if (eEncoderActions == EEncoderActions.eENMulti)
		{
			DataTable dataTable2 = AndromedaSet.Tables["Multifunction Settings"];
			int count2 = dataTable2.Rows.Count;
			if (AndromedaMultiEncoderState)
			{
				EncoderUpdate(Steps, ref CurrentMultifunctionOption, 0, count2 - 1);
				toolStripStatusLabelAndromedaMulti.Text = dataTable2.Rows[CurrentMultifunctionOption]["Multi Description"].ToString();
			}
			else
			{
				eEncoderActions = (EEncoderActions)dataTable2.Rows[CurrentMultifunctionOption]["Multi Action"];
				num = (int)dataTable2.Rows[CurrentMultifunctionOption]["Multi RX Selector"];
			}
		}
		if (eEncoderActions != EEncoderActions.eENMulti)
		{
			ExecuteEncoderStep(eEncoderActions, Steps, num);
		}
	}

	public void HandleFrontPanelVFOEncoderStep(int Steps)
	{
		if (!AndromedaG2Enabled && !AndromedaCATEnabled)
		{
			return;
		}
		if (!IsSetupFormNull && SetupForm.AndromedaFastTune)
		{
			Steps = CalculateFastTuneSteps(Steps);
		}
		if (show_rx1)
		{
			if (RX1DSPMode == DSPMode.FM)
			{
				FMSteps += Steps;
				Steps = FMSteps / 24;
				FMSteps %= 24;
			}
			VFOAFreq = CATVFOA + (double)Steps * (double)TuneStepList[TuneStepIndex].StepHz * 1E-06;
		}
		else
		{
			if (RX2DSPMode == DSPMode.FM)
			{
				FMSteps += Steps;
				Steps = FMSteps / 24;
				FMSteps %= 24;
			}
			VFOBFreq = CATVFOB + (double)Steps * (double)TuneStepList[TuneStepIndex].StepHz * 1E-06;
		}
	}

	private int CalculateFastTuneSteps(int RawSteps)
	{
		int num = 0;
		int num2 = ((RawSteps <= 0) ? (-RawSteps) : RawSteps);
		double num3 = 0.8 * (double)num2 + 0.04 * (double)num2 * (double)num2 + 0.005 * (double)num2 * (double)num2 * (double)num2;
		if (num3 > 200.0)
		{
			num3 = 200.0;
		}
		num = (int)(num3 + 0.5);
		if (RawSteps < 0)
		{
			num = -num;
		}
		return num;
	}

	public void HandleFrontPanelButtonPress(int Button, bool State, bool LongPress)
	{
		Band cATBand = Band.B160M;
		string sBand = "";
		DataTable dataTable = AndromedaSet.Tables["Pushbuttons"];
		int count = dataTable.Rows.Count;
		bool flag = false;
		if (!AndromedaG2Enabled && !AndromedaCATEnabled)
		{
			return;
		}
		if (andromedaEditorForm != null && andromedaEditorForm.AndromedaEditorVisible)
		{
			andromedaEditorForm.SetPushbuttonNumber(Button);
			flag = true;
		}
		if (flag)
		{
			return;
		}
		if (andromeda_g2_enabled)
		{
			if (LongPress)
			{
				EButtonBarActions assignedAction = (EButtonBarActions)dataTable.Rows[Button]["Pushbutton Action"];
				int overrideRX = (int)dataTable.Rows[Button]["Pushbutton RX Selector"];
				ExecuteButtonLongpress(assignedAction, overrideRX);
			}
			else if (State)
			{
				EButtonBarActions assignedAction = (EButtonBarActions)dataTable.Rows[Button]["Pushbutton Action"];
				int overrideRX = (int)dataTable.Rows[Button]["Pushbutton RX Selector"];
				ExecuteButtonAction(assignedAction, overrideRX);
			}
		}
		else if (Button >= 29 && Button <= 40)
		{
			if (LongPress)
			{
				EButtonBarActions assignedAction = (EButtonBarActions)dataTable.Rows[Button]["Pushbutton Action"];
				int overrideRX = (int)dataTable.Rows[Button]["Pushbutton RX Selector"];
				ExecuteButtonLongpress(assignedAction, overrideRX);
			}
			else
			{
				if (!State)
				{
					return;
				}
				if (AndromedaBandButtonsEnabled)
				{
					switch (Button)
					{
					case 29:
						sBand = "160m";
						cATBand = Band.B160M;
						break;
					case 30:
						sBand = "80m";
						cATBand = Band.B80M;
						break;
					case 31:
						sBand = "60m";
						cATBand = Band.B60M;
						break;
					case 32:
						sBand = "40m";
						cATBand = Band.B40M;
						break;
					case 33:
						sBand = "30m";
						cATBand = Band.B30M;
						break;
					case 34:
						sBand = "20m";
						cATBand = Band.B20M;
						break;
					case 35:
						sBand = "17m";
						cATBand = Band.B17M;
						break;
					case 36:
						sBand = "15m";
						cATBand = Band.B15M;
						break;
					case 37:
						sBand = "12m";
						cATBand = Band.B12M;
						break;
					case 38:
						sBand = "10m";
						cATBand = Band.B10M;
						break;
					case 39:
						sBand = "6m";
						cATBand = Band.B6M;
						break;
					case 40:
						sBand = "GEN";
						cATBand = Band.GEN;
						break;
					}
					if (show_rx1)
					{
						SetCATBand(cATBand);
					}
					else
					{
						SetupRX2Band(sBand);
					}
				}
				else
				{
					EButtonBarActions assignedAction = (EButtonBarActions)dataTable.Rows[Button]["Pushbutton Action"];
					int overrideRX = (int)dataTable.Rows[Button]["Pushbutton RX Selector"];
					ExecuteButtonAction(assignedAction, overrideRX);
				}
				if (!AndromedaStickyShift)
				{
					if (AndromedaBandButtonIsDefault)
					{
						AndromedaBandButtonsEnabled = true;
					}
					else
					{
						AndromedaBandButtonsEnabled = false;
					}
					AndromedaIndicatorCheck(EIndicatorActions.eINShiftEnabled, IsRX1: false, AndromedaBandButtonsEnabled);
				}
			}
		}
		else
		{
			if (Button < 0 || Button >= count)
			{
				return;
			}
			EButtonBarActions assignedAction = (EButtonBarActions)dataTable.Rows[Button]["Pushbutton Action"];
			int overrideRX = (int)dataTable.Rows[Button]["Pushbutton RX Selector"];
			if (assignedAction == EButtonBarActions.eBBMenuButton && State)
			{
				switch (overrideRX)
				{
				case 0:
				case 11:
					btnAndrBar1_Click(null, null);
					break;
				case 1:
				case 12:
					btnAndrBar2_Click(null, null);
					break;
				case 2:
				case 13:
					btnAndrBar3_Click(null, null);
					break;
				case 3:
				case 14:
					btnAndrBar4_Click(null, null);
					break;
				case 4:
				case 15:
					btnAndrBar5_Click(null, null);
					break;
				case 5:
				case 16:
					btnAndrBar6_Click(null, null);
					break;
				case 6:
				case 17:
					btnAndrBar7_Click(null, null);
					break;
				case 7:
				case 18:
					btnAndrBar8_Click(null, null);
					break;
				case 8:
				case 9:
				case 10:
					break;
				}
			}
			else if (State)
			{
				ExecuteButtonAction(assignedAction, overrideRX);
			}
			else if (LongPress)
			{
				ExecuteButtonLongpress(assignedAction, overrideRX);
			}
		}
	}

	public void MakeAttachedVersionString(int Product, int HardwareVersion, int SoftwareVersion)
	{
		switch (Product)
		{
		case 1:
		{
			string text = "Andromeda: h/w=" + HardwareVersion;
			text = text + "  s/w=" + SoftwareVersion;
			if (!IsSetupFormNull)
			{
				SetupForm.AndromedaVersionNumber = text;
			}
			InitialiseAndromedaIndicators(InitialiseAll: true);
			break;
		}
		case 2:
		{
			AriesPresent = true;
			string text = "Aries: h/w=" + HardwareVersion;
			text = text + "  s/w=" + SoftwareVersion;
			if (!IsSetupFormNull)
			{
				SetupForm.AriesVersionNumber = text;
			}
			InitialiseAries();
			break;
		}
		case 3:
		{
			GanymedePresent = true;
			string text = "Ganymede: h/w=" + HardwareVersion;
			text = text + "  s/w=" + SoftwareVersion;
			if (!IsSetupFormNull)
			{
				SetupForm.GanymedeVersionNumber = text;
			}
			InitialiseGanymede();
			break;
		}
		case 4:
		{
			string text = "G2 panel: h/w=" + HardwareVersion;
			text = text + "  s/w=" + SoftwareVersion;
			if (!IsSetupFormNull)
			{
				SetupForm.AndromedaVersionNumber = text;
			}
			break;
		}
		case 5:
		{
			G2V2PanelPresent = true;
			string text = "G2V2 panel: h/w=" + HardwareVersion;
			text = text + "  s/w=" + SoftwareVersion;
			if (!IsSetupFormNull)
			{
				SetupForm.AndromedaVersionNumber = text;
			}
			InitialiseAndromedaIndicators(InitialiseAll: true);
			break;
		}
		}
	}

	private void ExecuteEncoderStep(EEncoderActions Action, int Steps, int OverrideRX)
	{
		bool flag = false;
		bool flag2 = false;
		switch (OverrideRX)
		{
		case 0:
			flag = show_rx1;
			break;
		case 3:
			flag2 = true;
			break;
		case 1:
			flag = true;
			break;
		default:
			flag = false;
			break;
		}
		switch (Action)
		{
		case EEncoderActions.eENMasterGain:
		{
			int Value = AF;
			EncoderUpdate(Steps, ref Value, ptbAF.Minimum, ptbAF.Maximum);
			AF = Value;
			CheckGainFormAutoShow();
			break;
		}
		case EEncoderActions.eENAFGain:
			if (flag2)
			{
				int Value = RX1Gain;
				EncoderUpdate(Steps, ref Value, ptbRX1Gain.Minimum, ptbRX1Gain.Maximum);
				RX1Gain = Value;
				ShowAndromedaSlider(Value, ptbRX1Gain.Minimum, ptbRX1Gain.Maximum, "Sub RX AF");
			}
			else if (flag)
			{
				int Value = RX0Gain;
				EncoderUpdate(Steps, ref Value, ptbRX0Gain.Minimum, ptbRX0Gain.Maximum);
				RX0Gain = Value;
				ShowAndromedaSlider(Value, ptbRX0Gain.Minimum, ptbRX0Gain.Maximum, "RX1 AF");
			}
			else
			{
				int Value = RX2Gain;
				EncoderUpdate(Steps, ref Value, ptbRX2Gain.Minimum, ptbRX2Gain.Maximum);
				RX2Gain = Value;
				ShowAndromedaSlider(Value, ptbRX2Gain.Minimum, ptbRX2Gain.Maximum, "RX2 AF");
			}
			CheckGainFormAutoShow();
			break;
		case EEncoderActions.eENStereoBalance:
			if (flag2)
			{
				int Value = PanSubRX;
				EncoderUpdate(Steps, ref Value, ptbPanSubRX.Minimum, ptbPanSubRX.Maximum);
				ShowAndromedaSlider(Value, ptbPanSubRX.Minimum, ptbPanSubRX.Maximum, "Sub RX balance");
				PanSubRX = Value;
			}
			else if (flag)
			{
				int Value = PanMainRX;
				EncoderUpdate(Steps, ref Value, ptbPanMainRX.Minimum, ptbPanMainRX.Maximum);
				ShowAndromedaSlider(Value, ptbPanMainRX.Minimum, ptbPanMainRX.Maximum, "RX1 balance");
				PanMainRX = Value;
			}
			else
			{
				int Value = RX2Pan;
				EncoderUpdate(Steps, ref Value, ptbRX2Pan.Minimum, ptbRX2Pan.Maximum);
				ShowAndromedaSlider(Value, ptbRX2Pan.Minimum, ptbRX2Pan.Maximum, "RX2 balance");
				RX2Pan = Value;
			}
			CheckGainFormAutoShow();
			break;
		case EEncoderActions.eENAGCLevel:
			if (flag)
			{
				int Value = RF;
				EncoderUpdate(Steps, ref Value, ptbRF.Minimum, ptbRF.Maximum);
				ShowAndromedaSlider(Value, ptbRF.Minimum, ptbRF.Maximum, "RX1 AGC");
				if (Value != RF && AutoAGCRX1)
				{
					AutoAGCRX1 = false;
				}
				RF = Value;
			}
			else
			{
				int Value = RX2RF;
				EncoderUpdate(Steps, ref Value, ptbRX2RF.Minimum, ptbRX2RF.Maximum);
				ShowAndromedaSlider(Value, ptbRX2RF.Minimum, ptbRX2RF.Maximum, "RX2 AGC");
				if (Value != RX2RF && AutoAGCRX2)
				{
					AutoAGCRX2 = false;
				}
				RX2RF = Value;
			}
			CheckGainFormAutoShow();
			break;
		case EEncoderActions.eENStepAtten:
			if (flag)
			{
				int Value = SetupForm.ATTOnRX1;
				EncoderUpdate(Steps, ref Value, (int)udRX1StepAttData.Minimum, (int)udRX1StepAttData.Maximum);
				ShowAndromedaSlider(Value, (int)udRX1StepAttData.Minimum, (int)udRX1StepAttData.Maximum, "RX1 ATT");
				SetupForm.ATTOnRX1 = Value;
			}
			else
			{
				int Value = SetupForm.ATTOnRX2;
				EncoderUpdate(Steps, ref Value, (int)udRX2StepAttData.Minimum, (int)udRX2StepAttData.Maximum);
				ShowAndromedaSlider(Value, (int)udRX2StepAttData.Minimum, (int)udRX2StepAttData.Maximum, "RX2 ATT");
				SetupForm.ATTOnRX2 = Value;
			}
			CheckGainFormAutoShow();
			break;
		case EEncoderActions.eENFilterHigh:
			if (flag)
			{
				DSPMode rX1DSPMode = RX1DSPMode;
				int num = ((rX1DSPMode != DSPMode.CWL && rX1DSPMode != DSPMode.CWU) ? 50 : 10);
				SelectRX1VarFilter();
				if (rX1DSPMode == DSPMode.LSB || rX1DSPMode == DSPMode.CWL || rX1DSPMode == DSPMode.DIGL)
				{
					int Value = RX1FilterLow;
					EncoderUpdate(Steps * -num, ref Value, (int)udFilterLow.Minimum, (int)udFilterLow.Maximum);
					RX1FilterLow = Value;
				}
				else
				{
					int Value = RX1FilterHigh;
					EncoderUpdate(Steps * num, ref Value, (int)udFilterHigh.Minimum, (int)udFilterHigh.Maximum);
					RX1FilterHigh = Value;
				}
				UpdateRX1Filters(RX1FilterLow, RX1FilterHigh);
			}
			else
			{
				DSPMode rX1DSPMode = RX2DSPMode;
				int num = ((rX1DSPMode != DSPMode.CWL && rX1DSPMode != DSPMode.CWU) ? 50 : 10);
				SelectRX2VarFilter();
				if (rX1DSPMode == DSPMode.LSB || rX1DSPMode == DSPMode.CWL || rX1DSPMode == DSPMode.DIGL)
				{
					int Value = RX2FilterLow;
					EncoderUpdate(Steps * -num, ref Value, (int)udRX2FilterLow.Minimum, (int)udRX2FilterLow.Maximum);
					RX2FilterLow = Value;
				}
				else
				{
					int Value = RX2FilterHigh;
					EncoderUpdate(Steps * num, ref Value, (int)udRX2FilterHigh.Minimum, (int)udRX2FilterHigh.Maximum);
					RX2FilterHigh = Value;
				}
				UpdateRX2Filters(RX2FilterLow, RX2FilterHigh);
			}
			break;
		case EEncoderActions.eENFilterLow:
			if (flag)
			{
				DSPMode rX1DSPMode = RX1DSPMode;
				int num = ((rX1DSPMode != DSPMode.CWL && rX1DSPMode != DSPMode.CWU) ? 50 : 10);
				SelectRX1VarFilter();
				if (rX1DSPMode == DSPMode.LSB || rX1DSPMode == DSPMode.CWL || rX1DSPMode == DSPMode.DIGL)
				{
					int Value = RX1FilterHigh;
					EncoderUpdate(Steps * -num, ref Value, (int)udFilterHigh.Minimum, (int)udFilterHigh.Maximum);
					RX1FilterHigh = Value;
				}
				else
				{
					int Value = RX1FilterLow;
					EncoderUpdate(Steps * num, ref Value, (int)udFilterLow.Minimum, (int)udFilterLow.Maximum);
					RX1FilterLow = Value;
				}
				UpdateRX1Filters(RX1FilterLow, RX1FilterHigh);
			}
			else
			{
				DSPMode rX1DSPMode = RX2DSPMode;
				int num = ((rX1DSPMode != DSPMode.CWL && rX1DSPMode != DSPMode.CWU) ? 50 : 10);
				SelectRX2VarFilter();
				if (rX1DSPMode == DSPMode.LSB || rX1DSPMode == DSPMode.CWL || rX1DSPMode == DSPMode.DIGL)
				{
					int Value = RX2FilterHigh;
					EncoderUpdate(Steps * -num, ref Value, (int)udRX2FilterHigh.Minimum, (int)udRX2FilterHigh.Maximum);
					RX2FilterHigh = Value;
				}
				else
				{
					int Value = RX2FilterLow;
					EncoderUpdate(Steps * num, ref Value, (int)udRX2FilterLow.Minimum, (int)udRX2FilterLow.Maximum);
					RX2FilterLow = Value;
				}
				UpdateRX2Filters(RX2FilterLow, RX2FilterHigh);
			}
			break;
		case EEncoderActions.eENDrive:
		{
			int Value = PWR;
			EncoderUpdate(Steps, ref Value, ptbPWR.Minimum, ptbPWR.Maximum);
			ShowAndromedaSlider(Value, ptbPWR.Minimum, ptbPWR.Maximum, "Drive");
			PWR = Value;
			CheckGainFormAutoShow();
			break;
		}
		case EEncoderActions.eENMicGain:
		{
			int Value = CATMIC;
			EncoderUpdate(Steps, ref Value, ptbMic.Minimum, ptbMic.Maximum);
			ShowAndromedaSlider(Value, ptbMic.Minimum, ptbMic.Maximum, "Mic Gain");
			CATMIC = Value;
			CheckGainFormAutoShow();
			break;
		}
		case EEncoderActions.eENVFOATune:
			VFOAFreq = CATVFOA + (double)Steps * (double)TuneStepList[TuneStepIndex].StepHz * 1E-06;
			break;
		case EEncoderActions.eENVFOBTune:
			VFOBFreq = CATVFOB + (double)Steps * (double)TuneStepList[TuneStepIndex].StepHz * 1E-06;
			break;
		case EEncoderActions.eENVOXGain:
		{
			int Value = VOXSens;
			EncoderUpdate(Steps, ref Value, ptbVOX.Minimum, ptbVOX.Maximum);
			ShowAndromedaSlider(Value, ptbVOX.Minimum, ptbVOX.Maximum, "VOX Gain");
			VOXSens = Value;
			break;
		}
		case EEncoderActions.eENVOXHold:
		{
			int Value = (int)VOXHangTime;
			EncoderUpdate(Steps * 50, ref Value, 100, 4000);
			ShowAndromedaSlider(Value, 100, 4000, "VOX hold");
			VOXHangTime = Value;
			break;
		}
		case EEncoderActions.eENCWSidetone:
		{
			int Value = SetupForm.CATCWPitch;
			EncoderUpdate(Steps * 10, ref Value, (int)udCWPitch.Minimum, (int)udCWPitch.Maximum);
			ShowAndromedaSlider(Value, (int)udCWPitch.Minimum, (int)udCWPitch.Maximum, "CW pitch");
			SetupForm.CATCWPitch = Value;
			break;
		}
		case EEncoderActions.eENCWSpeed:
		{
			int Value = CATCWSpeed;
			EncoderUpdate(Steps, ref Value, ptbCWSpeed.Minimum, ptbCWSpeed.Maximum);
			ShowAndromedaSlider(Value, ptbCWSpeed.Minimum, ptbCWSpeed.Maximum, "CW speed");
			CATCWSpeed = Value;
			break;
		}
		case EEncoderActions.eENSquelch:
			if (flag)
			{
				int Value = Squelch;
				EncoderUpdate(Steps, ref Value, ptbSquelch.Minimum, ptbSquelch.Maximum);
				ShowAndromedaSlider(Value, ptbSquelch.Minimum, ptbSquelch.Maximum, "RX1 squelch");
				Squelch = Value;
			}
			else
			{
				int Value = Squelch2;
				EncoderUpdate(Steps, ref Value, ptbRX2Squelch.Minimum, ptbRX2Squelch.Maximum);
				ShowAndromedaSlider(Value, ptbRX2Squelch.Minimum, ptbRX2Squelch.Maximum, "RX2 squelch");
				Squelch2 = Value;
			}
			CheckGainFormAutoShow();
			break;
		case EEncoderActions.eENDiversityGain:
		{
			if (chkMOX.Checked)
			{
				TweakAriesInductance(Steps);
				break;
			}
			decimal cATDiversityGain = CATDiversityGain;
			cATDiversityGain += (decimal)Steps * 0.025m;
			CATDiversityGain = cATDiversityGain;
			CheckDiversityFormAutoShow();
			break;
		}
		case EEncoderActions.eENDiversityPhase:
		{
			if (chkMOX.Checked)
			{
				TweakAriesCapacitance(Steps);
				break;
			}
			decimal cATDiversityGain = CATDiversityPhase;
			cATDiversityGain += (decimal)Steps * 5.0m;
			if (cATDiversityGain >= 180.0m)
			{
				cATDiversityGain -= 360.0m;
			}
			else if (cATDiversityGain <= -180.0m)
			{
				cATDiversityGain += 360.0m;
			}
			CATDiversityPhase = cATDiversityGain;
			CheckDiversityFormAutoShow();
			break;
		}
		case EEncoderActions.eENCompanderThreshold:
		{
			int Value = CPDRLevel;
			EncoderUpdate(Steps, ref Value, ptbCPDR.Minimum, ptbCPDR.Maximum);
			ShowAndromedaSlider(Value, ptbCPDR.Minimum, ptbCPDR.Maximum, "COMP level");
			CPDRLevel = Value;
			break;
		}
		case EEncoderActions.eENRIT:
		{
			int Value = RITValue;
			EncoderUpdate(Steps * 10, ref Value, (int)udRIT.Minimum, (int)udRIT.Maximum);
			ShowAndromedaSlider(Value, (int)udRIT.Minimum, (int)udRIT.Maximum, "RIT");
			RITValue = Value;
			break;
		}
		case EEncoderActions.eENXIT:
		{
			int Value = XITValue;
			EncoderUpdate(Steps * 10, ref Value, (int)udXIT.Minimum, (int)udXIT.Maximum);
			ShowAndromedaSlider(Value, (int)udXIT.Minimum, (int)udXIT.Maximum, "XIT");
			XITValue = Value;
			break;
		}
		case EEncoderActions.eENRITXIT:
			if (chkRIT.Checked)
			{
				int Value = RITValue;
				EncoderUpdate(Steps * 10, ref Value, (int)udRIT.Minimum, (int)udRIT.Maximum);
				ShowAndromedaSlider(Value, (int)udRIT.Minimum, (int)udRIT.Maximum, "RIT");
				RITValue = Value;
			}
			else if (chkXIT.Checked)
			{
				int Value = XITValue;
				EncoderUpdate(Steps * 10, ref Value, (int)udXIT.Minimum, (int)udXIT.Maximum);
				ShowAndromedaSlider(Value, (int)udXIT.Minimum, (int)udXIT.Maximum, "XIT");
				XITValue = Value;
			}
			break;
		case EEncoderActions.eENDisplayPan:
		{
			int Value = Pan;
			EncoderUpdate(Steps, ref Value, ptbDisplayPan.Minimum, ptbDisplayPan.Maximum);
			ShowAndromedaSlider(Value, ptbDisplayPan.Minimum, ptbDisplayPan.Maximum, "PAN");
			Pan = Value;
			break;
		}
		case EEncoderActions.eENDisplayZoom:
		{
			int Value = Zoom;
			EncoderUpdate(Steps, ref Value, ptbDisplayZoom.Minimum, ptbDisplayZoom.Maximum);
			ShowAndromedaSlider(Value, ptbDisplayZoom.Minimum, ptbDisplayZoom.Maximum, "Zoom");
			Zoom = Value;
			break;
		}
		case EEncoderActions.eENVACRX:
			if (SetupForm != null)
			{
				if (flag)
				{
					int Value = SetupForm.VACRXGain;
					EncoderUpdate(Steps, ref Value, -40, 40);
					SetupForm.VACRXGain = Value;
					ShowAndromedaSlider(Value, -40, 40, "VAC1 RX");
				}
				else
				{
					int Value = SetupForm.VAC2RXGain;
					EncoderUpdate(Steps, ref Value, -40, 40);
					SetupForm.VAC2RXGain = Value;
					ShowAndromedaSlider(Value, -40, 40, "VAC2 RX");
				}
				CheckGainFormAutoShow();
			}
			break;
		case EEncoderActions.eENVACTX:
			if (SetupForm != null)
			{
				if (flag)
				{
					int Value = SetupForm.VACTXGain;
					EncoderUpdate(Steps, ref Value, -40, 40);
					SetupForm.VACTXGain = Value;
					ShowAndromedaSlider(Value, -40, 40, "VAC1 TX");
				}
				else
				{
					int Value = SetupForm.VAC2TXGain;
					EncoderUpdate(Steps, ref Value, -40, 40);
					SetupForm.VAC2TXGain = Value;
					ShowAndromedaSlider(Value, -40, 40, "VAC2 TX");
				}
				CheckGainFormAutoShow();
			}
			break;
		case EEncoderActions.eENTuneStep:
		{
			int Value = TuneStepIndex;
			EncoderUpdate(Steps, ref Value, 0, tune_step_list.Count - 1);
			TuneStepIndex = Value;
			break;
		}
		case EEncoderActions.eENNoAction:
		case EEncoderActions.eENMulti:
			break;
		}
	}

	private void CheckGainFormAutoShow()
	{
		if (!IsSetupFormNull && SetupForm.AndromedaGainAutoShow)
		{
			if (sliderForm == null || sliderForm.IsDisposed)
			{
				sliderForm = new SliderSettingsForm(this);
			}
			Invoke(new MethodInvoker(sliderForm.FormEncoderEvent));
		}
	}

	private void CheckDiversityFormAutoShow()
	{
		if (!IsSetupFormNull && SetupForm.AndromedaDiversityAutoShow)
		{
			if (diversityForm == null || diversityForm.IsDisposed)
			{
				diversityForm = new DiversityForm(this);
			}
			Invoke(new MethodInvoker(diversityForm.FormEncoderEvent));
		}
	}

	private void ShowAndromedaSlider(int Value, int Min, int Max, string Label)
	{
		double num = ((Max != Min) ? (100.0 * (double)(Value - Min) / (double)(Max - Min)) : 0.0);
		tbAndromedaEncoderSlider.Value = (int)num;
		tbAndromedaEncoderSlider.Visible = true;
		lblAndromedaEncoderSlider.Text = Label;
		lblAndromedaEncoderSlider.Visible = true;
		AndromedaTimer.Enabled = false;
		AndromedaTimer.AutoReset = false;
		AndromedaTimer.Interval = 5000.0;
		AndromedaTimer.Enabled = true;
	}

	private void Callback(object source, ElapsedEventArgs e)
	{
		lblAndromedaEncoderSlider.Visible = false;
		tbAndromedaEncoderSlider.Visible = false;
		AndromedaTimer.Enabled = false;
	}

	public void EncoderUpdate(int Steps, ref int Value, int Minimum, int Maximum)
	{
		Value += Steps;
		if (Value < Minimum)
		{
			Value = Minimum;
		}
		if (Value > Maximum)
		{
			Value = Maximum;
		}
	}

	private void ExecuteButtonBarPress(int ButtonNumber)
	{
		DataTable dataTable = AndromedaSet.Tables["Menu Bar Settings"];
		_ = dataTable.Rows.Count;
		if (ButtonNumber >= 1 && ButtonNumber <= 8)
		{
			int index = ButtonNumber - 1 + currentButtonBarMenu * 8;
			EButtonBarActions eButtonBarActions = (EButtonBarActions)dataTable.Rows[index]["Menu Action"];
			int overrideRX = (int)dataTable.Rows[index]["Menu RX Selector"];
			if (eButtonBarActions == EButtonBarActions.eBBMenu)
			{
				currentButtonBarMenu = (int)dataTable.Rows[index]["Menu Number"] - 1;
				UpdateButtonBarButtons();
			}
			else
			{
				ExecuteButtonAction(eButtonBarActions, overrideRX);
			}
			if (!AndromedaStickyMenus)
			{
				AndromedaMenuTimer.Enabled = false;
				AndromedaMenuTimer.AutoReset = false;
				AndromedaMenuTimer.Interval = 10000.0;
				AndromedaMenuTimer.Enabled = true;
			}
		}
	}

	private void AndromedaMenuTimerCallback(object source, ElapsedEventArgs e)
	{
		AndromedaMenuTimer.Enabled = false;
		currentButtonBarMenu = 0;
		UpdateButtonBarButtons();
	}

