			break;
		case EButtonBarActions.eBBVFOSettingForm:
			if (VFOSettingsForm == null || VFOSettingsForm.IsDisposed)
			{
				VFOSettingsForm = new VFOSettingsPopup(this);
			}
			Skin.Restore(CurrentSkin, AppDataPath, VFOSettingsForm);
			Invoke(new MethodInvoker(VFOSettingsForm.Show));
			break;
		case EButtonBarActions.eBBBandstackForm:
			Invoke(new MethodInvoker(((Control)BandStack2Form).Show));
			break;
		case EButtonBarActions.eBBBandstack:
			SetCATBand(RX1Band);
			break;
		case EButtonBarActions.eBBQuickSave:
			btnMemoryQuickSave_Click(null, null);
			break;
		case EButtonBarActions.eBBQuickRestore:
			btnMemoryQuickRestore_Click(null, null);
			break;
		case EButtonBarActions.eBBRXAntenna:
			chkRxAnt.Checked = !chkRxAnt.Checked;
			break;
		case EButtonBarActions.eBBDiversityForm:
			CATDiversityForm = true;
			break;
		case EButtonBarActions.eBBModeSettingsForm:
			if (modeDependentSettingsForm == null || modeDependentSettingsForm.IsDisposed)
			{
				modeDependentSettingsForm = new ModeDependentSettingsForm(this);
			}
			Invoke(new MethodInvoker(modeDependentSettingsForm.Show));
			setupModePanels();
			SelectModeDependentPanel();
			break;
		case EButtonBarActions.eBBPuresignalForm:
			if (psform == null || psform.IsDisposed)
			{
				psform = new PSForm(this);
			}
			Invoke(new MethodInvoker(psform.Show));
			break;
		case EButtonBarActions.eBBEqualiserForm:
			equalizerToolStripMenuItem_Click(this, EventArgs.Empty);
			break;
		case EButtonBarActions.eBBDisplaySettingsForm:
			if (displaySettingsForm == null || displaySettingsForm.IsDisposed)
			{
				displaySettingsForm = new DisplaySettingsForm(this);
			}
			Invoke(new MethodInvoker(displaySettingsForm.Show));
			break;
		case EButtonBarActions.eBBSetupForm:
			if (IsSetupFormNull)
			{
				setupToolStripMenuItem1_Click(this, EventArgs.Empty);
			}
			break;
		case EButtonBarActions.eBBATUOnOff:
		{
			int num = (int)(TXBand - 1);
			int num2 = 0;
			if (num < 12)
			{
				num2 = AntennaArrayByBand[num];
				if (!IsSetupFormNull)
				{
					SetupForm.SetAriesEnabledButton(num2, !AriesEnabled);
				}
			}
			AndromedaIndicatorCheck(EIndicatorActions.eINATUReady, IsRX1: true, AriesEnabled);
			break;
		}
		case EButtonBarActions.eBBMultiEncoderButton:
			AndromedaMultiEncoderState = !AndromedaMultiEncoderState;
			break;
		case EButtonBarActions.eBBShift:
			if (AndromedaBandButtonsEnabled)
			{
				AndromedaBandButtonsEnabled = false;
			}
			else
			{
				AndromedaBandButtonsEnabled = true;
			}
			AndromedaIndicatorCheck(EIndicatorActions.eINShiftEnabled, IsRX1: false, AndromedaBandButtonsEnabled);
			break;
		case EButtonBarActions.eBBMNFAdd:
			btnTNFAdd_Click(null, null);
			break;
		case EButtonBarActions.eBBAntennaStep:
			TXAntennaStep();
			break;
		}
		UpdateButtonBarButtons();
	}

	public void UpdateAndromedaSkins()
	{
		if (modePopupForm != null && modePopupForm.Visible)
		{
			Skin.Restore(CurrentSkin, AppDataPath, modePopupForm);
		}
		if (filterPopupForm != null && filterPopupForm.Visible)
		{
			Skin.Restore(CurrentSkin, AppDataPath, filterPopupForm);
		}
		if (bandPopupForm != null && bandPopupForm.Visible)
		{
			Skin.Restore(CurrentSkin, AppDataPath, bandPopupForm);
		}
		if (sliderForm != null && sliderForm.Visible)
		{
			Skin.Restore(CurrentSkin, AppDataPath, sliderForm);
		}
		if (VFOSettingsForm != null && VFOSettingsForm.Visible)
		{
			Skin.Restore(CurrentSkin, AppDataPath, VFOSettingsForm);
		}
	}

	private void setupModePanels()
	{
		Invoke(new MethodInvoker(panelModeSpecificCW.Show));
		Invoke(new MethodInvoker(panelModeSpecificPhone.Show));
		Invoke(new MethodInvoker(panelModeSpecificDigital.Show));
		Invoke(new MethodInvoker(panelModeSpecificFM.Show));
		panelModeSpecificCW.Location = new Point(0, 0);
		panelModeSpecificPhone.Location = new Point(0, 0);
		panelModeSpecificDigital.Location = new Point(0, 0);
		panelModeSpecificFM.Location = new Point(0, 0);
		panelModeSpecificCW.Parent = modeDependentSettingsForm;
		panelModeSpecificPhone.Parent = modeDependentSettingsForm;
		panelModeSpecificDigital.Parent = modeDependentSettingsForm;
		panelModeSpecificFM.Parent = modeDependentSettingsForm;
	}

	private void ExecuteButtonLongpress(EButtonBarActions assignedAction, int OverrideRX)
	{
		if (OverrideRX == 0)
		{
			_ = show_rx1;
		}
		else
		{
			_ = 1;
		}
		switch (assignedAction)
		{
		case EButtonBarActions.eBBFilterPlus:
			if (filterPopupForm == null || filterPopupForm.IsDisposed)
			{
				filterPopupForm = new FilterButtonsPopup(this);
			}
			Invoke(new MethodInvoker(filterPopupForm.Show));
			break;
		case EButtonBarActions.eBBFilterMinus:
			if (filterPopupForm == null || filterPopupForm.IsDisposed)
			{
				filterPopupForm = new FilterButtonsPopup(this);
			}
			Invoke(new MethodInvoker(filterPopupForm.Show));
			break;
		case EButtonBarActions.eBBModePlus:
			if (modePopupForm == null || modePopupForm.IsDisposed)
			{
				modePopupForm = new ModeButtonsPopup(this);
			}
			Invoke(new MethodInvoker(modePopupForm.Show));
			break;
		case EButtonBarActions.eBBModeMinus:
			if (modePopupForm == null || modePopupForm.IsDisposed)
			{
				modePopupForm = new ModeButtonsPopup(this);
			}
			Invoke(new MethodInvoker(modePopupForm.Show));
			break;
		}
		UpdateButtonBarButtons();
	}

	private void SelectModeDependentPanel()
	{
		bool flag = modeDependentSettingsForm != null && !modeDependentSettingsForm.IsDisposed;
		if (_iscollapsed && !_isexpanded)
		{
			if (!flag || !modeDependentSettingsForm.Visible)
			{
				panelModeSpecificPhone.Hide();
				panelModeSpecificCW.Hide();
				panelModeSpecificDigital.Hide();
				panelModeSpecificFM.Hide();
				return;
			}
			setupModePanels();
		}
		else
		{
			moveModeSpecificPanels();
		}
		switch (RX1DSPMode)
		{
		case DSPMode.LSB:
		case DSPMode.USB:
		case DSPMode.DSB:
		case DSPMode.AM:
		case DSPMode.SPEC:
		case DSPMode.SAM:
			panelModeSpecificPhone.Show();
			panelModeSpecificCW.Hide();
			panelModeSpecificDigital.Hide();
			panelModeSpecificFM.Hide();
			break;
		case DSPMode.CWL:
		case DSPMode.CWU:
			panelModeSpecificCW.Show();
			panelModeSpecificDigital.Hide();
			panelModeSpecificFM.Hide();
			panelModeSpecificPhone.Hide();
			break;
		case DSPMode.FM:
			panelModeSpecificFM.Show();
			panelModeSpecificCW.Hide();
			panelModeSpecificDigital.Hide();
			panelModeSpecificPhone.Hide();
			break;
		case DSPMode.DIGU:
		case DSPMode.DIGL:
		case DSPMode.DRM:
			panelModeSpecificDigital.Show();
			panelModeSpecificCW.Hide();
			panelModeSpecificFM.Hide();
			panelModeSpecificPhone.Hide();
			break;
		}
	}

	private string UpdateButtonBarLabel(EButtonBarActions assignedAction, string DefaultString, bool UseRX1)
	{
		string text = "";
		switch (assignedAction)
		{
		case EButtonBarActions.eBBNR:
			if (UseRX1)
			{
				if (_nr_selected[0] > 0)
				{
					return "RX1 " + chkNR.Text;
				}
				return "RX1 NR: off";
			}
			if (_nr_selected[1] > 0)
			{
				return "RX1 " + chkNR.Text;
			}
			return "RX1 NR: off";
		case EButtonBarActions.eBBNB:
			if (UseRX1)
			{
				if (chkNB.Checked)
				{
					return "RX1 " + chkNB.Text;
				}
				return "RX1 NB: off";
			}
			if (chkRX2NB.Checked)
			{
				return "RX2 " + chkRX2NB.Text;
			}
			return "RX2 NB: off";
		case EButtonBarActions.eBBSNB:
			if (UseRX1)
			{
				return "RX1 SNB";
			}
			return "RX2 SNB";
		case EButtonBarActions.eBBANF:
			if (UseRX1)
			{
				return "RX1 ANF";
			}
			return "RX2 ANF";
		case EButtonBarActions.eBBFilterPlus:
			if (UseRX1)
			{
				return "RX1 filter step up: " + lblFilterLabel.Text;
			}
			return "RX2 filter step up: " + lblRX2FilterLabel.Text;
		case EButtonBarActions.eBBFilterMinus:
			if (UseRX1)
			{
				return "RX1 filter step down: " + lblFilterLabel.Text;
			}
			return "RX2 filter step down: " + lblRX2FilterLabel.Text;
		case EButtonBarActions.eBBBandPlus:
			if (UseRX1)
			{
				return "RX1 Band step UP";
			}
			return "RX2 Band step UP";
		case EButtonBarActions.eBBBandMinus:
			if (UseRX1)
			{
				return "RX1 Band step DOWN";
			}
			return "RX2 Band step DOWN";
		case EButtonBarActions.eBBModePlus:
			if (UseRX1)
			{
				return "RX1 Mode step UP";
			}
			return "RX2 Mode step UP";
		case EButtonBarActions.eBBModeMinus:
			if (UseRX1)
			{
				return "RX1 Mode step DOWN";
			}
			return "RX2 Mode step DOWN";
		case EButtonBarActions.eBBAttenStep:
			if (UseRX1)
			{
				return "RX1 Atten: " + udRX1StepAttData.Value + "dB";
			}
			return "RX2 Atten: " + udRX2StepAttData.Value + "dB";
		case EButtonBarActions.eBBMuteOnOff:
			if (UseRX1)
			{
				return "RX1 Mute";
			}
			return "RX2 Mute";
		case EButtonBarActions.eBBBINOnOff:
			if (UseRX1)
			{
				return "RX1 Binaural";
			}
			return "RX2 Binaural";
		case EButtonBarActions.eBBAGCStep:
			if (UseRX1)
			{
				return "RX1 AGC: " + comboAGC.Text;
			}
			return "RX2 AGC: " + comboRX2AGC.Text;
		case EButtonBarActions.eBBSqlOnOff:
			if (UseRX1)
			{
				return "RX1 Squelch";
			}
			return "RX2 Squelch";
		case EButtonBarActions.eBBFMDeviation:
			if (radFMDeviation2kHz.Checked)
			{
				return "FM Deviation: 2KHz";
			}
			return "FM Deviation: 5KHz";
		case EButtonBarActions.eBBRXMeterStep:
			if (UseRX1)
			{
				return "RX1 Meter: " + comboMeterRXMode.Text;
			}
			return "RX2 Meter: " + comboRX2MeterMode.Text;
		case EButtonBarActions.eBBTXMeterStep:
			return "TX Meter: " + comboMeterTXMode.Text;
		case EButtonBarActions.eBBDisplayModeStep:
			if (UseRX1)
			{
				return "RX1 Display: " + comboDisplayMode.Text;
			}
			return "RX2 Display: " + comboRX2DisplayMode.Text;
		case EButtonBarActions.eBBDisplayDSPAVG:
			if (UseRX1)
			{
				return "RX1 Display AVG";
			}
			return "RX2 Display AVG";
		case EButtonBarActions.eBBDisplayDSPPeak:
			if (UseRX1)
			{
				return "RX1 Display PEAK";
			}
			return "RX2 Display PEAK";
		case EButtonBarActions.eBBBandstack:
			return DefaultString + "  " + regBandStackCurrentEntry.Text + "/" + regBandStackTotalEntries.Text;
		case EButtonBarActions.eBBQuickRestore:
			return DefaultString + " " + txtMemoryQuick.Text;
		case EButtonBarActions.eBBRXAntenna:
			if (Alex.trx_ant_different)
			{
				return chkRxAnt.Text;
			}
			return DefaultString + " (already = TX ant)";
		case EButtonBarActions.eBBCWQSK:
			if (chkQSK.Checked)
			{
				return chkQSK.Text;
			}
			return "QSK: off";
		case EButtonBarActions.eBBATUOnOff:
			if (AriesEnabled)
			{
				return "ATU: On";
			}
			return "ATU: Off";
		default:
			return DefaultString;
		}
	}

	private bool CheckButtonHighlight(EButtonBarActions assignedAction, bool UseRX1)
	{
		bool result = false;
		switch (assignedAction)
		{
		case EButtonBarActions.eBBStartStop:
			result = chkPower.Checked;
			break;
		case EButtonBarActions.eBBRX2OnOff:
			result = chkRX2.Checked;
			break;
		case EButtonBarActions.eBBDUP:
			result = chkRX2SR.Checked;
			break;
		case EButtonBarActions.eBBMON:
			result = chkMON.Checked;
			break;
		case EButtonBarActions.eBBTune:
			result = chkTUN.Checked;
			break;
		case EButtonBarActions.eBBMOX:
			result = chkMOX.Checked;
			break;
		case EButtonBarActions.eBBPuresignalOnOff:
			result = chkFWCATUBypass.Checked;
			break;
		case EButtonBarActions.eBBNR:
			result = _nr_selected[(!UseRX1) ? 1u : 0u] > 0;
			break;
		case EButtonBarActions.eBBNB:
			result = ((!UseRX1) ? chkRX2NB.Checked : chkNB.Checked);
			break;
		case EButtonBarActions.eBBSNB:
			result = ((!UseRX1) ? chkRX2NB2.Checked : chkDSPNB2.Checked);
			break;
		case EButtonBarActions.eBBANF:
			result = ((!UseRX1) ? chkRX2ANF.Checked : chkANF.Checked);
			break;
		case EButtonBarActions.eBBMNF:
			result = chkTNF.Checked;
			break;
		case EButtonBarActions.eBBVFOSplit:
			result = chkVFOSplit.Checked;
			break;
		case EButtonBarActions.eBBVFOSyncOnOff:
			result = chkVFOSync.Checked;
			break;
		case EButtonBarActions.eBBVFOLockOnOff:
			result = ((!UseRX1) ? chkVFOBLock.Checked : chkVFOLock.Checked);
			break;
		case EButtonBarActions.eBBVFOCTUNEOnOff:
			result = ((!UseRX1) ? chkX2TR.Checked : chkFWCATU.Checked);
			break;
		case EButtonBarActions.eBBToggleAB:
			if (CATRX1RX2RadioButton == 1)
			{
				result = true;
			}
			break;
		case EButtonBarActions.eBBRITOnOff:
			result = chkRIT.Checked;
			break;
		case EButtonBarActions.eBBXITOnOff:
			result = chkXIT.Checked;
			break;
		case EButtonBarActions.eBBMuteOnOff:
			result = ((!UseRX1) ? chkRX2Mute.Checked : chkMUT.Checked);
			break;
		case EButtonBarActions.eBBBINOnOff:
			result = ((!UseRX1) ? chkRX2BIN.Checked : chkBIN.Checked);
			break;
		case EButtonBarActions.eBBSDOnOff:
			result = chkDX.Checked;
			break;
		case EButtonBarActions.eBBVAC1OnOff:
			result = chkVAC1.Checked;
			break;
		case EButtonBarActions.eBBVAC2OnOff:
			result = chkVAC2.Checked;
			break;
		case EButtonBarActions.eBBSqlOnOff:
			result = ((!UseRX1) ? chkRX2Squelch.Checked : chkSquelch.Checked);
			break;
		case EButtonBarActions.eBBRXEQOnOff:
			result = chkRXEQ.Checked;
			break;
		case EButtonBarActions.eBBTXEQOnOff:
			result = chkTXEQ.Checked;
			break;
		case EButtonBarActions.eBBTXFLShow:
			result = chkShowTXFilter.Checked;
			break;
		case EButtonBarActions.eBBMICOnOff:
			result = chkMicMute.Checked;
			break;
		case EButtonBarActions.eBBCOMPOnOff:
			result = chkCPDR.Checked;
			break;
		case EButtonBarActions.eBBVOXOnOff:
			result = chkVOX.Checked;
			break;
		case EButtonBarActions.eBBDEXPOnOff:
			result = chkNoiseGate.Checked;
			break;
		case EButtonBarActions.eBBCWIambic:
			result = chkCWIambic.Checked;
			break;
		case EButtonBarActions.eBBCWSidetone:
			result = chkCWSidetone.Checked;
			break;
		case EButtonBarActions.eBBCWShowTX:
			result = chkShowTXCWFreq.Checked;
			break;
		case EButtonBarActions.eBBCWShowZero:
			result = chkShowCWZero.Checked;
			break;
		case EButtonBarActions.eBBCWQSK:
			result = chkQSK.Checked;
			break;
		case EButtonBarActions.eBBRX1APF:
			result = chkCWAPFEnabled.Checked;
			break;
		case EButtonBarActions.eBBCTCSSOnOff:
			result = chkFMCTCSS.Checked;
			break;
		case EButtonBarActions.eBBDiversityOnOff:
			result = CATDiversityEnable;
			break;
		case EButtonBarActions.eBBSubRXOnOff:
			result = chkEnableMultiRX.Checked;
			break;
		case EButtonBarActions.eBBDisplayDSPAVG:
			result = ((!UseRX1) ? chkRX2DisplayAVG.Checked : chkDisplayAVG.Checked);
			break;
		case EButtonBarActions.eBBDisplayDSPPeak:
			result = ((!UseRX1) ? chkRX2DisplayPeak.Checked : chkDisplayPeak.Checked);
			break;
		case EButtonBarActions.eBBRXAntenna:
			result = chkRxAnt.Checked;
			break;
		case EButtonBarActions.eBBRecordAudio:
			result = ckQuickRec.Checked;
			break;
		case EButtonBarActions.eBBPlayAudio:
			result = ckQuickPlay.Checked;
			break;
		case EButtonBarActions.eBBATUOnOff:
			result = AriesEnabled;
			break;
		case EButtonBarActions.eBBMenuButton:
			result = false;
			break;
		case EButtonBarActions.eBBMultiEncoderButton:
			result = AndromedaMultiEncoderState;
			break;
		default:
			result = false;
			break;
		case EButtonBarActions.eBBPuresignal2Tone:
		case EButtonBarActions.eUnusedButton1:
			break;
		}
		return result;
	}

