			defaultString = (string)dataTable.Rows[num]["Menu Text"];
			useRX = num2 switch
			{
				0 => show_rx1, 
				1 => true, 
				_ => false, 
			};
			btnAndrBar8.Text = UpdateButtonBarLabel(assignedAction, defaultString, useRX);
			backColor = ((!CheckButtonHighlight(assignedAction, useRX)) ? SystemColors.ButtonFace : SystemColors.GradientActiveCaption);
			btnAndrBar8.BackColor = backColor;
			num++;
		}
	}

