	[DllImport("user32.dll")]
	private static extern int SendMessage(IntPtr hWnd, int wMsg, bool wParam, int lParam);

	[DllImport("user32.dll")]
	private static extern bool RedrawWindow(IntPtr hWnd, IntPtr lprcUpdate, IntPtr hrgnUpdate, uint flags);

	public Console(string[] args)
	{
		Process.GetCurrentProcess().PriorityClass = ProcessPriorityClass.High;
		ThreadPriority priority = Thread.CurrentThread.Priority;
		Thread.CurrentThread.Priority = ThreadPriority.Highest;
		base.Opacity = 0.0;
		LogTool.ShowNewLog(base.Handle);
		LogTool.AddLogEntry("Thetis is loading...", "THET", colour_warn: false);
		Display.specready = false;
		bool flag = false;
		CultureInfo cultureInfo = (CultureInfo.DefaultThreadCurrentUICulture = (CultureInfo.DefaultThreadCurrentCulture = new CultureInfo("en-US")));
		Thread.CurrentThread.CurrentCulture = cultureInfo;
		Thread.CurrentThread.CurrentUICulture = cultureInfo;
		m_bLogShutdown = Common.HasArg(args, "-logshutdown");
		if (!checkVersions())
		{
			MessageBox.Show("An incorrect version of a required dll has been found.\nPlease resolve the issue otherwise unexpected behaviour may occur.", "Version error", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			_exitConsoleInDispose = false;
			Environment.Exit(1);
			return;
		}
		LogTool.AddLogEntry("Dll's checked ok");
		bool flag2 = requires_reposition();
		string text = "";
		foreach (string text2 in args)
		{
			if (text2.StartsWith("-datapath:"))
			{
				string text3 = text2.Trim().Substring(text2.Trim().IndexOf(":") + 1);
				if (text3.EndsWith("\""))
				{
					text3 = text3.Substring(0, text3.Length - 1);
				}
				if (!text3.EndsWith("\\"))
				{
					text3 += "\\";
				}
				if (Directory.Exists(text3))
				{
					text = text3;
				}
				else if (MessageBox.Show("-datapath: command line option found, but the folder specified was not found.\nWould you like to create this folder?  If not, the default folder will be used.\n\n(" + text3 + ")", "Command Line Option: Create Folder?", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144) == DialogResult.Yes)
				{
					Directory.CreateDirectory(text3);
					text = text3;
				}
			}
		}
		if (string.IsNullOrEmpty(text))
		{
			text = ((!Environment.Is64BitProcess) ? (Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData) + "\\OpenHPSDR\\Thetis\\") : (Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData) + "\\OpenHPSDR\\Thetis-x64\\"));
		}
		AppDataPath = text;
		if (_check_error_log)
		{
			_error_log_initial_size = getErrorLogSize();
		}
		if (!Directory.Exists(AppDataPath))
		{
			Directory.CreateDirectory(AppDataPath);
		}
		_use_additional_sas = !Common.HasArg(args, "-nospec");
		_touch_support = Common.HasArg(args, "-touch");
