	protected override void Dispose(bool disposing)
	{
		shutdownLogStringToPath("Inside Console Dispose()");
		shutdownLogStringToPath("Before LogTool.Shutdown()");
		LogTool.Shutdown();
		if (_exitConsoleInDispose)
		{
			ExitConsole();
		}
		if (_frmShutDownForm != null)
		{
			shutdownLogStringToPath("Before _frmShutDownForm.Close()");
			_frmShutDownForm.Close();
			_frmShutDownForm.Dispose();
			shutdownLogStringToPath("After _frmShutDownForm.Dispose()");
		}
		if (_check_error_log)
		{
			shutdownLogStringToPath("Before error log size check");
			if (getErrorLogSize() != _error_log_initial_size)
			{
				MessageBox.Show("The ErrorLog.txt has been updated during this sesson.\n\nPlease email it to MW0LGE at : [mw0lge@grange-lane.co.uk].\n\nIt is located in this folder : [" + AppDataPath + "].", "Error Log Change", MessageBoxButtons.OK, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			}
			shutdownLogStringToPath("After error log size check");
		}
		if (disposing && components != null)
		{
			components.Dispose();
		}
		base.Dispose(disposing);
		shutdownLogStringToPath("Leaving Console Dispose()");
	}

	[DllImport("kernel32.dll")]
	private static extern bool AttachConsole(int dwProcessId);

	[DllImport("kernel32.dll")]
	private static extern bool FreeConsole();

	private static bool showHelpInfo()
	{
		bool flag = AttachConsole(-1);
		if (flag)
		{
			string text = "\n\nThetis v" + Common.GetVerNum(include_revision: true) + " command line help :\n\n";
			text += "  -help   this help\n\n";
			text += "  -autostart         attempt to power on radio at start up\n";
			text += "  -cmasioconfig      show the cmASIO setup tab in audio setup\n";
			text += "  -noinstancewarn    do not warn if other instances are running\n";
			text += "  -nospec            do not use additional spectrum analysers from WDSP for filter item display\n";
			text += "  -touch             provide touch support for containers to simulate mouse down/move/up\n";
			text += "  -logshutdown       generate shutdown_log.txt when closing down\n\n";
			text += "  -datapath:c:\\thetisdatafolder\\                  use this data folder for everything\n";
			text += "  -datapath:c:\\thetisdatafolder\\ -autostart       as above, with autostart\n";
			text += "  \"-datapath:c:\\test with spaces\\\"                use this data folder for everything, but with spaces in the path\n";
			text += "  \"-datapath:c:\\test with spaces\\\" -autostart     as above, with autostart\n\n";
			text += "  -dbid:xyz    keep the active database unique to the install run via this shortcut\n";
			text += "  -dbid:HL2    another example to keep the active database unique to the install run via this shortcut\n";
			text += "  -dbid:G2     another example to keep the active database unique to the install run via this shortcut\n\n";
			text += "  -adaptor:#     use the following adaptor # for rendering, eg: -adaptor:0\n";
			Display.AdaptorInfo[] array = Display.DX2Adaptors();
			for (int i = 0; i < array.Length; i++)
			{
				text += $"  {i} ... {array[i].Description}   (hardware:{array[i].IsHardware.ToString().ToLower()})";
				text += (array[i].IsDefaultHardware ? " (default hardware)\n" : "\n");
			}
			System.Console.WriteLine(text);
			SendKeys.SendWait("{ENTER}");
			FreeConsole();
		}
		return flag;
	}

