	private static string cleanArg(string input)
	{
		if (string.IsNullOrEmpty(input))
		{
			return string.Empty;
		}
		StringBuilder stringBuilder = new StringBuilder();
		string text = input.Normalize(NormalizationForm.FormC);
		foreach (char c in text)
		{
			UnicodeCategory unicodeCategory = CharUnicodeInfo.GetUnicodeCategory(c);
			if (unicodeCategory != UnicodeCategory.Control && unicodeCategory != UnicodeCategory.Format && unicodeCategory != UnicodeCategory.OtherNotAssigned && (unicodeCategory != UnicodeCategory.SpaceSeparator || c == ' '))
			{
				stringBuilder.Append(c);
			}
		}
		return stringBuilder.ToString().Trim();
	}

	[DllImport("user32.dll", SetLastError = true)]
	private static extern IntPtr SetProcessDpiAwarenessContext(IntPtr value);

	[DllImport("shcore.dll", SetLastError = true)]
	private static extern int SetProcessDpiAwareness(int awareness);

	[STAThread]
	private static void Main(string[] args)
	{
		Application.ThreadException += Application_ThreadException;
		AppDomain.CurrentDomain.UnhandledException += CurrentDomain_UnhandledException;
		args = (from a in args
			select cleanArg(a) into a
			where !string.IsNullOrWhiteSpace(a)
			select a).ToArray();
		if (LogTool.GetRegistryDpiAwareness())
		{
			try
			{
				Display.HiDpiPhysicalRender = true;
			}
			catch
			{
			}
		}
		if (Common.HasArg(args, "-help") && showHelpInfo())
		{
			return;
		}
		if (Common.HasArg(args, "-adaptor"))
		{
			string text = Common.ArgParam(args, "-adaptor:");
			if (!string.IsNullOrEmpty(text) && int.TryParse(text, out var result))
			{
				Display.AdaptorInfo[] array = Display.DX2Adaptors();
				if (result >= 0 && result < array.Length)
				{
					Display.DisplayAdaptor = array[result];
				}
			}
		}
		string text2 = "";
		if (Common.HasArg(args, "-datapath"))
		{
			string[] array2 = args;
			foreach (string text3 in array2)
			{
				if (text3.StartsWith("-datapath:"))
				{
					string text4 = text3.Trim().Substring(text3.Trim().IndexOf(":") + 1);
					if (text4.EndsWith("\""))
					{
						text4 = text4.Substring(0, text4.Length - 1);
					}
					if (!text4.EndsWith("\\"))
					{
						text4 += "\\";
					}
					if (Directory.Exists(text4))
					{
						text2 = text4;
					}
					else if (MessageBox.Show("-datapath: command line option found, but the folder specified was not found.\nWould you like to create this folder?  If not, the default folder will be used.\n\n(" + text4 + ")", "Command Line Option: Create Folder?", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144) == DialogResult.Yes)
					{
						Directory.CreateDirectory(text4);
						text2 = text4;
					}
				}
			}
		}
		if (string.IsNullOrEmpty(text2))
		{
			text2 = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData) + "\\OpenHPSDR\\Thetis\\";
			if (Environment.Is64BitProcess)
			{
				text2 = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData) + "\\OpenHPSDR\\Thetis-x64\\";
			}
		}
		bool flag = false;
		try
		{
			if (!Directory.Exists(text2))
			{
				Directory.CreateDirectory(text2);
			}
			if (!Common.HasArg(args, "-noinstancewarn") && !SingleInstance.CheckAndPrompt())
			{
				return;
			}
			Common.SetLogPath(text2);
			Win32.TimeBeginPeriod(1u);
			Application.EnableVisualStyles();
			Application.DoEvents();
			_theConsole = new Console(args);
			Application.Run(_theConsole);
			flag = _theConsole.Restart && !Common.ShiftKeyDown;
		}
		catch (Exception ex)
		{
			if (ex.Message.Contains("does not belong to table", StringComparison.InvariantCultureIgnoreCase))
			{
				MessageBox.Show("The database is incorrectly configured for this version of Thetis.\n\nThis is most likely because the database has not yet been updated.\n\nThetis will normally offer to update the database automatically on startup.\nIf the automatic update was declined or failed, you can force it by holding either CTRL key while launching Thetis, or by creating an empty file named 'updatedb.txt' in your data folder.", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			}
			else
			{
				MessageBox.Show(build_exception_text(ex), "Fatal Error", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			}
			Application.Exit();
		}
		if (flag)
		{
			Application.Restart();
		}
	}

	private static string build_exception_text(Exception ex)
	{
		StringBuilder stringBuilder = new StringBuilder();
		for (Exception ex2 = ex; ex2 != null; ex2 = ex2.InnerException)
		{
			stringBuilder.AppendLine(ex2.GetType().FullName);
			stringBuilder.AppendLine(ex2.Message);
			stringBuilder.AppendLine(ex2.StackTrace);
			stringBuilder.AppendLine();
		}
		return stringBuilder.ToString();
	}

	private string getTitleWithFWVersion()
	{
		string text = "";
		if (!IsSetupFormNull)
