	public void SetupInfoBarButton(ucInfoBar.ActionTypes action, bool bEnabled)
	{
		infoBar.UpdateButtonState(action, bEnabled);
	}

	private void SetupInfoBar()
	{
		infoBar.LateInit(this);
		if (psform != null)
		{
			infoBar.PSAEnabled = psform.AutoCalEnabled;
		}
		if (!IsSetupFormNull)
		{
			infoBar.UpdateButtonState(ucInfoBar.ActionTypes.Blobs, SetupForm.PeakBlobsEnabled, bIncludePopup: false);
			infoBar.UpdateButtonState(ucInfoBar.ActionTypes.ActivePeaks, SetupForm.ActivePeakHoldsEnabled, bIncludePopup: false);
			infoBar.UpdateButtonState(ucInfoBar.ActionTypes.CFC, SetupForm.CFCEnabled, bIncludePopup: false);
			infoBar.UpdateButtonState(ucInfoBar.ActionTypes.CursorInfo, SetupForm.ShowDisplayMHzCursorInfo, bIncludePopup: false);
			infoBar.UpdateButtonState(ucInfoBar.ActionTypes.Leveler, SetupForm.TXLevelerOn, bIncludePopup: false);
			infoBar.UpdateButtonState(ucInfoBar.ActionTypes.CFCeq, SetupForm.CFCPEQEnabled, bIncludePopup: false);
			infoBar.UpdateButtonState(ucInfoBar.ActionTypes.ShowSpots, SetupForm.ShowTCISpots, bIncludePopup: false);
			infoBar.UpdateButtonState(ucInfoBar.ActionTypes.DisplayFill, SetupForm.DisplayPanFill, bIncludePopup: false);
			infoBar.UpdateButtonState(ucInfoBar.ActionTypes.DisplayPause, Display.PausedDisplay);
		}
		infoBar.SetToolTipLeft(1, 1, "RBW - Resolution Bandwidth");
		infoBar.SetToolTipLeft(1, 2, "PB - Passband Bandwidth");
		infoBar.SetToolTipRight(1, 1, "NPSD - Noise Floor Power Spectral Density");
		infoBar.SetToolTipRight(1, 2, "PBNP - Estimated Passband Noise Power");
		infoBar.SetToolTipRight(1, 3, "PBSNR - Estimated Passband SNR");
	}

	public void InfoBarFeedbackLevel(int level, bool bFeedbackLevelOk, bool bCorrectionsBeingApplied, bool bCalibrationAttemptsChanged, Color feedbackColour)
	{
		if (infoBar.InvokeRequired)
		{
			infoBar.Invoke((Action)delegate
			{
				infoBar.PSInfo(level, bFeedbackLevelOk, bCorrectionsBeingApplied, bCalibrationAttemptsChanged, feedbackColour);
			});
		}
		else
		{
			infoBar.PSInfo(level, bFeedbackLevelOk, bCorrectionsBeingApplied, bCalibrationAttemptsChanged, feedbackColour);
		}
	}

	public void InfoBarPSState(string state)
	{
		if (infoBar.InvokeRequired)
		{
			infoBar.Invoke((Action)delegate
			{
				infoBar.PSState(state);
			});
		}
		else
		{
			infoBar.PSState(state);
		}
	}

