	private void OnTCPIIPcatClientDisconnect()
	{
		if (m_tcpCATServer != null && !IsSetupFormNull)
		{
			SetupForm.TCPIPcatClientsConnectedChange = m_tcpCATServer.ClientsConnected;
		}
	}

	private void OnTCPIIPcatClientError(SocketException se)
	{
	}

	private void OnTCPIIPcatServerError(SocketException se)
	{
	}

	private void addTCPIPcatDelegates()
	{
		if (!_bTCPIPcatDelegatesAdded)
		{
			TCPIPcatServer tcpCATServer = m_tcpCATServer;
			tcpCATServer.ClientConnectedHandlers = (TCPIPcatServer.ClientConnected)Delegate.Combine(tcpCATServer.ClientConnectedHandlers, new TCPIPcatServer.ClientConnected(OnTCPIIPcatClientConnect));
			TCPIPcatServer tcpCATServer2 = m_tcpCATServer;
			tcpCATServer2.ClientDisconnectedHandlers = (TCPIPcatServer.ClientDisconnected)Delegate.Combine(tcpCATServer2.ClientDisconnectedHandlers, new TCPIPcatServer.ClientDisconnected(OnTCPIIPcatClientDisconnect));
			TCPIPcatServer tcpCATServer3 = m_tcpCATServer;
			tcpCATServer3.ClientErrorHandlers = (TCPIPcatServer.ClientError)Delegate.Combine(tcpCATServer3.ClientErrorHandlers, new TCPIPcatServer.ClientError(OnTCPIIPcatClientError));
			TCPIPcatServer tcpCATServer4 = m_tcpCATServer;
			tcpCATServer4.ServerErrorHandlers = (TCPIPcatServer.ServerError)Delegate.Combine(tcpCATServer4.ServerErrorHandlers, new TCPIPcatServer.ServerError(OnTCPIIPcatServerError));
			_bTCPIPcatDelegatesAdded = true;
		}
	}

	private void removeTCPIPcatDelegates()
	{
		if (_bTCPIPcatDelegatesAdded)
		{
			TCPIPcatServer tcpCATServer = m_tcpCATServer;
			tcpCATServer.ClientConnectedHandlers = (TCPIPcatServer.ClientConnected)Delegate.Remove(tcpCATServer.ClientConnectedHandlers, new TCPIPcatServer.ClientConnected(OnTCPIIPcatClientConnect));
			TCPIPcatServer tcpCATServer2 = m_tcpCATServer;
			tcpCATServer2.ClientDisconnectedHandlers = (TCPIPcatServer.ClientDisconnected)Delegate.Remove(tcpCATServer2.ClientDisconnectedHandlers, new TCPIPcatServer.ClientDisconnected(OnTCPIIPcatClientDisconnect));
			TCPIPcatServer tcpCATServer3 = m_tcpCATServer;
			tcpCATServer3.ClientErrorHandlers = (TCPIPcatServer.ClientError)Delegate.Remove(tcpCATServer3.ClientErrorHandlers, new TCPIPcatServer.ClientError(OnTCPIIPcatClientError));
			TCPIPcatServer tcpCATServer4 = m_tcpCATServer;
			tcpCATServer4.ServerErrorHandlers = (TCPIPcatServer.ServerError)Delegate.Remove(tcpCATServer4.ServerErrorHandlers, new TCPIPcatServer.ServerError(OnTCPIIPcatServerError));
			_bTCPIPcatDelegatesAdded = false;
		}
	}

	public void SetupTCPIPCat(bool bOn)
	{
		if (bOn)
		{
			if (IPAddress.TryParse(m_sTCPIPCatAddress, out var address))
			{
				if (m_objTCPIPCatParser == null)
				{
					m_objTCPIPCatParser = new CATParser(this);
				}
				if (m_tcpCATServer != null)
				{
					m_tcpCATServer.StopServer();
				}
				m_tcpCATServer = new TCPIPcatServer(address, m_nTCPIPCatPort);
				addTCPIPcatDelegates();
				m_tcpCATServer.StartServer(this, m_bTCPIPcatWelcomeMessage);
				if (m_tcpCATServer.IsServerRunning)
				{
					NetworkIO.SetCATPort(m_nTCPIPCatPort);
				}
				else
				{
					if (!IsSetupFormNull)
					{
						SetupForm.DisableTCPIPCatServerDueToError();
					}
					removeTCPIPcatDelegates();
					MessageBox.Show("Unable to start the server." + Environment.NewLine + Environment.NewLine + "[ " + m_tcpCATServer.LastError + " ]", "TCPIP CAT Server", MessageBoxButtons.OK, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
				}
			}
		}
		else if (m_tcpCATServer != null)
		{
			NetworkIO.SetCATPort(0);
			Thread.Sleep(100);
			m_tcpCATServer.CloseLog();
			m_tcpCATServer.StopServer();
			removeTCPIPcatDelegates();
		}
		UpdateStatusBarStatusIcons(StatusBarIconGroup.TCPIPCat);
	}

