	}

	private void addTCIDelegates()
	{
		if (!_bTCIDelegatesAdded)
		{
			TCPIPtciServer tcpTCIServer = m_tcpTCIServer;
			tcpTCIServer.ClientConnectedHandlers = (TCPIPtciServer.ClientConnected)Delegate.Combine(tcpTCIServer.ClientConnectedHandlers, new TCPIPtciServer.ClientConnected(OnTCIClientConnect));
			TCPIPtciServer tcpTCIServer2 = m_tcpTCIServer;
			tcpTCIServer2.ClientDisconnectedHandlers = (TCPIPtciServer.ClientDisconnected)Delegate.Combine(tcpTCIServer2.ClientDisconnectedHandlers, new TCPIPtciServer.ClientDisconnected(OnTCIClientDisconnect));
			TCPIPtciServer tcpTCIServer3 = m_tcpTCIServer;
			tcpTCIServer3.ClientErrorHandlers = (TCPIPtciServer.ClientError)Delegate.Combine(tcpTCIServer3.ClientErrorHandlers, new TCPIPtciServer.ClientError(OnTCIClientError));
			TCPIPtciServer tcpTCIServer4 = m_tcpTCIServer;
			tcpTCIServer4.ServerErrorHandlers = (TCPIPtciServer.ServerError)Delegate.Combine(tcpTCIServer4.ServerErrorHandlers, new TCPIPtciServer.ServerError(OnTCIServerError));
			_bTCIDelegatesAdded = true;
		}
	}

	private void removeTCIDelegates()
	{
		if (_bTCIDelegatesAdded)
		{
			TCPIPtciServer tcpTCIServer = m_tcpTCIServer;
			tcpTCIServer.ClientConnectedHandlers = (TCPIPtciServer.ClientConnected)Delegate.Remove(tcpTCIServer.ClientConnectedHandlers, new TCPIPtciServer.ClientConnected(OnTCIClientConnect));
			TCPIPtciServer tcpTCIServer2 = m_tcpTCIServer;
			tcpTCIServer2.ClientDisconnectedHandlers = (TCPIPtciServer.ClientDisconnected)Delegate.Remove(tcpTCIServer2.ClientDisconnectedHandlers, new TCPIPtciServer.ClientDisconnected(OnTCIClientDisconnect));
			TCPIPtciServer tcpTCIServer3 = m_tcpTCIServer;
			tcpTCIServer3.ClientErrorHandlers = (TCPIPtciServer.ClientError)Delegate.Remove(tcpTCIServer3.ClientErrorHandlers, new TCPIPtciServer.ClientError(OnTCIClientError));
			TCPIPtciServer tcpTCIServer4 = m_tcpTCIServer;
			tcpTCIServer4.ServerErrorHandlers = (TCPIPtciServer.ServerError)Delegate.Remove(tcpTCIServer4.ServerErrorHandlers, new TCPIPtciServer.ServerError(OnTCIServerError));
			_bTCIDelegatesAdded = false;
		}
	}

