	public void SetupTCI(bool bOn, int rateLimit)
	{
		if (bOn)
		{
			if (IPAddress.TryParse(m_sTCIAddress, out var address))
			{
				if (m_tcpTCIServer != null)
				{
					m_tcpTCIServer.StopServer();
					cmaster.TCIServer = null;
				}
				m_tcpTCIServer = new TCPIPtciServer(address, m_nTCIPort);
				cmaster.TCIServer = m_tcpTCIServer;
				addTCIDelegates();
				m_tcpTCIServer.StartServer(this, rateLimit);
				if (!m_tcpTCIServer.IsServerRunning)
				{
					if (!IsSetupFormNull)
					{
						SetupForm.DisableTCIServerDueToError();
					}
					removeTCIDelegates();
					MessageBox.Show("Unable to start the server." + Environment.NewLine + Environment.NewLine + "[ " + m_tcpTCIServer.LastError + " ]", "TCI Server", MessageBoxButtons.OK, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
				}
			}
		}
		else if (m_tcpTCIServer != null)
		{
			m_tcpTCIServer.CloseLog();
			m_tcpTCIServer.StopServer();
			cmaster.TCIServer = null;
			removeTCIDelegates();
		}
		UpdateStatusBarStatusIcons(StatusBarIconGroup.TCI);
	}

