	private void SyncDSP()
	{
		for (int i = 0; i < 2; i++)
		{
			for (int j = 0; j < 2; j++)
			{
				RadioDSPRX dSPRX = radio.GetDSPRX(i, j);
				dSPRX.Update = true;
				dSPRX.Force = true;
				dSPRX.BufferSize = dSPRX.BufferSize;
				dSPRX.Force = false;
			}
		}
		for (int k = 0; k < 1; k++)
		{
			RadioDSPTX dSPTX = radio.GetDSPTX(k);
			dSPTX.Update = true;
			dSPTX.Force = true;
			dSPTX.BufferSize = dSPTX.BufferSize;
			dSPTX.Force = false;
		}
		SetupForm.UpdateTXDisplayFFT();
		for (int l = 0; l < 2; l++)
		{
			for (int m = 0; m < 2; m++)
			{
				RadioDSPRX dSPRX2 = radio.GetDSPRX(l, m);
				dSPRX2.Update = false;
				dSPRX2.Force = true;
				dSPRX2.Update = true;
				dSPRX2.Force = false;
			}
		}
		for (int n = 0; n < 1; n++)
		{
			RadioDSPTX dSPTX2 = radio.GetDSPTX(n);
			dSPTX2.Update = false;
			dSPTX2.Force = true;
			dSPTX2.Update = true;
			dSPTX2.Force = false;
		}
	}

	public void ExitConsole()
	{
		shutdownLogStringToPath("Inside ExitConsole()");
		shutdownLogStringToPath("Before recorder/player stops");
		ARP.StopRecord(out var error);
		ARP.StopPlayback(out error);
		shutdownLogStringToPath("Before finder WriteXmlFinderFile()");
		if (_frmFinder != null)
		{
			_frmFinder.WriteXmlFinderFile(AppDataPath);
		}
		shutdownLogStringToPath("Before Midi2Cat.CloseMidi2Cat()");
		if (Midi2Cat != null)
		{
			Midi2Cat.CloseMidi2Cat();
		}
		shutdownLogStringToPath("Before N1MM.Stop()");
		N1MM.Stop();
		shutdownLogStringToPath("Before m_frmCWXForm.Close()");
		if (m_frmCWXForm != null)
		{
			m_frmCWXForm.Close();
		}
		shutdownLogStringToPath("Before n1mm_udp_client.Close()");
		if (n1mm_udp_client != null)
		{
			n1mm_udp_client.Close();
		}
		shutdownLogStringToPath("Before SetupForm.Dispose()");
		if (!IsSetupFormNull)
		{
			SetupForm.Dispose();
		}
		shutdownLogStringToPath("Before PA19.PA_Terminate()");
		PA19.PA_Terminate();
		shutdownLogStringToPath("Before DB.Exit()");
		DB.Exit();
		shutdownLogStringToPath("Before DBMan.Shutdown()");
		DBMan.Shutdown();
		shutdownLogStringToPath("Before NetworkIO.DestroyRNet()");
		NetworkIO.DestroyRNet();
		shutdownLogStringToPath("Before radio.Shutdown()");
		if (radio != null)
		{
			radio.Shutdown();
		}
		shutdownLogStringToPath("Before resume sleep/screensave");
		Common.ResumeSleep();
		Common.ResumeScreenSaver();
		shutdownLogStringToPath("Before Win32.TimeEndPeriod(1)");
		Win32.TimeEndPeriod(1u);
		Thread.Sleep(100);
		shutdownLogStringToPath("Before SingleInstance.release");
		SingleInstance.Release();
		shutdownLogStringToPath("Leaving ExitConsole()");
	}

