	public List<string> GetStateList()
	{
		List<string> list = new List<string>();
		list.Add(chkVFOLock.Name);
		list.Add(chkVFOBLock.Name);
		list.Add(chkVFOSync.Name);
		List<string> list2 = new List<string>();
		foreach (Control control in base.Controls)
		{
			if (control.GetType() == typeof(GroupBoxTS) || control.GetType() == typeof(PanelTS))
			{
				foreach (Control control2 in control.Controls)
				{
					addControlState(list2, control2, list, combo_use_items_count: true, print_not_saving: true);
				}
			}
			else
			{
				addControlState(list2, control, list, combo_use_items_count: false, print_not_saving: false);
