	private void addControlState(List<string> a, Control c, List<string> always_save, bool combo_use_items_count, bool print_not_saving)
	{
		if (!c.Enabled && !always_save.Contains(c.Name))
		{
			return;
		}
		if (c.GetType() == typeof(CheckBoxTS))
		{
			a.Add(c.Name + "/" + ((CheckBoxTS)c).Checked);
		}
		else if (c.GetType() == typeof(ComboBoxTS))
		{
			ComboBoxTS comboBoxTS = (ComboBoxTS)c;
			if (combo_use_items_count)
			{
				if (comboBoxTS.Items.Count > 0)
				{
					a.Add(c.Name + "/" + comboBoxTS.Text);
				}
			}
			else if (comboBoxTS.SelectedIndex >= 0)
			{
				a.Add(c.Name + "/" + comboBoxTS.Text);
			}
		}
		else if (c.GetType() == typeof(NumericUpDownTS))
		{
			a.Add(c.Name + "/" + ((NumericUpDownTS)c).Value);
		}
		else if (c.GetType() == typeof(RadioButtonTS))
		{
			a.Add(c.Name + "/" + ((RadioButtonTS)c).Checked);
		}
		else if (c.GetType() == typeof(TextBoxTS))
		{
			TextBoxTS textBoxTS = (TextBoxTS)c;
			if (!textBoxTS.ReadOnly)
			{
				a.Add(c.Name + "/" + textBoxTS.Text);
			}
		}
		else if (c.GetType() == typeof(TrackBarTS))
		{
			a.Add(c.Name + "/" + ((TrackBarTS)c).Value);
		}
		else if (c.GetType() == typeof(PrettyTrackBar))
		{
			a.Add(c.Name + "/" + ((PrettyTrackBar)c).Value);
		}
	}

	public void SaveState()
	{
		if (!DB.Merged)
		{
			if (_current_breakin_mode == BreakIn.QSK)
			{
				QSKEnabled = false;
			}
			chkPower.Checked = false;
			List<string> stateList = GetStateList();
			DB.PurgeNotches();
			DB.SaveVars("State", stateList);
		}
	}

	public void GetState()
	{
		bool flag = false;
		Point location = new Point(base.Top, base.Left);
		Size size = new Size(base.Width, base.Height);
		Dictionary<string, Control> dictionary = new Dictionary<string, Control>();
		foreach (Control control3 in base.Controls)
		{
			if (control3.GetType() == typeof(GroupBoxTS) || control3.GetType() == typeof(PanelTS))
			{
				foreach (Control control4 in control3.Controls)
				{
					dictionary.Add(control4.Name, control4);
				}
			}
			else
			{
				dictionary.Add(control3.Name, control3);
			}
		}
		List<string> vars = DB.GetVars("State");
		vars.Sort();
		List<KeyValuePair<string, string>> list = new List<KeyValuePair<string, string>>();
		double num = 7.1;
		double num2 = 7.1;
		double centreFrequency = 7.1;
		double centreRX2Frequency = 7.1;
		bool flag2 = false;
		bool flag3 = false;
		foreach (string item in vars)
		{
			string[] array = item.Split('/');
