	private void InitDisplayModes()
	{
		for (DisplayMode displayMode = DisplayMode.SPECTRUM; displayMode < DisplayMode.LAST; displayMode++)
		{
			string text = displayMode.ToString().ToLower();
			text = text.Substring(0, 1).ToUpper() + text.Substring(1, text.Length - 1);
			comboDisplayMode.Items.Add(text);
		}
		comboDisplayMode.Items.Add("Detach Panafall");
	}

	private void InitAGCModes()
	{
		for (AGCMode aGCMode = AGCMode.FIXD; aGCMode < AGCMode.LAST; aGCMode++)
		{
			string text = aGCMode.ToString().ToLower();
			text = text.Substring(0, 1).ToUpper() + text.Substring(1, text.Length - 1);
			comboAGC.Items.Add(text);
		}
		for (AGCMode aGCMode2 = AGCMode.FIXD; aGCMode2 < AGCMode.LAST; aGCMode2++)
		{
			string text2 = aGCMode2.ToString().ToLower();
			text2 = text2.Substring(0, 1).ToUpper() + text2.Substring(1, text2.Length - 1);
			comboRX2AGC.Items.Add(text2);
		}
	}

