	private void DisableAllFilters()
	{
		foreach (Control control in panelFilter.Controls)
		{
			if (control.GetType() == typeof(RadioButtonTS))
			{
				control.Enabled = false;
			}
		}
		filterToolStripMenuItem.Enabled = false;
	}

	private void DisableAllRX2Filters()
	{
		foreach (Control control in panelRX2Filter.Controls)
		{
			if (control.GetType() == typeof(RadioButtonTS))
			{
				control.Enabled = false;
			}
		}
	}

	private void EnableAllFilters()
	{
		foreach (Control control in panelFilter.Controls)
		{
			if (control.GetType() == typeof(RadioButtonTS))
			{
				control.Enabled = true;
				if (control.BackColor == vfo_text_dark_color)
				{
					control.BackColor = button_selected_color;
				}
			}
		}
		filterToolStripMenuItem.Enabled = true;
	}

	private void EnableAllRX2Filters()
	{
		foreach (Control control in panelRX2Filter.Controls)
		{
			if (control.GetType() == typeof(RadioButtonTS))
			{
				control.Enabled = true;
				if (control.BackColor == vfo_text_dark_color)
				{
					control.BackColor = button_selected_color;
				}
			}
		}
	}

	private void DisableAllBands()
	{
		foreach (Control control in panelBandHF.Controls)
		{
			control.Enabled = false;
			if (control is RadioButtonTS radioButtonTS && radioButtonTS.BackColor == button_selected_color)
			{
				radioButtonTS.BackColor = vfo_text_dark_color;
			}
		}
		foreach (Control control2 in panelBandVHF.Controls)
		{
			control2.Enabled = false;
			if (control2 is RadioButtonTS radioButtonTS2 && radioButtonTS2.BackColor == button_selected_color)
			{
				radioButtonTS2.BackColor = vfo_text_dark_color;
			}
		}
		foreach (Control control3 in panelBandGEN.Controls)
		{
			control3.Enabled = false;
			if (control3 is RadioButtonTS radioButtonTS3 && radioButtonTS3.BackColor == button_selected_color)
			{
				radioButtonTS3.BackColor = vfo_text_dark_color;
			}
		}
	}

	private void EnableAllBands()
	{
		foreach (Control control4 in panelBandHF.Controls)
		{
			if (control4 is RadioButtonTS radioButtonTS)
			{
				radioButtonTS.Enabled = control4 != radBand2 || XVTRPresent;
				if (radioButtonTS.BackColor == vfo_text_dark_color)
				{
					radioButtonTS.BackColor = button_selected_color;
				}
			}
			else
			{
				control4.Enabled = true;
			}
		}
		foreach (Control control5 in panelBandVHF.Controls)
		{
			if (control5 is RadioButtonTS radioButtonTS2)
			{
				if (radioButtonTS2.Name == "panelBandHF")
				{
					radioButtonTS2.Enabled = true;
				}
				else
				{
					int index = int.Parse(radioButtonTS2.Name.Substring(10));
					if (XVTRForm.GetEnabled(index))
					{
						radioButtonTS2.Enabled = true;
					}
				}
				if (radioButtonTS2.BackColor == vfo_text_dark_color)
				{
					radioButtonTS2.BackColor = button_selected_color;
				}
			}
			else
			{
				control5.Enabled = true;
			}
		}
		foreach (Control control6 in panelBandGEN.Controls)
		{
			if (control6 is RadioButtonTS radioButtonTS3)
			{
				radioButtonTS3.Enabled = true;
				if (radioButtonTS3.BackColor == vfo_text_dark_color)
				{
					radioButtonTS3.BackColor = button_selected_color;
				}
			}
			else
			{
				control6.Enabled = true;
			}
		}
	}

	private void DisableAllModes()
	{
		foreach (RadioButtonTS control in panelMode.Controls)
		{
			control.Enabled = false;
			if (control.BackColor == button_selected_color)
			{
				control.BackColor = vfo_text_dark_color;
			}
		}
	}

	private void EnableAllModes()
	{
		foreach (RadioButtonTS control in panelMode.Controls)
		{
			if (!string.IsNullOrEmpty(control.Text))
			{
				control.Enabled = true;
			}
			if (control.BackColor == vfo_text_dark_color)
			{
				control.BackColor = button_selected_color;
			}
		}
	}

	private void GetVFOCharWidth()
	{
		Graphics graphics = txtVFOAFreq.CreateGraphics();
		SizeF sizeF = measureStringFromCache("0", txtVFOAFreq.Font, 1000, StringFormat.GenericTypographic, graphics);
		vfo_char_width = (int)Math.Round(sizeF.Width - 2f, 0);
		float num = sizeF.Width - 2f;
