	public void SetBand(string mode, string filter, double freq, bool CTUN, int zoomFactor, double centerFreq)
	{
		Band rX1Band = RX1Band;
		DSPMode rX1DSPMode = RX1DSPMode;
		Filter rX1Filter = RX1Filter;
		double vFOAFreq = VFOAFreq;
		double centreFrequency = CentreFrequency;
		bool clickTuneDisplay = ClickTuneDisplay;
		int value = ptbDisplayZoom.Value;
		m_bSetBandRunning = true;
		RX1Band_changing_to = BandByFreq(freq, tx_xvtr_index, current_region);
		qsk_band_changing = true;
		RX1DSPMode = (DSPMode)Enum.Parse(typeof(DSPMode), mode, ignoreCase: true);
		if (_rx1_dsp_mode != DSPMode.DRM && _rx1_dsp_mode != DSPMode.SPEC)
		{
			RX1Filter = (Filter)Enum.Parse(typeof(Filter), filter, ignoreCase: true);
		}
		ClickTuneDisplay = false;
		chkFWCATU.Checked = ClickTuneDisplay;
		Zoom = zoomFactor;
		if (CTUN)
		{
			CentreFrequency = centerFreq;
			VFOAFreq = CentreFrequency;
		}
		ClickTuneDisplay = CTUN;
		chkFWCATU.Checked = ClickTuneDisplay;
		VFOAFreq = freq;
		qsk_band_changing = false;
		if (RX1Band_changing_to != rX1Band)
		{
			if (CurrentBreakInMode == BreakIn.QSK && !QSKEnabled)
			{
				QSKEnabled = true;
			}
			else if (CurrentBreakInMode != BreakIn.QSK && QSKEnabled)
			{
				rx1_agcm_by_band[(int)rX1Band] = non_qsk_agc;
				non_qsk_agc = rx1_agcm_by_band[(int)RX1Band_changing_to];
				QSKEnabled = false;
			}
			else if (CurrentBreakInMode == BreakIn.QSK && QSKEnabled)
			{
				rx1_agcm_by_band[(int)rX1Band] = non_qsk_agc;
				non_qsk_agc = rx1_agcm_by_band[(int)RX1Band_changing_to];
				RX1AGCMode = AGCMode.CUSTOM;
			}
			else if (CurrentBreakInMode != BreakIn.QSK && !QSKEnabled)
			{
				RX1AGCMode = rx1_agcm_by_band[(int)RX1Band_changing_to];
			}
		}
		else
		{
			if (CurrentBreakInMode == BreakIn.QSK && !QSKEnabled)
			{
				QSKEnabled = true;
			}
			else if (CurrentBreakInMode != BreakIn.QSK && QSKEnabled)
			{
				QSKEnabled = false;
			}
			else if (CurrentBreakInMode == BreakIn.QSK)
			{
				_ = QSKEnabled;
			}
			if (RX1DSPMode != DSPMode.CWL && RX1DSPMode != DSPMode.CWU && !QSKEnabled)
			{
				RX1AGCMode = non_qsk_agc;
			}
		}
		getButtonForBand(rX1Band).BackColor = SystemColors.Control;
		getButtonForBand(RX1Band).BackColor = button_selected_color;
		m_bSetBandRunning = false;
		if (rX1Band != RX1Band || vFOAFreq != VFOAFreq)
		{
			SetBandChangeHanders?.Invoke(1, rX1Band, RX1Band, rX1DSPMode, RX1DSPMode, rX1Filter, RX1Filter, vFOAFreq, VFOAFreq, centreFrequency, CentreFrequency, clickTuneDisplay, ClickTuneDisplay, value, ptbDisplayZoom.Value);
		}
	}

