	public Band RX1BandForVFOB()
	{
		if (XVTRForm != null)
		{
			double num = XVTRForm.TranslateFreq(VFOBFreq);
			if (VFOBFreq == num)
			{
				return BandByFreq(VFOBFreq, -1, current_region);
			}
			return BandByFreq(VFOBFreq, rx1_xvtr_index, current_region);
		}
		return BandByFreq(VFOBFreq, rx1_xvtr_index, current_region);
	}

	public Band GetTransverterTranslatedRXBand(double freq)
	{
		if (XVTRForm == null)
		{
			return Band.GEN;
		}
		double freq2 = XVTRForm.TranslateFreq(freq);
		return BandByFreq(freq2, -1, current_region);
	}

	public Band GetTransverterTranslatedTXBand()
	{
		if (XVTRForm == null)
		{
			return Band.GEN;
		}
		double freq = XVTRForm.TranslateFreq(TXFreq);
		return BandByFreq(freq, -1, current_region);
	}

	private Band BandByFreq(double freq, int xvtr_index, FRSRegion region)
	{
		if (xvtr_index >= 0)
		{
			return (Band)(14 + xvtr_index);
		}
		if (!BandStackManager.Ready)
		{
			return Band.GEN;
		}
		return BandStackManager.GetBandFrequencyDataForFrequency(freq, extended, region).First().band;
	}

	private void SetRX1Band(Band b)
	{
		if (!MOX || (!VFOATX && (rx2_enabled || !VFOBTX)))
		{
			if (disable_split_on_bandchange && RX1Band != b && !_tuning && chkVFOSplit.Checked)
			{
				chkVFOSplit.Checked = false;
			}
			Band num = rx1_band;
			RX1Band = b;
			if (num != b)
			{
				UpdateBandButtonColors();
				UpdateWaterfallLevelValues();
				updateDisplayGridLevelValues();
				UpdateDiversityValues();
			}
			if (rx1_xvtr_index >= 0)
			{
				setBandPanelVisible(gen: false, hf: false, vhf: true);
			}
			else
			{
				setBandPanelVisible(BandGENSelected, BandHFSelected, vhf: false);
			}
		}
	}

	private void SetRX2Band(Band b)
	{
		Band num = rx2_band;
		RX2Band = b;
		if (num != b)
		{
			UpdateBandButtonColors();
			UpdateWaterfallLevelValues();
			updateDisplayGridLevelValues();
		}
	}

	private void SetTXBand(Band b, bool bIngoreBandChange = false)
	{
		if (!MOX)
		{
			if (disable_split_on_bandchange && !bIngoreBandChange && TXBand != b && !_tuning && chkVFOSplit.Checked)
			{
				chkVFOSplit.Checked = false;
			}
			Band tx_band = _tx_band;
			TXBand = b;
			if (tx_band != b)
			{
				UpdateBandButtonColors();
			}
		}
	}

	private float GainByBand(Band b, int nDriveValue)
	{
		if (IsSetupFormNull)
		{
			return 1000f;
		}
		return SetupForm.GetPAGain(b, nDriveValue);
	}

	public void CheckSelectedButtonColor()
	{
		foreach (Control control3 in base.Controls)
		{
			if (control3.GetType() == typeof(GroupBoxTS))
			{
				foreach (Control control4 in ((GroupBoxTS)control3).Controls)
				{
					if (control4.GetType() == typeof(RadioButtonTS))
					{
						RadioButtonTS radioButtonTS = (RadioButtonTS)control4;
						if (radioButtonTS.Checked && radioButtonTS.BackColor != SystemColors.Control)
						{
							control4.BackColor = button_selected_color;
						}
					}
					else if (control4.GetType() == typeof(CheckBoxTS))
					{
						CheckBoxTS checkBoxTS = (CheckBoxTS)control4;
						if (checkBoxTS.Checked && checkBoxTS.BackColor != SystemColors.Control)
						{
							control4.BackColor = button_selected_color;
						}
					}
					else if (control4.GetType() == typeof(NumericUpDownTS))
					{
						if (((NumericUpDownTS)control4).BackColor != SystemColors.Window)
						{
							control4.BackColor = button_selected_color;
						}
					}
					else if (control4.GetType() == typeof(ButtonTS) && ((ButtonTS)control4).BackColor != SystemColors.Control)
					{
						control4.BackColor = button_selected_color;
					}
				}
			}
			else if (control3.GetType() == typeof(RadioButtonTS))
			{
				RadioButtonTS radioButtonTS2 = (RadioButtonTS)control3;
				if (radioButtonTS2.Checked && radioButtonTS2.BackColor != SystemColors.Control)
				{
					control3.BackColor = button_selected_color;
				}
			}
			else if (control3.GetType() == typeof(CheckBoxTS))
			{
				CheckBoxTS checkBoxTS2 = (CheckBoxTS)control3;
				if (checkBoxTS2.Checked && checkBoxTS2.BackColor != SystemColors.Control)
				{
					control3.BackColor = button_selected_color;
				}
			}
			else if (control3.GetType() == typeof(NumericUpDownTS))
			{
				if (((NumericUpDownTS)control3).BackColor != SystemColors.Window)
				{
					control3.BackColor = button_selected_color;
				}
			}
			else if (control3.GetType() == typeof(ButtonTS) && ((ButtonTS)control3).BackColor != SystemColors.Control)
			{
				control3.BackColor = button_selected_color;
			}
		}
	}

	private double PABandOffset(Band b)
	{
		return 0.0;
	}

	private double SWR(int adc_fwd, int adc_rev)
	{
		if (adc_fwd == 0 && adc_rev == 0)
		{
			return 1.0;
		}
		if (adc_rev > adc_fwd)
		{
			return 50.0;
		}
		double num = ScaledVoltage(adc_fwd);
		double num2 = ScaledVoltage(adc_rev);
		return (num + num2) / (num - num2);
	}

	private double ScaledVoltage(int adc)
	{
		return (double)adc * 0.062963 * 10.39853 * PABandOffset(_tx_band);
	}

	private double ADCtodBm(int adc_data)
	{
		if (adc_data == 0)
		{
			return 0.0;
		}
		double num = 100000.0 / Math.Pow(225.0 / PABandOffset(_tx_band), 2.0);
		return 10.0 * Math.Log10(num * Math.Pow(adc_data, 2.0));
	}

	private double PAPower(int adc)
	{
		return Math.Max(Math.Pow(ScaledVoltage(adc), 2.0) / 50.0, 0.0);
	}

	private double WattsTodBm(double watts)
	{
		return 10.0 * Math.Log10(watts / 0.001);
	}

	private double dBmToWatts(double dBm)
	{
		return Math.Pow(10.0, dBm / 10.0) * 0.001;
	}

	public float CalibratedPAPower()
	{
		float watts = alex_fwd;
		float num = 10f;
		float[] table = new float[11]
		{
			0f, SetupForm.PA10W, SetupForm.PA20W, SetupForm.PA30W, SetupForm.PA40W, SetupForm.PA50W, SetupForm.PA60W, SetupForm.PA70W, SetupForm.PA80W, SetupForm.PA90W,
			SetupForm.PA100W
		};
		switch (HardwareSpecific.Model)
		{
		case HPSDRModel.ANAN100D:
		{
			num = 10f;
			float[] table2 = new float[11]
			{
				0f, 11f, 24f, 35f, 46f, 57f, 67f, 81f, 90f, 103f,
				114f
			};
			watts = PowerKernel(watts, num, 11, table2);
			break;
		}
		case HPSDRModel.ANAN7000D:
		case HPSDRModel.ANAN_G2:
		case HPSDRModel.ANAN_G2_1K:
		case HPSDRModel.ANVELINAPRO3:
		case HPSDRModel.REDPITAYA:
			num = 10f;
			break;
		case HPSDRModel.ANAN8000D:
			num = 20f;
			break;
		case HPSDRModel.ANAN10:
		case HPSDRModel.ANAN10E:
			num = 1f;
			break;
		default:
			num = 10f;
			break;
		}
		return PowerKernel(watts, num, 11, table);
	}

	private float PowerKernel(float watts, float interval, int entries, float[] table)
	{
		int i = 0;
		if (watts > table[entries - 1])
		{
			i = entries - 2;
		}
		else
		{
			for (; watts > table[i]; i++)
			{
			}
			if (i > 0)
			{
				i--;
			}
		}
		float num = (watts - table[i]) / (table[i + 1] - table[i]);
		return interval * ((1f - num) * (float)i + num * (float)(i + 1));
	}

	public bool CheckValidTXFreq(FRSRegion r, double f, DSPMode mode, bool bIgnoreFilter = false)
	{
		if (extended || tx_xvtr_index > -1)
		{
			return true;
		}
		bool result = false;
		int num = ((!bIgnoreFilter) ? Display.TXFilterLow : 0);
		int num2 = ((!bIgnoreFilter) ? Display.TXFilterHigh : 0);
		switch (mode)
		{
		case DSPMode.LSB:
		case DSPMode.USB:
		case DSPMode.DSB:
		case DSPMode.FM:
		case DSPMode.AM:
		case DSPMode.DIGU:
		case DSPMode.SPEC:
		case DSPMode.DIGL:
		case DSPMode.SAM:
			result = checkValidTXFreq_local(r, f + (double)num * 1E-06) && checkValidTXFreq_local(r, f + (double)num2 * 1E-06);
			break;
		case DSPMode.CWL:
		case DSPMode.CWU:
			result = checkValidTXFreq_local(r, f);
			break;
		case DSPMode.DRM:
			result = checkValidTXFreq_local(r, f - 0.012 + (double)num * 1E-06) && checkValidTXFreq_local(r, f - 0.012 + (double)num2 * 1E-06);
			break;
		}
		return result;
	}

	private bool checkValidTXFreq_local(FRSRegion r, double f)
	{
		if (extended || tx_xvtr_index > -1)
		{
			return true;
		}
		f = Math.Round(f, 6);
		return BandStackManager.IsOKToTX(f, extended, r);
	}

