	public void UpdateRX1Filters(int low, int high, bool force = false, bool from_change_event = false)
	{
		if (_ignore_rx1_filter_update)
		{
			return;
		}
		int num;
		int num2;
		if (!filterAndDspModeValid(1))
		{
			num = 0;
			num2 = 0;
		}
		else
		{
			num = rx1_filters[(int)_rx1_dsp_mode].GetLow(rx1_filter);
			num2 = rx1_filters[(int)_rx1_dsp_mode].GetHigh(rx1_filter);
		}
		switch (_rx1_dsp_mode)
		{
		case DSPMode.LSB:
		case DSPMode.CWL:
		case DSPMode.DIGL:
			if (low > high - 10)
			{
				low = high - 10;
			}
			break;
		case DSPMode.USB:
		case DSPMode.CWU:
		case DSPMode.DIGU:
			if (high < low + 10)
			{
				high = low + 10;
			}
			break;
		case DSPMode.DSB:
		case DSPMode.AM:
		case DSPMode.SPEC:
		case DSPMode.SAM:
			if (high < low + 10)
			{
				if (Math.Abs(high) < Math.Abs(low))
				{
					high = low + 10;
				}
				else
				{
					low = high - 10;
				}
			}
			break;
		case DSPMode.FM:
		{
			int num3 = (int)(radio.GetDSPRX(0, 0).RXFMDeviation + radio.GetDSPRX(0, 0).RXFMHighCut);
			int num4 = num3 * 2 / 1000;
			low = -num3;
			high = num3;
			lblFilterLabel.Text = num4 + "k";
			break;
		}
		}
		clampFilterMinMax(1, _rx1_dsp_mode == DSPMode.FM, low, high);
		ConstrainFilter(ref low, ref high, 1);
		if (low == high)
		{
			return;
		}
		radio.GetDSPRX(0, 0).SetRXFilter(low, high);
		radio.GetDSPRX(0, 1).SetRXFilter(low, high);
		Display.RX1FilterLow = low;
		Display.RX1FilterHigh = high;
		if (!from_change_event)
		{
			if (udFilterLow.Value == (decimal)low)
			{
				udFilterLow_ValueChanged(this, EventArgs.Empty);
			}
			else
			{
				udFilterLow.Value = low;
			}
			if (udFilterHigh.Value == (decimal)high)
			{
				udFilterHigh_ValueChanged(this, EventArgs.Empty);
			}
			else
			{
				udFilterHigh.Value = high;
			}
		}
		ptbFilterShift_Update(low, high);
		ptbFilterWidth_Update(low, high);
		if (!radio.GetDSPRX(0, 0).SpectrumPreFilter)
		{
			UpdateRXDisplayVars(low, high);
		}
		if (high - low > 250)
		{
			udXIT.Increment = 10m;
			udRIT.Increment = 10m;
		}
		else
		{
			udXIT.Increment = 5m;
			udRIT.Increment = 5m;
		}
		if (filterRX1Form != null && !filterRX1Form.IsDisposed && filterRX1Form.DSPMode == _rx1_dsp_mode)
		{
			filterRX1Form.CurrentFilter = rx1_filter;
		}
		if (filterAndDspModeValid(1) && (force || num != low || num2 != high))
		{
			FilterEdgesChangedHandlers?.Invoke(1, rx1_filter, RX1Band, low, high, rx1_filters[(int)_rx1_dsp_mode].GetName(rx1_filter), _max_filter_width, _max_filter_shift);
		}
		m_nLowOutRX1 = low;
		m_nHighOutRX1 = high;
	}

	public void UpdateRX2Filters(int low, int high, bool force = false, bool from_change_event = false)
	{
		if (_ignore_rx2_filter_update)
		{
			return;
		}
		int num;
		int num2;
		if (!filterAndDspModeValid(2))
		{
			num = 0;
			num2 = 0;
		}
		else
		{
			num = rx2_filters[(int)_rx2_dsp_mode].GetLow(rx2_filter);
			num2 = rx2_filters[(int)_rx2_dsp_mode].GetHigh(rx2_filter);
		}
		switch (_rx2_dsp_mode)
		{
		case DSPMode.LSB:
		case DSPMode.CWL:
		case DSPMode.DIGL:
			if (low > high - 10)
			{
				low = high - 10;
			}
			break;
		case DSPMode.USB:
		case DSPMode.CWU:
		case DSPMode.DIGU:
			if (high < low + 10)
			{
				high = low + 10;
			}
			break;
		case DSPMode.DSB:
		case DSPMode.AM:
		case DSPMode.SPEC:
		case DSPMode.SAM:
			if (high < low + 10)
			{
				if (Math.Abs(high) < Math.Abs(low))
				{
					high = low + 10;
				}
				else
				{
					low = high - 10;
				}
			}
			break;
		case DSPMode.FM:
		{
			int num3 = (int)(radio.GetDSPRX(1, 0).RXFMDeviation + radio.GetDSPRX(1, 0).RXFMHighCut);
			low = -num3;
			high = num3;
			break;
		}
		}
		clampFilterMinMax(2, _rx2_dsp_mode == DSPMode.FM, low, high);
		ConstrainFilter(ref low, ref high, 2);
		if (low == high)
		{
			return;
		}
		radio.GetDSPRX(1, 0).SetRXFilter(low, high);
		radio.GetDSPRX(1, 1).SetRXFilter(low, high);
		Display.RX2FilterLow = low;
		Display.RX2FilterHigh = high;
		if (!from_change_event)
		{
			if (udRX2FilterLow.Value == (decimal)low)
			{
				udRX2FilterLow_ValueChanged(this, EventArgs.Empty);
			}
			else
			{
				udRX2FilterLow.Value = low;
			}
			if (udRX2FilterHigh.Value == (decimal)high)
			{
				udRX2FilterHigh_ValueChanged(this, EventArgs.Empty);
			}
			else
			{
				udRX2FilterHigh.Value = high;
			}
		}
		if (filterRX2Form != null && !filterRX2Form.IsDisposed && filterRX2Form.DSPMode == _rx2_dsp_mode)
		{
			filterRX2Form.CurrentFilter = rx2_filter;
		}
		if (filterAndDspModeValid(2) && (force || num != low || num2 != high))
		{
			FilterEdgesChangedHandlers?.Invoke(2, rx2_filter, RX2Band, low, high, rx2_filters[(int)_rx2_dsp_mode].GetName(rx2_filter), _max_filter_width, _max_filter_shift);
		}
		m_nLowOutRX2 = low;
		m_nHighOutRX2 = high;
	}

