	private bool sioPut(object sio_listener, string msg)
	{
		if (sio_listener == null)
		{
			return false;
		}
		bool result = false;
		try
		{
			if (!(sio_listener is SIOListenerII sIOListenerII))
			{
				if (!(sio_listener is SIO2ListenerII sIO2ListenerII))
				{
					if (!(sio_listener is SIO3ListenerII sIO3ListenerII))
					{
						if (sio_listener is SIO4ListenerII { SIO4: not null } sIO4ListenerII && sIO4ListenerII.SIO4.IsOpen)
						{
							sIO4ListenerII.SIO4.put(msg);
							result = true;
						}
					}
					else if (sIO3ListenerII.SIO3 != null && sIO3ListenerII.SIO3.IsOpen)
					{
						sIO3ListenerII.SIO3.put(msg);
						result = true;
					}
				}
				else if (sIO2ListenerII.SIO2 != null && sIO2ListenerII.SIO2.IsOpen)
				{
					sIO2ListenerII.SIO2.put(msg);
					result = true;
				}
			}
			else if (sIOListenerII.SIO != null && sIOListenerII.SIO.IsOpen)
			{
				sIOListenerII.SIO.put(msg);
				result = true;
			}
		}
		catch
		{
		}
		return result;
	}

