	private void UpdateRXDisplayVars(int l, int h)
	{
		if (Display.CurrentDisplayMode == DisplayMode.SPECTRUM || Display.CurrentDisplayMode == DisplayMode.HISTOGRAM || Display.CurrentDisplayMode == DisplayMode.SPECTRASCOPE)
		{
			int num = 0;
			int num2 = 0;
			int bufferSize = radio.GetDSPRX(0, 0).BufferSize;
			switch (_rx1_dsp_mode)
			{
			case DSPMode.LSB:
				num = l - 1000;
				num2 = 0;
				break;
			case DSPMode.CWL:
			case DSPMode.DIGL:
				num = l - 500;
				num2 = 0;
				break;
			case DSPMode.USB:
				num = 0;
				num2 = h + 1000;
				break;
			case DSPMode.CWU:
			case DSPMode.DIGU:
				num = 0;
				num2 = h + 500;
				break;
			default:
				num = l - 1000;
				num2 = h + 1000;
				break;
			}
			Display.RXSpectrumDisplayLow = num;
			Display.RXSpectrumDisplayHigh = num2;
			specRX.GetSpecRX(0).CalcSpectrum(num, num2, bufferSize, 48000);
		}
	}

	private void UpdateTXDisplayVars(int l, int h)
	{
		if (Display.CurrentDisplayMode == DisplayMode.SPECTRUM || Display.CurrentDisplayMode == DisplayMode.HISTOGRAM || Display.CurrentDisplayMode == DisplayMode.SPECTRASCOPE)
		{
			int num = 0;
			int num2 = 0;
			int bufferSize = radio.GetDSPTX(0).BufferSize;
			if (l < 0 && h <= 0)
			{
				num2 = 0;
				num = ((l < -910) ? ((int)((double)l * 1.1)) : (-1000));
			}
			else if (l >= 0 && h > 0)
			{
				num = 0;
				num2 = ((h > 910) ? ((int)((double)h * 1.1)) : 1000);
			}
			else if (l < 0 && h > 0)
			{
				int num3 = Math.Max(-l, h);
				num = (int)((double)num3 * -1.1);
				num2 = (int)((double)num3 * 1.1);
			}
			Display.TXSpectrumDisplayLow = num;
			Display.TXSpectrumDisplayHigh = num2;
			specRX.GetSpecRX(cmaster.inid(1, 0)).CalcSpectrum(num, num2, bufferSize, 96000);
		}
	}

	public void UpdateTXLowHighFilterForMode(DSPMode mode, ref int low, ref int high)
	{
		int num = 0;
		int num2 = 0;
		switch (mode)
		{
		case DSPMode.LSB:
		case DSPMode.CWL:
		case DSPMode.DIGL:
			num = -high;
			num2 = -low;
			break;
		case DSPMode.USB:
		case DSPMode.CWU:
		case DSPMode.DIGU:
			num = low;
			num2 = high;
			break;
		case DSPMode.DSB:
			num = -high;
			num2 = high;
			break;
		case DSPMode.AM:
		case DSPMode.SAM:
			num = -high;
			num2 = high;
			break;
		case DSPMode.FM:
		{
			int num3 = (int)(radio.GetDSPTX(0).TXFMDeviation + radio.GetDSPTX(0).TXFMHighCut);
			num = -num3;
			num2 = num3;
			break;
		}
		case DSPMode.DRM:
			num = 7000;
			num2 = 17000;
			break;
		}
		low = num;
		high = num2;
	}

	public void SetTXFilters(DSPMode mode, int low, int high, bool force = false)
	{
		int tXFilterLow = radio.GetDSPTX(0).TXFilterLow;
		int tXFilterHigh = radio.GetDSPTX(0).TXFilterHigh;
		UpdateTXLowHighFilterForMode(mode, ref low, ref high);
		DisplayMode currentDisplayMode = Display.CurrentDisplayMode;
		if (currentDisplayMode != DisplayMode.PANADAPTER && currentDisplayMode != DisplayMode.WATERFALL && (uint)(currentDisplayMode - 8) > 1u)
		{
			UpdateTXDisplayVars(low, high);
		}
		radio.GetDSPTX(0).SetTXFilter(low, high);
		if (mode == DSPMode.FM)
		{
			radio.GetDSPTX(0).Force = true;
			radio.GetDSPTX(0).TXFMLowCut = radio.GetDSPTX(0).TXFMLowCut;
			radio.GetDSPTX(0).TXFMHighCut = radio.GetDSPTX(0).TXFMHighCut;
			radio.GetDSPTX(0).Force = false;
		}
		Display.TXFilterLow = low;
		Display.TXFilterHigh = high;
		if (force || tXFilterLow != low || tXFilterHigh != high)
		{
			TXFiltersChangedHandlers?.Invoke(low, high);
		}
	}

