	public void UpdateTXProfile(string name)
	{
		if (!IsSetupFormNull)
		{
			string text = comboTXProfile.Text;
			string text2 = comboDigTXProfile.Text;
			string text3 = comboFMTXProfile.Text;
			string text4 = comboAMTXProfile.Text;
			BuildTXProfileCombos();
			switch (_rx1_dsp_mode)
			{
			case DSPMode.DIGU:
			case DSPMode.DIGL:
				comboDigTXProfile.Text = name;
				comboTXProfile.Text = text;
				comboFMTXProfile.Text = text3;
				comboAMTXProfile.Text = text4;
				break;
			case DSPMode.FM:
				comboFMTXProfile.Text = name;
				comboDigTXProfile.Text = text2;
				comboTXProfile.Text = text;
				comboAMTXProfile.Text = text4;
				break;
			case DSPMode.AM:
			case DSPMode.SAM:
				comboAMTXProfile.Text = name;
				comboDigTXProfile.Text = text2;
				comboTXProfile.Text = text;
				comboFMTXProfile.Text = text3;
				break;
			default:
				comboTXProfile.Text = name;
				comboDigTXProfile.Text = text2;
				comboFMTXProfile.Text = text3;
				comboAMTXProfile.Text = text4;
				break;
			}
			if (string.IsNullOrEmpty(comboTXProfile.Text))
			{
				comboTXProfile.Text = "Default";
			}
			if (string.IsNullOrEmpty(comboDigTXProfile.Text))
			{
				comboDigTXProfile.Text = "Default";
			}
			if (string.IsNullOrEmpty(comboFMTXProfile.Text))
			{
				comboFMTXProfile.Text = "Default";
			}
			if (string.IsNullOrEmpty(comboAMTXProfile.Text))
			{
				comboAMTXProfile.Text = "Default";
			}
		}
	}

	public void UpdateDDCs(bool rx2_enabled)
	{
		if (initializing)
		{
			return;
		}
		int num = 0;
		int num2 = 1;
		int num3 = 2;
		int num4 = 4;
		int num5 = 8;
		int sync = 0;
		int[] array = new int[8];
		int sampleRateRX = SampleRateRX1;
		int sampleRateRX2 = SampleRateRX2;
		int pSrate = cmaster.PSrate;
		int ddcconfig = 0;
		int en_diversity = 0;
		int rxcount = 0;
		int nddc = 0;
		int aDC_cntrl = 0;
		int aDC_cntrl2 = 0;
		bool flag = NetworkIO.CurrentRadioProtocol == RadioProtocol.USB;
		bool pSEnabled = psform.PSEnabled;
		bool diversity = Diversity2;
		if (diversity)
		{
			en_diversity = 1;
		}
		switch (HardwareSpecific.Model)
		{
		case HPSDRModel.ANAN100D:
		case HPSDRModel.ANAN200D:
		case HPSDRModel.ORIONMKII:
		case HPSDRModel.ANAN7000D:
		case HPSDRModel.ANAN8000D:
		case HPSDRModel.ANAN_G2:
		case HPSDRModel.ANAN_G2_1K:
		case HPSDRModel.ANVELINAPRO3:
			rxcount = 5;
			nddc = 5;
			if (!_mox)
			{
				if (diversity)
				{
					ddcconfig = (num = num2);
					sync = num3;
					array[0] = sampleRateRX;
					array[1] = sampleRateRX;
					aDC_cntrl = rx_adc_ctrl1 & 0xFF;
					aDC_cntrl2 = rx_adc_ctrl2 & 0x3F;
				}
				else
				{
					ddcconfig = 1;
					num = num4;
