					aDC_cntrl2 = rx_adc_ctrl2 & 0x3F;
				}
				else
				{
					ddcconfig = 1;
					num = num4;
					sync = 0;
					array[0] = sampleRateRX;
					array[1] = sampleRateRX;
					array[2] = sampleRateRX;
					aDC_cntrl = rx_adc_ctrl1 & 0xFF;
					aDC_cntrl2 = rx_adc_ctrl2 & 0x3F;
				}
			}
			else if (!diversity && !pSEnabled)
			{
				ddcconfig = 1;
				num = num4;
				sync = 0;
				array[0] = sampleRateRX;
				array[1] = sampleRateRX;
				array[2] = sampleRateRX;
				aDC_cntrl = rx_adc_ctrl1 & 0xFF;
				aDC_cntrl2 = rx_adc_ctrl2 & 0x3F;
			}
			else if (!diversity & pSEnabled)
			{
				ddcconfig = 3;
				num = num2 + num4;
				sync = num3;
				array[0] = pSrate;
				array[1] = pSrate;
				array[2] = sampleRateRX;
				aDC_cntrl = (rx_adc_ctrl1 & 0xF3) | 8;
				aDC_cntrl2 = rx_adc_ctrl2 & 0x3F;
			}
			else if (diversity & pSEnabled)
			{
				ddcconfig = 3;
				num = num2 + num4;
				sync = num3;
				array[0] = pSrate;
				array[1] = pSrate;
				array[2] = sampleRateRX;
				aDC_cntrl = (rx_adc_ctrl1 & 0xF3) | 8;
				aDC_cntrl2 = rx_adc_ctrl2 & 0x3F;
			}
			else
			{
				ddcconfig = 2;
				num = num2;
				sync = num3;
				array[0] = sampleRateRX;
				array[1] = sampleRateRX;
