			}
			if (rx2_enabled)
			{
				num += num5;
				array[3] = sampleRateRX2;
			}
			break;
		case HPSDRModel.HERMES:
		case HPSDRModel.ANAN10:
		case HPSDRModel.ANAN100:
		case HPSDRModel.ANAN_G2E:
			rxcount = 4;
			nddc = 4;
			if (!_mox)
			{
				if (!diversity)
				{
					ddcconfig = 4;
					num = num2;
					sync = 0;
					array[0] = sampleRateRX;
					aDC_cntrl = 0;
					aDC_cntrl2 = 0;
					if (rx2_enabled)
					{
						num += num3;
						array[1] = sampleRateRX2;
					}
				}
				else
				{
					ddcconfig = 5;
					num = num2;
					sync = num3;
					array[0] = sampleRateRX;
					array[1] = sampleRateRX;
					aDC_cntrl = 0;
					aDC_cntrl2 = 0;
				}
			}
			else if (!diversity && !pSEnabled)
			{
				ddcconfig = 4;
				num = num2;
				sync = 0;
				array[0] = sampleRateRX;
				aDC_cntrl = 0;
				aDC_cntrl2 = 0;
				if (rx2_enabled)
				{
					num += num3;
					array[1] = sampleRateRX2;
				}
			}
			else if (diversity && !pSEnabled)
			{
				ddcconfig = 5;
				num = num2;
				sync = num3;
				array[0] = sampleRateRX;
				array[1] = sampleRateRX;
				aDC_cntrl = 0;
				aDC_cntrl2 = 0;
			}
			else
			{
				ddcconfig = 6;
				num = num2;
				sync = num3;
				array[0] = pSrate;
				array[1] = pSrate;
				aDC_cntrl = 4;
				aDC_cntrl2 = 0;
			}
			break;
		case HPSDRModel.ANAN10E:
		case HPSDRModel.ANAN100B:
			rxcount = 2;
			nddc = 2;
			if (!_mox)
			{
				if (!diversity)
				{
					ddcconfig = 4;
					num = num2;
					sync = 0;
					array[0] = sampleRateRX;
					aDC_cntrl = 0;
					aDC_cntrl2 = 0;
					if (rx2_enabled)
					{
						num += num3;
						array[1] = sampleRateRX2;
					}
				}
				else
				{
					ddcconfig = 5;
					num = num2;
					sync = num3;
					array[0] = sampleRateRX;
					array[1] = sampleRateRX;
					aDC_cntrl = 0;
					aDC_cntrl2 = 0;
				}
			}
			else if (!diversity && !pSEnabled)
			{
				ddcconfig = 4;
				num = num2;
				sync = 0;
				array[0] = sampleRateRX;
				aDC_cntrl = 0;
				aDC_cntrl2 = 0;
				if (rx2_enabled)
				{
					num += num3;
					array[1] = sampleRateRX2;
				}
			}
			else if (diversity && !pSEnabled)
			{
				ddcconfig = 5;
				num = num2;
				sync = num3;
