				aDC_cntrl = 0;
				aDC_cntrl2 = 0;
			}
			else
			{
				ddcconfig = 5;
				num = num2;
				sync = num3;
				array[0] = pSrate;
				array[1] = pSrate;
				aDC_cntrl = 4;
				aDC_cntrl2 = 0;
			}
			break;
		}
		NetworkIO.EnableRxs(num);
		NetworkIO.EnableRxSync(0, sync);
		for (int i = 0; i < 4; i++)
		{
			NetworkIO.SetDDCRate(i, array[i]);
		}
		NetworkIO.SetADC_cntrl1(aDC_cntrl);
		NetworkIO.SetADC_cntrl2(aDC_cntrl2);
		NetworkIO.CmdRx();
		NetworkIO.Protocol1DDCConfig(ddcconfig, en_diversity, rxcount, nddc);
		if (!IsSetupFormNull)
		{
			SetupForm.UpdateDDCTab();
		}
	}

	public void GetDDC(out int DDCrx1, out int DDCrx2, out int DDCsync1, out int DDCsync2, out int DDCpsrx, out int DDCpstx)
	{
		int num = -1;
		int num2 = -1;
		int num3 = -1;
		int num4 = -1;
		int num5 = -1;
		int num6 = -1;
		bool num7 = MOX;
		int num8 = ((diversityForm != null && Diversity2) ? 1 : 0);
		int num9 = (psform.PSEnabled ? 1 : 0);
		int num10 = (num7 ? 1 : 0) + (num8 << 1) + (num9 << 2);
		if (NetworkIO.CurrentRadioProtocol == RadioProtocol.ETH)
		{
			switch (HardwareSpecific.Hardware)
			{
			case HPSDRHW.Angelia:
			case HPSDRHW.Orion:
			case HPSDRHW.OrionMKII:
			case HPSDRHW.Saturn:
				switch (num10)
				{
				case 0:
					num = 2;
					num2 = 3;
					break;
				case 1:
					num = 2;
					num2 = 3;
					break;
				case 2:
					num3 = 0;
					num4 = 1;
					num2 = 3;
					break;
				case 3:
					num3 = 0;
					num4 = 1;
					num2 = 3;
					break;
				case 4:
					num = 2;
					num2 = 3;
					break;
				case 5:
					num = 2;
					num2 = 3;
					break;
				case 6:
					num3 = 0;
					num4 = 1;
					num2 = 3;
					break;
				case 7:
					num = 2;
					num2 = 3;
					break;
				}
				break;
			case HPSDRHW.Hermes:
			case HPSDRHW.HermesII:
			case HPSDRHW.HermesC10:
				switch (num10)
				{
				case 0:
					num = 0;
					num2 = 1;
					break;
				case 1:
					num = 0;
					num2 = 1;
					break;
				case 2:
					num3 = 0;
					num4 = 1;
					break;
				case 3:
					num3 = 0;
					num4 = 1;
					break;
				case 4:
					num = 0;
					num2 = 1;
					break;
				case 6:
					num3 = 0;
					num4 = 1;
					break;
				}
				break;
			}
		}
		else if (NetworkIO.CurrentRadioProtocol == RadioProtocol.USB)
		{
			switch (HardwareSpecific.Hardware)
			{
			case HPSDRHW.Angelia:
			case HPSDRHW.Orion:
			case HPSDRHW.OrionMKII:
				switch (num10)
				{
				case 0:
					num = 0;
					num2 = 2;
					break;
				case 1:
					num = 0;
					num2 = 2;
					break;
				case 2:
					num3 = 0;
					num4 = 1;
					num2 = 2;
					break;
				case 3:
					num3 = 0;
					num4 = 1;
					num2 = 2;
					break;
				case 4:
					num = 0;
					num2 = 2;
					break;
				case 5:
					num = 0;
					num2 = 2;
					num5 = 3;
					num6 = 4;
					break;
				case 6:
					num3 = 0;
					num4 = 1;
					num2 = 2;
					break;
				case 7:
					num3 = 0;
					num4 = 1;
					num2 = 2;
					num5 = 3;
					num6 = 4;
					break;
				}
				break;
			case HPSDRHW.Hermes:
			case HPSDRHW.HermesC10:
				switch (num10)
				{
				case 0:
					num = 0;
					num2 = 1;
					break;
				case 1:
					num = 0;
					num2 = 1;
					break;
				case 2:
					num = 0;
					num2 = 1;
					break;
				case 3:
					num = 0;
					num2 = 1;
					break;
				case 4:
					num = 0;
					num2 = 1;
					break;
				case 5:
					num = 0;
					num2 = 1;
					num5 = 2;
					num6 = 3;
					break;
				case 6:
					num = 0;
					num2 = 1;
					break;
				case 7:
					num = 0;
					num2 = 1;
					num5 = 2;
					num6 = 3;
					break;
				}
				break;
			case HPSDRHW.HermesII:
				switch (num10)
				{
				case 0:
					num = 0;
					num2 = 1;
					break;
				case 1:
					num = 0;
					num2 = 1;
					break;
				case 2:
					num = 0;
					num2 = 1;
					break;
				case 3:
					num = 0;
					num2 = 1;
					break;
				case 4:
					num = 0;
					num2 = 1;
					break;
				case 5:
					num5 = 0;
					num6 = 1;
					break;
				case 6:
					num = 0;
					num2 = 1;
					break;
				case 7:
					num5 = 0;
					num6 = 1;
					break;
				}
				break;
			}
		}
		if (diversityForm != null && Diversity2)
		{
			switch (diversityForm.EXTDIVOutput)
			{
			case 0:
			case 2:
				if (num3 != -1)
				{
					num = num3;
				}
				break;
			case 1:
				if (num4 != -1)
				{
					num = num4;
				}
				break;
			}
		}
		if (!MOX && num == -1 && num5 != -1)
		{
			num = num5;
		}
		if (MOX && num == -1 && num6 != -1)
		{
			num = num6;
		}
		if (num2 == -1)
		{
			num2 = num;
		}
		DDCrx1 = num;
		DDCrx2 = num2;
		DDCsync1 = num3;
		DDCsync2 = num4;
		DDCpsrx = num5;
		DDCpstx = num6;
	}

