	public bool RX1IsIn60m()
	{
		double vFOAFreq = VFOAFreq;
		if (vFOAFreq >= 5.1)
		{
			return vFOAFreq <= 5.5;
		}
		return false;
	}

	public bool RX1IsOn60mChannel(Channel c)
	{
		double value = VFOAFreq - ModeFreqOffset(_rx1_dsp_mode);
		value = Math.Round(value, 6);
		return c.Freq == value;
	}

	public bool RX1IsIn60mChannel(Channel c)
	{
		double vFOAFreq = VFOAFreq;
		vFOAFreq = Math.Round(vFOAFreq, 6);
		if (vFOAFreq >= c.Low)
		{
			return vFOAFreq <= c.High;
		}
		return false;
	}

	public bool RX1IsIn60mChannel()
	{
		foreach (Channel item in Channels60m)
		{
			if (RX1IsIn60mChannel(item))
			{
				return true;
			}
		}
		return false;
	}

	public bool RX1IsOn60mChannel()
	{
		foreach (Channel item in Channels60m)
		{
			if (RX1IsOn60mChannel(item))
			{
				return true;
			}
		}
		return false;
	}

