	private double ModeFreqOffset(DSPMode mode)
	{
		switch (mode)
		{
		case DSPMode.LSB:
		case DSPMode.DIGL:
			return 0.0015;
		case DSPMode.USB:
		case DSPMode.DIGU:
		case DSPMode.DRM:
			return -0.0015;
		case DSPMode.DSB:
		case DSPMode.CWL:
		case DSPMode.CWU:
		case DSPMode.FM:
		case DSPMode.AM:
		case DSPMode.SAM:
			return 0.0;
		default:
			return 0.0;
		}
	}

	public string CATGetXVTRBandNames()
	{
		string text = "";
		for (int i = 0; i < 14; i++)
		{
			text = ((!XVTRForm.GetEnabled(i)) ? (text + "     ") : (text + vhf_text[i].Text.ToString().PadLeft(5, ' ')));
