	public string GetFilterPresets(int mode_ndx)
	{
		string text = "";
		for (Filter filter = Filter.F1; filter < Filter.NONE; filter++)
		{
			text += rx1_filters[mode_ndx].GetName(filter).PadLeft(5, ' ');
			text += rx1_filters[mode_ndx].GetHigh(filter).ToString().PadLeft(5, ' ');
			text += rx1_filters[mode_ndx].GetLow(filter).ToString().PadLeft(5, ' ');
		}
		return text;
	}

