	public unsafe bool CalibrateFreq(float freq)
	{
		if (!chkPower.Checked)
		{
			MessageBox.Show("Power must be on in order to calibrate Frequency.", "Power Is Off", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			return false;
		}
		bool gridMinFollowsNFRX = GridMinFollowsNFRX1;
		GridMinFollowsNFRX1 = false;
		calibration_running = true;
		SetupForm.HPSDRFreqCorrectFactorViaAutoCalibration = 1.0;
		string s = txtVFOAFreq.Text;
		bool flag = chkRIT.Checked;
		chkRIT.Checked = false;
		int rITValue = (int)udRIT.Value;
		udRIT.Value = 0m;
		VFOAFreq = freq;
		int val = (int)((float)specRX.GetSpecRX(0).FFTSize / (float)specRX.GetSpecRX(0).SampleRate * 1000f + 500f);
		val = Math.Max(1000, val);
		Thread.Sleep(val);
		int ss = 0;
		int fFTSize = specRX.GetSpecRX(0).FFTSize;
		double[,] array = new double[fFTSize, 2];
		double[] array2 = new double[fFTSize];
		_spectrum_mutex.WaitOne();
		for (int i = 0; i < 10; i++)
		{
			fixed (double* snap_buff = &array[0, 0])
			{
				SpecHPSDRDLL.SnapSpectrum(0, ss, 0, snap_buff);
			}
			for (int j = 0; j < fFTSize; j++)
			{
				array2[j] += array[j, 0] * array[j, 0] + array[j, 1] * array[j, 1];
			}
			Thread.Sleep(50);
		}
		_spectrum_mutex.ReleaseMutex();
		double num = (double)sample_rate_rx1 / (double)fFTSize;
		int num2 = (int)(2500.0 / num);
		double num3 = double.MinValue;
		int num4 = 0;
		for (int k = fFTSize / 2 - num2; k <= fFTSize / 2 + num2; k++)
		{
			if (array2[k] > num3)
			{
				num3 = array2[k];
				num4 = k;
			}
		}
		double num5 = num * (double)(fFTSize / 2 - num4);
		double hPSDRFreqCorrectFactorViaAutoCalibration = 1.0 - num5 / ((double)freq * 1000000.0);
		SetupForm.HPSDRFreqCorrectFactorViaAutoCalibration = hPSDRFreqCorrectFactorViaAutoCalibration;
		SetupForm.RXOnly = _rx_only;
		chkRIT.Checked = flag;
		RITValue = rITValue;
		VFOAFreq = float.Parse(s);
		calibration_running = false;
		GridMinFollowsNFRX1 = gridMinFollowsNFRX;
		return true;
	}

