	public bool LowPowerPASweep(Progress progress, int power)
	{
		bool result = false;
		if (!chkPower.Checked)
		{
			MessageBox.Show("Power must be on in order to run PA Sweep.", "Power Is Off", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			return false;
		}
		calibrating = true;
		DSPMode rX1DSPMode = RX1DSPMode;
		RX1DSPMode = DSPMode.USB;
		double vFOAFreq = VFOAFreq;
		int pWR = PWR;
		PWR = power;
		progress.SetPercent(0f);
		float[] array = new float[10] { 1.9f, 3.75f, 5.3715f, 7.15f, 10.125f, 14.175f, 18.1f, 21.225f, 24.9f, 28.85f };
		int num = 0;
		while (true)
		{
			if (num < array.Length)
			{
				VFOAFreq = array[num];
				Audio.TXInputSignal = Audio.SignalSource.SINE;
				Audio.SourceScale = 1.0;
				chkMOX.Checked = true;
				for (int i = 0; i < 30; i++)
				{
					Thread.Sleep(100);
					if (!progress.Visible)
					{
						goto end_IL_0121;
					}
				}
				chkMOX.Checked = false;
				Audio.TXInputSignal = Audio.SignalSource.RADIO;
				if (!progress.Visible)
				{
					break;
				}
				for (int j = 0; j < 40; j++)
				{
					Thread.Sleep(100);
					if (!progress.Visible)
					{
						goto end_IL_0121;
					}
				}
				if (!progress.Visible)
				{
					break;
				}
				progress.SetPercent((float)(num + 1) / 10f);
				num++;
				continue;
			}
			result = true;
			break;
			continue;
			end_IL_0121:
			break;
		}
		progress.Hide();
		chkMOX.Checked = false;
		Audio.TXInputSignal = Audio.SignalSource.RADIO;
		RX1DSPMode = rX1DSPMode;
		VFOAFreq = vFOAFreq;
		txtVFOAFreq_LostFocus(this, EventArgs.Empty);
		PWR = pWR;
		calibrating = false;
		return result;
	}

