	public void SetAFLinks(int source, bool state)
	{
		if (source >= 0 && source <= 3)
		{
			_masterAFLink[source] = state;
			int value = 0;
			switch (source)
			{
			case 0:
				value = AF;
				break;
			case 1:
				value = RX0Gain;
				break;
			case 2:
				value = RX1Gain;
				break;
			case 3:
				value = RX2Gain;
				break;
			}
			setLinkedAF(source, value);
		}
	}

	public bool IsMasterAFLinked(int rx)
	{
		if (rx < 0 || rx > 3)
		{
			return false;
		}
		return _masterAFLink[rx];
	}

	private void setLinkedAF(int source, int value)
	{
		if ((!IsSetupFormNull && SetupForm.LinkAFSlidersOnlyIfCtrlHeld && !Common.CtrlKeyDown) || source < 0 || source > 3 || _settingLinked)
		{
			return;
		}
		_settingLinked = true;
		if (!_mox && _masterAFLink[source])
		{
			if (_masterAFLink[0])
			{
				AF = value;
			}
			if (_masterAFLink[1])
			{
				RX0Gain = value;
			}
			if (_masterAFLink[2])
			{
				RX1Gain = value;
			}
			if (_masterAFLink[3])
			{
				RX2Gain = value;
			}
		}
		_settingLinked = false;
	}

