	public void SafeTXProfileSet(string profile)
	{
		ComboBox comboBox = null;
		switch (_rx1_dsp_mode)
		{
		case DSPMode.DIGU:
		case DSPMode.DIGL:
			comboBox = comboDigTXProfile;
			break;
		case DSPMode.FM:
			comboBox = comboFMTXProfile;
			break;
		case DSPMode.AM:
		case DSPMode.SAM:
			comboBox = comboAMTXProfile;
			break;
		default:
			comboBox = comboTXProfile;
			break;
		}
		if (comboBox == null || string.IsNullOrEmpty(profile))
		{
			return;
		}
		for (int i = 0; i < comboBox.Items.Count; i++)
		{
			object obj = comboBox.Items[i];
			if (obj != null && string.Equals(obj.ToString(), profile, StringComparison.Ordinal))
			{
				TXProfile = profile;
				break;
			}
		}
	}

	private void setCWSideToneVolume()
	{
		int num = 0;
		if (_cw_sidetones)
		{
			if (_cw_hw_sidetone || _cw_sw_sidetone)
			{
				num = (qsk_enabled ? ((!_cw_sw_sidetone) ? ((int)((double)qsk_sidetone_volume * 1.27)) : 0) : ((_current_breakin_mode != BreakIn.Manual) ? ((int)((double)txaf * 1.27)) : ((int)((double)txaf * 0.73))));
			}
			if (_cw_hw_sidetone)
			{
				NetworkIO.SetCWSidetoneVolume(num);
			}
			else
			{
				NetworkIO.SetCWSidetoneVolume(0);
			}
			if (_cw_sw_sidetone)
			{
				NetworkIO.SetSidetoneVolume(0, (float)num / 100f);
			}
			else
			{
				NetworkIO.SetSidetoneVolume(0, 0.0);
			}
		}
		else
		{
			NetworkIO.SetCWSidetoneVolume(0);
			NetworkIO.SetSidetoneVolume(0, 0.0);
		}
	}

