		NetworkIO.FWVersionsChecked = false;
		switch (HardwareSpecific.Model)
		{
		case HPSDRModel.HERMES:
			chkDX.Checked = false;
			chkDX.Visible = false;
			_rx2_preamp_present = false;
			break;
		case HPSDRModel.ANAN10:
			chkDX.Checked = false;
			chkDX.Visible = false;
			_rx2_preamp_present = false;
			break;
		case HPSDRModel.ANAN10E:
			chkDX.Checked = false;
			chkDX.Visible = false;
			_rx2_preamp_present = false;
			break;
		case HPSDRModel.ANAN100:
			chkDX.Checked = false;
			chkDX.Visible = false;
			_rx2_preamp_present = false;
			break;
		case HPSDRModel.ANAN100B:
			chkDX.Checked = false;
			chkDX.Visible = false;
			_rx2_preamp_present = false;
			break;
		case HPSDRModel.ANAN100D:
			chkDX.Visible = false;
			_rx2_preamp_present = true;
			break;
		case HPSDRModel.ANAN200D:
			chkDX.Visible = false;
			_rx2_preamp_present = true;
			break;
		case HPSDRModel.ORIONMKII:
			chkDX.Visible = false;
			_rx2_preamp_present = true;
			break;
		case HPSDRModel.ANAN7000D:
			chkDX.Visible = false;
			_rx2_preamp_present = true;
			break;
		case HPSDRModel.ANAN8000D:
			chkDX.Visible = false;
			_rx2_preamp_present = true;
			break;
		case HPSDRModel.ANAN_G2E:
			chkDX.Visible = false;
			_rx2_preamp_present = false;
			break;
		case HPSDRModel.ANAN_G2:
			chkDX.Visible = false;
			_rx2_preamp_present = true;
			break;
		case HPSDRModel.ANAN_G2_1K:
			chkDX.Visible = false;
			_rx2_preamp_present = true;
			break;
		case HPSDRModel.ANVELINAPRO3:
			chkDX.Visible = false;
			_rx2_preamp_present = true;
			break;
		case HPSDRModel.REDPITAYA:
			chkDX.Visible = false;
			_rx2_preamp_present = true;
			break;
		}
		RX2PreampPresent = _rx2_preamp_present;
		switch (HardwareSpecific.Model)
		{
		case HPSDRModel.HERMES:
		case HPSDRModel.ANAN10:
		case HPSDRModel.ANAN10E:
		case HPSDRModel.ANAN100:
		case HPSDRModel.ANAN100B:
		case HPSDRModel.ANAN100D:
		case HPSDRModel.ANAN200D:
		case HPSDRModel.ORIONMKII:
		case HPSDRModel.ANAN7000D:
		case HPSDRModel.ANAN8000D:
		case HPSDRModel.ANAN_G2:
		case HPSDRModel.ANAN_G2_1K:
		case HPSDRModel.ANVELINAPRO3:
		case HPSDRModel.REDPITAYA:
		case HPSDRModel.ANAN_G2E:
			if (!comboMeterTXMode.Items.Contains("Ref Pwr"))
			{
				comboMeterTXMode.Items.Insert(1, "Ref Pwr");
			}
			if (!comboMeterTXMode.Items.Contains("SWR"))
			{
				comboMeterTXMode.Items.Insert(2, "SWR");
			}
			if (!comboMeterTXMode.Items.Contains("Fwd SWR"))
			{
				comboMeterTXMode.Items.Insert(3, "Fwd SWR");
			}
			break;
		}
		SetComboPreampForHPSDR();
		UpdateDDCs(rx2_enabled);
		if (!initializing)
		{
			RX1MeterCalOffset = rx_meter_cal_offset_by_radio[HardwareSpecific.ModelInt];
			RX1DisplayCalOffset = rx_display_cal_offset_by_radio[HardwareSpecific.ModelInt];
			RX2MeterCalOffset = rx_meter_cal_offset_by_radio[HardwareSpecific.ModelInt];
			RX2DisplayCalOffset = rx_display_cal_offset_by_radio[HardwareSpecific.ModelInt];
		}
		if (!IsSetupFormNull && HardwareSpecific.OldModel != HardwareSpecific.Model)
		{
			txtVFOAFreq_LostFocus(this, EventArgs.Empty);
		}
		cmaster.CMSetTXOutputLevelRun();
		CurrentModelChangedHandlers?.Invoke(HardwareSpecific.OldModel, HardwareSpecific.Model);
	}

