	public int GetADCInUse(int ddc)
	{
		if (ddc < 0 || ddc > 7)
		{
			return -1;
		}
		int num = 0;
		if (NetworkIO.CurrentRadioProtocol == RadioProtocol.ETH)
		{
			num = ((ddc < 4) ? RXADCCtrl1 : RXADCCtrl2);
			if (ddc >= 4)
			{
				ddc -= 4;
			}
		}
		else
		{
			if (NetworkIO.CurrentRadioProtocol != RadioProtocol.USB)
			{
				return -1;
			}
			num = RXADCCtrl_P1;
		}
		int num2 = 3 << ddc * 2;
		return (num & num2) >> ddc * 2;
	}

	public void SetWavePlayback(int id, bool enabled)
	{
		if (id < 0 || id > _wave_playback.Length - 1)
		{
			return;
		}
		_wave_playback[id] = enabled;
		switch (id)
		{
		case 0:
			_wave_playback_frequency[id] = VFOAFreq * 1000000.0 % (double)sample_rate_rx1;
			txtVFOAFreq_LostFocus(this, EventArgs.Empty);
			break;
		case 1:
			_wave_playback_frequency[id] = VFOBFreq * 1000000.0 % (double)sample_rate_rx2;
			if (RX2Enabled)
			{
				txtVFOBFreq_LostFocus(this, EventArgs.Empty);
			}
			break;
		}
	}

	private bool getWavePlayback(int id)
	{
		if (id < 0 || id > _wave_playback.Length - 1)
		{
			return false;
		}
		return _wave_playback[id];
	}

	public double getWavePlaybackFreq(int id)
	{
		if (id < 0 || id > _wave_playback.Length - 1)
		{
			return 0.0;
		}
		return _wave_playback_frequency[id];
	}

	private void UpdateRX1DDSFreq()
	{
		if (!initializing)
		{
			setAlex1HPF(_rx1_dds_freq);
			UpdateAlexTXFilter();
			UpdateAlexRXFilter();
			Display.CentreFreqRX1 = rx1_dds_freq_mhz;
			HPSDRModel model = HardwareSpecific.Model;
			if ((uint)(model - 1) <= 4u || model == HPSDRModel.ANAN_G2E)
			{
				NetworkIO.VFOfreq(0, rx1_dds_freq_mhz, 0);
				return;
			}
			NetworkIO.VFOfreq(0, rx1_dds_freq_mhz, 0);
			NetworkIO.VFOfreq(1, rx1_dds_freq_mhz, 0);
			NetworkIO.VFOfreq(2, rx1_dds_freq_mhz, 0);
		}
	}

	private void UpdateRX2DDSFreq()
	{
		if (!initializing)
		{
			UpdateAlexTXFilter();
			UpdateAlexRXFilter();
			Display.CentreFreqRX2 = rx2_dds_freq_mhz;
			if (HardwareSpecific.Model == HPSDRModel.ORIONMKII || HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.REDPITAYA)
			{
				setAlex2HPF(rx2_dds_freq_mhz);
			}
			HPSDRModel model = HardwareSpecific.Model;
			if ((uint)(model - 1) <= 4u || model == HPSDRModel.ANAN_G2E)
			{
				NetworkIO.VFOfreq(1, rx2_dds_freq_mhz, 0);
			}
			else
			{
				NetworkIO.VFOfreq(3, rx2_dds_freq_mhz, 0);
			}
		}
	}

	private void UpdateTXDDSFreq()
	{
		if (initializing)
		{
			return;
		}
		setAlexLPF(tx_dds_freq_mhz, freqIsTX: true);
		if (_mox)
		{
			setAlex1HPF(_rx1_dds_freq);
		}
		if (MOX)
		{
			if (RX2Enabled && VFOBTX)
			{
				Display.CentreFreqRX2 = tx_dds_freq_mhz;
			}
			else
			{
				Display.CentreFreqRX1 = tx_dds_freq_mhz;
			}
		}
		NetworkIO.VFOfreq(0, tx_dds_freq_mhz, 1);
	}

	private void UpdateAlexTXFilter()
	{
		if (_mox)
		{
			return;
		}
		if (!_rx2_preamp_present && chkRX2.Checked)
		{
			if (rx1_dds_freq_mhz > rx2_dds_freq_mhz)
			{
				setAlexLPF(rx1_dds_freq_mhz, freqIsTX: false);
			}
			else
			{
				setAlexLPF(rx2_dds_freq_mhz, freqIsTX: false);
			}
		}
		else
		{
			setAlexLPF(rx1_dds_freq_mhz, freqIsTX: false);
		}
	}

	private void UpdateAlexRXFilter()
	{
		if (!_mox && !_rx2_preamp_present && chkRX2.Checked)
		{
			if (rx1_dds_freq_mhz < rx2_dds_freq_mhz)
			{
				setAlex1HPF(rx1_dds_freq_mhz);
			}
			else
			{
				setAlex1HPF(rx2_dds_freq_mhz);
			}
		}
	}

	public string ThreadSafeCatParse(string msg)
	{
		if (base.IsDisposed)
		{
			return "";
		}
		if (base.InvokeRequired)
		{
			return (string)Invoke((Func<string>)(() => safeCat(msg)));
		}
		return safeCat(msg);
	}

	private string safeCat(string msg)
	{
		if (m_objTCPIPCatParser == null)
		{
			m_objTCPIPCatParser = new CATParser(this);
		}
		lock (m_objCatParseLocker)
		{
			return m_objTCPIPCatParser.Get(msg);
		}
	}

