		case "VHF12":
			text = "VHF13";
			text2 = "VHF11";
			break;
		case "VHF13":
			text = "GEN";
			text2 = "VHF12";
			break;
		}
		if (text.StartsWith("VHF"))
		{
			int index = Convert.ToInt32(text.Substring(3));
			if (!XVTRForm.GetEnabled(index))
			{
				text = "GEN";
			}
		}
		if (text2.StartsWith("VHF"))
		{
			int num = Convert.ToInt32(text2.Substring(3));
			if (num != 0)
			{
				if (num > 0)
				{
					for (int num2 = num - 1; num2 >= 0; num2--)
					{
						if (XVTRForm.GetEnabled(num2))
						{
							text2 = "VHF" + num2;
							break;
						}
						text2 = "WWV";
					}
				}
				else
				{
					text2 = "WWV";
				}
			}
		}
		string s = ((direction != 1) ? text2 : text);
		BandStackFilter filter = BandStackManager.GetFilter(BandStackManager.StringToBand(s));
		if (filter != null)
		{
			BandStackEntry bandStackEntry = filter.First();
			if (bandStackEntry == null)
			{
				bandStackEntry = filter.LastVisited.Copy();
				bandStackEntry.Band = BandStackManager.StringToBand(s);
			}
			if (bandStackEntry != null)
			{
				RX2DSPMode = bandStackEntry.Mode;
				RX2Filter = bandStackEntry.Filter;
				VFOBFreq = bandStackEntry.Frequency;
			}
		}
		btnHidden.Focus();
	}

