	public bool SetTXFilter(Filter filter)
	{
		if (filter == Filter.FIRST || filter == Filter.NONE || filter == Filter.LAST)
		{
			return false;
		}
		int low = 0;
		int high = 0;
		DSPMode dSPMode = DSPMode.LAST;
		switch ((!RX2Enabled || !VFOBTX) ? 1 : 2)
		{
		case 1:
			low = rx1_filters[(int)_rx1_dsp_mode].GetLow(filter);
			high = rx1_filters[(int)_rx1_dsp_mode].GetHigh(filter);
			dSPMode = RX1DSPMode;
			break;
		case 2:
			low = rx2_filters[(int)_rx1_dsp_mode].GetLow(filter);
			high = rx2_filters[(int)_rx1_dsp_mode].GetHigh(filter);
			dSPMode = RX2DSPMode;
			break;
		}
		if (dSPMode == DSPMode.LAST)
		{
			return false;
		}
		UpdateTXLowHighFilterForMode(dSPMode, ref low, ref high);
		TXFilterLow = low;
		TXFilterHigh = high;
		_tx_filter = filter;
		return true;
	}

	public int GetDSPcwPitchShiftToZero(int rx)
	{
		int result = 0;
		switch (rx)
		{
		case 1:
			if (RX1DSPMode == DSPMode.CWL)
			{
				result = CWPitch;
			}
			else if (RX1DSPMode == DSPMode.CWU)
			{
				result = -CWPitch;
			}
			break;
		case 2:
			if (RX2DSPMode == DSPMode.CWL)
			{
				result = CWPitch;
			}
			else if (RX2DSPMode == DSPMode.CWU)
			{
				result = -CWPitch;
			}
			break;
		}
		return result;
	}

