	public float RXPreampOffset(int rx)
	{
		if (_ignore_attenuator_offset)
		{
			return 0f;
		}
		if (rx == 1)
		{
			return _rx1_step_att_enabled ? ((float)_rx1_attenuator_data) : rx1_preamp_offset[(int)rx1_preamp_mode];
		}
		if (_rx2_preamp_present || HardwareSpecific.Model == HPSDRModel.ANAN100D || HardwareSpecific.Model == HPSDRModel.ANAN200D || HardwareSpecific.Model == HPSDRModel.ORIONMKII || HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.REDPITAYA)
		{
			return _rx2_step_att_enabled ? ((float)rx2_attenuator_data) : rx2_preamp_offset[(int)rx2_preamp_mode];
		}
		return _rx1_step_att_enabled ? ((float)_rx1_attenuator_data) : rx1_preamp_offset[(int)rx1_preamp_mode];
	}

	public float RXCalibrationOffset(int rx)
	{
		float num;
		if (rx == 1)
		{
			num = _rx1_meter_cal_offset + _rx1_xvtr_gain_offset + _rx1_6m_gain_offset;
		}
		else
		{
			num = _rx2_meter_cal_offset + _rx2_xvtr_gain_offset;
			if (HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.REDPITAYA)
			{
				num += _rx2_6m_gain_offset;
			}
		}
		return num;
	}

	public float RXOffset(int rx)
	{
		return RXPreampOffset(rx) + RXCalibrationOffset(rx);
	}

	public double RXPBsnr(int rx)
	{
		float num = RXOffset(rx);
		if (rx == 1)
		{
			if (!Display.FastAttackNoiseFloorRX1 && _lastRX1NoiseFloorGood)
			{
				float num2 = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.AVG_SIGNAL_STRENGTH) + num;
				return spectralCalculations(1, num2).estimated_snr;
			}
			return -999.0;
		}
		if (!Display.FastAttackNoiseFloorRX2 && _lastRX2NoiseFloorGood)
		{
			float num3 = WDSP.CalculateRXMeter(2u, 0u, WDSP.MeterType.AVG_SIGNAL_STRENGTH) + num;
			return spectralCalculations(2, num3).estimated_snr;
		}
		return -999.0;
	}

	private SpectralResult spectralCalculations(int rx, double signal)
	{
		SpectralResult result = new SpectralResult
		{
			estimated_snr = 0.0
		};
		if (rx == 1)
		{
			result.bin_width = (double)specRX.GetSpecRX(0).SampleRate / (double)specRX.GetSpecRX(0).FFTSize;
			result.rbw = specRX.GetSpecRX(0).DisplayENB * result.bin_width;
			result.passband_bandwidth = Display.RX1FilterHigh - Display.RX1FilterLow;
			result.noise_floor_power_spectral_density = (double)_lastRX1NoiseFloor - 10.0 * Math.Log10(result.rbw);
			result.estimated_passband_noise_power = result.noise_floor_power_spectral_density + 10.0 * Math.Log10(result.passband_bandwidth);
			if (!MOX)
			{
				result.estimated_snr = signal - result.estimated_passband_noise_power + m_fRX1_PBSNR_shift;
			}
			else
			{
				result.estimated_snr = -999.0;
			}
		}
		else
		{
			result.bin_width = (double)specRX.GetSpecRX(1).SampleRate / (double)specRX.GetSpecRX(1).FFTSize;
			result.rbw = specRX.GetSpecRX(1).DisplayENB * result.bin_width;
			result.passband_bandwidth = Display.RX2FilterHigh - Display.RX2FilterLow;
			result.noise_floor_power_spectral_density = (double)_lastRX2NoiseFloor - 10.0 * Math.Log10(result.rbw);
			result.estimated_passband_noise_power = result.noise_floor_power_spectral_density + 10.0 * Math.Log10(result.passband_bandwidth);
			if (!MOX)
			{
				result.estimated_snr = signal - result.estimated_passband_noise_power + m_fRX2_PBSNR_shift;
			}
			else
			{
				result.estimated_snr = -999.0;
			}
		}
		result.rx_dBHz = 10.0 * Math.Log10(result.passband_bandwidth);
		result.rbw_dBHz = 10.0 * Math.Log10(result.rbw);
		return result;
	}

	private async void checkOverloadsAndSync()
	{
		string sWarning = "";
		bool red_warning = false;
		bool flag = true;
		_have_sync = NetworkIO.getHaveSync() == 1;
		if (!_have_sync)
		{
			if (chkPower.Checked)
			{
				chkPower.Checked = false;
			}
			if (_had_radio_sync)
			{
				sWarning = "Lost Radio Sync   ";
				_had_radio_sync = false;
				flag = false;
			}
		}
		else if (!_had_radio_sync)
		{
			_had_radio_sync = true;
		}
		if (amp_protect && cmaster.GetAndResetAmpProtect(0) == 1)
		{
			ptbPWR.Value -= 2;
			ptbPWR_Scroll(this, EventArgs.Empty);
			await Task.Delay(100);
			cmaster.GetAndResetAmpProtect(0);
			sWarning += "AMP Overload  ";
			flag = false;
		}
		string[] array = new string[3] { "ADC0", "ADC1", "ADC2" };
		int num;
		try
		{
			num = NetworkIO.getAndResetADC_Overload();
		}
		catch
		{
			num = -1;
		}
		if (_check_for_bad_adc && num == -1)
		{
			MessageBox.Show("There has been an issue obtaining the ADC overload state. This will not be performed until the power is turned off/on inside Thetis.", "ADC Overload Issue", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			_check_for_bad_adc = false;
		}
		if (!_check_for_bad_adc)
		{
			return;
		}
		for (int i = 0; i < 3; i++)
		{
			_adc_overloaded[i] = ((num >> i) & 1) != 0;
			if (_adc_overloaded[i])
			{
				_adc_overload_level[i]++;
				if (_adc_overload_level[i] > 5)
				{
					_adc_overload_level[i] = 5;
				}
				red_warning = red_warning || _adc_overload_level[i] > 3;
			}
			else
			{
				_adc_overload_level[i]--;
				if (_adc_overload_level[i] < 0)
				{
					_adc_overload_level[i] = 0;
				}
			}
			if (_adc_overload_level[i] > 0)
			{
				sWarning = sWarning + array[i] + " Overload   ";
			}
		}
		if (!string.IsNullOrEmpty(sWarning))
		{
			sWarning = sWarning.Trim();
			infoBar.Warning(sWarning, red_warning, flag ? 1000 : 2000);
		}
		handleOverload();
	}

	private void keep_att_entries_for_band(Stack<HistoricAttenuatorReading> readings_stack, Band target_band)
	{
		if (readings_stack == null || readings_stack.Count == 0)
		{
			return;
		}
		List<HistoricAttenuatorReading> list = new List<HistoricAttenuatorReading>();
		while (readings_stack.Count > 0)
		{
			HistoricAttenuatorReading historicAttenuatorReading = readings_stack.Pop();
			if (historicAttenuatorReading.band == target_band)
			{
				list.Add(historicAttenuatorReading);
			}
		}
		for (int num = list.Count - 1; num >= 0; num--)
		{
			readings_stack.Push(list[num]);
		}
	}

	private void handleOverload()
	{
		for (int i = 0; i < 3; i++)
		{
			if (_adc_overloaded[i])
			{
				_adc_step_shift[i]++;
				if (_adc_step_shift[i] > 31)
				{
					_adc_step_shift[i] = 31;
				}
			}
			else if (_adc_step_shift[i] > 0)
			{
				_adc_step_shift[i]--;
			}
		}
		if (_auto_attTX_when_not_in_ps)
		{
			if (psform != null && !psform.AutoCalEnabled)
			{
				if (_mox)
				{
					if (_adc_overloaded[0] && _adc_overload_level[0] > 3)
					{
						HistoricAttenuatorReading historicAttenuatorReading = new HistoricAttenuatorReading();
						historicAttenuatorReading.stepAttenuator = TxAttenData;
						int num = historicAttenuatorReading.stepAttenuator + _adc_step_shift[0];
						if (num > 31)
						{
							num = 31;
						}
						if (num != historicAttenuatorReading.stepAttenuator)
						{
							if (!ATTOnTX)
							{
								ATTOnTX = true;
							}
							TxAttenData = num;
							_historic_attenuator_readings_tx.Push(historicAttenuatorReading);
							if (RX2Enabled && VFOBTX)
							{
								AutoAttAppliedRX2 = true;
							}
							else
							{
								AutoAttAppliedRX1 = true;
							}
						}
					}
				}
				else if (_historic_attenuator_readings_tx.Any())
				{
					HistoricAttenuatorReading historicAttenuatorReading2 = _historic_attenuator_readings_tx.Pop();
					if (_auto_undoTXatt && historicAttenuatorReading2 != null && historicAttenuatorReading2.stepAttenuator != TxAttenData)
					{
						TxAttenData = historicAttenuatorReading2.stepAttenuator;
					}
					if (RX2Enabled && VFOBTX)
					{
						AutoAttAppliedRX2 = _historic_attenuator_readings_tx.Any();
					}
					else
					{
						AutoAttAppliedRX1 = _historic_attenuator_readings_tx.Any();
					}
				}
			}
			else if (_historic_attenuator_readings_tx.Any())
			{
				_historic_attenuator_readings_tx.Clear();
				if (RX2Enabled && VFOBTX)
				{
					AutoAttAppliedRX2 = false;
				}
				else
				{
					AutoAttAppliedRX1 = false;
				}
			}
		}
		else if (_historic_attenuator_readings_tx.Any())
		{
			_historic_attenuator_readings_tx.Clear();
		}
		if (_mox)
		{
			return;
		}
		if (!_auto_att_rx1 && _historic_attenuator_readings_rx1.Any())
		{
			_historic_attenuator_readings_rx1.Clear();
			AutoAttAppliedRX1 = false;
		}
		if (!_auto_att_rx2 && _historic_attenuator_readings_rx2.Any())
		{
			_historic_attenuator_readings_rx2.Clear();
			AutoAttAppliedRX2 = false;
		}
		if (!_auto_att_rx1 && !_auto_att_rx2)
		{
			return;
		}
		keep_att_entries_for_band(_historic_attenuator_readings_rx1, RX1Band);
		keep_att_entries_for_band(_historic_attenuator_readings_rx2, RX2Band);
		if (_historic_attenuator_readings_rx1.Count == 0 && AutoAttAppliedRX1)
		{
			AutoAttAppliedRX1 = false;
		}
		if (_historic_attenuator_readings_rx2.Count == 0 && AutoAttAppliedRX2)
		{
			AutoAttAppliedRX2 = false;
		}
		int DDCrx = -1;
		int DDCrx2 = -1;
		int DDCsync = -1;
		int DDCsync2 = -1;
		int DDCpsrx = -1;
		int DDCpstx = -1;
		GetDDC(out DDCrx, out DDCrx2, out DDCsync, out DDCsync2, out DDCpsrx, out DDCpstx);
		DateTime utcNow = DateTime.UtcNow;
		bool flag = HardwareSpecific.Model == HPSDRModel.ANAN10 || HardwareSpecific.Model == HPSDRModel.ANAN10E || HardwareSpecific.Model == HPSDRModel.ANAN100 || HardwareSpecific.Model == HPSDRModel.ANAN100B || HardwareSpecific.Model == HPSDRModel.ANAN100D || HardwareSpecific.Model == HPSDRModel.ANAN200D || HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.REDPITAYA;
		if (_auto_att_rx1 & flag)
		{
			int aDCInUse = GetADCInUse(DDCrx);
			if ((_adc_overloaded[0] && _adc_overload_level[0] > 3 && aDCInUse == 0) || (_adc_overloaded[1] && _adc_overload_level[1] > 3 && aDCInUse == 1))
			{
				HistoricAttenuatorReading historicAttenuatorReading3 = new HistoricAttenuatorReading();
				historicAttenuatorReading3.band = RX1Band;
				if (_rx1_step_att_enabled)
				{
					historicAttenuatorReading3.stepAttenuator = RX1AttenuatorData;
					int num2 = historicAttenuatorReading3.stepAttenuator + (_adc_overloaded[0] ? _adc_step_shift[0] : _adc_step_shift[1]);
					if (num2 > 31)
					{
						num2 = 31;
					}
					if (num2 != historicAttenuatorReading3.stepAttenuator)
					{
						RX1AttenuatorData = num2;
						_auto_att_last_hold_time_rx1 = utcNow;
						_historic_attenuator_readings_rx1.Push(historicAttenuatorReading3);
						AutoAttAppliedRX1 = true;
					}
				}
				else
				{
					historicAttenuatorReading3.preampMode = RX1PreampMode;
					PreampMode preampMode = historicAttenuatorReading3.preampMode;
					switch (preampMode)
					{
					case PreampMode.HPSDR_OFF:
					case PreampMode.HPSDR_ON:
						preampMode = PreampMode.SA_MINUS10;
						break;
					case PreampMode.SA_MINUS10:
						preampMode = PreampMode.SA_MINUS20;
						break;
					case PreampMode.SA_MINUS20:
						preampMode = PreampMode.SA_MINUS30;
						break;
					}
					if (preampMode != historicAttenuatorReading3.preampMode)
					{
						RX1PreampMode = preampMode;
						_auto_att_last_hold_time_rx1 = utcNow;
						_historic_attenuator_readings_rx1.Push(historicAttenuatorReading3);
						AutoAttAppliedRX1 = true;
					}
				}
			}
			else if ((aDCInUse == 0 || aDCInUse == 1) && _historic_attenuator_readings_rx1.Any() && (!_auto_att_undo_rx1 || (_auto_att_undo_rx1 && (utcNow - _auto_att_last_hold_time_rx1).TotalSeconds >= (double)_auto_att_hold_delay_rx1)))
			{
				HistoricAttenuatorReading historicAttenuatorReading4 = _historic_attenuator_readings_rx1.Pop();
				if (historicAttenuatorReading4 != null && _auto_att_undo_rx1)
				{
					if (_rx1_step_att_enabled && historicAttenuatorReading4.stepAttenuator != -1)
					{
						if (historicAttenuatorReading4.stepAttenuator != RX1AttenuatorData)
						{
							RX1AttenuatorData = historicAttenuatorReading4.stepAttenuator;
						}
					}
					else if (historicAttenuatorReading4.preampMode != PreampMode.FIRST && historicAttenuatorReading4.preampMode != RX1PreampMode)
					{
						RX1PreampMode = historicAttenuatorReading4.preampMode;
					}
				}
				_auto_att_last_hold_time_rx1 = utcNow;
				AutoAttAppliedRX1 = _historic_attenuator_readings_rx1.Any();
			}
		}
		bool flag2 = HardwareSpecific.Model == HPSDRModel.ANAN100D || HardwareSpecific.Model == HPSDRModel.ANAN200D || HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.REDPITAYA;
		if (!(_auto_att_rx2 & flag2))
		{
			return;
		}
		int aDCInUse2 = GetADCInUse(DDCrx);
		int aDCInUse3 = GetADCInUse(DDCrx2);
		if ((_adc_overloaded[0] && _adc_overload_level[0] > 3 && aDCInUse3 == 0) || (_adc_overloaded[1] && _adc_overload_level[1] > 3 && aDCInUse3 == 1))
		{
			HistoricAttenuatorReading historicAttenuatorReading5 = new HistoricAttenuatorReading();
			if (_rx2_step_att_enabled)
			{
				historicAttenuatorReading5.stepAttenuator = RX2AttenuatorData;
				historicAttenuatorReading5.band = RX2Band;
				int num3 = historicAttenuatorReading5.stepAttenuator + (_adc_overloaded[0] ? _adc_step_shift[0] : _adc_step_shift[1]);
				if (num3 > 31)
				{
					num3 = 31;
				}
				if (num3 != historicAttenuatorReading5.stepAttenuator)
				{
					RX2AttenuatorData = num3;
					_auto_att_last_hold_time_rx2 = utcNow;
					_historic_attenuator_readings_rx2.Push(historicAttenuatorReading5);
					AutoAttAppliedRX2 = true;
				}
			}
			else
			{
				historicAttenuatorReading5.preampMode = RX2PreampMode;
				PreampMode preampMode2 = historicAttenuatorReading5.preampMode;
				switch (preampMode2)
				{
				case PreampMode.HPSDR_OFF:
				case PreampMode.HPSDR_ON:
					preampMode2 = PreampMode.SA_MINUS10;
					break;
				case PreampMode.SA_MINUS10:
					preampMode2 = PreampMode.SA_MINUS20;
					break;
				case PreampMode.SA_MINUS20:
					preampMode2 = PreampMode.SA_MINUS30;
					break;
				}
				if (preampMode2 != historicAttenuatorReading5.preampMode)
				{
					RX2PreampMode = preampMode2;
					_auto_att_last_hold_time_rx2 = utcNow;
					_historic_attenuator_readings_rx2.Push(historicAttenuatorReading5);
					AutoAttAppliedRX2 = true;
				}
			}
			AutoAttAppliedRX2 = _historic_attenuator_readings_rx2.Any();
		}
		else
		{
			if ((aDCInUse3 != 0 && aDCInUse3 != 1) || !_historic_attenuator_readings_rx2.Any() || (_auto_att_undo_rx2 && (!_auto_att_undo_rx2 || !((utcNow - _auto_att_last_hold_time_rx2).TotalSeconds >= (double)_auto_att_hold_delay_rx2))))
			{
				return;
			}
			HistoricAttenuatorReading historicAttenuatorReading6 = _historic_attenuator_readings_rx2.Pop();
			if (aDCInUse2 != aDCInUse3 && historicAttenuatorReading6 != null && _auto_att_undo_rx2)
			{
				if (_rx2_step_att_enabled && historicAttenuatorReading6.stepAttenuator != -1)
				{
					if (historicAttenuatorReading6.stepAttenuator != RX2AttenuatorData)
					{
						RX2AttenuatorData = historicAttenuatorReading6.stepAttenuator;
					}
				}
				else if (historicAttenuatorReading6.preampMode != PreampMode.FIRST && historicAttenuatorReading6.preampMode != RX2PreampMode)
				{
					RX2PreampMode = historicAttenuatorReading6.preampMode;
				}
			}
			_auto_att_last_hold_time_rx2 = utcNow;
			AutoAttAppliedRX2 = _historic_attenuator_readings_rx2.Any();
		}
	}

	private async void pollOverloadSyncSeqErr()
	{
		int count = 0;
		bool run = false;
		_check_for_bad_adc = true;
		try
		{
			if (base.InvokeRequired)
			{
				Invoke((MethodInvoker)delegate
				{
					run = chkPower.Checked;
				});
			}
			else
			{
				run = chkPower.Checked;
			}
		}
		catch
		{
		}
		if (run)
		{
			NetworkIO.getAndResetADC_Overload();
		}
		while (run)
		{
			try
			{
				if (base.InvokeRequired)
				{
					Invoke((MethodInvoker)delegate
					{
						checkOverloadsAndSync();
						if (count == 0)
						{
							checkSeqErrors();
						}
						run = chkPower.Checked;
					});
				}
				else
				{
					checkOverloadsAndSync();
					if (count == 0)
					{
						checkSeqErrors();
					}
					run = chkPower.Checked;
				}
				count++;
				if (count == 5)
				{
					count = 0;
				}
			}
			catch
			{
			}
			await Task.Delay(100);
		}
	}

	private void checkSeqErrors()
	{
		int oOO = NetworkIO.getOOO();
		if (oOO <= 0)
		{
			return;
		}
		string text = "";
		if (isBitSet(oOO, 0))
		{
			text += "CC ";
		}
		if (isBitSet(oOO, 1))
		{
			text += "DDC0 ";
		}
		if (isBitSet(oOO, 2))
		{
			text += "DDC1 ";
		}
		if (isBitSet(oOO, 3))
		{
			text += "DDC2 ";
		}
		if (isBitSet(oOO, 4))
		{
			text += "DDC3 ";
		}
		if (isBitSet(oOO, 5))
		{
			text += "DDC4 ";
		}
		if (isBitSet(oOO, 6))
		{
			text += "DDC5 ";
		}
		if (isBitSet(oOO, 7))
		{
			text += "DDC6 ";
		}
		if (isBitSet(oOO, 8))
		{
			text += "Mic ";
		}
		int[] array = new int[40];
		StringBuilder stringBuilder = new StringBuilder(24);
		bool flag = false;
		bool flag2 = false;
		for (int i = 0; i < 7; i++)
		{
			if (!isBitSet(oOO, i + 1))
			{
				continue;
			}
			flag2 = true;
			string text2 = "DCC" + i + Environment.NewLine;
			int num = 0;
			bool bInit = true;
			uint received_seqnum;
			uint last_seqnum;
			while (NetworkIO.getSeqInDelta(bInit, i, array, stringBuilder, out received_seqnum, out last_seqnum))
			{
				bInit = false;
				text2 = text2 + "s" + num + "=";
				for (int j = 0; j < array.Length; j++)
				{
					text2 = text2 + array[j] + " ";
					if (array[j] < 0)
					{
						flag = true;
					}
				}
				text2 = text2 + " r:" + received_seqnum + " l:" + last_seqnum + " " + stringBuilder.ToString() + Environment.NewLine;
				num++;
			}
			m_frmSeqLog.LogString(text2);
		}
		if (flag2)
		{
			bool visible = true;
			if (flag)
			{
				toolStripStatusLabel_SeqWarning.BackColor = Color.Red;
				DumpCap.StopDumpcap();
			}
			else
			{
				toolStripStatusLabel_SeqWarning.BackColor = Color.Transparent;
				if (!DumpCap.KillOnNegativeSeqOnly)
				{
					DumpCap.StopDumpcap();
				}
				visible = !m_frmSeqLog.StatusBarWarningOnNegativeOnly;
			}
			DumpCap.StartDumpcap(2000);
			toolStripStatusLabel_SeqWarning.Visible = visible;
		}
		if (_bInfoBarShowSEQErrors)
		{
			infoBar.Warning("Sequence error : " + oOO + " (" + text.Trim() + ")");
		}
	}

	private void UpdatePeakText()
	{
		if (string.IsNullOrEmpty(txtVFOAFreq.Text) || txtVFOAFreq.Text == "." || txtVFOAFreq.Text == ",")
		{
			return;
		}
		bool flag = !rx2_enabled;
		bool flag2 = false;
		if (rx2_enabled)
		{
			if (DisplayCursorX != -1 && DisplayCursorY != -1)
			{
				flag = overRX(DisplayCursorX, DisplayCursorY, 1, bIgnorePanafallWaterfall: false);
				flag2 = overRX(DisplayCursorX, DisplayCursorY, 2, bIgnorePanafallWaterfall: false);
			}
			if (!flag && !flag2)
			{
				flag = true;
			}
		}
		float num = PixelToHz(Display.MaxX);
		float maxY = Display.MaxY;
		double num2 = VFOAFreq + (double)num * 1E-06;
		switch (RX1DSPMode)
		{
		case DSPMode.CWL:
			num2 += (double)cw_pitch * 1E-06;
			break;
		case DSPMode.CWU:
			num2 -= (double)cw_pitch * 1E-06;
			break;
		case DSPMode.FM:
		case DSPMode.AM:
		case DSPMode.SAM:
			if (chkTUN.Checked && !_display_duplex)
			{
				num2 -= (double)cw_pitch * 1E-06;
			}
			break;
		case DSPMode.USB:
		case DSPMode.DSB:
		case DSPMode.DIGU:
			if (chkTUN.Checked && !_display_duplex)
			{
				num2 = ((!RX1IsOn60mChannel() || current_region != FRSRegion.US) ? (num2 - (double)cw_pitch * 1E-06) : (num2 - (ModeFreqOffset(_rx1_dsp_mode) + (double)cw_pitch * 1E-06)));
			}
			break;
		case DSPMode.LSB:
		case DSPMode.DIGL:
			if (chkTUN.Checked && !_display_duplex)
			{
				num2 += (double)cw_pitch * 1E-06;
			}
			break;
		}
		DisplayMode currentDisplayMode = Display.CurrentDisplayMode;
		if ((uint)currentDisplayMode <= 1u || (uint)(currentDisplayMode - 6) <= 4u)
		{
			infoBar.Right1(0, num.ToString("f1") + "Hz");
			infoBar.Right2(0, maxY.ToString("f1") + "dBm");
			double vFOAFreq = VFOAFreq;
			string text = (((!_click_tune_display || _mox) && (!_click_tune_display || !_display_duplex)) ? (num2.ToString("f6") + " MHz") : ((num2 + (CentreFrequency - vFOAFreq)).ToString("f6") + " MHz"));
			int startIndex = text.IndexOf(separator) + 4;
			infoBar.Right3(0, text.Insert(startIndex, " "));
		}
		else
		{
			infoBar.Right1(0, "");
			infoBar.Right2(0, "");
			infoBar.Right3(0, "");
		}
		if (flag | flag2)
		{
			string text2 = "";
			string text3 = "";
			SpectralResult spectralResult;
			if (flag)
			{
				float num3 = -200f;
				if (!MOX)
				{
					num3 = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.AVG_SIGNAL_STRENGTH);
					num3 += RXOffset(1);
					num3 = ((!(num3 > _RX1_smoothed_sig_avg_for_estimated_snr)) ? (_RX1_smoothed_sig_avg_for_estimated_snr = num3 * 0.2f + _RX1_smoothed_sig_avg_for_estimated_snr * 0.8f) : (_RX1_smoothed_sig_avg_for_estimated_snr = num3 * 0.8f + _RX1_smoothed_sig_avg_for_estimated_snr * 0.2f));
				}
				spectralResult = spectralCalculations(1, num3);
				if (!MOX)
				{
					if (_UseSUnitsForPBNPPBSNR)
					{
						text3 = Common.GetSMeterUnits(spectralResult.estimated_passband_noise_power, VFOAFreq >= S9Frequency).ToString("N1") + "su";
						text2 = (spectralResult.estimated_snr / 6.0).ToString("N1") + "su";
					}
					else
					{
						text3 = spectralResult.estimated_passband_noise_power.ToString("N1") + "dBm";
						text2 = spectralResult.estimated_snr.ToString("N1") + "dB";
					}
				}
			}
			else
			{
				float num4 = -200f;
				if (!MOX)
				{
					num4 = WDSP.CalculateRXMeter(2u, 0u, WDSP.MeterType.AVG_SIGNAL_STRENGTH);
					num4 += RXOffset(2);
					num4 = ((!(num4 > _RX2_smoothed_sig_avg_for_estimated_snr)) ? (_RX2_smoothed_sig_avg_for_estimated_snr = num4 * 0.2f + _RX2_smoothed_sig_avg_for_estimated_snr * 0.8f) : (_RX2_smoothed_sig_avg_for_estimated_snr = num4 * 0.8f + _RX2_smoothed_sig_avg_for_estimated_snr * 0.2f));
				}
				spectralResult = spectralCalculations(2, num4);
				if (!MOX)
				{
					if (_UseSUnitsForPBNPPBSNR)
					{
						text3 = Common.GetSMeterUnits(spectralResult.estimated_passband_noise_power, VFOBFreq >= S9Frequency).ToString("N1") + "su";
						text2 = (spectralResult.estimated_snr / 6.0).ToString("N1") + "sU";
					}
					else
					{
						text3 = spectralResult.estimated_passband_noise_power.ToString("N1") + "dBm";
						text2 = spectralResult.estimated_snr.ToString("N1") + "dBm";
					}
				}
			}
			infoBar.Left1(1, "RBW " + spectralResult.rbw.ToString("N1") + "Hz (" + spectralResult.rbw_dBHz.ToString("N1") + "dBHz)", 160);
			infoBar.Left2(1, "PB " + spectralResult.passband_bandwidth + "Hz (" + spectralResult.rx_dBHz.ToString("N1") + "dBHz)", 160);
			if (!MOX)
			{
				infoBar.Right1(1, "NPSD " + spectralResult.noise_floor_power_spectral_density.ToString("N1") + "dBm/Hz", 140);
				infoBar.Right2(1, "PBNP " + text3, 120);
				infoBar.Right3(1, "PBSNR " + text2, 120);
			}
			else
			{
				infoBar.Right1(1, "");
				infoBar.Right2(1, "");
				infoBar.Right3(1, "");
			}
		}
		else
		{
			infoBar.Left1(1, "");
			infoBar.Left2(1, "");
			infoBar.Right1(1, "");
			infoBar.Right2(1, "");
			infoBar.Right3(1, "");
		}
	}

	private int HzInNPixels(int nPixelCount, int rx)
	{
		getLowHighForRXn(rx, out var low, out var high);
		int num = high - low;
		return (int)((double)nPixelCount / (double)pnlDisplay.Width * (double)num);
	}

	private void getLowHighForRXn(int rx, out int low, out int high, bool bIncludeRitXit = true)
	{
		bool flag = _mox && (VFOATX || (VFOBTX && !RX2Enabled));
		bool flag2 = _mox && VFOBTX && RX2Enabled;
		bool num = (flag && rx == 1) || (flag2 && rx == 2);
		bool flag3 = rx == 1 && (Display.CurrentDisplayMode == DisplayMode.SPECTRUM || Display.CurrentDisplayMode == DisplayMode.HISTOGRAM);
		low = 0;
		high = 0;
		if (num)
		{
			if (rx == 1)
			{
				if (flag)
				{
					if (_display_duplex)
					{
						low = (flag3 ? Display.RXSpectrumDisplayLow : Display.RXDisplayLow);
						high = (flag3 ? Display.RXSpectrumDisplayHigh : Display.RXDisplayHigh);
					}
					else
					{
						low = (flag3 ? Display.TXSpectrumDisplayLow : Display.TXDisplayLow);
						high = (flag3 ? Display.TXSpectrumDisplayHigh : Display.TXDisplayHigh);
					}
				}
				else
				{
					low = Display.RXDisplayLow;
					high = Display.RXDisplayHigh;
				}
			}
			else if (flag2)
			{
				low = Display.TXDisplayLow;
				high = Display.TXDisplayHigh;
			}
			else
			{
				low = Display.RX2DisplayLow;
				high = Display.RX2DisplayHigh;
			}
		}
		else if (rx == 1)
		{
			low = (flag3 ? Display.RXSpectrumDisplayLow : Display.RXDisplayLow);
			high = (flag3 ? Display.RXSpectrumDisplayHigh : Display.RXDisplayHigh);
		}
		else
		{
			low = Display.RX2DisplayLow;
			high = Display.RX2DisplayHigh;
		}
		if (!bIncludeRitXit)
		{
			return;
		}
		if (rx == 1)
		{
			if (!flag)
			{
				if (chkRIT.Checked && !CTuneDisplay)
				{
					int num2 = (int)udRIT.Value;
					low += num2;
					high += num2;
				}
			}
			else if (chkXIT.Checked && !_display_duplex)
			{
				int num3 = (int)udXIT.Value;
				low += num3;
				high += num3;
			}
		}
		else if (flag2 && chkXIT.Checked)
		{
			int num4 = (int)udXIT.Value;
			low += num4;
			high += num4;
		}
	}

	private float PixelToHz(float x)
	{
		return PixelToHz(x, 1);
	}

	private float PixelToHz(float x, int rx)
	{
		getLowHighForRXn(rx, out var low, out var high);
		int num = high - low;
		return (float)((double)low + (double)x / (double)pnlDisplay.Width * (double)num);
	}

	private int HzToPixel(float freq)
	{
		return HzToPixel(freq, 1);
	}

	private int HzToPixel(float freq, int rx)
	{
		bool flag = _mox && (VFOATX || (VFOBTX && !RX2Enabled));
		bool flag2 = _mox && VFOBTX && RX2Enabled;
		getLowHighForRXn(rx, out var low, out var high, bIncludeRitXit: false);
		int num = ((rx == 1 && !flag && RITOn && CTuneDisplay) ? RITValue : 0);
		int num2 = 0;
		if (rx == 1)
		{
			if (flag)
			{
				num2 = (XITOn ? XITValue : 0);
			}
		}
		else if (flag2)
		{
			num2 = (XITOn ? XITValue : 0);
		}
		int num3 = high - low;
		return (int)((double)(freq - (float)low + (float)num + (float)num2) / (double)num3 * (double)pnlDisplay.Width);
	}

	private float PixelToDb(float y)
	{
		return (float)((double)Display.SpectrumGridMaxMoxModified - (double)y * (double)(Display.SpectrumGridMaxMoxModified - Display.SpectrumGridMinMoxModified) / (double)Display.RX1DisplayHeight);
	}

	private float PixelToRx2Db(float y)
	{
		y -= (float)Display.RX1DisplayHeight;
		if (Display.CurrentDisplayMode == DisplayMode.PANAFALL)
		{
			y -= (float)Display.RX1DisplayHeight;
		}
		return (float)((double)Display.RX2SpectrumGridMaxMoxModified - (double)y * (double)(Display.RX2SpectrumGridMaxMoxModified - Display.RX2SpectrumGridMinMoxModified) / (double)Display.RX2DisplayHeight);
	}

	private float WaterfallPixelToTime(float y, int rx)
	{
		int num;
		if (rx == 1)
		{
			int rX1DisplayHeight = Display.RX1DisplayHeight;
			num = Display.WaterfallUpdatePeriod;
			if (Display.CurrentDisplayMode == DisplayMode.PANAFALL)
			{
				y -= (float)rX1DisplayHeight;
			}
		}
		else
		{
			if (y > (float)(pnlDisplay.Height / 2))
			{
				y -= (float)(pnlDisplay.Height / 2);
			}
			int rX1DisplayHeight = Display.RX2DisplayHeight;
			num = Display.RX2WaterfallUpdatePeriod;
			if (Display.CurrentDisplayModeBottom == DisplayMode.PANAFALL)
			{
				y -= (float)rX1DisplayHeight;
			}
		}
		int num2 = Display.CurrentFPS;
		if (num2 == 0)
		{
			num2 = _display_fps;
		}
		float num3 = (y - 16f) * ((float)num * (1000f / (float)num2));
		if (num3 < 0f)
		{
			num3 = 0f;
		}
		return num3;
	}

	private float WaterfallPixelToTime(float y)
	{
		return WaterfallPixelToTime(y, 1);
	}

	private SizeF measureStringFromCache(string str, Font font, int width, StringFormat format, Graphics g)
	{
		MeasureKey key = new MeasureKey(str, font, width, format);
		if (_measureCache.TryGetValue(key, out var value))
		{
			return value;
		}
		SizeF sizeF = g.MeasureString(str, font, width, format);
		_measureCache[key] = sizeF;
		return sizeF;
	}

