	private void storeRX1SignalPixels_X(float x)
	{
		int num = Math.Min(meter_delay, meter_dig_delay);
		if (!(m_objRX1HistoryDelayTimer.ElapsedMsec < (double)Math.Max(num, 2000)))
		{
			m_objRX1HistoryDelayTimer.Stop();
			m_RX1SignalPixels_X.Add(x);
			int num2 = m_RX1SignalPixels_X.Count - m_nSignalHistoryDuration / num;
			if (num2 > 0)
			{
				m_RX1SignalPixels_X.RemoveRange(0, num2);
			}
		}
	}

	private void storeRX2SignalPixels_X(float x)
	{
		int num = Math.Min(meter_delay, meter_dig_delay);
		if (!(m_objRX2HistoryDelayTimer.ElapsedMsec < (double)Math.Max(num, 2000)))
		{
			m_objRX2HistoryDelayTimer.Stop();
			m_RX2SignalPixels_X.Add(x);
			int num2 = m_RX2SignalPixels_X.Count - m_nSignalHistoryDuration / num;
			if (num2 > 0)
			{
				m_RX2SignalPixels_X.RemoveRange(0, num2);
			}
		}
	}

	private void clearRXSignalPixels(int rx)
	{
		switch (rx)
		{
		case 1:
			m_RX1SignalPixels_X.Clear();
			m_objRX1HistoryDelayTimer.Reset();
			break;
		case 2:
			m_RX2SignalPixels_X.Clear();
			m_objRX2HistoryDelayTimer.Reset();
			break;
		}
	}

	private void picMultiMeterDigital_Paint(object sender, PaintEventArgs e)
	{
		int num = picMultiMeterDigital.ClientSize.Height;
		int num2 = picMultiMeterDigital.ClientSize.Width;
		Graphics graphics = e.Graphics;
		double num3 = -200.0;
		string text = "";
		if (meter_data_ready)
		{
			current_meter_data = new_meter_data;
			current_swrmeter_data = new_swrmeter_data;
		}
		if (avg_num != -999.9990234375)
		{
			num3 = ((!((double)current_meter_data > avg_num)) ? (avg_num = (double)current_meter_data * 0.2 + avg_num * 0.8) : (avg_num = (double)current_meter_data * 0.8 + avg_num * 0.2));
		}
		else
		{
			num3 = (avg_num = current_meter_data);
			clearRXSignalPixels(1);
		}
		MeterTXMode meterTXMode = (chkTUN.Checked ? tune_meter_tx_mode : current_meter_tx_mode);
		int pixel_x;
		int pixel_x_swr;
		switch (current_meter_display_mode)
		{
		case MultiMeterDisplayMode.Original:
			graphics.FillRectangle(meter_background_pen.Brush, 0, 0, num2, num);
			getMeterPixelPosAndDrawScales(1, graphics, num, num2, num3, out pixel_x, out pixel_x_swr, 1, bDrawMarkers: false);
			if ((!_mox && current_meter_rx_mode != MeterRXMode.OFF) || (_mox && meterTXMode != MeterTXMode.OFF && meterTXMode != MeterTXMode.SWR_POWER))
			{
				pixel_x = Math.Max(1, pixel_x);
				pixel_x = Math.Min(num2 - 3, pixel_x);
				if (!_mox && num3 != -200.0)
				{
					storeRX1SignalPixels_X((float)pixel_x / (float)num2);
				}
				using (LinearGradientBrush brush = new LinearGradientBrush(new Rectangle(0, 0, pixel_x, num - 10), meter_left_color, meter_right_color, LinearGradientMode.Horizontal))
				{
					graphics.FillRectangle(brush, 0, 0, pixel_x, num - 10);
				}
				for (int i = 0; i < num2 / 8 - 1; i++)
				{
					graphics.DrawLine(meter_background_pen, 8 + i * 8, 0, 8 + i * 8, num - 10);
				}
				graphics.DrawLine(Pens.Red, pixel_x, 0, pixel_x, num - 10);
				graphics.FillRectangle(meter_background_pen.Brush, pixel_x + 1, 0, num2 - pixel_x, num - 10);
				if (pixel_x >= meter_peak_value)
				{
					meter_peak_count = 0;
					meter_peak_value = pixel_x;
				}
				else if (meter_peak_count++ >= multimeter_peak_hold_samples)
				{
					meter_peak_count = 0;
					meter_peak_value = pixel_x;
				}
				else
				{
					graphics.DrawLine(Pens.Red, meter_peak_value, 0, meter_peak_value, num - 10);
					graphics.DrawLine(Pens.Red, meter_peak_value - 1, 0, meter_peak_value - 1, num - 10);
				}
				if (m_bUseSignalHistory && !_mox && m_RX1SignalPixels_X.Count > 0)
				{
					float num6 = m_RX1SignalPixels_X.Min() * (float)num2;
					float num7 = m_RX1SignalPixels_X.Max() * (float)num2;
					graphics.FillRectangle(m_SignalHistoryColourPen.Brush, num6, num - 10, num7 - num6, 10f);
				}
			}
			else if (_mox && meterTXMode == MeterTXMode.SWR_POWER)
			{
				pixel_x = Math.Max(1, pixel_x);
				pixel_x = Math.Min(num2 - 3, pixel_x);
				pixel_x_swr = Math.Max(1, pixel_x_swr);
				pixel_x_swr = Math.Min(num2 - 3, pixel_x_swr);
				using (LinearGradientBrush brush2 = new LinearGradientBrush(new Rectangle(0, 0, pixel_x_swr, num / 2 - 8), meter_left_color, meter_right_color, LinearGradientMode.Horizontal))
				{
					graphics.FillRectangle(brush2, 0, 8, pixel_x_swr, num / 2 - 8);
				}
				using (LinearGradientBrush brush3 = new LinearGradientBrush(new Rectangle(0, 0, pixel_x, num / 2 - 8), meter_left_color, meter_right_color, LinearGradientMode.Horizontal))
				{
					graphics.FillRectangle(brush3, 0, num / 2, pixel_x, num / 2 - 8);
				}
				for (int j = 0; j < num2 / 8 - 1; j++)
				{
					graphics.DrawLine(meter_background_pen, 8 + j * 8, num / 2, 8 + j * 8, num - 8);
					graphics.DrawLine(meter_background_pen, 8 + j * 8, 10, 8 + j * 8, num / 2 - 8);
				}
				graphics.DrawLine(Pens.Red, pixel_x, num / 2, pixel_x, num);
				graphics.DrawLine(Pens.Red, pixel_x_swr, 0, pixel_x_swr, num / 2);
				graphics.FillRectangle(meter_background_pen.Brush, pixel_x + 1, num / 2, num2 - pixel_x, num / 2 - 8);
				graphics.FillRectangle(meter_background_pen.Brush, pixel_x_swr + 1, 8, num2 - pixel_x_swr, num / 2 - 8);
				if (pixel_x >= meter_peak_value)
				{
					meter_peak_count = 0;
					meter_peak_value = pixel_x;
				}
				else if (meter_peak_count++ >= multimeter_peak_hold_samples)
				{
					meter_peak_count = 0;
					meter_peak_value = pixel_x;
				}
				else
				{
					graphics.DrawLine(Pens.Red, meter_peak_value, num / 2, meter_peak_value, num);
					graphics.DrawLine(Pens.Red, meter_peak_value - 1, num / 2, meter_peak_value - 1, num);
				}
			}
			break;
		case MultiMeterDisplayMode.Edge:
			graphics.DrawRectangle(edge_meter_background_pen, 0, 0, num2, num);
			getMeterPixelPosAndDrawScales(1, graphics, num, num2, num3, out pixel_x, out pixel_x_swr, 12, bDrawMarkers: true);
			if ((!_mox && current_meter_rx_mode != MeterRXMode.OFF) || (_mox && meterTXMode != MeterTXMode.OFF && meterTXMode != MeterTXMode.SWR_POWER))
			{
				pixel_x = Math.Max(0, pixel_x);
				pixel_x = Math.Min(num2 - 3, pixel_x);
				if (!_mox && num3 != -200.0)
				{
					storeRX1SignalPixels_X((float)pixel_x / (float)num2);
				}
				line_dark_pen.Color = Color.FromArgb((edge_avg_color.R + edge_meter_background_color.R) / 2, (edge_avg_color.G + edge_meter_background_color.G) / 2, (edge_avg_color.B + edge_meter_background_color.B) / 2);
				graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
				graphics.SmoothingMode = SmoothingMode.HighQuality;
				if (m_bUseSignalHistory && !_mox && m_RX1SignalPixels_X.Count > 0)
				{
					float num4 = m_RX1SignalPixels_X.Min() * (float)num2;
					float num5 = m_RX1SignalPixels_X.Max() * (float)num2;
					graphics.FillRectangle(m_SignalHistoryColourPen.Brush, num4, 0f, num5 - num4, num);
				}
				graphics.DrawLine(line_dark_pen, pixel_x - 1, 0, pixel_x - 1, num);
				graphics.DrawLine(line_pen, pixel_x, 0, pixel_x, num);
				graphics.DrawLine(line_dark_pen, pixel_x + 1, 0, pixel_x + 1, num);
				graphics.InterpolationMode = InterpolationMode.Default;
				graphics.SmoothingMode = SmoothingMode.Default;
			}
			else if (_mox && meterTXMode == MeterTXMode.SWR_POWER)
			{
				pixel_x = Math.Max(0, pixel_x);
				pixel_x = Math.Min(num2 - 3, pixel_x);
				pixel_x_swr = Math.Max(0, pixel_x_swr);
				pixel_x_swr = Math.Min(num2 - 3, pixel_x_swr);
				line_dark_pen.Color = Color.FromArgb((edge_avg_color.R + edge_meter_background_color.R) / 2, (edge_avg_color.G + edge_meter_background_color.G) / 2, (edge_avg_color.B + edge_meter_background_color.B) / 2);
				graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
				graphics.SmoothingMode = SmoothingMode.HighQuality;
				if (!_mox)
				{
					graphics.DrawLine(line_dark_pen, pixel_x - 1, 0, pixel_x - 1, num);
					graphics.DrawLine(line_pen, pixel_x, 0, pixel_x, num);
					graphics.DrawLine(line_dark_pen, pixel_x + 1, 0, pixel_x + 1, num);
				}
				else
				{
					graphics.DrawLine(line_dark_pen, pixel_x - 1, num / 2 + 3, pixel_x - 1, num);
					graphics.DrawLine(line_pen, pixel_x, num / 2 + 3, pixel_x, num);
					graphics.DrawLine(line_dark_pen, pixel_x + 1, num / 2 + 3, pixel_x + 1, num);
					graphics.DrawLine(line_dark_pen, pixel_x_swr - 1, 0, pixel_x_swr - 1, num / 2 - 3);
					graphics.DrawLine(line_pen, pixel_x_swr, 0, pixel_x_swr, num / 2 - 3);
					graphics.DrawLine(line_dark_pen, pixel_x_swr + 1, 0, pixel_x_swr + 1, num / 2 - 3);
				}
				graphics.InterpolationMode = InterpolationMode.Default;
				graphics.SmoothingMode = SmoothingMode.Default;
			}
			break;
		}
		meter_timer.Stop();
		string text2 = "f0";
		if (meter_detail)
		{
			text2 = "f1";
		}
		if (meter_timer.DurationMsec >= (double)meter_dig_delay)
		{
			if (!_mox)
			{
				switch (current_meter_rx_mode)
				{
				case MeterRXMode.SIGNAL_STRENGTH:
				case MeterRXMode.SIGNAL_AVERAGE:
					switch (m_eMeasureMode)
					{
					case MultiMeterMeasureMode.SMeter:
						text = Common.SMeterFromDBM(num3, VFOAFreq >= S9Frequency);
						break;
					case MultiMeterMeasureMode.DBM:
						text = num3.ToString(text2) + " dBm";
						break;
					case MultiMeterMeasureMode.UV:
						if (meter_detail)
						{
							text2 = "f2";
						}
						text = Common.UVfromDBM(num3).ToString(text2) + " uV";
						break;
					}
					break;
				case MeterRXMode.ADC_L:
				case MeterRXMode.ADC_R:
				case MeterRXMode.ADC2_L:
				case MeterRXMode.ADC2_R:
					text = num3.ToString("f1") + " dBFS";
					break;
				case MeterRXMode.OFF:
					text = "";
					break;
				}
			}
			else
			{
				switch (meterTXMode)
				{
				case MeterTXMode.MIC:
				case MeterTXMode.EQ:
				case MeterTXMode.LEVELER:
				case MeterTXMode.LVL_G:
				case MeterTXMode.CFC_PK:
				case MeterTXMode.CFC_G:
				case MeterTXMode.COMP:
				case MeterTXMode.ALC:
				case MeterTXMode.ALC_G:
				case MeterTXMode.ALC_GROUP:
					text = num3.ToString(text2) + " dB";
					break;
				case MeterTXMode.FORWARD_POWER:
				case MeterTXMode.REVERSE_POWER:
				case MeterTXMode.SWR_POWER:
					text = ((HardwareSpecific.Model != HPSDRModel.ANAN10 && HardwareSpecific.Model != HPSDRModel.ANAN10E && !apollopresent) ? ((!alexpresent && !pa_present) ? (num3.ToString(text2) + " mW") : (num3.ToString(text2) + " W")) : (num3.ToString(text2) + " W"));
					break;
				case MeterTXMode.SWR:
					text = num3.ToString("f1") + " : 1";
					break;
				case MeterTXMode.OFF:
					text = "";
					break;
				}
			}
			txtMultiText.Text = text;
			meter_timer.Start();
		}
		if (meter_data_ready)
		{
			meter_data_ready = false;
		}
	}

