	private void panelVFOAHover_Paint(object sender, PaintEventArgs e)
	{
		if (vfoa_hover_digit < 0)
		{
			return;
		}
		int num = 0;
		int num2 = 0;
		if (small_lsd && txtVFOALSD.Visible)
		{
			num += (vfo_char_width + vfo_char_space) * vfoa_hover_digit;
			if (vfoa_hover_digit > 3)
			{
				num += vfo_decimal_space - vfo_char_space;
			}
			if (vfoa_hover_digit > 6)
			{
				num += vfo_small_char_width;
				num += (vfo_small_char_width + vfo_small_char_space - vfo_char_width - vfo_char_space) * (vfoa_hover_digit - 6);
				num2 = num + vfo_small_char_width;
			}
			else
			{
				num2 = num + vfo_char_width;
			}
		}
		else
		{
			num += (vfo_char_width + vfo_char_space) * vfoa_hover_digit;
			if (vfoa_hover_digit > 3)
			{
				num += vfo_decimal_space - vfo_char_space;
			}
			num2 = num + vfo_char_width;
		}
		e.Graphics.DrawLine(txtvfoafreq_forecolor_pen, num, 1, num2, 1);
	}

