	private async void UpdateMultimeter()
	{
		meter_timer.Start();
		while (!_hide_legacy_meters && chkPower.Checked)
		{
			if (!meter_data_ready)
			{
				if (!_mox)
				{
					switch (CurrentMeterRXMode)
					{
					case MeterRXMode.SIGNAL_STRENGTH:
					{
						float num = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.SIGNAL_STRENGTH);
						num += RXOffset(1);
						new_meter_data = num;
						break;
					}
					case MeterRXMode.SIGNAL_AVERAGE:
					{
						float num = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.AVG_SIGNAL_STRENGTH);
						num += RXOffset(1);
						new_meter_data = num;
						break;
					}
					case MeterRXMode.ADC_L:
					{
						float num = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.ADC_REAL);
						new_meter_data = num;
						break;
					}
					case MeterRXMode.ADC_R:
					{
						float num = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.ADC_IMAG);
						new_meter_data = num;
						break;
					}
					case MeterRXMode.ADC2_L:
					{
						float num = WDSP.CalculateRXMeter(2u, 0u, WDSP.MeterType.ADC_REAL);
						new_meter_data = num;
						break;
					}
					case MeterRXMode.ADC2_R:
					{
						float num = WDSP.CalculateRXMeter(2u, 0u, WDSP.MeterType.ADC_IMAG);
						new_meter_data = num;
						break;
					}
					case MeterRXMode.OFF:
						new_meter_data = -200f;
						break;
					}
				}
				else
				{
					switch (CurrentMeterTXMode)
					{
					case MeterTXMode.MIC:
					{
						float num2 = Math.Max(-195f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.MIC_PK));
						new_meter_data = num2;
						break;
					}
					case MeterTXMode.EQ:
					{
						float num2 = Math.Max(-30f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.EQ_PK));
						new_meter_data = num2;
						break;
					}
					case MeterTXMode.LEVELER:
					{
						float num2 = Math.Max(-30f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.LEVELER_PK));
						new_meter_data = num2;
						break;
					}
					case MeterTXMode.LVL_G:
					{
						float num2 = Math.Max(0f, WDSP.CalculateTXMeter(1u, WDSP.MeterType.LVL_G));
						new_meter_data = num2;
						break;
					}
					case MeterTXMode.CFC_PK:
					{
						float num2 = Math.Max(-30f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.CFC_PK));
						new_meter_data = num2;
						break;
					}
					case MeterTXMode.CFC_G:
					{
						float num2 = Math.Max(0f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.CFC_G));
						new_meter_data = num2;
						break;
					}
					case MeterTXMode.COMP:
					{
						float num2 = ((!peak_tx_meter) ? Math.Max(-30f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.CPDR)) : Math.Max(-30f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.CPDR_PK)));
						new_meter_data = num2;
						break;
					}
					case MeterTXMode.ALC:
					{
						float num2 = ((!peak_tx_meter) ? Math.Max(-30f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.ALC)) : Math.Max(-30f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.ALC_PK)));
						new_meter_data = num2;
						break;
					}
					case MeterTXMode.ALC_G:
					{
						float num2 = Math.Max(0f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.ALC_G));
						new_meter_data = num2;
						break;
					}
					case MeterTXMode.ALC_GROUP:
					{
						float num2 = ((!peak_tx_meter) ? Math.Max(-30f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.ALC)) : Math.Max(-30f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.ALC_PK)));
						num2 += Math.Max(0f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.ALC_G));
						new_meter_data = num2;
						break;
					}
					case MeterTXMode.FORWARD_POWER:
					case MeterTXMode.SWR_POWER:
						if (alexpresent || apollopresent)
						{
							if (HardwareSpecific.Model == HPSDRModel.ANAN8000D)
							{
								if (tx_xvtr_index >= 0)
								{
									new_meter_data = drivepwr;
								}
								else
								{
									new_meter_data = calfwdpower;
								}
							}
							else
							{
								new_meter_data = calfwdpower;
							}
						}
						else
						{
							new_meter_data = drivepwr;
						}
						if (current_meter_tx_mode == MeterTXMode.SWR_POWER)
						{
							new_swrmeter_data = alex_swr;
						}
						break;
					case MeterTXMode.REVERSE_POWER:
						if (alexpresent || apollopresent)
						{
							new_meter_data = alex_rev;
						}
						break;
					case MeterTXMode.SWR:
						new_meter_data = alex_swr;
						break;
					case MeterTXMode.OFF:
						new_meter_data = -200f;
						break;
					}
					if (pa_values)
					{
						SetupForm.textDriveFwdADCValue.Text = average_drvadc.ToString("f0");
						SetupForm.textFwdADCValue.Text = average_fwdadc.ToString("f0");
						SetupForm.textRevADCValue.Text = average_revadc.ToString("f0");
						SetupForm.textDrivePower.Text = average_drivepwr.ToString("f0") + " mW";
						SetupForm.textPAFwdPower.Text = alex_fwd.ToString("f1") + " W";
						SetupForm.textPARevPower.Text = alex_rev.ToString("f1") + " W";
						SetupForm.textCaldFwdPower.Text = calfwdpower.ToString("f1") + " W";
						SetupForm.textSWR.Text = alex_swr.ToString("f2") + ":1";
					}
				}
				meter_data_ready = true;
				picMultiMeterDigital.Invalidate();
			}
			await Task.Delay(Math.Min(meter_delay, meter_dig_delay));
		}
	}

	private async void UpdateRX2Multimeter()
	{
		rx2_meter_timer.Start();
		while (!_hide_legacy_meters && chkPower.Checked && rx2_enabled)
		{
			if (!rx2_meter_data_ready)
			{
				switch (RX2MeterMode)
				{
				case MeterRXMode.SIGNAL_STRENGTH:
				{
					float num = WDSP.CalculateRXMeter(2u, 0u, WDSP.MeterType.SIGNAL_STRENGTH);
					num += RXOffset(2);
					rx2_meter_new_data = num;
					break;
				}
				case MeterRXMode.SIGNAL_AVERAGE:
				{
					float num = WDSP.CalculateRXMeter(2u, 0u, WDSP.MeterType.AVG_SIGNAL_STRENGTH);
					num += RXOffset(2);
					rx2_meter_new_data = num;
					break;
				}
				case MeterRXMode.ADC_L:
				{
					float num = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.ADC_REAL);
					rx2_meter_new_data = num;
					break;
				}
				case MeterRXMode.ADC_R:
				{
					float num = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.ADC_IMAG);
					rx2_meter_new_data = num;
					break;
				}
				case MeterRXMode.ADC2_L:
				{
					float num = WDSP.CalculateRXMeter(2u, 0u, WDSP.MeterType.ADC_REAL);
					rx2_meter_new_data = num;
					break;
				}
				case MeterRXMode.ADC2_R:
				{
					float num = WDSP.CalculateRXMeter(2u, 0u, WDSP.MeterType.ADC_IMAG);
					rx2_meter_new_data = num;
					break;
				}
				case MeterRXMode.OFF:
					rx2_meter_new_data = -200f;
					break;
				}
				rx2_meter_data_ready = true;
				picRX2Meter.Invalidate();
			}
			await Task.Delay(Math.Min(meter_delay, meter_dig_delay));
		}
	}

	public float computeHermesDCVoltage()
	{
		float num = 6.7317076f;
		return (float)NetworkIO.getHermesDCVoltage() / 4095f * 3.3f * num * _supply_volt_cal;
	}

	private async void readMKIIPAVoltsAmps()
	{
		string sVALog = Path.Combine(AppDataPath, "VALog.txt");
		while (chkPower.Checked && HardwareSpecific.HasVolts && HardwareSpecific.HasAmps)
		{
			int adc0 = NetworkIO.getUserADC0();
			int adc1 = NetworkIO.getUserADC1();
			_voltsQueue.Enqueue(adc0);
			_ampsQueue.Enqueue(adc1);
			int nTries = 0;
			while (_voltsQueue.Count > 150 && nTries < 100)
			{
				if (!_voltsQueue.TryDequeue(out var _))
				{
					await Task.Delay(1);
					nTries++;
				}
			}
			nTries = 0;
			while (_ampsQueue.Count > 100 && nTries < 100)
			{
				if (!_ampsQueue.TryDequeue(out var _))
				{
					await Task.Delay(1);
					nTries++;
				}
			}
			await Task.Delay(8);
			if (!_logVA)
			{
				continue;
			}
			DateTime utcNow = DateTime.UtcNow;
			if (!(utcNow.Subtract(_lastSaveTime).TotalSeconds >= 1.0))
			{
				continue;
			}
			try
			{
				using StreamWriter streamWriter = File.AppendText(sVALog);
				streamWriter.WriteLine(string.Format("{0:yyyy-MM-dd HH:mm:ss}\tadc0(v)={1}\tadc1(a)={2}\tvolts={3}\tamps={4}", utcNow, adc0, adc1, convertToVolts(adc0).ToString("f2"), convertToAmps(adc1).ToString("f2")));
			}
			catch
			{
			}
			finally
			{
				_lastSaveTime = DateTime.UtcNow;
			}
			if (utcNow.Subtract(_firstSaveTime).TotalMinutes >= 60.0 && !IsSetupFormNull)
			{
				SetupForm.LogVA = false;
			}
		}
		_MKIIPAVolts = 0f;
		_MKIIPAAmps = 0f;
		int num = _voltsQueue.Count;
		while (_voltsQueue.Count > 0 && num > 0)
		{
			_voltsQueue.TryDequeue(out var _);
			num--;
		}
		num = _ampsQueue.Count;
		while (_ampsQueue.Count > 0 && num > 0)
		{
			_ampsQueue.TryDequeue(out var _);
			num--;
		}
	}

	private void computeMKIIPAVoltsAmps()
	{
		float iOreading = ((_voltsQueue.Count > 0) ? ((float)_voltsQueue.Average()) : 0f);
		float iOreading2 = ((_ampsQueue.Count > 0) ? ((float)_ampsQueue.Average()) : 0f);
		_MKIIPAVolts = convertToVolts(iOreading);
		_MKIIPAAmps = convertToAmps(iOreading2);
	}

	private float convertToVolts(float IOreading)
	{
		float num = 20.90909f;
		return IOreading / 4095f * 5f * num * _pa_volt_cal;
	}

	private float convertToAmps(float IOreading)
	{
		float amp_voff = _amp_voff;
		float amp_sens = _amp_sens;
		float num = IOreading * 5000f / 4095f;
		if (num < 0f)
		{
			num = 0f;
		}
		float num2 = (num - amp_voff) / amp_sens;
		if (num2 < 0f)
		{
			num2 = 0f;
		}
		return num2;
	}

	public float computeRefPower()
	{
		float num = 0f;
		float num2 = 0f;
		float num3 = 0f;
		int num4 = 0;
		switch (HardwareSpecific.Model)
		{
		case HPSDRModel.ANAN100:
		case HPSDRModel.ANAN100B:
			num2 = 0.095f;
			if (_tx_band == Band.B6M)
			{
				num2 = 0.5f;
			}
			num3 = 3.3f;
			num4 = 3;
			break;
		case HPSDRModel.ANAN100D:
			num2 = 0.095f;
			if (_tx_band == Band.B6M)
			{
				num2 = 0.5f;
			}
			num3 = 3.3f;
			num4 = 3;
			break;
		case HPSDRModel.ANAN200D:
			num2 = 0.108f;
			if (_tx_band == Band.B6M)
			{
				num2 = 0.5f;
			}
			num3 = 5f;
			num4 = 2;
			break;
		case HPSDRModel.ANAN7000D:
		case HPSDRModel.ANAN_G2:
		case HPSDRModel.ANAN_G2_1K:
		case HPSDRModel.ANVELINAPRO3:
		case HPSDRModel.REDPITAYA:
		case HPSDRModel.ANAN_G2E:
			num2 = 0.15f;
			if (_tx_band == Band.B6M)
			{
				num2 = 0.7f;
			}
			num3 = 5f;
			num4 = 28;
			break;
		case HPSDRModel.ORIONMKII:
		case HPSDRModel.ANAN8000D:
			num2 = 0.08f;
			if (_tx_band == Band.B6M)
			{
				num2 = 0.08f;
			}
			num3 = 5f;
			num4 = 16;
			break;
		default:
			num2 = 0.09f;
			if (_tx_band == Band.B6M)
			{
				num2 = 0.09f;
			}
			num3 = 3.3f;
			num4 = 3;
			break;
		}
		num = NetworkIO.getRevPower();
		if (num < 0f)
		{
			num = 0f;
		}
		float num5 = (float)((double)(num - (float)num4) / 4095.0 * (double)num3);
		if (num5 < 0f)
		{
			num5 = 0f;
		}
		float num6 = (float)(Math.Pow(num5, 2.0) / (double)num2 * PABandCalMult(_tx_band));
		if (num6 < 0f)
		{
			num6 = 0f;
		}
		if (MeterManager.RequiresUpdate(1, Reading.REV_VOLT))
		{
			_RX1MeterValues[Reading.REV_VOLT] = num5;
		}
		if (PAValues)
		{
			average_revadc = 0.9f * average_revadc + 0.100000024f * num;
			SetupForm.textRevVoltage.Text = num5.ToString("f2") + " V";
		}
		return num6;
	}

	private double PABandCalMult(Band b)
	{
		if (IsSetupFormNull || b <= Band.FIRST || b >= Band.LAST)
		{
			return 1.0;
		}
		return SetupForm.GetPABandCalMult(b);
	}

	public float computeAlexFwdPower()
