		switch (HardwareSpecific.Model)
		{
		case HPSDRModel.ANAN100:
		case HPSDRModel.ANAN100B:
			num2 = 0.095f;
			num3 = 3.3f;
			num4 = 6;
			break;
		case HPSDRModel.ANAN100D:
			num2 = 0.095f;
			num3 = 3.3f;
			num4 = 6;
			break;
		case HPSDRModel.ANAN200D:
			num2 = 0.108f;
			num3 = 5f;
			num4 = 4;
