	private PTTMode getFallbackPTTModeAfterTCIRelease(DSPMode tx_mode, bool mic_ptt, bool cw_ptt, bool cat_ptt, bool vox_ptt)
	{
		if (cat_ptt)
		{
			return PTTMode.CAT;
		}
		if ((tx_mode == DSPMode.CWL || tx_mode == DSPMode.CWU) && (cw_ptt | mic_ptt))
		{
			return PTTMode.CW;
		}
		if ((tx_mode == DSPMode.LSB || tx_mode == DSPMode.USB || tx_mode == DSPMode.DSB || tx_mode == DSPMode.AM || tx_mode == DSPMode.SAM || tx_mode == DSPMode.DIGU || tx_mode == DSPMode.DIGL || tx_mode == DSPMode.FM || _all_mode_mic_ptt) & mic_ptt)
		{
			return PTTMode.MIC;
		}
		if ((tx_mode == DSPMode.LSB || tx_mode == DSPMode.USB || tx_mode == DSPMode.DSB || tx_mode == DSPMode.AM || tx_mode == DSPMode.SAM || tx_mode == DSPMode.DIGU || tx_mode == DSPMode.DIGL || tx_mode == DSPMode.FM) & vox_ptt)
		{
			return PTTMode.VOX;
		}
		return PTTMode.NONE;
	}

	private async void PollPTT()
	{
		while (chkPower.Checked)
		{
			int num = NetworkIO.nativeGetDotDashPTT();
			DSPMode dSPMode = ((chkVFOBTX.Checked && chkRX2.Checked) ? _rx2_dsp_mode : _rx1_dsp_mode);
			if (!_manual_mox && !_disable_ptt && !_rx_only && !_tx_inhibit && !QSKEnabled && !_ganymede_pa_issue)
			{
				bool flag = (num & 1) != 0;
				bool flag2 = CWInput.KeyerPTT && _current_breakin_mode == BreakIn.Semi;
				bool flag3 = (!_mic_muted || ((vac_enabled || vac2_enabled) && !_allow_micvox_bypass)) && Audio.VOXActive;
				bool flag4 = (_ptt_bit_bang_enabled && serialPTT != null && serialPTT.isPTT()) | (!_ptt_bit_bang_enabled && CWInput.CATPTT) | _cat_ptt;
				if (!_mox)
				{
					if (_stop_all_tx)
					{
						if ((flag | flag2 | flag4 | flag3) || _tci_ptt)
						{
							await Task.Delay(1);
							continue;
						}
						_stop_all_tx = false;
					}
					if (!ARP.IsBusy || !BypassVACWhenPlayingWAV)
					{
						if (chkVAC1.Checked && (((flag | flag2) && _allow_vac_bypass) || (VOXEnable && _allow_micvox_bypass)))
						{
							if (!Audio.VACBypass)
							{
								Audio.VACBypass = true;
							}
						}
						else if (chkVAC1.Checked && Audio.VACBypass)
						{
							Audio.VACBypass = false;
						}
					}
					if (_tci_ptt)
					{
						_current_ptt_mode = PTTMode.TCI;
						chkMOX.Checked = true;
					}
					if (flag4)
					{
						_current_ptt_mode = PTTMode.CAT;
						chkMOX.Checked = true;
					}
					if ((dSPMode == DSPMode.CWL || dSPMode == DSPMode.CWU) && (flag2 | flag))
					{
						_current_ptt_mode = PTTMode.CW;
						chkMOX.Checked = true;
					}
					if (((dSPMode == DSPMode.LSB || dSPMode == DSPMode.USB || dSPMode == DSPMode.DSB || dSPMode == DSPMode.AM || dSPMode == DSPMode.SAM || dSPMode == DSPMode.DIGU || dSPMode == DSPMode.DIGL || dSPMode == DSPMode.FM || _all_mode_mic_ptt) & flag) && _current_ptt_mode != PTTMode.CW)
					{
						_current_ptt_mode = PTTMode.MIC;
						chkMOX.Checked = true;
					}
					if ((dSPMode == DSPMode.LSB || dSPMode == DSPMode.USB || dSPMode == DSPMode.DSB || dSPMode == DSPMode.AM || dSPMode == DSPMode.SAM || dSPMode == DSPMode.DIGU || dSPMode == DSPMode.DIGL || dSPMode == DSPMode.FM) & flag3)
					{
						_current_ptt_mode = PTTMode.VOX;
						chkMOX.Checked = true;
					}
				}
				else
				{
					bool flag5 = false;
					switch (_current_ptt_mode)
					{
					case PTTMode.TCI:
					{
						if (_tci_ptt)
						{
							flag5 = true;
							break;
						}
						PTTMode fallbackPTTModeAfterTCIRelease = getFallbackPTTModeAfterTCIRelease(dSPMode, flag, flag2, flag4, flag3);
						if (fallbackPTTModeAfterTCIRelease == PTTMode.NONE)
						{
							chkMOX.Checked = false;
							flag5 = true;
						}
						else
						{
							_current_ptt_mode = fallbackPTTModeAfterTCIRelease;
							flag5 = fallbackPTTModeAfterTCIRelease == PTTMode.CAT;
						}
						break;
					}
					case PTTMode.CAT:
						if (!flag4)
						{
							chkMOX.Checked = false;
						}
						flag5 = true;
						break;
					case PTTMode.MIC:
						if (!flag)
						{
							chkMOX.Checked = false;
							flag5 = true;
						}
						break;
					case PTTMode.CW:
						if (!flag2 && !flag)
						{
							chkMOX.Checked = false;
							flag5 = true;
						}
						break;
					case PTTMode.VOX:
						if (!flag3)
						{
							chkMOX.Checked = false;
						}
						break;
					}
					if ((!ARP.IsBusy || !BypassVACWhenPlayingWAV) && (chkVAC1.Checked & flag5) && Audio.VACBypass)
					{
						Audio.VACBypass = false;
					}
				}
			}
			await Task.Delay(1);
		}
	}

	private async void PollCW()
	{
		while (chkPower.Checked)
		{
			int num = NetworkIO.nativeGetDotDashPTT();
			bool flag = (num & 4) != 0;
			if (flag != _last_dot)
			{
				FWDot = flag;
				if ((_rx1_dsp_mode == DSPMode.CWL || _rx1_dsp_mode == DSPMode.CWU) && _current_breakin_mode == BreakIn.Manual)
				{
					AudioMOXChanged(flag);
				}
				_last_dot = flag;
			}
			bool flag2 = (num & 2) != 0;
			if (flag2 != _last_dash)
			{
				FWDash = flag2;
				if ((_rx1_dsp_mode == DSPMode.CWL || _rx1_dsp_mode == DSPMode.CWU) && _current_breakin_mode == BreakIn.Manual)
				{
					AudioMOXChanged(flag2);
				}
				_last_dash = flag2;
			}
			update_for_auto_mode_return(flag | flag2);
			await Task.Delay(1);
		}
	}

	private void cwAutoModeTick(object o)
	{
		if (_old_cw_auto_mode == DSPMode.FIRST)
		{
			return;
		}
		if (_cw_auto_mode_tx_on_rx2)
		{
			if (base.InvokeRequired)
			{
				Invoke((Action)delegate
				{
					RX2DSPMode = _old_cw_auto_mode;
				});
			}
			else
			{
				RX2DSPMode = _old_cw_auto_mode;
			}
		}
		else if (base.InvokeRequired)
		{
			Invoke((Action)delegate
			{
				RX1DSPMode = _old_cw_auto_mode;
			});
		}
		else
		{
			RX1DSPMode = _old_cw_auto_mode;
		}
		_old_cw_auto_mode = DSPMode.FIRST;
	}

	private void update_for_auto_mode_return(bool enabled)
	{
		if (!(_cw_auto_mode_switch & enabled))
		{
			return;
		}
		bool flag = RX2Enabled && VFOBTX;
		DSPMode dSPMode = (flag ? RX2DSPMode : RX1DSPMode);
		bool flag2 = dSPMode == DSPMode.CWL || dSPMode == DSPMode.CWU;
		if (!flag2)
		{
			switch (dSPMode)
			{
			case DSPMode.LSB:
			case DSPMode.DIGL:
				if (flag)
				{
					RX2DSPMode = DSPMode.CWL;
				}
				else
				{
					RX1DSPMode = DSPMode.CWL;
				}
				break;
			default:
				if (flag)
				{
					RX2DSPMode = DSPMode.CWU;
				}
				else
				{
					RX1DSPMode = DSPMode.CWU;
				}
				break;
			case DSPMode.CWL:
			case DSPMode.CWU:
				break;
			}
		}
		if (_return_from_cw_auto_mode_switch)
		{
			if (!flag2)
			{
				_old_cw_auto_mode = dSPMode;
			}
			_cw_auto_mode_tx_on_rx2 = flag;
			if (_cwAutoModeTick == null)
			{
				_cwAutoModeTick = new System.Threading.Timer(cwAutoModeTick, null, _return_from_cw_auto_mode_switch_ms, -1);
			}
			else
			{
				_cwAutoModeTick.Change(_return_from_cw_auto_mode_switch_ms, -1);
			}
		}
		else
		{
			_old_cw_auto_mode = DSPMode.FIRST;
		}
	}

	private void UpdatePreamps()
	{
		if (HardwareSpecific.Model == HPSDRModel.HPSDR)
		{
			update_preamp = false;
			update_preamp_mode = false;
		}
		else
		{
			if (_mox || !m_bATTonTX || initializing)
			{
				return;
			}
			if (update_preamp_mode && !update_preamp_mutex)
			{
				update_preamp_mutex = true;
				SetupForm.RX1EnableAtt = old_satt;
				SetupForm.ATTOnRX1 = old_satt_data;
				RX1PreampMode = preamp;
				if (HardwareSpecific.Model == HPSDRModel.ANAN100D || HardwareSpecific.Model == HPSDRModel.ANAN200D || HardwareSpecific.Model == HPSDRModel.ORIONMKII || HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ANAN_G2E || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.REDPITAYA)
				{
					SetupForm.RX2EnableAtt = old_rx2_satt;
					SetupForm.ATTOnRX2 = old_rx2_satt_data;
					RX2PreampMode = rx2_preamp;
				}
				update_preamp_mode = false;
				update_preamp_mutex = false;
			}
			if (update_preamp && !update_preamp_mutex)
			{
				old_satt = _rx1_step_att_enabled;
				old_satt_data = SetupForm.ATTOnRX1;
				preamp = RX1PreampMode;
				if (HardwareSpecific.Model == HPSDRModel.ANAN100D || HardwareSpecific.Model == HPSDRModel.ANAN200D || HardwareSpecific.Model == HPSDRModel.ORIONMKII || HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ANAN_G2E || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.REDPITAYA)
				{
					old_rx2_satt = SetupForm.RX2EnableAtt;
					old_rx2_satt_data = SetupForm.ATTOnRX2;
					rx2_preamp = RX2PreampMode;
				}
				update_preamp = false;
			}
		}
	}

	private async void PollTXInhibit()
	{
		while (chkPower.Checked)
		{
			if (_useTxInhibit && HardwareSpecific.Model != HPSDRModel.HPSDR)
			{
				bool flag = ((NetworkIO.CurrentRadioProtocol == RadioProtocol.USB) ? ((HardwareSpecific.Model != HPSDRModel.ANAN_G2E && HardwareSpecific.Model != HPSDRModel.ANAN7000D && HardwareSpecific.Model != HPSDRModel.ANAN8000D && HardwareSpecific.Model != HPSDRModel.REDPITAYA) ? (!NetworkIO.getUserI01()) : (!NetworkIO.getUserI02())) : ((HardwareSpecific.Model != HPSDRModel.ANAN7000D && HardwareSpecific.Model != HPSDRModel.ANAN8000D && HardwareSpecific.Model != HPSDRModel.ANAN_G2 && HardwareSpecific.Model != HPSDRModel.ANAN_G2_1K && HardwareSpecific.Model != HPSDRModel.ANVELINAPRO3 && HardwareSpecific.Model != HPSDRModel.REDPITAYA) ? (!NetworkIO.getUserI04_p2()) : (!NetworkIO.getUserI05_p2())));
				if (_reverseTxInhibit)
				{
					flag = !flag;
				}
				if (TXInhibit != flag)
				{
					TXInhibitChangedHandlers?.Invoke(TXInhibit, flag);
				}
			}
			else if (!_useTxInhibit && TXInhibit)
			{
				TXInhibitChangedHandlers?.Invoke(TXInhibit, newState: false);
			}
			await Task.Delay(100);
		}
	}

	private async void PollN1MMPacket()
	{
		if (n1mm_udp_client != null)
		{
			n1mm_udp_client.Close();
		}
		IPEndPoint udp_ep = new IPEndPoint(IPAddress.Any, focus_master_udp_port);
		n1mm_udp_client = new UdpClient(udp_ep);
		while (focus_master_mode == FocusMasterMode.Logger)
		{
			try
			{
				byte[] bytes = n1mm_udp_client.Receive(ref udp_ep);
				string str = Encoding.UTF8.GetString(bytes);
				HandleXml(str);
			}
			catch (SocketException)
			{
				await Task.Delay(500);
			}
			catch
			{
			}
		}
		if (n1mm_udp_client != null)
		{
			n1mm_udp_client.Close();
			n1mm_udp_client = null;
		}
	}

	private void n1mm_delay_Elapsed(object sender, ElapsedEventArgs e)
	{
		if (selectByClick & !initializing)
		{
			IntPtr foregroundWindow = Win32.GetForegroundWindow();
			if (foregroundWindow != myHandle)
			{
				n1mm_handle = foregroundWindow;
				selectByClick = false;
				SetFocusMaster(state: false);
				StringBuilder stringBuilder = new StringBuilder(Win32.GetWindowTextLengthW(n1mm_handle) + 1);
				Win32.GetWindowTextW(n1mm_handle, stringBuilder, 256);
				SetupForm.FocusMasterTitle = stringBuilder.ToString();
			}
			else
			{
				ToggleFocusMasterTimer();
			}
		}
		if (n1mm_handle != IntPtr.Zero && !Win32.IsWindow(n1mm_handle))
		{
			n1mm_handle = IntPtr.Zero;
			SetupForm.FocusMasterMode = FocusMasterMode.None;
			SetupForm.FocusMasterTitle = "";
		}
		if (n1mm_state == 3)
		{
			n1mm_state = 0;
			if (n1mm_handle != IntPtr.Zero)
			{
				Win32.SetForegroundWindow(n1mm_handle);
			}
		}
	}

	private void HandleXml(string str)
	{
		XElement xElement = XElement.Parse(str);
		if (xElement.Name == "RadioInfo" && int.TryParse(xElement.Element("FocusEntry").Value, out var result))
		{
			n1mm_handle = (IntPtr)result;
		}
	}

	private void ToggleFocusMasterTimer()
	{
		if (focus_master_mode != FocusMasterMode.None && n1mm_state != 1 && n1mm_delay != null)
		{
			n1mm_state = 3;
			n1mm_delay.Enabled = false;
			n1mm_delay.Enabled = true;
		}
	}

	private async void PollPAPWR()
	{
		int high_swr_count = 0;
		bool swr_pass = false;
		while (chkPower.Checked)
		{
			float sWRProtect;
			float num2;
			if (_mox)
			{
				sWRProtect = NetworkIO.SWRProtect;
				alex_fwd = computeAlexFwdPower();
				alex_rev = computeRefPower();
				switch (HardwareSpecific.Model)
				{
				case HPSDRModel.ANAN200D:
					drivepwr = computeOrionExciterPower();
					break;
				case HPSDRModel.ORIONMKII:
				case HPSDRModel.ANAN7000D:
				case HPSDRModel.ANAN8000D:
				case HPSDRModel.ANAN_G2:
				case HPSDRModel.ANAN_G2_1K:
				case HPSDRModel.ANVELINAPRO3:
				case HPSDRModel.REDPITAYA:
				case HPSDRModel.ANAN_G2E:
					drivepwr = computeOrionMkIIExciterPower();
					break;
				default:
					drivepwr = computeExciterPower();
					break;
				}
				calfwdpower = CalibratedPAPower();
				average_drivepwr = 0.9f * average_drivepwr + 0.100000024f * drivepwr;
				float num = (float)Math.Sqrt(alex_rev / alex_fwd);
				num2 = ((!float.IsNaN(num) && !float.IsInfinity(num)) ? ((1f + num) / (1f - num)) : 1f);
				if ((alex_fwd <= 2f && alex_rev <= 2f) || num2 < 1f)
				{
					num2 = 1f;
				}
				if (alexpresent || apollopresent)
				{
					if (!chkTUN.Checked && swrprotection && alex_fwd > 10f && alex_fwd - alex_rev < 1f && HardwareSpecific.Model != HPSDRModel.ANAN8000D)
					{
						num2 = 50f;
						NetworkIO.SWRProtect = 0.01f;
						chkMOX.Checked = false;
						if (base.InvokeRequired)
						{
							Invoke((MethodInvoker)delegate
							{
								checkAntennaWarning();
							});
						}
						else
						{
							checkAntennaWarning();
						}
						goto IL_03f9;
					}
				}
				else
				{
					num2 = 1f;
					alex_fwd = 0f;
					alex_rev = 0f;
				}
				if (chkTUN.Checked && disable_swr_on_tune && (alexpresent || apollopresent))
				{
					int num3 = (chk2TONE.Checked ? (TwoToneDrivePowerOrigin switch
					{
						DrivePowerSource.TUNE_SLIDER => ptbTune.Value, 
						DrivePowerSource.DRIVE_SLIDER => ptbPWR.Value, 
						_ => ptbPWR.Value, 
					}) : (TuneDrivePowerOrigin switch
					{
						DrivePowerSource.TUNE_SLIDER => ptbTune.Value, 
						DrivePowerSource.DRIVE_SLIDER => ptbPWR.Value, 
						_ => ptbPWR.Value, 
					}));
					swr_pass = ((alex_fwd >= 1f && alex_fwd <= _tunePowerSwrIgnore && num3 <= 70) ? true : false);
				}
				if (tx_xvtr_index >= 0 || hf_tr_relay)
				{
					swr_pass = true;
				}
				float num4 = 5f;
				if (HardwareSpecific.Model == HPSDRModel.ANAN8000D)
				{
					num4 = 2f * (float)ptbPWR.Value;
				}
				if (num2 > _swrProtectionLimit && alex_fwd > num4 && swrprotection && !swr_pass)
				{
					high_swr_count++;
					if (high_swr_count >= 4)
					{
						high_swr_count = 0;
						NetworkIO.SWRProtect = _swrProtectionLimit / (num2 + 1f);
						HighSWR = true;
					}
				}
				else
				{
					high_swr_count = 0;
					NetworkIO.SWRProtect = 1f;
					HighSWR = false;
				}
				if (swrprotection && (_swr_wind_back_power & !_wind_back_engaged) && HighSWR)
				{
					_wind_back_engaged = true;
				}
				if (_wind_back_engaged)
				{
					NetworkIO.SWRProtect = 0.01f;
					Display.PowerFoldedBack = true;
				}
				else
				{
					Display.PowerFoldedBack = false;
				}
				goto IL_03f9;
			}
			if (high_swr)
			{
				HighSWR = false;
			}
			goto IL_0460;
			IL_0460:
			if (_mox)
			{
				await Task.Delay(1);
			}
			else
			{
				await Task.Delay(10);
			}
			continue;
			IL_03f9:
			swr_pass = false;
			if (float.IsNaN(num2) || float.IsInfinity(num2) || num2 < 1f)
			{
				alex_swr = 1f;
			}
			else
			{
				alex_swr = num2;
			}
			if (_swr_wind_back_power && swrprotection && sWRProtect != NetworkIO.SWRProtect)
			{
				Audio.RadioVolume = Audio.RadioVolume;
			}
			goto IL_0460;
		}
		alex_fwd = 0f;
		alex_rev = 0f;
		drivepwr = 0f;
		calfwdpower = 0f;
		alex_swr = 0f;
		average_drivepwr = 0f;
	}

	private void checkAntennaWarning()
	{
		MessageBox.Show("Please check your antenna connection.", "High SWR condition detected", MessageBoxButtons.OK, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
	}

	private double SWRScale(double ref_pow)
	{
		if (ref_pow < 19.0)
		{
			return 1.0;
		}
		return Math.Max(ref_pow * -0.01774 + 1.137097, 0.25);
	}

	private void timer_cpu_volts_meter_Tick(object sender, EventArgs e)
	{
		if (DisplayVoltsAmps && HardwareSpecific.HasVolts && HardwareSpecific.HasAmps)
		{
			computeMKIIPAVoltsAmps();
			if (!toolStripStatusLabel_Volts.Visible)
			{
				toolStripStatusLabel_Volts.Visible = true;
			}
			if (!toolStripStatusLabel_Amps.Visible)
			{
				toolStripStatusLabel_Amps.Visible = true;
			}
			if (Math.Abs(_MKIIPAVolts - _oldMKIIPAVolts) >= 0.1f)
			{
				toolStripStatusLabel_Volts.Text = $"{_MKIIPAVolts:#0.0}V";
				_oldMKIIPAVolts = _MKIIPAVolts;
			}
			else
			{
				toolStripStatusLabel_Volts.Text = $"{_oldMKIIPAVolts:#0.0}V";
			}
			if (Math.Abs(_MKIIPAAmps - _oldMKIIPAAmps) >= 0.1f)
			{
				toolStripStatusLabel_Amps.Text = $"{_MKIIPAAmps:#0.0}A";
				_oldMKIIPAAmps = _MKIIPAAmps;
			}
			else
			{
				toolStripStatusLabel_Amps.Text = $"{_oldMKIIPAAmps:#0.0}A";
			}
		}
		else
		{
			if (toolStripStatusLabel_Volts.Visible)
			{
				toolStripStatusLabel_Volts.Visible = false;
			}
			if (toolStripStatusLabel_Amps.Visible)
			{
				toolStripStatusLabel_Amps.Visible = false;
			}
		}
		if (!_cpu_usage_setup || Environment.ProcessorCount <= 0 || ((_total_cpu_usage == null || !m_bShowSystemCPUUsage) && m_bShowSystemCPUUsage))
		{
			return;
		}
		if (!toolStripDropDownButton_CPU.Visible)
		{
			toolStripDropDownButton_CPU.Visible = true;
		}
		float num = 0f;
		if (m_bShowSystemCPUUsage)
		{
			if (_total_cpu_usage != null)
			{
				num = _total_cpu_usage.NextValue();
			}
		}
		else
		{
			num = (float)Common.ProcessCPUUsage();
		}
		_cpu_perc_smoothed = _cpu_perc_smoothed * 0.8f + num * 0.2f;
		toolStripDropDownButton_CPU.Text = $"{_cpu_perc_smoothed:##0}%";
	}

