	private void Console_KeyDown(object sender, KeyEventArgs e)
	{
		if (Common.ShiftKeyDown)
		{
			Display.DisplayShiftKeyDown = true;
		}
		if (e.Alt && e.KeyCode == Keys.M)
		{
			ALTM = true;
			if (memoryForm == null || memoryForm.IsDisposed)
			{
				memoryForm = new MemoryForm(this);
			}
			memoryForm.MemoryRecordAdd_Click(memoryForm.MemoryRecordAdd, EventArgs.Empty);
		}
		ALTM = false;
		if (e.Control && e.Alt)
		{
			Keys keyCode = e.KeyCode;
			if (keyCode <= Keys.D)
			{
				if (keyCode != Keys.D4)
				{
					_ = 68;
				}
			}
			else if (keyCode != Keys.F && keyCode != Keys.R)
			{
				_ = 85;
			}
		}
		else if (!enable_kb_shortcuts)
		{
			e.Handled = true;
		}
		else if (e.Control && !e.Alt)
		{
			switch (e.KeyCode)
			{
			case Keys.F1:
			case Keys.F2:
			case Keys.F3:
			case Keys.F4:
			case Keys.F5:
			case Keys.F6:
			case Keys.F7:
			case Keys.F8:
			case Keys.F9:
			case Keys.F10:
			{
				int num = 0;
				if (e.KeyCode == Keys.F1)
				{
					num = 1;
				}
				else if (e.KeyCode == Keys.F2)
				{
					num = 2;
				}
				else if (e.KeyCode == Keys.F3)
				{
					num = 3;
				}
				else if (e.KeyCode == Keys.F4)
				{
					num = 4;
				}
				else if (e.KeyCode == Keys.F5)
				{
					num = 5;
				}
				else if (e.KeyCode == Keys.F6)
				{
					num = 6;
				}
				else if (e.KeyCode == Keys.F7)
				{
					num = 7;
				}
				else if (e.KeyCode == Keys.F8)
				{
					num = 8;
				}
				else if (e.KeyCode == Keys.F9)
				{
					num = 9;
				}
				if (num == 0)
				{
					CWXForm.CWXStop();
				}
				else
				{
					CWXForm.StartQueue = num;
				}
				e.Handled = true;
				break;
			}
			case Keys.Add:
				if (ptbRF.Value != ptbRF.Maximum)
				{
					RF++;
				}
				break;
			case Keys.Subtract:
				if (ptbRF.Value != ptbRF.Minimum)
				{
					RF--;
				}
				break;
			case Keys.Left:
				ChangeTuneStepUp();
				e.Handled = true;
				break;
			case Keys.Right:
				ChangeTuneStepDown();
				e.Handled = true;
				break;
			case Keys.Up:
				enableOutsideSpectral();
				Console_MouseWheel(this, new MouseEventArgs(MouseButtons.None, 0, 0, 0, 120));
				restoreOutsideSpectral();
				e.Handled = true;
				break;
			case Keys.Down:
				enableOutsideSpectral();
				Console_MouseWheel(this, new MouseEventArgs(MouseButtons.None, 0, 0, 0, -120));
				restoreOutsideSpectral();
				e.Handled = true;
				break;
			case Keys.A:
				if (RX1AGCMode == AGCMode.FAST)
				{
					RX1AGCMode = AGCMode.FIXD;
				}
				else
				{
					RX1AGCMode++;
				}
				break;
			case Keys.B:
				if (_nr_selected[0] > 0)
				{
					SelectNR(1, incude_sub: true, 0);
				}
				else
				{
					SelectNR(1, incude_sub: true, 1);
				}
				break;
			case Keys.C:
				btnMemoryQuickSave_Click(this, EventArgs.Empty);
				break;
			case Keys.D:
				switch (Display.CurrentDisplayMode)
				{
				case DisplayMode.PANADAPTER:
					comboDisplayMode.Text = "Spectrum";
					break;
				case DisplayMode.SPECTRUM:
					comboDisplayMode.Text = "Panadapter";
					break;
				default:
					comboDisplayMode.Text = "Panadapter";
					break;
				}
				break;
			case Keys.E:
				if (ptbRF.Value != ptbRF.Minimum)
				{
					RF--;
				}
				break;
			case Keys.F:
			{
				int num2 = (int)udFilterLow.Value;
				int num3 = (int)udFilterHigh.Value;
				SelectRX1VarFilter(update: false);
				switch (_rx1_dsp_mode)
				{
				case DSPMode.DSB:
				case DSPMode.CWL:
				case DSPMode.CWU:
				case DSPMode.FM:
				case DSPMode.AM:
				case DSPMode.SAM:
					UpdateRX1Filters(num2 + 10, num3 - 10);
					break;
				case DSPMode.USB:
				case DSPMode.DIGU:
					UpdateRX1Filters(num2, num3 - 50);
					break;
				case DSPMode.LSB:
				case DSPMode.DIGL:
					UpdateRX1Filters(num2 + 50, num3);
					break;
				}
				e.Handled = true;
				break;
			}
			case Keys.J:
			{
				int num2 = (int)udFilterLow.Value;
				int num3 = (int)udFilterHigh.Value;
				int num4 = 0;
				SelectRX1VarFilter(update: false);
				switch (_rx1_dsp_mode)
				{
				case DSPMode.CWL:
				case DSPMode.CWU:
				case DSPMode.DIGU:
				case DSPMode.DIGL:
					num4 = 10;
					break;
				default:
					num4 = 50;
					break;
				}
				UpdateRX1Filters(num2 - num4, num3 - num4);
				e.Handled = true;
				break;
			}
			case Keys.L:
				if (chkVFOLock.Enabled)
				{
					chkVFOLock.Checked = !chkVFOLock.Checked;
				}
				break;
			case Keys.M:
				if (chkMOX.Enabled)
				{
					chkMOX.Checked = !_mox;
				}
				break;
			case Keys.N:
				chkANF.Checked = !chkANF.Checked;
				break;
			case Keys.P:
				RX1PreampMode = (PreampMode)((int)(rx1_preamp_mode + 1) % 10);
				break;
			case Keys.R:
				if (ptbRF.Value != ptbRF.Maximum)
				{
					RF++;
				}
				break;
			case Keys.S:
				if (chkVFOSplit.Enabled)
				{
					chkVFOSplit.Checked = !chkVFOSplit.Checked;
				}
				break;
			case Keys.V:
				btnMemoryQuickRestore_Click(this, EventArgs.Empty);
				break;
			case Keys.W:
				if (ptbCWSpeed.Value != ptbCWSpeed.Minimum)
				{
					ptbCWSpeed.Value--;
					ptbCWSpeed_Scroll(this, EventArgs.Empty);
				}
				break;
			}
		}
		else if (e.Alt && !e.Control)
		{
			switch (e.KeyCode)
			{
			case Keys.Up:
				if (ptbMic.Value != ptbMic.Maximum)
				{
					ptbMic.Value++;
					ptbMic_Scroll(this, EventArgs.Empty);
				}
				break;
			case Keys.Down:
				if (ptbMic.Value != ptbMic.Minimum)
				{
					ptbMic.Value--;
					ptbMic_Scroll(this, EventArgs.Empty);
				}
				break;
			case Keys.Right:
				if (ptbVOX.Value != ptbVOX.Maximum)
				{
					ptbVOX.Value++;
					ptbVOX_Scroll(this, EventArgs.Empty);
				}
				break;
			case Keys.Left:
				if (ptbVOX.Value != ptbVOX.Minimum)
				{
					ptbVOX.Value--;
					ptbVOX_Scroll(this, EventArgs.Empty);
				}
				break;
			case Keys.B:
				chkNB.Checked = !chkNB.Checked;
				break;
			case Keys.D:
				chkEnableMultiRX.Checked = !chkEnableMultiRX.Checked;
				break;
			case Keys.F:
			{
				int num5 = (int)udFilterLow.Value;
				int num6 = (int)udFilterHigh.Value;
				SelectRX1VarFilter(update: false);
				switch (_rx1_dsp_mode)
				{
				case DSPMode.DSB:
				case DSPMode.CWL:
				case DSPMode.CWU:
				case DSPMode.FM:
				case DSPMode.AM:
				case DSPMode.SAM:
					UpdateRX1Filters(num5 - 10, num6 + 10);
					break;
				case DSPMode.USB:
				case DSPMode.DIGU:
					UpdateRX1Filters(num5, num6 + 50);
					break;
				case DSPMode.LSB:
				case DSPMode.DIGL:
					UpdateRX1Filters(num5 - 50, num6);
					break;
				}
				e.Handled = true;
				break;
			}
			case Keys.G:
				btnVFOAtoB_Click(this, EventArgs.Empty);
				break;
			case Keys.H:
				btnVFOBtoA_Click(this, EventArgs.Empty);
				break;
			case Keys.I:
				btnFilterShiftReset_Click(this, EventArgs.Empty);
				break;
			case Keys.J:
			{
				int num5 = (int)udFilterLow.Value;
				int num6 = (int)udFilterHigh.Value;
				int num7 = 0;
				SelectRX1VarFilter(update: false);
				switch (_rx1_dsp_mode)
				{
				case DSPMode.CWL:
				case DSPMode.CWU:
				case DSPMode.DIGU:
				case DSPMode.DIGL:
					num7 = 10;
					break;
				default:
					num7 = 50;
					break;
				}
				UpdateRX1Filters(num5 + num7, num6 + num7);
				e.Handled = true;
				break;
			}
			case Keys.N:
				chkDSPNB2.Checked = !chkDSPNB2.Checked;
				break;
			case Keys.Q:
				if (ptbCWSpeed.Value != ptbCWSpeed.Maximum)
				{
					ptbCWSpeed.Value++;
					ptbCWSpeed_Scroll(this, EventArgs.Empty);
				}
				break;
			case Keys.R:
				btnRITReset_Click(this, EventArgs.Empty);
				break;
			case Keys.T:
				chkTUN.Checked = !chkTUN.Checked;
				break;
			case Keys.V:
				btnVFOSwap_Click(this, EventArgs.Empty);
				break;
			case Keys.Y:
				btnXITReset_Click(this, EventArgs.Empty);
				break;
			case Keys.Z:
				if (btnZeroBeat.Enabled)
				{
					btnZeroBeat_Click(this, EventArgs.Empty);
				}
				break;
			}
		}
		else
		{
			if (e.Alt || e.Control)
			{
				return;
			}
			if (base.ActiveControl is TextBoxTS || base.ActiveControl is NumericUpDownTS)
			{
				if (e.KeyCode != Keys.Space)
				{
					return;
				}
				btnHidden.Focus();
				e.SuppressKeyPress = true;
			}
			switch (e.KeyCode)
			{
			case Keys.Space:
				if (chkPower.Checked)
				{
					if (spacebar_ptt)
					{
						_current_ptt_mode = PTTMode.SPACE;
						chkMOX.Checked = !chkMOX.Checked;
						if (!ARP.IsBusy || !BypassVACWhenPlayingWAV)
						{
							if (chkMOX.Checked)
							{
								if (chkVAC1.Checked && allow_space_bypass)
								{
									Audio.VACBypass = true;
								}
							}
							else if (chkVAC1.Checked && Audio.VACBypass)
							{
								Audio.VACBypass = false;
							}
						}
						e.Handled = true;
					}
					else if (spacebar_vox)
					{
						chkVOX.Checked = !chkVOX.Checked;
						e.Handled = true;
					}
					else if (spacebar_mic_mute)
					{
						chkMicMute.Checked = !chkMicMute.Checked;
						e.Handled = true;
					}
					else if (_spacebar_vfobtx)
					{
						if (VFOATX)
						{
							VFOBTX = true;
						}
						else
						{
							VFOATX = true;
						}
						e.Handled = true;
					}
					else if (!spacebar_last_btn)
					{
					}
				}
				else if (!spacebar_last_btn)
				{
					e.Handled = true;
				}
				break;
			case Keys.Multiply:
				chkMUT.Checked = !chkMUT.Checked;
				break;
			case Keys.Add:
				if (ptbAF.Value != ptbAF.Maximum)
				{
					ptbAF.Value++;
					ptbAF_Scroll(this, EventArgs.Empty);
				}
				break;
			case Keys.Subtract:
				if (ptbAF.Value != ptbAF.Minimum)
				{
					ptbAF.Value--;
					ptbAF_Scroll(this, EventArgs.Empty);
				}
				break;
			}
			if (e.KeyCode == key_tune_up_1)
			{
				double vFOAFreq = VFOAFreq;
				vFOAFreq++;
				VFOAFreq = vFOAFreq;
			}
			else if (e.KeyCode == key_tune_down_1)
			{
				double vFOAFreq2 = VFOAFreq;
				vFOAFreq2--;
				VFOAFreq = vFOAFreq2;
			}
			else if (e.KeyCode == key_tune_up_2)
			{
				double vFOAFreq3 = VFOAFreq;
				vFOAFreq3 += 0.1;
				VFOAFreq = vFOAFreq3;
			}
			else if (e.KeyCode == key_tune_down_2)
			{
				double vFOAFreq4 = VFOAFreq;
				vFOAFreq4 -= 0.1;
				VFOAFreq = vFOAFreq4;
			}
			else if (e.KeyCode == key_tune_up_3)
			{
				double vFOAFreq5 = VFOAFreq;
				vFOAFreq5 += 0.01;
				VFOAFreq = vFOAFreq5;
			}
			else if (e.KeyCode == key_tune_down_3)
			{
				double vFOAFreq6 = VFOAFreq;
				vFOAFreq6 -= 0.01;
				VFOAFreq = vFOAFreq6;
			}
			else if (e.KeyCode == key_tune_up_4)
			{
				double vFOAFreq7 = VFOAFreq;
				vFOAFreq7 += 0.001;
				VFOAFreq = vFOAFreq7;
			}
			else if (e.KeyCode == key_tune_down_4)
			{
				double vFOAFreq8 = VFOAFreq;
				vFOAFreq8 -= 0.001;
				VFOAFreq = vFOAFreq8;
			}
			else if (e.KeyCode == key_tune_up_5)
			{
				double vFOAFreq9 = VFOAFreq;
				vFOAFreq9 += 0.0001;
				VFOAFreq = vFOAFreq9;
			}
			else if (e.KeyCode == key_tune_down_5)
			{
				double vFOAFreq10 = VFOAFreq;
				vFOAFreq10 -= 0.0001;
				VFOAFreq = vFOAFreq10;
			}
			else if (e.KeyCode == key_tune_up_6)
			{
				double vFOAFreq11 = VFOAFreq;
				vFOAFreq11 += 1E-05;
				VFOAFreq = vFOAFreq11;
			}
			else if (e.KeyCode == key_tune_down_6)
			{
				double vFOAFreq12 = VFOAFreq;
				vFOAFreq12 -= 1E-05;
				VFOAFreq = vFOAFreq12;
			}
			else if (e.KeyCode == key_tune_up_7)
			{
				double vFOAFreq13 = VFOAFreq;
				vFOAFreq13 += 1E-06;
				VFOAFreq = vFOAFreq13;
			}
			else if (e.KeyCode == key_tune_down_7)
			{
				double vFOAFreq14 = VFOAFreq;
				vFOAFreq14 -= 1E-06;
				VFOAFreq = vFOAFreq14;
			}
			else if (e.KeyCode == key_rit_up)
			{
				udRIT.Value += udRIT.Increment;
			}
			else if (e.KeyCode == key_rit_down)
			{
				udRIT.Value -= udRIT.Increment;
			}
			else if (e.KeyCode == key_xit_up)
			{
				udXIT.Value += udXIT.Increment;
			}
			else if (e.KeyCode == key_xit_down)
			{
				udXIT.Value -= udXIT.Increment;
			}
			else if (e.KeyCode == key_filter_up)
			{
				if (rx1_filter != Filter.NONE)
				{
					if (rx1_filter == Filter.VAR2)
					{
						RX1Filter = Filter.F1;
					}
					else
					{
						RX1Filter++;
					}
				}
			}
			else if (e.KeyCode == key_filter_down)
			{
				if (rx1_filter != Filter.NONE)
				{
					if (rx1_filter == Filter.F1)
					{
						RX1Filter = Filter.VAR2;
					}
					else
					{
						RX1Filter--;
					}
				}
			}
			else if (e.KeyCode == key_mode_up)
			{
				switch (_rx1_dsp_mode)
				{
				case DSPMode.LSB:
					RX1DSPMode = DSPMode.USB;
					break;
				case DSPMode.USB:
					RX1DSPMode = DSPMode.DSB;
					break;
				case DSPMode.DSB:
					RX1DSPMode = DSPMode.CWL;
					break;
				case DSPMode.CWL:
					RX1DSPMode = DSPMode.CWU;
					break;
				case DSPMode.CWU:
					RX1DSPMode = DSPMode.FM;
					break;
				case DSPMode.FM:
					RX1DSPMode = DSPMode.AM;
					break;
				case DSPMode.AM:
					RX1DSPMode = DSPMode.SAM;
					break;
				case DSPMode.SAM:
					RX1DSPMode = DSPMode.DIGL;
					break;
				case DSPMode.DIGL:
					RX1DSPMode = DSPMode.DIGU;
					break;
				case DSPMode.DIGU:
					RX1DSPMode = DSPMode.SPEC;
					break;
				case DSPMode.SPEC:
					RX1DSPMode = DSPMode.DRM;
					break;
				case DSPMode.DRM:
					RX1DSPMode = DSPMode.LSB;
					break;
				}
			}
			else if (e.KeyCode == key_mode_down)
			{
				switch (_rx1_dsp_mode)
				{
				case DSPMode.LSB:
					RX1DSPMode = DSPMode.DRM;
					break;
				case DSPMode.USB:
					RX1DSPMode = DSPMode.LSB;
					break;
				case DSPMode.DSB:
					RX1DSPMode = DSPMode.USB;
					break;
				case DSPMode.CWL:
					RX1DSPMode = DSPMode.DSB;
					break;
				case DSPMode.CWU:
					RX1DSPMode = DSPMode.CWL;
					break;
				case DSPMode.FM:
					RX1DSPMode = DSPMode.CWU;
					break;
				case DSPMode.AM:
					RX1DSPMode = DSPMode.FM;
					break;
				case DSPMode.SAM:
					RX1DSPMode = DSPMode.AM;
					break;
				case DSPMode.DIGL:
					RX1DSPMode = DSPMode.SAM;
					break;
				case DSPMode.DIGU:
					RX1DSPMode = DSPMode.DIGL;
					break;
				case DSPMode.SPEC:
					RX1DSPMode = DSPMode.DIGU;
					break;
				case DSPMode.DRM:
					RX1DSPMode = DSPMode.SPEC;
					break;
				}
			}
			else if (e.KeyCode == key_band_up && VFOLock != CheckState.Checked)
			{
				BandStackFilter filter = BandStackManager.GetFilter(RX1Band);
				if (filter != null)
				{
					int indexOfCurrent = filter.IndexOfCurrent;
					if (indexOfCurrent == -1 || indexOfCurrent == filter.NumberOfEntries - 1)
					{
						Band rX1Band = RX1Band;
						rX1Band++;
						if (rX1Band > Band.B6M)
						{
							rX1Band = Band.B160M;
						}
						RX1Band = rX1Band;
						filter = BandStackManager.GetFilter(rX1Band);
						if (filter != null)
						{
							filter.IndexOfCurrent = 0;
							BandStackEntry bse = filter.Current();
							if (bse != null)
							{
								setRX1BandFromBandStackEntry(in bse);
							}
							else
							{
								setRX1BandFromBandStackEntry(filter.LastVisited.Copy());
							}
							BandStack2Form.UpdateSelected();
						}
					}
					else
					{
						BandStackEntry bse2 = filter.Next();
						if (bse2 != null)
						{
							setRX1BandFromBandStackEntry(in bse2);
						}
						else
						{
							setRX1BandFromBandStackEntry(filter.LastVisited.Copy());
						}
						BandStack2Form.UpdateSelected();
					}
				}
				e.Handled = true;
			}
			else if (e.KeyCode == key_band_down && VFOLock != CheckState.Checked)
			{
				BandStackFilter filter2 = BandStackManager.GetFilter(RX1Band);
				if (filter2 != null)
				{
					if (filter2.IndexOfCurrent <= 0)
					{
						Band rX1Band2 = RX1Band;
						rX1Band2--;
						if (rX1Band2 < Band.B160M)
						{
							rX1Band2 = Band.B6M;
						}
						RX1Band = rX1Band2;
						filter2 = BandStackManager.GetFilter(rX1Band2);
						if (filter2 != null)
						{
							filter2.IndexOfCurrent = filter2.NumberOfEntries - 1;
							BandStackEntry bse3 = filter2.Current();
							if (bse3 != null)
							{
								setRX1BandFromBandStackEntry(in bse3);
							}
							else
							{
								setRX1BandFromBandStackEntry(filter2.LastVisited.Copy());
							}
							BandStack2Form.UpdateSelected();
						}
					}
					else
					{
						BandStackEntry bse4 = filter2.Previous();
						if (bse4 != null)
						{
							setRX1BandFromBandStackEntry(in bse4);
						}
						else
						{
							setRX1BandFromBandStackEntry(filter2.LastVisited.Copy());
						}
						BandStack2Form.UpdateSelected();
					}
				}
				e.Handled = true;
			}
			else
			{
				if (e.KeyCode == key_cw_dot || e.KeyCode == key_cw_dash)
				{
					return;
				}
				if (e.KeyCode == key_ptt_rx)
				{
					if (!chkPower.Checked)
					{
						return;
					}
					if (key_ptt_rx != key_ptt_tx)
					{
						if (_mox)
						{
							chkMOX.Checked = false;
						}
					}
					else
					{
						chkMOX.Checked = !chkMOX.Checked;
					}
					e.Handled = true;
				}
				else if (e.KeyCode == key_ptt_tx)
				{
					if (!chkPower.Checked)
					{
						return;
					}
					if (key_ptt_rx != key_ptt_tx)
					{
						if (!_mox)
						{
							chkMOX.Checked = true;
						}
					}
					else
					{
						chkMOX.Checked = !chkMOX.Checked;
					}
					e.Handled = true;
				}
				else
				{
					if (VFOLock == CheckState.Checked || !quick_qsy)
					{
						return;
					}
					if (e.KeyCode >= Keys.D0 && e.KeyCode <= Keys.D9)
					{
						if (small_lsd)
						{
							txtVFOAMSD.Visible = false;
							txtVFOALSD.Visible = false;
						}
						txtVFOAFreq.Focus();
						txtVFOAFreq.Text = ((int)(e.KeyCode - 48)).ToString();
						txtVFOAFreq.Select(1, 0);
					}
					else if (e.KeyCode >= Keys.NumPad0 && e.KeyCode <= Keys.NumPad9)
					{
						if (small_lsd)
						{
							txtVFOAMSD.Visible = false;
							txtVFOALSD.Visible = false;
						}
						txtVFOAFreq.Focus();
						txtVFOAFreq.Text = ((int)(e.KeyCode - 96)).ToString();
						txtVFOAFreq.Select(1, 0);
					}
					else if (e.KeyCode.Equals(Keys.Decimal) || (separator == "." && e.KeyCode.Equals(Keys.OemPeriod)) || (separator == "," && e.KeyCode.Equals(Keys.Oemcomma)))
					{
						if (small_lsd)
						{
							txtVFOAMSD.Visible = false;
							txtVFOALSD.Visible = false;
						}
						txtVFOAFreq.Focus();
						txtVFOAFreq.Text = separator;
						txtVFOAFreq.Select(1, 0);
					}
				}
			}
		}
	}

	private void setupLegacyMeterThreads(int rx)
	{
		if (!_hide_legacy_meters && chkPower.Checked)
		{
			if (rx == 1 && (multimeter_thread == null || !multimeter_thread.IsAlive))
			{
				multimeter_thread = new Thread(UpdateMultimeter)
				{
					Name = "Multimeter Thread",
					Priority = ThreadPriority.Lowest,
					IsBackground = true
				};
				multimeter_thread.Start();
			}
			if (rx2_enabled && rx == 2 && (rx2_meter_thread == null || !rx2_meter_thread.IsAlive))
			{
				rx2_meter_thread = new Thread(UpdateRX2Multimeter)
				{
					Name = "RX2 Meter Thread",
					Priority = ThreadPriority.Lowest,
					IsBackground = true
				};
				rx2_meter_thread.Start();
			}
		}
	}

	private void chkPower_CheckedChanged(object sender, EventArgs e)
	{
		if (DBMan.IsVisible && chkPower.Checked)
		{
			chkPower.Checked = false;
			return;
		}
		if (chkPower.Checked)
		{
			chkPower.BackColor = button_selected_color;
			txtVFOAFreq.ForeColor = vfo_text_light_color;
			txtVFOAMSD.ForeColor = vfo_text_light_color;
			txtVFOALSD.ForeColor = small_vfo_color;
			UpdateDDCs(rx2_enabled);
			UpdateVFOASub();
			if (rx2_enabled)
			{
				update_rx2_display = false;
				chkRX2_CheckedChanged(this, EventArgs.Empty);
			}
			_rx1_dds_freq = 0.0;
			_rx2_dds_freq = 0.0;
			txtVFOAFreq_LostFocus(this, EventArgs.Empty);
			comboDisplayMode_SelectedIndexChanged(this, EventArgs.Empty);
			if (PTTBitBangEnabled && serialPTT == null)
			{
				PTTBitBangEnabled = true;
			}
			Audio.CurrentAudioState1 = Audio.AudioState.DTTSP;
			if (vac_enabled)
			{
				VACEnabled = true;
			}
			if (vac2_enabled)
			{
				VAC2Enabled = true;
			}
			Thread.Sleep(100);
			psform.ForcePS();
			if (m_bATTonTX)
			{
				int tXstepAttenuatorForBand = getTXstepAttenuatorForBand(_tx_band);
				NetworkIO.SetTxAttenData(tXstepAttenuatorForBand);
				Display.TXAttenuatorOffset = tXstepAttenuatorForBand;
			}
			else
			{
				NetworkIO.SetTxAttenData(0);
				Display.TXAttenuatorOffset = 0f;
			}
			enableAudioAmplfier();
			if (!IsSetupFormNull)
			{
				SetupForm.BoardWarning = "";
			}
			if (!Audio.Start())
			{
				chkPower.Checked = false;
				return;
			}
			psform.HardResetPS();
			if (!IsSetupFormNull)
			{
				SetupForm.BoardWarning = NetworkIO.BoardMismatch;
			}
			if (chkEnableMultiRX.Checked)
			{
				chkEnableMultiRX_CheckedChanged(this, EventArgs.Empty);
			}
			if (chkVFOSplit.Checked)
			{
				chkVFOSplit_CheckedChanged(this, EventArgs.Empty);
			}
			setupLegacyMeterThreads(1);
			if (multimeter2_thread_rx1 == null || !multimeter2_thread_rx1.IsAlive)
			{
				multimeter2_thread_rx1 = new Thread(MultiMeter2UpdateRX1)
				{
					Name = "Multimeter2 RX1 Thread",
					Priority = ThreadPriority.Lowest,
					IsBackground = true
				};
				multimeter2_thread_rx1.Start();
			}
			if (rx2_enabled)
			{
				setupLegacyMeterThreads(2);
				if (multimeter2_thread_rx2 == null || !multimeter2_thread_rx2.IsAlive)
				{
					multimeter2_thread_rx2 = new Thread(MultiMeter2UpdateRX2)
					{
						Name = "Multimeter2 RX2 Thread",
						Priority = ThreadPriority.Lowest,
						IsBackground = true
					};
					multimeter2_thread_rx2.Start();
				}
				if (rx2_sql_update_thread == null || !rx2_sql_update_thread.IsAlive)
				{
					rx2_sql_update_thread = new Thread(UpdateRX2SQL)
					{
						Name = "Update RX2 SQL",
						Priority = ThreadPriority.Normal,
						IsBackground = true
					};
					rx2_sql_update_thread.Start();
				}
			}
			if (sql_update_thread == null || !sql_update_thread.IsAlive)
			{
				sql_update_thread = new Thread(UpdateSQL)
				{
					Name = "Update SQL",
					Priority = ThreadPriority.Normal,
					IsBackground = true
				};
				sql_update_thread.Start();
			}
			if (noise_gate_update_thread == null || !noise_gate_update_thread.IsAlive)
			{
				noise_gate_update_thread = new Thread(UpdateNoiseGate)
				{
					Name = "Update NoiseGate",
					Priority = ThreadPriority.Normal,
					IsBackground = true
				};
				noise_gate_update_thread.Start();
			}
			if (vox_update_thread == null || !vox_update_thread.IsAlive)
			{
				vox_update_thread = new Thread(UpdateVOX)
				{
					Name = "Update VOX",
					Priority = ThreadPriority.Normal,
					IsBackground = true
				};
				vox_update_thread.Start();
			}
			if (poll_ptt_thread == null || !poll_ptt_thread.IsAlive)
			{
				poll_ptt_thread = new Thread(PollPTT)
				{
					Name = "Poll PTT Thread",
					Priority = ThreadPriority.Normal,
					IsBackground = true
				};
				poll_ptt_thread.Start();
			}
			if (poll_cw_thread == null || !poll_cw_thread.IsAlive)
			{
				poll_cw_thread = new Thread(PollCW)
				{
					Name = "Poll CW Thread",
					Priority = ThreadPriority.BelowNormal,
					IsBackground = true
				};
				poll_cw_thread.Start();
			}
			if (poll_pa_pwr_thread == null || !poll_pa_pwr_thread.IsAlive)
			{
				poll_pa_pwr_thread = new Thread(PollPAPWR)
				{
					Name = "Poll PA PWR Thread",
					Priority = ThreadPriority.BelowNormal,
					IsBackground = true
				};
				poll_pa_pwr_thread.Start();
			}
			if (_overload_thread == null || !_overload_thread.IsAlive)
			{
				_overload_thread = new Thread(pollOverloadSyncSeqErr)
				{
					Name = "Overload Thread",
					Priority = ThreadPriority.BelowNormal,
					IsBackground = true
				};
				_overload_thread.Start();
			}
			if (poll_tx_inhibit_thead == null || !poll_tx_inhibit_thead.IsAlive)
			{
				poll_tx_inhibit_thead = new Thread(PollTXInhibit)
				{
					Name = "Poll TX Inhibit input Thread",
					Priority = ThreadPriority.Normal,
					IsBackground = true
				};
				poll_tx_inhibit_thead.Start();
			}
			if (HardwareSpecific.HasVolts && HardwareSpecific.HasAmps && (display_volts_amps_thead == null || !display_volts_amps_thead.IsAlive))
			{
				display_volts_amps_thead = new Thread(readMKIIPAVoltsAmps)
				{
					Name = "Update Volts Amps Thread",
					Priority = ThreadPriority.BelowNormal,
					IsBackground = true
				};
				display_volts_amps_thead.Start();
			}
			if (m_frmCWXForm != null && !m_frmCWXForm.IsDisposed)
			{
				m_frmCWXForm.StopEverything(chkPower.Checked);
			}
			if (!_rx_only)
			{
				chkMOX.Enabled = true;
				chkTUN.Enabled = true;
				chk2TONE.Enabled = true;
			}
			chkVFOLock.Enabled = true;
			chkVFOBLock.Enabled = true;
			timer_peak_text.Enabled = true;
			UpdateDDCs(rx2_enabled);
			UpdateAAudioMixerStates();
			WDSP.SetChannelState(WDSP.id(0u, 0u), 1, 1);
			if (radio.GetDSPRX(0, 1).Active)
			{
				WDSP.SetChannelState(WDSP.id(0u, 1u), 1, 1);
			}
			if (radio.GetDSPRX(1, 0).Active)
			{
				WDSP.SetChannelState(WDSP.id(2u, 0u), 1, 1);
			}
			DataFlowing = true;
			SetupForm.UpdateGeneraHardware();
			SetMicGain();
			chkQSK_CheckStateChanged(this, EventArgs.Empty);
			if (RX1DSPMode != DSPMode.CWL && RX1DSPMode != DSPMode.CWU)
			{
				CWFWKeyer = false;
			}
			if (andromeda_cat_enabled)
			{
				NetworkIO.ATU_Tune(1);
			}
			else
			{
				NetworkIO.ATU_Tune(0);
			}
			if (!IsSetupFormNull && SetupForm.DetachPanafall && !Display.DetachPanafallEnabled)
			{
				try
				{
					BeginInvoke((Action)delegate
					{
						try
						{
							DetachPanafall(enable: true);
						}
						catch
						{
						}
					});
				}
				catch
				{
				}
			}
		}
		else
		{
			DataFlowing = false;
			SetupForm.TestIMD = false;
			if (HaveSync)
			{
				WDSP.SetChannelState(WDSP.id(0u, 0u), 0, 1);
				if (radio.GetDSPRX(0, 1).Active)
				{
					WDSP.SetChannelState(WDSP.id(0u, 1u), 0, 1);
				}
				if (radio.GetDSPRX(1, 0).Active)
				{
					WDSP.SetChannelState(WDSP.id(2u, 0u), 0, 1);
				}
			}
			UpdateAAudioMixerStates();
			UpdateDDCs(rx2_enabled);
			if (m_frmCWXForm != null && !m_frmCWXForm.IsDisposed)
			{
				m_frmCWXForm.StopEverything(chkPower.Checked);
			}
			chkMOX.Checked = false;
			chkMOX.Enabled = false;
			chkTUN.Checked = false;
			chkTUN.Enabled = false;
			chk2TONE.Checked = false;
			chk2TONE.Enabled = false;
			if (serialPTT != null)
			{
				serialPTT.Destroy();
				serialPTT = null;
			}
			chkVFOLock.Enabled = false;
			chkVFOBLock.Enabled = false;
			chkPower.BackColor = SystemColors.Control;
			txtVFOAFreq.ForeColor = vfo_text_dark_color;
			txtVFOAMSD.ForeColor = vfo_text_dark_color;
			txtVFOALSD.ForeColor = vfo_text_dark_color;
			UpdateVFOASub();
			txtVFOBFreq.ForeColor = vfo_text_dark_color;
			txtVFOBMSD.ForeColor = vfo_text_dark_color;
			txtVFOBLSD.ForeColor = vfo_text_dark_color;
			txtVFOBBand.ForeColor = band_text_dark_color;
			timer_peak_text.Enabled = false;
			Audio.Stop();
			if (vac_enabled)
			{
				ivac.SetIVACrun(0, 0);
				ivac.StopAudioIVAC(0);
			}
			if (vac2_enabled)
			{
				ivac.SetIVACrun(1, 0);
				ivac.StopAudioIVAC(1);
			}
			if (multimeter_thread != null && !multimeter_thread.Join(Math.Max(meter_delay, meter_dig_delay) + 50))
			{
				multimeter_thread.Abort();
			}
			if (rx2_meter_thread != null && !rx2_meter_thread.Join(Math.Max(meter_delay, meter_dig_delay) + 50))
			{
				rx2_meter_thread.Abort();
			}
			if (multimeter2_thread_rx1 != null && !multimeter2_thread_rx1.Join(MeterManager.QuickestUpdateInterval(1, MOX)))
			{
				multimeter2_thread_rx1.Abort();
			}
			if (multimeter2_thread_rx2 != null && !multimeter2_thread_rx2.Join(MeterManager.QuickestUpdateInterval(2, MOX)))
			{
				multimeter2_thread_rx2.Abort();
			}
			if (rx2_sql_update_thread != null && !rx2_sql_update_thread.Join(500))
			{
				rx2_sql_update_thread.Abort();
			}
			if (rx2_sql_update_thread != null && !rx2_sql_update_thread.Join(500))
			{
				rx2_sql_update_thread.Abort();
			}
			if (sql_update_thread != null && !sql_update_thread.Join(500))
			{
				sql_update_thread.Abort();
			}
			if (noise_gate_update_thread != null && !noise_gate_update_thread.Join(500))
			{
				noise_gate_update_thread.Abort();
			}
			if (vox_update_thread != null && !vox_update_thread.Join(500))
			{
				vox_update_thread.Abort();
			}
			if (poll_ptt_thread != null && !poll_ptt_thread.Join(500))
			{
				poll_ptt_thread.Abort();
			}
			if (poll_cw_thread != null && !poll_cw_thread.Join(500))
			{
				poll_cw_thread.Abort();
			}
			if (poll_pa_pwr_thread != null && !poll_pa_pwr_thread.Join(500))
			{
				poll_pa_pwr_thread.Abort();
			}
			if (_overload_thread != null && !_overload_thread.Join(500))
			{
				_overload_thread.Abort();
			}
			if (poll_tx_inhibit_thead != null && !poll_tx_inhibit_thead.Join(500))
			{
				poll_tx_inhibit_thead.Abort();
			}
			if (display_volts_amps_thead != null && !display_volts_amps_thead.Join(650))
			{
				display_volts_amps_thead.Abort();
			}
			if (ATUTunetokenSource != null && !ATUTunetokenSource.IsCancellationRequested)
			{
				ATUTunetokenSource.Cancel();
			}
		}
		panelVFOAHover.Invalidate();
		panelVFOBHover.Invalidate();
		if (m_bOldPower != chkPower.Checked)
		{
			PowerChangeHanders?.Invoke(m_bOldPower, chkPower.Checked);
			m_bOldPower = chkPower.Checked;
		}
	}

	public unsafe void UpdateAAudioMixerStates()
	{
		int num = 1 << WDSP.id(0u, 0u);
		int num2 = 1 << WDSP.id(0u, 1u);
		int num3 = 1 << WDSP.id(2u, 0u);
		int num4 = 1 << WDSP.id(1u, 0u);
		int num5 = (rx2_enabled ? (1 << WDSP.id(2u, 0u)) : 0);
		switch (NetworkIO.CurrentRadioProtocol)
		{
		case RadioProtocol.USB:
			switch (HardwareSpecific.Model)
			{
			case HPSDRModel.ANAN10E:
			case HPSDRModel.ANAN100B:
				cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num + num2 + num3 + num4);
				cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, num + num2 + num3);
				break;
			case HPSDRModel.HERMES:
			case HPSDRModel.ANAN10:
			case HPSDRModel.ANAN100:
			case HPSDRModel.ANAN100D:
			case HPSDRModel.ANAN200D:
			case HPSDRModel.ORIONMKII:
			case HPSDRModel.ANAN7000D:
			case HPSDRModel.ANAN8000D:
			case HPSDRModel.REDPITAYA:
			case HPSDRModel.ANAN_G2E:
				cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num + num2 + num3 + num4);
				cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, num + num2 + num3);
				break;
			case HPSDRModel.ANAN_G2:
			case HPSDRModel.ANAN_G2_1K:
			case HPSDRModel.ANVELINAPRO3:
			case HPSDRModel.HERMESLITE:
				break;
			}
			break;
		case RadioProtocol.ETH:
			switch (HardwareSpecific.Model)
			{
			case HPSDRModel.HERMES:
			case HPSDRModel.ANAN10:
			case HPSDRModel.ANAN10E:
			case HPSDRModel.ANAN100:
			case HPSDRModel.ANAN100B:
			case HPSDRModel.ANAN_G2E:
				if (chkPower.Checked)
				{
					if (!_mox)
					{
						if (!_diversity2)
						{
							if (!psform.PSEnabled)
							{
								cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num + num2 + num5 + num4);
								cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, num + num2 + num5);
							}
							else
							{
								cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num + num2 + num5 + num4);
								cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, num + num2 + num5);
							}
						}
						else if (!psform.PSEnabled)
						{
							cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num + num2 + num4);
							cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, num + num2);
						}
						else
						{
							cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num + num2 + num4);
							cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, num + num2);
						}
					}
					else if (!_diversity2)
					{
						if (!psform.PSEnabled)
						{
							cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num + num2 + num5 + num4);
							cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, num + num2 + num5);
						}
						else
						{
							cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num4);
							cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, 0);
						}
					}
					else if (!psform.PSEnabled)
					{
						cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num + num2 + num4);
						cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, num + num2);
					}
					else
					{
						cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num4);
						cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, 0);
					}
					cmaster.MONMixState = true;
				}
				else
				{
					cmaster.MONMixState = false;
					cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, 0);
					cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, 0);
				}
				break;
			case HPSDRModel.ANAN100D:
			case HPSDRModel.ANAN200D:
			case HPSDRModel.ORIONMKII:
			case HPSDRModel.ANAN7000D:
			case HPSDRModel.ANAN8000D:
			case HPSDRModel.ANAN_G2:
			case HPSDRModel.ANAN_G2_1K:
			case HPSDRModel.ANVELINAPRO3:
			case HPSDRModel.REDPITAYA:
				if (chkPower.Checked)
				{
					cmaster.MONMixState = true;
					cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, num + num2 + num5 + num4);
					cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, num + num2 + num5);
				}
				else
				{
					cmaster.MONMixState = false;
					cmaster.SetAAudioMixStates(null, 0, num + num2 + num3 + num4, 0);
					cmaster.SetAntiVOXSourceStates(0, num + num2 + num3, 0);
				}
				break;
			case HPSDRModel.HERMESLITE:
				break;
			}
			break;
		}
	}

	public void comboDisplayMode_SelectedIndexChanged(object sender, EventArgs e)
	{
		_pause_DisplayThread = true;
		DisplayMode currentDisplayMode = Display.CurrentDisplayMode;
		switch (comboDisplayMode.Text)
		{
		case "Spectrum":
			Display.CurrentDisplayMode = DisplayMode.SPECTRUM;
			SpecDisplay = false;
			UpdateRXDisplayVars((int)udFilterLow.Value, (int)udFilterHigh.Value);
			UpdateTXDisplayVars((int)udTXFilterLow.Value, (int)udTXFilterHigh.Value);
			WDSP.SetRXASpectrum(WDSP.id(0u, 0u), 1, 0, 0, 0);
			break;
		case "Panadapter":
			Display.CurrentDisplayMode = DisplayMode.PANADAPTER;
			WDSP.SetRXASpectrum(WDSP.id(0u, 0u), 0, 0, 0, 0);
			CalcDisplayFreq();
			CalcRX2DisplayFreq();
			CalcTXDisplayFreq();
			SpecDisplay = true;
			break;
		case "Scope":
			Display.CurrentDisplayMode = DisplayMode.SCOPE;
			break;
		case "Scope2":
			Display.CurrentDisplayMode = DisplayMode.SCOPE2;
			break;
		case "Phase":
			Display.CurrentDisplayMode = DisplayMode.PHASE;
			break;
		case "Phase2":
			Display.CurrentDisplayMode = DisplayMode.PHASE2;
			break;
		case "Waterfall":
			Display.CurrentDisplayMode = DisplayMode.WATERFALL;
			WDSP.SetRXASpectrum(WDSP.id(0u, 0u), 0, 0, 0, 0);
			CalcDisplayFreq();
			CalcRX2DisplayFreq();
			CalcTXDisplayFreq();
			SpecDisplay = true;
			break;
		case "Histogram":
			Display.CurrentDisplayMode = DisplayMode.HISTOGRAM;
			SpecDisplay = false;
			UpdateRXDisplayVars((int)udFilterLow.Value, (int)udFilterHigh.Value);
			UpdateTXDisplayVars((int)udTXFilterLow.Value, (int)udTXFilterHigh.Value);
			WDSP.SetRXASpectrum(WDSP.id(0u, 0u), 1, 0, 0, 0);
			break;
		case "Panafall":
			Display.CurrentDisplayMode = DisplayMode.PANAFALL;
			WDSP.SetRXASpectrum(WDSP.id(0u, 0u), 0, 0, 0, 0);
			CalcDisplayFreq();
			CalcRX2DisplayFreq();
			CalcTXDisplayFreq();
			SpecDisplay = true;
			break;
		case "Panascope":
			Display.CurrentDisplayMode = DisplayMode.PANASCOPE;
			WDSP.SetRXASpectrum(WDSP.id(0u, 0u), 0, 0, 0, 0);
			CalcDisplayFreq();
			CalcRX2DisplayFreq();
			CalcTXDisplayFreq();
			SpecDisplay = true;
			UpdateTXSpectrumDisplayVars();
			break;
		case "Spectrascope":
			Display.CurrentDisplayMode = DisplayMode.SPECTRASCOPE;
			SpecDisplay = false;
			UpdateRXDisplayVars((int)udFilterLow.Value, (int)udFilterHigh.Value);
			UpdateTXDisplayVars((int)udTXFilterLow.Value, (int)udTXFilterHigh.Value);
			WDSP.SetRXASpectrum(WDSP.id(0u, 0u), 1, 0, 0, 0);
			break;
		case "Off":
			Display.CurrentDisplayMode = DisplayMode.OFF;
			break;
		case "Detach Panafall":
			DetachPanafall(enable: true);
			break;
		}
		if (comboDisplayMode.Text != "Detach Panafall" && Display.DetachPanafallEnabled)
		{
			DetachPanafall(enable: false);
		}
		if (currentDisplayMode == DisplayMode.PANADAPTER || currentDisplayMode == DisplayMode.WATERFALL || (uint)(currentDisplayMode - 8) <= 1u)
		{
			DisplayMode currentDisplayMode2 = Display.CurrentDisplayMode;
			if (currentDisplayMode2 != DisplayMode.PANADAPTER && currentDisplayMode2 != DisplayMode.WATERFALL && (uint)(currentDisplayMode2 - 8) > 1u)
			{
				RX1Filter = rx1_filter;
				TXFilterLow = TXFilterLow;
			}
		}
		switch (Display.CurrentDisplayMode)
		{
		case DisplayMode.WATERFALL:
			Display.ResetWaterfallTimers();
			chkDisplayAVG.Enabled = true;
			if (chkDisplayAVG.Checked)
			{
				chkDisplayAVG.BackColor = button_selected_color;
			}
			chkDisplayPeak.Enabled = true;
			if (chkDisplayPeak.Checked)
			{
				chkDisplayPeak.BackColor = button_selected_color;
			}
			radio.GetDSPRX(0, 0).SpectrumPreFilter = true;
			radio.GetDSPRX(1, 0).SpectrumPreFilter = true;
			pnlDisplay.BringToFront();
			break;
		case DisplayMode.PANADAPTER:
			chkDisplayAVG.Enabled = true;
			if (chkDisplayAVG.Checked)
			{
				chkDisplayAVG.BackColor = button_selected_color;
			}
			chkDisplayPeak.Enabled = true;
			if (chkDisplayPeak.Checked)
			{
				chkDisplayPeak.BackColor = button_selected_color;
			}
			radio.GetDSPRX(0, 0).SpectrumPreFilter = true;
			radio.GetDSPRX(1, 0).SpectrumPreFilter = true;
			pnlDisplay.BringToFront();
			break;
		case DisplayMode.SPECTRUM:
		case DisplayMode.HISTOGRAM:
		case DisplayMode.SPECTRASCOPE:
			chkDisplayAVG.Enabled = true;
			if (chkDisplayAVG.Checked)
			{
				chkDisplayAVG.BackColor = button_selected_color;
			}
			chkDisplayPeak.Enabled = true;
			if (chkDisplayPeak.Checked)
			{
				chkDisplayPeak.BackColor = button_selected_color;
			}
			if (_rx1_dsp_mode != DSPMode.SPEC)
			{
				radio.GetDSPRX(0, 0).SpectrumPreFilter = false;
				radio.GetDSPRX(1, 0).SpectrumPreFilter = false;
			}
			else
			{
				radio.GetDSPRX(0, 0).SpectrumPreFilter = true;
				radio.GetDSPRX(1, 0).SpectrumPreFilter = true;
			}
			RX1Filter = rx1_filter;
			break;
		case DisplayMode.PANAFALL:
			Display.ResetWaterfallTimers();
			chkDisplayAVG.Enabled = true;
			if (chkDisplayAVG.Checked)
			{
				chkDisplayAVG.BackColor = button_selected_color;
			}
			chkDisplayPeak.Enabled = true;
			if (chkDisplayPeak.Checked)
			{
				chkDisplayPeak.BackColor = button_selected_color;
			}
			radio.GetDSPRX(0, 0).SpectrumPreFilter = true;
			radio.GetDSPRX(1, 0).SpectrumPreFilter = true;
			break;
		case DisplayMode.PANASCOPE:
			chkDisplayAVG.Enabled = true;
			if (chkDisplayAVG.Checked)
			{
				chkDisplayAVG.BackColor = button_selected_color;
			}
			chkDisplayPeak.Enabled = true;
			if (chkDisplayPeak.Checked)
			{
				chkDisplayPeak.BackColor = button_selected_color;
			}
			radio.GetDSPRX(0, 0).SpectrumPreFilter = true;
			radio.GetDSPRX(1, 0).SpectrumPreFilter = true;
			break;
		default:
			chkDisplayAVG.Enabled = true;
			if (chkDisplayAVG.Checked)
			{
				chkDisplayAVG.BackColor = button_selected_color;
			}
			chkDisplayPeak.Enabled = true;
			if (chkDisplayPeak.Checked)
			{
				chkDisplayPeak.BackColor = button_selected_color;
			}
			if (_rx1_dsp_mode != DSPMode.SPEC)
			{
				radio.GetDSPRX(0, 0).SpectrumPreFilter = false;
				radio.GetDSPRX(1, 0).SpectrumPreFilter = false;
			}
			else
			{
				radio.GetDSPRX(0, 0).SpectrumPreFilter = true;
				radio.GetDSPRX(1, 0).SpectrumPreFilter = true;
			}
			break;
		case DisplayMode.SCOPE:
		case DisplayMode.SCOPE2:
		case DisplayMode.PHASE:
		case DisplayMode.PHASE2:
		case DisplayMode.OFF:
			break;
		}
		was_panadapter = false;
		was_waterfall = false;
		UpdateRX1DisplayOffsets();
		UpdateRX2DisplayOffsets();
		if (comboDisplayMode.Focused)
		{
			btnHidden.Focus();
		}
		_pause_DisplayThread = false;
		if (currentDisplayMode != Display.CurrentDisplayMode)
		{
			DisplayModeChangedHandlers?.Invoke(1, currentDisplayMode, Display.CurrentDisplayMode);
		}
	}

