	private void comboAGC_SelectedIndexChanged(object sender, EventArgs e)
	{
		if (comboAGC.SelectedIndex >= 0)
		{
			AGCMode rXAGCMode = radio.GetDSPRX(0, 0).RXAGCMode;
			radio.GetDSPRX(0, 0).RXAGCMode = (AGCMode)comboAGC.SelectedIndex;
			radio.GetDSPRX(0, 1).RXAGCMode = (AGCMode)comboAGC.SelectedIndex;
			lblAGCLabel.Text = "AGC: " + comboAGC.Text;
			m_RX1agcMode = (AGCMode)comboAGC.SelectedIndex;
			switch ((AGCMode)comboAGC.SelectedIndex)
			{
			case AGCMode.LONG:
				SetupForm.CustomRXAGCEnabled = false;
				radio.GetDSPRX(0, 0).RXAGCHang = 2000;
				radio.GetDSPRX(0, 1).RXAGCHang = 2000;
				radio.GetDSPRX(0, 0).RXAGCDecay = 2000;
				radio.GetDSPRX(0, 1).RXAGCDecay = 2000;
				SetupForm.tbDSPAGCHangThreshold.Enabled = true;
				SetupForm.AGCRX1HangThreshold = SetupForm.tbDSPAGCHangThreshold.Value;
				toolTip1.SetToolTip(comboAGC, "Automatic Gain Control Mode Setting:\nLong (Attack 2ms, Hang 2000ms, Decay 2000ms)");
				break;
			case AGCMode.SLOW:
				SetupForm.CustomRXAGCEnabled = false;
				radio.GetDSPRX(0, 0).RXAGCHang = 1000;
				radio.GetDSPRX(0, 1).RXAGCHang = 1000;
				radio.GetDSPRX(0, 0).RXAGCDecay = 500;
				radio.GetDSPRX(0, 1).RXAGCDecay = 500;
				SetupForm.tbDSPAGCHangThreshold.Enabled = true;
				SetupForm.AGCRX1HangThreshold = SetupForm.tbDSPAGCHangThreshold.Value;
				toolTip1.SetToolTip(comboAGC, "Automatic Gain Control Mode Setting:\nSlow (Attack 2ms, Hang 1000ms, Decay 500ms)");
				break;
			case AGCMode.MED:
				SetupForm.CustomRXAGCEnabled = false;
				radio.GetDSPRX(0, 0).RXAGCHang = 0;
				radio.GetDSPRX(0, 1).RXAGCHang = 0;
				radio.GetDSPRX(0, 0).RXAGCDecay = 250;
				radio.GetDSPRX(0, 1).RXAGCDecay = 250;
				WDSP.SetRXAAGCHangThreshold(WDSP.id(0u, 0u), 100);
				SetupForm.tbDSPAGCHangThreshold.Enabled = false;
				toolTip1.SetToolTip(comboAGC, "Automatic Gain Control Mode Setting:\nMedium (Attack 2ms, Hang OFF, Decay 250ms)");
				break;
			case AGCMode.FAST:
				SetupForm.CustomRXAGCEnabled = false;
				radio.GetDSPRX(0, 0).RXAGCHang = 0;
				radio.GetDSPRX(0, 1).RXAGCHang = 0;
				radio.GetDSPRX(0, 0).RXAGCDecay = 50;
				radio.GetDSPRX(0, 1).RXAGCDecay = 50;
				WDSP.SetRXAAGCHangThreshold(WDSP.id(0u, 0u), 100);
				SetupForm.tbDSPAGCHangThreshold.Enabled = false;
				toolTip1.SetToolTip(comboAGC, "Automatic Gain Control Mode Setting:\nFast (Attack 2ms, Hang OFF, Decay 50ms)");
				break;
			case AGCMode.CUSTOM:
				SetupForm.CustomRXAGCEnabled = true;
				SetupForm.tbDSPAGCHangThreshold.Enabled = true;
				SetupForm.AGCRX1HangThreshold = SetupForm.tbDSPAGCHangThreshold.Value;
				toolTip1.SetToolTip(comboAGC, "Automatic Gain Control Mode Setting:\nCustom - Set specifics in Setup Form -> DSP -> AGC/ALC");
				break;
			case AGCMode.FIXD:
				SetupForm.CustomRXAGCEnabled = false;
				toolTip1.SetToolTip(comboAGC, "Automatic Gain Control Mode Setting:\nFixed - Set gain with AGC-T control above");
				break;
			}
			if (comboAGC.SelectedIndex == 0)
			{
				RF = SetupForm.AGCFixedGain;
			}
			else
			{
				RF = SetupForm.AGCMaxGain;
			}
			if (RX1DSPMode != DSPMode.CWL && RX1DSPMode != DSPMode.CWU)
			{
				non_qsk_agc = (AGCMode)comboAGC.SelectedIndex;
			}
			if (comboAGC.Focused)
			{
				btnHidden.Focus();
			}
			if (rXAGCMode != radio.GetDSPRX(0, 0).RXAGCMode)
			{
				AGCModeChangedHandlers?.Invoke(1, rXAGCMode, radio.GetDSPRX(0, 0).RXAGCMode);
			}
		}
	}

	private Task run_console_closing_handlers_async()
	{
		if (ConsoleClosingHandlersAsync == null)
		{
			return Task.CompletedTask;
		}
		Delegate[] invocationList = ConsoleClosingHandlersAsync.GetInvocationList();
		List<Task> list = new List<Task>(invocationList.Length);
		for (int i = 0; i < invocationList.Length; i++)
		{
			Func<Task> function = (Func<Task>)invocationList[i];
			list.Add(Task.Run(function));
		}
		return Task.WhenAll(list);
	}

	private void Console_Closing(object sender, CancelEventArgs e)
	{
		if (Display.RunningFPSProfile)
		{
			MessageBox.Show("Stop the FPS profile test first !", "FPS Profile Test", MessageBoxButtons.OK, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			e.Cancel = true;
			return;
		}
		if (!_is_shutting_down)
		{
			shutdownLogStringToPath("Inside Console_Closing()");
			try
			{
				psform?.SaveCurveCache();
			}
			catch
			{
			}
			e.Cancel = true;
			_is_shutting_down = true;
			_frmShutDownForm = new ShutdownForm();
			_frmShutDownForm.StartPosition = FormStartPosition.Manual;
			_frmShutDownForm.Location = new Point(base.Location.X + base.Size.Width / 2 - _frmShutDownForm.Size.Width / 2, base.Location.Y + base.Size.Height / 2 - _frmShutDownForm.Size.Height / 2);
			_frmShutDownForm.Show(this);
			_frmShutDownForm.BringToFront();
			BeginInvoke((Action)async delegate
			{
				await run_console_closing_handlers_async();
				Close();
			});
			return;
		}
		shutdownLogStringToPath("Before ThetisBotDiscord.Disconnect()");
		ThetisBotDiscord.Shutdown();
		if (_autoLoadFormTimerFormTimer != null)
		{
			shutdownLogStringToPath("Before _autoLoadFormTimerFormTimer.Stop()");
			_autoLoadFormTimerFormTimer.Stop();
		}
		shutdownLogStringToPath("Before autoLaunchTryToClose()");
		autoLaunchTryToClose();
		shutdownLogStringToPath("Before MessageFloodControl.Shutdown()");
		MessageFloodControl.Shutdown();
		if (m_tcpTCIServer != null)
		{
			shutdownLogStringToPath("Before m_tcpTCIServer.StopServer()");
			m_tcpTCIServer.StopServer();
			cmaster.TCIServer = null;
			removeTCIDelegates();
			m_tcpTCIServer = null;
		}
		if (m_tcpCATServer != null)
		{
			shutdownLogStringToPath("Before m_tcpCATServer.StopServer()");
			NetworkIO.SetCATPort(0);
			Thread.Sleep(100);
			m_tcpCATServer.StopServer();
			removeTCPIPcatDelegates();
		}
		shutdownLogStringToPath("Before infoBar.ShutDown()");
		if (infoBar != null)
		{
			infoBar.ShutDown();
		}
		shutdownLogStringToPath("Before serial disable");
		CATEnabled = false;
		if (Sio2listen != null)
		{
			Sio2listen.disableCAT2();
		}
		if (Sio3listen != null)
		{
			Sio3listen.disableCAT3();
		}
		if (Sio4listen != null)
		{
			Sio4listen.disableCAT4();
		}
		AndromedaCATEnabled = false;
		AriesCATEnabled = false;
		GanymedeCATEnabled = false;
		shutdownLogStringToPath("Before power off");
		if (chkPower.Checked)
		{
			chkPower.Checked = false;
		}
		Thread.Sleep(200);
		if (psform != null)
		{
			shutdownLogStringToPath("Before psform.CloseAmpView()");
			psform.CloseAmpView();
			shutdownLogStringToPath("Before psform.StopPSThread()");
			psform.StopPSThread();
		}
		shutdownLogStringToPath("Before undoXVTRantennaModify()");
		undoXVTRantennaModify(0);
		undoXVTRantennaModify(1);
		shutdownLogStringToPath("Before SaveState()");
		SaveState();
		shutdownLogStringToPath("Before MemoryList.Save()");
		MemoryList.Save();
		if (!IsSetupFormNull)
		{
			shutdownLogStringToPath("Before SetupForm.CloseUsbBcdDevice()");
			SetupForm.CloseUsbBcdDevice();
			shutdownLogStringToPath("Before SetupForm.SaveNotchesToDatabase()");
			SetupForm.SaveNotchesToDatabase();
			SetupForm.CloseBandwidthForm();
			SetupForm.Owner = null;
			SetupForm.Hide();
		}
		shutdownLogStringToPath("Before hides");
		if (_frmReleaseNotes != null)
		{
			_frmReleaseNotes.Hide();
		}
		if (m_frmCWXForm != null)
		{
			m_frmCWXForm.Hide();
		}
		if (EQForm != null)
		{
			EQForm.Hide();
		}
		if (XVTRForm != null)
		{
			XVTRForm.Hide();
		}
		if (memoryForm != null)
		{
			memoryForm.Hide();
		}
		if (diversityForm != null)
		{
			diversityForm.Hide();
		}
		if (psform != null)
		{
			psform.Hide();
		}
		if (m_frmNotchPopup != null)
		{
			m_frmNotchPopup.Hide();
		}
		if (m_frmSeqLog != null)
		{
			m_frmSeqLog.Hide();
		}
		cmaster.Hidewb(0);
		shutdownLogStringToPath("Before Display.ShutdownDX2D()");
		try
		{
			if (detachedPanafallForm != null && !detachedPanafallForm.IsDisposed && detachedPanafallForm.Visible)
			{
				detachedPanafallForm.Hide();
			}
		}
		catch (Exception ex)
		{
			shutdownLogStringToPath("Detach hide on shutdown: " + ex);
		}
		m_bDisplayLoopRunning = false;
		GPUWaterfallLogger.Log("Shutdown", "before Join(1100), thread alive=" + (draw_display_thread != null && draw_display_thread.IsAlive));
		if (draw_display_thread != null && draw_display_thread.IsAlive)
		{
			draw_display_thread.Join(1100);
		}
		GPUWaterfallLogger.Log("Shutdown", "after Join(1100), thread alive=" + (draw_display_thread != null && draw_display_thread.IsAlive));
		if (draw_display_thread != null && draw_display_thread.IsAlive)
		{
			GPUWaterfallLogger.Log("Shutdown", "WARNING: draw_display_thread still alive after Join(1100) — likely wedged in DX. Proceeding with device teardown.");
			shutdownLogStringToPath("WARNING: draw_display_thread still alive after Join(1100) — likely wedged in DX. Proceeding with device teardown.");
		}
		try
		{
			Display.ShutdownDetachedRenderer();
		}
		catch (Exception ex2)
		{
			shutdownLogStringToPath("Detached renderer shutdown exception: " + ex2);
		}
		GPUWaterfallLogger.Log("Shutdown", "before ShutdownDX2D");
		Display.ShutdownDX2D();
		GPUWaterfallLogger.Log("Shutdown", "after ShutdownDX2D");
		shutdownLogStringToPath("Before removeDelegates()");
		removeDelegates();
		if (!IsSetupFormNull)
		{
			SetupForm.RemoveDelegates();
		}
		shutdownLogStringToPath("Before TimeOutTimerManager.Shutdown()");
		TimeOutTimerManager.Shutdown();
		if (!IsSetupFormNull)
		{
			shutdownLogStringToPath("Before SetupForm save");
			SetupForm.IgnoreButtonState = true;
			SetupForm.WaitForSaveLoad(10000);
			if (SetupForm.StillWaitingForSaveLoad)
			{
				MessageBox.Show("Saving to the database did not complete in the alloted time. Your settings will not be saved.", "DB Save TimeOut", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			}
			shutdownLogStringToPath("Before SetupForm.SaveOptions()");
			SetupForm.SaveOptions();
			shutdownLogStringToPath("Before MultiMeterIOStopTimers()");
			SetupForm.MultiMeterIOStopTimers();
			shutdownLogStringToPath("Leaving SetupForm save");
		}
		shutdownLogStringToPath("Before MeterManager.Shutdown()");
		MeterManager.Shutdown();
		shutdownLogStringToPath("Before forms close");
		if (EQForm != null)
		{
			EQForm.Close();
		}
		if (memoryForm != null)
		{
			memoryForm.Close();
		}
		if (diversityForm != null)
		{
			diversityForm.Close();
		}
		if (psform != null)
		{
			psform.Close();
		}
		if (_frmReleaseNotes != null)
		{
			_frmReleaseNotes.Close();
		}
		if (m_frmCWXForm != null && !m_frmCWXForm.IsDisposed)
		{
			m_frmCWXForm.StopEverything();
		}
		cmaster.Closewb(0);
		shutdownLogStringToPath("Before SpotManager2.FreeUpFlags()");
		SpotManager2.FreeUpFlags();
		shutdownLogStringToPath("Before DumpCap.StopDumpcap()");
		DumpCap.StopDumpcap();
		shutdownLogStringToPath("Before Bandstack Save");
		BandStackFilter filter = BandStackManager.GetFilter(RX1Band, bIncludeUserDefined: false);
		if (filter != null)
		{
			filter.UpdateCurrentWithLastVisitedData(m_bIgnoreFrequencyDupes);
			filter.GenerateFilteredList(bMaintainSelected: true);
		}
		BandStackManager.SaveToDB();
		if (m_frmBandStack2 != null)
		{
			BandStack2Form.Store();
		}
		shutdownLogStringToPath("Before SetupForm.SaveTXProfileData()");
		if (!IsSetupFormNull && SaveTXProfileOnExit)
		{
			SetupForm.SaveTXProfileData();
		}
		shutdownLogStringToPath("Before chkPower + ckQuickRec");
		chkPower.Checked = false;
		ckQuickRec.Checked = false;
		shutdownLogStringToPath("Before hide()");
		Hide();
		shutdownLogStringToPath("Leaving Console_Closing()");
	}

	private long getErrorLogSize()
	{
		string text = Path.Combine(AppDataPath, "ErrorLog.txt");
		if (File.Exists(text))
		{
			return new FileInfo(text).Length;
		}
		return -1L;
	}

	private void shutdownLogStringToPath(string entry)
	{
		if (!m_bLogShutdown || string.IsNullOrEmpty(entry))
		{
			return;
		}
		try
		{
			using StreamWriter streamWriter = File.AppendText(AppDataPath + "\\shutdown_log.txt");
			streamWriter.WriteLine(entry);
		}
		catch
		{
		}
	}

	private void removeShutdownLog()
	{
		try
		{
			if (File.Exists(AppDataPath + "\\shutdown_log.txt"))
			{
				File.Delete(AppDataPath + "\\shutdown_log.txt");
			}
		}
		catch
		{
		}
	}

	private void comboPreamp_SelectedIndexChanged(object sender, EventArgs e)
	{
		PreampMode rX1PreampMode = PreampMode.FIRST;
		bool flag = false;
		string text = comboPreamp.Text;
		if (text == null)
		{
			goto IL_010e;
		}
		int length = text.Length;
		if (length != 3)
		{
			if (length != 5)
			{
				goto IL_010e;
			}
			switch (text[1])
			{
			case '2':
				break;
			case '1':
				goto IL_0079;
			case '3':
				goto IL_0095;
			case '4':
				goto IL_00b1;
			case '5':
				goto IL_00c0;
			default:
				goto IL_010e;
			}
			if (text == "-20dB")
			{
				rX1PreampMode = ((HardwareSpecific.Model != HPSDRModel.HPSDR) ? PreampMode.SA_MINUS20 : PreampMode.HPSDR_OFF);
			}
			else
			{
				if (!(text == "-20db"))
				{
					goto IL_010e;
				}
				rX1PreampMode = PreampMode.HPSDR_MINUS20;
			}
		}
		else
		{
			if (!(text == "0dB"))
			{
				goto IL_010e;
			}
			rX1PreampMode = PreampMode.HPSDR_ON;
		}
		goto IL_0110;
		IL_00b1:
		if (!(text == "-40db"))
		{
			goto IL_010e;
		}
		rX1PreampMode = PreampMode.HPSDR_MINUS40;
		goto IL_0110;
		IL_010e:
		flag = true;
		goto IL_0110;
		IL_0110:
		if (comboPreamp.Focused)
		{
			btnHidden.Focus();
		}
		if (!flag)
		{
			RX1PreampMode = rX1PreampMode;
			if (!_mox)
			{
				update_preamp = true;
				UpdatePreamps();
			}
		}
		return;
		IL_00c0:
		if (!(text == "-50db"))
		{
			goto IL_010e;
		}
		rX1PreampMode = PreampMode.HPSDR_MINUS50;
		goto IL_0110;
		IL_0095:
		if (!(text == "-30dB"))
		{
			if (!(text == "-30db"))
			{
				goto IL_010e;
			}
			rX1PreampMode = PreampMode.HPSDR_MINUS30;
		}
		else
		{
			rX1PreampMode = PreampMode.SA_MINUS30;
		}
		goto IL_0110;
		IL_0079:
		if (!(text == "-10dB"))
		{
			if (!(text == "-10db"))
			{
				goto IL_010e;
			}
			rX1PreampMode = PreampMode.HPSDR_MINUS10;
		}
		else
		{
			rX1PreampMode = PreampMode.SA_MINUS10;
		}
		goto IL_0110;
	}

	private void comboRX2Preamp_SelectedIndexChanged(object sender, EventArgs e)
	{
		PreampMode rX2PreampMode = PreampMode.FIRST;
		bool flag = false;
		switch (comboRX2Preamp.Text)
		{
		case "-20dB":
			rX2PreampMode = ((HardwareSpecific.Model != HPSDRModel.HPSDR) ? PreampMode.SA_MINUS20 : PreampMode.HPSDR_OFF);
			break;
		case "0dB":
			rX2PreampMode = PreampMode.HPSDR_ON;
			break;
		case "-10dB":
			rX2PreampMode = PreampMode.SA_MINUS10;
			break;
		case "-30dB":
			rX2PreampMode = PreampMode.SA_MINUS30;
			break;
		default:
			flag = true;
			break;
		}
		if (comboRX2Preamp.Focused)
		{
			btnHidden.Focus();
		}
		if (!flag)
		{
			RX2PreampMode = rX2PreampMode;
			if (!_mox)
			{
				update_preamp = true;
				UpdatePreamps();
			}
		}
	}

	private void chkMUT_CheckedChanged(object sender, EventArgs e)
	{
		bool muteRX = Audio.MuteRX1;
		if (chkMUT.Checked)
		{
			Audio.MuteRX1 = true;
			if (m_bMuteWillMuteVAC1)
			{
				radio.GetDSPRX(0, 0).RXOutputGain = 0.0;
				radio.GetDSPRX(0, 1).RXOutputGain = 0.0;
			}
			chkMUT.BackColor = button_selected_color;
			lblRX1MuteVFOA.Text = "MUTE";
			lblRX1MuteVFOA.Show();
		}
		else
		{
			Audio.MuteRX1 = false;
			radio.GetDSPRX(0, 0).RXOutputGain = (double)ptbRX0Gain.Value / (double)ptbRX0Gain.Maximum;
			radio.GetDSPRX(0, 1).RXOutputGain = (double)ptbRX1Gain.Value / (double)ptbRX1Gain.Maximum;
			ptbAF_Scroll(this, EventArgs.Empty);
			chkMUT.BackColor = SystemColors.Control;
			lblRX1MuteVFOA.Text = "";
			lblRX1MuteVFOA.Hide();
		}
		if (sliderForm != null)
		{
			sliderForm.RX1MuteOnOff = chkMUT.Checked;
		}
		if (chkMUT.Focused)
		{
			btnHidden.Focus();
		}
		if (path_Illustrator != null)
		{
			path_Illustrator.pi_Changed();
		}
		if (muteRX != Audio.MuteRX1)
		{
			MuteChangedHandlers?.Invoke(1, muteRX, Audio.MuteRX1);
		}
		setMuteAllGeneralSettings();
	}

	public bool ModelIsHPSDRorHermes()
	{
		if (HardwareSpecific.Model == HPSDRModel.HPSDR)
		{
			return true;
		}
		if (HardwareSpecific.Model == HPSDRModel.HERMES)
		{
			return true;
		}
		return false;
	}

