	{
		if (_bDelayUpdateDriveLabel)
		{
			UpdateDriveLabel(bShowLimitValue: false, EventArgs.Empty);
		}
	}

	private void OnTuneSliderUpdateTimerTick(object sender, ElapsedEventArgs e)
	{
