		}
	}

	public void UpdateDriveLabel(bool bShowLimitValue, EventArgs e)
	{
		if (IsSetupFormNull)
		{
			return;
		}
		bool pABandUsesMaxPower = SetupForm.GetPABandUsesMaxPower(TXBand);
		int num;
		if (!bShowLimitValue)
		{
			num = ((!ptbPWR.IsConstrained) ? ptbPWR.Value : ptbPWR.ConstrainedValue);
		}
		else
		{
			PrettyTrackBar.LimitConstraint obj = e as PrettyTrackBar.LimitConstraint;
			num = obj.LimitValue;
			if (obj.MouseWheel)
			{
				_bDelayUpdateDriveLabel = true;
				if (_tmrDriveSliderUpdate == null)
				{
					_tmrDriveSliderUpdate = new System.Timers.Timer(500.0);
					_tmrDriveSliderUpdate.Elapsed += OnDriveSliderUpdateTimerTick;
					_tmrDriveSliderUpdate.AutoReset = false;
					_tmrDriveSliderUpdate.Enabled = true;
				}
				else
				{
					_tmrDriveSliderUpdate.Stop();
					_tmrDriveSliderUpdate.Start();
				}
			}
		}
		string text = ((!pABandUsesMaxPower) ? num.ToString() : ((int)((float)num / (float)(ptbPWR.Maximum - ptbPWR.Minimum) * SetupForm.GetPABandMaxPower(TXBand)) + "w"));
		if (!bShowLimitValue)
		{
			if (ptbPWR.IsConstrained)
			{
				lblPWR.Text = "Drive:  (" + text + ")";
			}
			else
			{
				lblPWR.Text = "Drive:  " + text;
			}
		}
		else
		{
			lblPWR.Text = "Limit: " + text;
		}
	}

	private void ptbPWR_MouseUp(object sender, MouseEventArgs e)
	{
		UpdateDriveLabel(bShowLimitValue: false, EventArgs.Empty);
	}

	private void ptbPWR_Scroll(object sender, EventArgs e)
	{
		if (!IsSetupFormNull)
		{
			PrettyTrackBar.LimitConstraint limitConstraint = e as PrettyTrackBar.LimitConstraint;
			if (limitConstraint != null)
			{
				limitPower_by_band[(int)_tx_band] = limitConstraint.LimitValue;
			}
			int num = setPowerFromDriveSlider(out var bConstrain, e != EventArgs.Empty);
			power_by_band[(int)_tx_band] = ptbPWR.Value;
			UpdateDriveLabel((limitConstraint != null) & bConstrain, e);
			if (sender.GetType() == typeof(PrettyTrackBar))
			{
				ptbPWR.Focus();
			}
			double num2 = Convert.ToDouble(num) / 100.0;
			if (num2 <= 0.0)
			{
				num2 = 0.0;
			}
			else if (num2 < 1.0 / 15.0)
			{
				num2 = 1.0 / 15.0;
			}
			Midi2Cat.SendUpdateToMidi(CatCmd.DriveLevel, num2);
			num2 = Convert.ToDouble(ptbPWR.Value - ptbPWR.Minimum) / Convert.ToDouble(ptbPWR.Maximum - ptbPWR.Minimum);
			Midi2Cat.SendUpdateToMidi(CatCmd.DriveLevel_inc, num2);
			if (sliderForm != null)
			{
				sliderForm.TXDrive = ptbPWR.Value;
			}
			if (m_fDrivePower != (double)num)
			{
				m_fDrivePower = num;
				DrivePowerChangedHandlers?.Invoke(1, num, TUN || chk2TONE.Checked);
			}
		}
	}

	private void ptbAF_Scroll(object sender, EventArgs e)
	{
		lblAF.Text = "Master AF:  " + ptbAF.Value;
		if (!initializing && !_mox && e != EventArgs.Empty && m_bRXAFSlidersWillUnmute)
		{
			if (chkMUT.Checked)
			{
				chkMUT.Checked = false;
			}
			if (RX2Enabled && chkRX2Mute.Checked)
			{
				chkRX2Mute.Checked = false;
			}
		}
		if (!_mox || chkMON.Checked)
		{
			if ((_rx1_dsp_mode == DSPMode.CWL || _rx1_dsp_mode == DSPMode.CWU) && !_mox && Audio.MOX && _current_breakin_mode == BreakIn.Manual)
			{
				Audio.MonitorVolume = 0.0;
				if (!m_bIgnoreAFChangeForMonitor)
				{
					TXAF = ptbAF.Value;
				}
			}
			else
			{
				Audio.MonitorVolume = (double)ptbAF.Value / 100.0;
			}
		}
		if ((!MOX && !Audio.MOX) || (MOX && !Audio.MOX))
		{
			RXAF = ptbAF.Value;
		}
		else if (MOX && chkMON.Checked && !m_bIgnoreAFChangeForMonitor)
		{
			TXAF = ptbAF.Value;
		}
		setLinkedAF(0, ptbAF.Value);
		if (sender.GetType() == typeof(PrettyTrackBar))
		{
			ptbAF.Focus();
		}
		if (sliderForm != null)
		{
			sliderForm.MasterAFGain = ptbAF.Value;
		}
		if (_old_master_af != -999 && _old_master_af != ptbAF.Value)
		{
			VolumeChangedHandlers?.Invoke(_old_master_af, ptbAF.Value);
		}
		_old_master_af = ptbAF.Value;
	}

