	private void setAudioMicGain(double gain_db)
	{
		if (chkMicMute.Checked)
		{
			Audio.MicPreamp = Math.Pow(10.0, gain_db / 20.0);
			_mic_muted = false;
		}
		else
		{
			Audio.MicPreamp = 0.0;
			_mic_muted = true;
		}
	}

