		{
			num /= (double)Audio.VOXGain;
		}
		int num2 = (int)((double)picVOX.Width - 20.0 * Math.Log10(num) * (double)picVOX.Width / (double)ptbVOX.Minimum);
		int num3 = picVOX.Width - ptbVOX.Value * picVOX.Width / ptbVOX.Minimum;
		if (num2 < 0)
		{
			num2 = (num3 = 0);
		}
		e.Graphics.FillRectangle(Brushes.LimeGreen, 0, 0, num2, picVOX.Height);
		if (num3 < num2)
		{
			e.Graphics.FillRectangle(Brushes.Red, num3 + 1, 0, num2 - num3 - 1, picVOX.Height);
		}
	}

