	private void HdwMOXChanged(bool tx, double freq)
	{
		if (tx)
		{
			if (m_bQSOResetTimerOnMox)
			{
				QSOTimerReset();
			}
			if (m_bQSOTimerDuringMoxOnly && !m_bQSOTimerRunning)
			{
				QSOTimerRunning = true;
			}
			if (bpf2_gnd)
			{
				NetworkIO.SetBPF2Gnd(1);
			}
			updateVFOFreqs(tx);
			UpdateRX1DDSFreq();
			UpdateRX2DDSFreq();
			UpdateTXDDSFreq();
			Band band = BandByFreq(XVTRForm.TranslateFreq(VFOAFreq), rx1_xvtr_index, current_region);
			Band bandb = BandByFreq(XVTRForm.TranslateFreq(VFOBFreq), rx2_xvtr_index, current_region);
			if (penny_ext_ctrl_enabled)
			{
				int bits = Penny.getPenny().UpdateExtCtrl(band, bandb, _mox, _tuning, SetupForm.TestIMD, chkExternalPA.Checked);
				if (!IsSetupFormNull)
				{
					SetupForm.UpdateOCLedStrip(_mox, bits);
				}
			}
			UpdateTRXAnt();
			if (rx1_xvtr_index >= 0)
			{
				Alex.getAlex().UpdateAlexAntSelection(band, _mox, alex_ant_ctrl_enabled, xvtr: true);
			}
			else
			{
				Alex.getAlex().UpdateAlexAntSelection(_tx_band, _mox, alex_ant_ctrl_enabled, xvtr: false);
			}
			UpdateTRXAnt();
			NetworkIO.SetTRXrelay(1);
			if (cw_fw_keyer && (RX1DSPMode == DSPMode.CWL || RX1DSPMode == DSPMode.CWU) && !chkTUN.Checked && _current_ptt_mode != PTTMode.SPACE && _current_ptt_mode != PTTMode.CAT && _current_ptt_mode != PTTMode.CW)
			{
				NetworkIO.SetPttOut(0);
			}
			else
			{
				NetworkIO.SetPttOut(1);
			}
			if (serialPTT != null)
			{
				serialPTT.setDTR(v: true);
			}
			return;
		}
		if (m_bQSOTimerDuringMoxOnly && m_bQSOTimerRunning)
		{
			QSOTimerRunning = false;
		}
		NetworkIO.SetPttOut(0);
		NetworkIO.SetTRXrelay(0);
		if (serialPTT != null)
		{
			serialPTT.setDTR(v: false);
		}
		if (!_rx1_step_att_enabled)
		{
			RX1PreampMode = rx1_preamp_mode;
		}
		updateVFOFreqs(tx);
		UpdateRX1DDSFreq();
		UpdateRX2DDSFreq();
		UpdateTXDDSFreq();
		Band band2 = Band.FIRST;
		Band band3 = Band.FIRST;
		band2 = BandByFreq(XVTRForm.TranslateFreq(VFOAFreq), rx1_xvtr_index, current_region);
		band3 = BandByFreq(XVTRForm.TranslateFreq(VFOBFreq), rx2_xvtr_index, current_region);
		if (penny_ext_ctrl_enabled)
		{
			int bits2 = Penny.getPenny().UpdateExtCtrl(band2, band3, _mox, _tuning, SetupForm.TestIMD, chkExternalPA.Checked);
			if (!IsSetupFormNull)
			{
				SetupForm.UpdateOCLedStrip(_mox, bits2);
			}
		}
		UpdateTRXAnt();
		if (rx1_xvtr_index >= 0)
		{
			Alex.getAlex().UpdateAlexAntSelection(band2, _mox, alex_ant_ctrl_enabled, xvtr: true);
		}
		else
		{
			Alex.getAlex().UpdateAlexAntSelection(rx1_band, _mox, alex_ant_ctrl_enabled, xvtr: false);
		}
		NetworkIO.SetBPF2Gnd(0);
		UpdateTRXAnt();
	}

	private void UIMOXChangedTrue()
	{
		_nb_CheckState = chkNB.CheckState;
		if (_display_duplex)
		{
			chkNB.CheckState = CheckState.Unchecked;
		}
		meter_peak_count = multimeter_peak_hold_samples;
		comboMeterRXMode.ForeColor = Color.Gray;
		comboMeterTXMode.ForeColor = Color.White;
		comboMeterTXMode_SelectedIndexChanged(this, EventArgs.Empty);
		if (((_rx1_dsp_mode == DSPMode.CWL || _rx1_dsp_mode == DSPMode.CWU) && !disable_ui_mox_changes) || (_rx1_dsp_mode != DSPMode.CWL && _rx1_dsp_mode != DSPMode.CWU))
		{
			DisableAllBands();
			DisableAllModes();
			chkVFOSplit.Enabled = false;
			btnVFOAtoB.Enabled = false;
			btnVFOBtoA.Enabled = false;
			btnVFOSwap.Enabled = false;
			chkPower.BackColor = Color.Red;
		}
		chkVFOLock.Enabled = !chkMOX.Checked;
		chkVFOBLock.Enabled = !chkMOX.Checked;
		updateAttNudsCombos();
		SetupForm.MOX = chkMOX.Checked;
		ResetMultiMeterPeak();
		picSquelch.Invalidate();
	}

	private void UIMOXChangedFalse()
	{
		if (_display_duplex)
		{
			chkNB.CheckState = _nb_CheckState;
		}
		if (((_rx1_dsp_mode == DSPMode.CWL || _rx1_dsp_mode == DSPMode.CWU) && !disable_ui_mox_changes) || (_rx1_dsp_mode != DSPMode.CWL && _rx1_dsp_mode != DSPMode.CWU))
		{
			if (!VFOALock)
			{
				EnableAllBands();
				EnableAllModes();
			}
			chkVFOSplit.Enabled = true;
			btnVFOAtoB.Enabled = true;
			btnVFOBtoA.Enabled = true;
			btnVFOSwap.Enabled = true;
		}
		if (PowerOn)
		{
			chkPower.BackColor = button_selected_color;
		}
		comboMeterTXMode.ForeColor = Color.Gray;
		comboMeterRXMode.ForeColor = Color.White;
		comboMeterRXMode_SelectedIndexChanged(this, EventArgs.Empty);
		comboRX2MeterMode_SelectedIndexChanged(this, EventArgs.Empty);
		comboMeterTXMode_SelectedIndexChanged(this, EventArgs.Empty);
		pa_fwd_power = 0;
		pa_rev_power = 0;
		NetworkIO.SWRProtect = 1f;
		_wind_back_engaged = false;
		Display.PowerFoldedBack = false;
		Audio.HighSWRScale = 1.0;
		HighSWR = false;
		try
		{
			NetworkIO.getAndResetADC_Overload();
		}
		catch
		{
		}
		for (int i = 0; i < _adc_overload_level.Length; i++)
		{
			_adc_overload_level[i] = 0;
			_adc_overloaded[i] = false;
		}
		for (int j = 0; j < meter_text_history.Length; j++)
		{
			meter_text_history[j] = 0f;
		}
		chkVFOLock.Enabled = !chkMOX.Checked;
		chkVFOBLock.Enabled = !chkMOX.Checked;
		updateAttNudsCombos();
		SetupForm.MOX = chkMOX.Checked;
		ResetMultiMeterPeak();
		chkMOX.BackColor = SystemColors.Control;
		picNoiseGate.Invalidate();
	}

	private void updateAttNudsCombos()
	{
		if (_rx1_step_att_enabled)
		{
			udRX1StepAttData.BringToFront();
		}
		else
		{
			comboPreamp.BringToFront();
		}
		if (_rx2_step_att_enabled)
		{
			udRX2StepAttData.BringToFront();
		}
		else
		{
			comboRX2Preamp.BringToFront();
		}
		if (_mox && (_isexpanded || (_iscollapsed && !_showAndromedaTopControls && !_showAndromedaButtonBar)))
		{
			if (VFOATX || (VFOBTX && !rx2_enabled))
			{
				comboPreamp.Enabled = false;
				udRX1StepAttData.Enabled = false;
				comboRX2Preamp.Enabled = true;
				udRX2StepAttData.Enabled = true;
				udTXStepAttData.Location = udRX1StepAttData.Location;
				udTXStepAttData.Parent = udRX1StepAttData.Parent;
				udTXStepAttData.BringToFront();
				udTXStepAttData.Visible = m_bATTonTX;
				lblPreamp.Text = (m_bATTonTX ? "[S-ATT]" : (_rx1_step_att_enabled ? "S-ATT" : "ATT"));
			}
			else if (VFOBTX && rx2_enabled)
			{
				comboPreamp.Enabled = true;
				udRX1StepAttData.Enabled = true;
				comboRX2Preamp.Enabled = false;
				udRX2StepAttData.Enabled = false;
				udTXStepAttData.Location = udRX2StepAttData.Location;
				udTXStepAttData.Parent = udRX2StepAttData.Parent;
				udTXStepAttData.BringToFront();
				udTXStepAttData.Visible = m_bATTonTX;
				lblRX2Preamp.Text = (m_bATTonTX ? "[S-ATT]" : (_rx2_step_att_enabled ? "S-ATT" : "ATT"));
			}
		}
		else
		{
			comboPreamp.Enabled = true;
			udRX1StepAttData.Enabled = true;
			comboRX2Preamp.Enabled = _rx2_preamp_present;
			udRX2StepAttData.Enabled = _rx2_preamp_present;
			udTXStepAttData.Visible = false;
			lblPreamp.Text = (_rx1_step_att_enabled ? "S-ATT" : "ATT");
			lblRX2Preamp.Text = (_rx2_step_att_enabled ? "S-ATT" : (_rx2_preamp_present ? "ATT" : ""));
		}
		if (_iscollapsed && !_isexpanded)
		{
			MeterManager.BringToFront();
		}
	}

	private void chkMOX_CheckedChanged2(object sender, EventArgs e)
	{
		if (chkMOX.Checked && _ganymede_pa_issue)
		{
			chkMOX.CheckedChanged -= chkMOX_CheckedChanged2;
			chkMOX.Checked = false;
			chkMOX.CheckedChanged += chkMOX_CheckedChanged2;
			return;
		}
		bool mox = _mox;
		MoxPreChangeHandlers?.Invoke((!rx2_enabled || !VFOBTX) ? 1 : 2, _mox, chkMOX.Checked);
		NetworkIO.SendHighPriority(1);
		if (_rx_only && chkMOX.Checked)
		{
			chkMOX.Checked = false;
			return;
		}
		if ((!ARP.IsBusy || !BypassVACWhenPlayingWAV) && allow_mox_bypass && _current_ptt_mode != PTTMode.MIC && _current_ptt_mode != PTTMode.SPACE && _current_ptt_mode != PTTMode.CAT)
		{
			if (chkMOX.Checked)
			{
				if (chkVAC1.Checked)
				{
					Audio.VACBypass = true;
				}
			}
			else if (chkVAC1.Checked && Audio.VACBypass)
			{
				Audio.VACBypass = false;
			}
		}
		bool flag = chkMOX.Checked;
		if (!flag)
		{
			if (CATPTT)
			{
				CATPTT = false;
			}
			if (TCIPTT)
			{
				TCIPTT = false;
			}
		}
		if (flag)
		{
			_mox = flag;
		}
		double num = 0.0;
		if (flag)
		{
			if (radio.GetDSPTX(0).CurrentDSPMode == DSPMode.FM && current_fm_tx_mode != FMTXMode.Simplex && !chkVFOSplit.Checked)
			{
				switch (current_fm_tx_mode)
				{
				case FMTXMode.Low:
					if (!chkFMTXRev.Checked)
					{
						TXFreq -= fm_tx_offset_mhz;
					}
					else
					{
						TXFreq += fm_tx_offset_mhz;
					}
					break;
				case FMTXMode.High:
					if (!chkFMTXRev.Checked)
					{
						TXFreq += fm_tx_offset_mhz;
					}
					else
					{
						TXFreq -= fm_tx_offset_mhz;
					}
					break;
				}
			}
			num = ((chkVFOBTX.Checked || (!chkRX2.Checked && chkVFOSplit.Checked)) ? VFOBFreq : ((!chkRX2.Checked || !chkVFOSplit.Checked) ? VFOAFreq : VFOASubFreq));
			if (chkXIT.Checked)
			{
				num += (double)(int)udXIT.Value * 1E-06;
			}
			if (!calibrating)
			{
				if (_preventTXonDifferentBandToRXband && ((!RX2Enabled && VFOBTX && RX1Band != TXBand) || (RX2Enabled && VFOBTX && RX2Band != TXBand)))
				{
					if (m_frmCWXForm != null && !m_frmCWXForm.IsDisposed)
					{
						m_frmCWXForm.StopEverything(chkPower.Checked);
					}
					chkMOX.Checked = false;
					MessageBox.Show("Your TX band is different to your RX band and you have selected the option to prevent this.", "Transmit Error: TX/RX bands different", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
					return;
				}
				if (_tx_band == Band.B60M && current_region == FRSRegion.US && !extended)
				{
					switch (radio.GetDSPTX(0).CurrentDSPMode)
					{
					default:
						MessageBox.Show(_rx1_dsp_mode.ToString() + " mode is not allowed on 60M band.", "Transmit Error: Mode/Band", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
						chkMOX.Checked = false;
						return;
					case DSPMode.USB:
					case DSPMode.CWL:
					case DSPMode.CWU:
					case DSPMode.DIGU:
						break;
					}
				}
				if (!CheckValidTXFreq(current_region, num, radio.GetDSPTX(0).CurrentDSPMode, chkTUN.Checked))
				{
					if (_tx_band == Band.B60M && current_region == FRSRegion.US && checkValidTXFreq_local(current_region, num) && !extended)
					{
						MessageBox.Show("The transmit filter you have selected exceeds the bandwidth\nconstraints (2.8kHz) for the 60m band in this region.", "60m Bandwidth", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
					}
					else
					{
						DSPMode currentDSPMode = radio.GetDSPTX(0).CurrentDSPMode;
						if ((uint)(currentDSPMode - 3) <= 1u)
						{
							MessageBox.Show("The frequency " + num.ToString("f6") + "MHz is not within the\nBand specifications for your region (" + current_region.ToString() + ").", "Transmit Error: Out Of Band", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
						}
						else if (!chkTUN.Checked)
						{
							MessageBox.Show("The frequency " + num.ToString("f6") + "MHz in combination with your TX filter\nsettings [" + Display.TXFilterLow + ", " + Display.TXFilterHigh + "] are not within the Band specifications for your region (" + current_region.ToString() + ").", "Transmit Error: Out Of Band", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
						}
						else
						{
							MessageBox.Show("The frequency " + num.ToString("f6") + "MHz is not within the\nBand specifications for your region (" + current_region.ToString() + ").", "Transmit Error: Out Of Band", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
						}
					}
					chkMOX.Checked = false;
					return;
				}
			}
			switch (_rx1_dsp_mode)
			{
			case DSPMode.CWL:
				num += (double)cw_pitch * 1E-06;
				break;
			case DSPMode.CWU:
				num -= (double)cw_pitch * 1E-06;
				break;
			}
		}
		else
		{
			_current_ptt_mode = PTTMode.NONE;
			if (radio.GetDSPTX(0).CurrentDSPMode == DSPMode.FM && current_fm_tx_mode != FMTXMode.Simplex && !chkVFOSplit.Checked)
			{
				switch (current_fm_tx_mode)
				{
				case FMTXMode.Low:
					if (!chkFMTXRev.Checked)
					{
						TXFreq += fm_tx_offset_mhz;
					}
					else
					{
						TXFreq -= fm_tx_offset_mhz;
					}
					break;
				case FMTXMode.High:
					if (!chkFMTXRev.Checked)
					{
						TXFreq -= fm_tx_offset_mhz;
					}
					else
					{
						TXFreq += fm_tx_offset_mhz;
					}
					break;
				}
			}
		}
		_pause_DisplayThread = true;
		if (flag)
		{
			if (!chkTUN.Checked && !chk2TONE.Checked)
			{
				ptbPWR_Scroll(this, EventArgs.Empty);
			}
			if (!full_duplex)
			{
				bool num2 = chkVFOATX.Checked || (chkVFOBTX.Checked && !RX2Enabled) || mute_rx1_on_vfob_tx || (chkVFOBTX.Checked && HardwareSpecific.Model == HPSDRModel.ANAN10E && psform.PSEnabled);
				bool flag2 = (chkVFOBTX.Checked && RX2Enabled) || mute_rx2_on_vfoa_tx || (chkVFOATX.Checked && RX2Enabled && HardwareSpecific.Model == HPSDRModel.ANAN10E && psform.PSEnabled);
				if (num2 && !flag2)
				{
					WDSP.SetChannelState(WDSP.id(0u, 1u), 0, 0);
					WDSP.SetChannelState(WDSP.id(0u, 0u), 0, 1);
				}
				if (!num2 & flag2)
				{
					WDSP.SetChannelState(WDSP.id(2u, 0u), 0, 1);
				}
				if (num2 & flag2)
				{
					WDSP.SetChannelState(WDSP.id(0u, 1u), 0, 0);
					WDSP.SetChannelState(WDSP.id(0u, 0u), 0, 0);
					WDSP.SetChannelState(WDSP.id(2u, 0u), 0, 1);
				}
			}
			if (m_bATTonTX)
			{
				if (HardwareSpecific.Model == HPSDRModel.HPSDR)
				{
					temp_mode = RX1PreampMode;
					SetupForm.RX1EnableAtt = false;
					RX1PreampMode = PreampMode.HPSDR_OFF;
					if (_rx2_preamp_present)
					{
						temp_mode2 = RX2PreampMode;
						RX2PreampMode = PreampMode.HPSDR_OFF;
					}
				}
				else
				{
					int aTTOnTX = getTXstepAttenuatorForBand(_tx_band);
					if ((!chkFWCATUBypass.Checked && _forceATTwhenPSAoff) || radio.GetDSPTX(0).CurrentDSPMode == DSPMode.CWL || radio.GetDSPTX(0).CurrentDSPMode == DSPMode.CWU)
					{
						aTTOnTX = 31;
					}
					SetupForm.ATTOnRX1 = getRX1stepAttenuatorForBand(rx1_band);
					SetupForm.ATTOnTX = aTTOnTX;
					updateAttNudsCombos();
				}
			}
			else
			{
				NetworkIO.SetTxAttenData(0);
				Display.TXAttenuatorOffset = 0f;
			}
			UpdateAAudioMixerStates();
			UpdateDDCs(rx2_enabled);
			HdwMOXChanged(flag, num);
			Display.MOX = flag;
			psform.Mox = flag;
			cmaster.Mox = flag;
			Audio.RX1BlankDisplayTX = blank_rx1_on_vfob_tx;
			if (radio.GetDSPTX(0).CurrentDSPMode != DSPMode.CWL && radio.GetDSPTX(0).CurrentDSPMode != DSPMode.CWU)
			{
				if (rf_delay > 0)
				{
					Thread.Sleep(rf_delay);
				}
				AudioMOXChanged(flag);
				WDSP.SetChannelState(WDSP.id(1u, 0u), 1, 0);
			}
			else
			{
				AudioMOXChanged(flag);
			}
		}
		else
		{
			if (space_mox_delay > 0)
			{
				Thread.Sleep(space_mox_delay);
			}
			_mox = flag;
			psform.Mox = flag;
			WDSP.SetChannelState(WDSP.id(1u, 0u), 0, 1);
			if (radio.GetDSPTX(0).CurrentDSPMode == DSPMode.CWL || radio.GetDSPTX(0).CurrentDSPMode == DSPMode.CWU)
			{
				if (!cw_fw_keyer && key_up_delay > 0)
				{
					Thread.Sleep(key_up_delay);
				}
			}
			else if (mox_delay > 0)
			{
				Thread.Sleep(mox_delay);
			}
			UpdateDDCs(rx2_enabled);
			UpdateAAudioMixerStates();
			AudioMOXChanged(flag);
			HdwMOXChanged(flag, num);
			Display.MOX = flag;
			cmaster.Mox = flag;
			if (ptt_out_delay > 0)
			{
				Thread.Sleep(ptt_out_delay);
			}
			WDSP.SetChannelState(WDSP.id(0u, 0u), 1, 0);
			if (RX2Enabled)
			{
				WDSP.SetChannelState(WDSP.id(2u, 0u), 1, 0);
			}
			if (radio.GetDSPRX(0, 1).Active)
			{
				WDSP.SetChannelState(WDSP.id(0u, 1u), 1, 0);
			}
			Audio.RX1BlankDisplayTX = blank_rx1_on_vfob_tx;
			if (m_bATTonTX)
			{
				if (HardwareSpecific.Model == HPSDRModel.HPSDR)
				{
					RX1PreampMode = temp_mode;
					if (_rx2_preamp_present)
					{
						RX2PreampMode = temp_mode2;
					}
				}
				else
				{
					updateAttNudsCombos();
					update_preamp_mode = true;
					update_preamp = true;
					UpdatePreamps();
				}
			}
			else
			{
				NetworkIO.SetTxAttenData(0);
				Display.TXAttenuatorOffset = 0f;
			}
		}
		if (!flag)
		{
			pa_fwd_power = 0;
			pa_rev_power = 0;
			HighSWR = false;
		}
		if (flag)
		{
			UIMOXChangedTrue();
		}
		else
		{
			UIMOXChangedFalse();
		}
		AndromedaIndicatorCheck(EIndicatorActions.eINMOX, IsRX1: false, flag);
		_pause_DisplayThread = false;
		if (mox != flag)
		{
			MoxChangeHandlers?.Invoke((!rx2_enabled || !VFOBTX) ? 1 : 2, mox, flag);
		}
	}

	private void chkMOX_Click(object sender, EventArgs e)
	{
		if (chkMOX.Checked)
		{
			_manual_mox = true;
			if (cw_fw_keyer && (RX1DSPMode == DSPMode.CWL || RX1DSPMode == DSPMode.CWU))
			{
				NetworkIO.SetPttOut(1);
			}
			return;
		}
		_manual_mox = false;
		if (chkTUN.Checked)
		{
			chkTUN.Checked = false;
		}
		if (chk2TONE.Checked)
		{
			chk2TONE.Checked = false;
		}
	}

	private void comboMeterRXMode_SelectedIndexChanged(object sender, EventArgs e)
	{
		if (comboMeterRXMode.Items.Count == 0 || comboMeterRXMode.SelectedIndex < 0)
		{
			current_meter_rx_mode = MeterRXMode.FIRST;
		}
		else
		{
			MeterRXMode meterRXMode = MeterRXMode.FIRST;
			switch (comboMeterRXMode.Text)
			{
			case "Signal":
				meterRXMode = MeterRXMode.SIGNAL_STRENGTH;
				break;
			case "Sig Avg":
				meterRXMode = MeterRXMode.SIGNAL_AVERAGE;
				break;
			case "ADC L":
				meterRXMode = MeterRXMode.ADC_L;
				break;
			case "ADC R":
				meterRXMode = MeterRXMode.ADC_R;
				break;
			case "ADC2 L":
				meterRXMode = MeterRXMode.ADC2_L;
				break;
			case "ADC2 R":
				meterRXMode = MeterRXMode.ADC2_R;
				break;
			case "Off":
				meterRXMode = MeterRXMode.OFF;
				break;
			}
			current_meter_rx_mode = meterRXMode;
			if (show_rx1)
			{
				lblRXMeter.Text = comboMeterRXMode.Text;
			}
			if (!_mox)
			{
				ResetMultiMeterPeak();
			}
		}
		picMultiMeterDigital.Invalidate();
		if (comboMeterRXMode.Focused)
		{
			btnHidden.Focus();
		}
	}

	private void comboMeterTXMode_SelectedIndexChanged(object sender, EventArgs e)
	{
		MeterTXMode meterTXMode = MeterTXMode.FIRST;
		switch (comboMeterTXMode.Text)
		{
		case "Fwd Pwr":
			meterTXMode = MeterTXMode.FORWARD_POWER;
			break;
		case "Ref Pwr":
			meterTXMode = MeterTXMode.REVERSE_POWER;
			break;
		case "Fwd SWR":
			meterTXMode = MeterTXMode.SWR_POWER;
			break;
		case "Mic":
			meterTXMode = MeterTXMode.MIC;
			break;
		case "EQ":
			meterTXMode = MeterTXMode.EQ;
			break;
		case "Leveler":
			meterTXMode = MeterTXMode.LEVELER;
			break;
		case "Lev Gain":
			meterTXMode = MeterTXMode.LVL_G;
			break;
		case "CFC":
			meterTXMode = MeterTXMode.CFC_PK;
			break;
		case "CFC Comp":
			meterTXMode = MeterTXMode.CFC_G;
			break;
		case "COMP":
			meterTXMode = MeterTXMode.COMP;
			break;
		case "ALC":
			meterTXMode = MeterTXMode.ALC;
			break;
		case "ALC Comp":
			meterTXMode = MeterTXMode.ALC_G;
			break;
		case "ALC Group":
			meterTXMode = MeterTXMode.ALC_GROUP;
			break;
		case "SWR":
			meterTXMode = MeterTXMode.SWR;
			break;
		case "Off":
			meterTXMode = MeterTXMode.OFF;
			break;
		}
		if (chkTUN.Checked)
		{
			if (!isMeterModeAvailableWhenTune(meterTXMode))
			{
				CurrentMeterTXMode = tune_meter_tx_mode;
				return;
			}
			tune_meter_tx_mode = meterTXMode;
			if (!IsSetupFormNull)
			{
				SetupForm.TuneMeterTXMode = meterTXMode;
			}
		}
		current_meter_tx_mode = meterTXMode;
		if (_mox)
		{
			ResetMultiMeterPeak();
		}
		picMultiMeterDigital.Invalidate();
		if (comboMeterTXMode.Focused)
		{
			btnHidden.Focus();
		}
	}

	private bool isMeterModeAvailableWhenTune(MeterTXMode meterMode)
	{
		if (meterMode != MeterTXMode.FORWARD_POWER && meterMode != MeterTXMode.REVERSE_POWER && meterMode != MeterTXMode.SWR_POWER && meterMode != MeterTXMode.SWR)
		{
			return meterMode == MeterTXMode.OFF;
		}
		return true;
	}

	private void chkDisplayAVG_CheckedChanged(object sender, EventArgs e)
	{
		bool averageOn = specRX.GetSpecRX(0).AverageOn;
		specRX.GetSpecRX(0).AverageOn = chkDisplayAVG.Checked;
		UpdateRXSpectrumDisplayVars();
		specRX.GetSpecRX(cmaster.inid(1, 0)).AverageOn = chkDisplayAVG.Checked;
		UpdateTXSpectrumDisplayVars();
		if (chkDisplayAVG.Checked)
		{
			chkDisplayAVG.BackColor = button_selected_color;
		}
		else
		{
			chkDisplayAVG.BackColor = SystemColors.Control;
		}
		RX1AVGToolStripMenuItem.Checked = chkDisplayAVG.Checked;
		if (averageOn != specRX.GetSpecRX(0).AverageOn)
		{
			AVGChangedHandlers?.Invoke(1, averageOn, specRX.GetSpecRX(0).AverageOn);
		}
	}

	private void chkDisplayPeak_CheckedChanged(object sender, EventArgs e)
	{
		bool peakOn = specRX.GetSpecRX(0).PeakOn;
		specRX.GetSpecRX(0).PeakOn = chkDisplayPeak.Checked;
		UpdateRXSpectrumDisplayVars();
		specRX.GetSpecRX(cmaster.inid(1, 0)).PeakOn = chkDisplayPeak.Checked;
		UpdateTXSpectrumDisplayVars();
		if (chkDisplayPeak.Checked)
		{
			chkDisplayPeak.BackColor = button_selected_color;
		}
		else
		{
			chkDisplayPeak.BackColor = SystemColors.Control;
		}
		RX1PeakToolStripMenuItem.Checked = chkDisplayPeak.Checked;
		if (peakOn != specRX.GetSpecRX(0).PeakOn)
		{
			PeakChangedHandlers?.Invoke(1, peakOn, specRX.GetSpecRX(0).PeakOn);
		}
	}

	private void updateVFOFreqs(bool tx, bool isTune = false)
	{
		if (!RX2Enabled || !tx)
		{
			if (tx)
			{
				if (PSState || (!VFOATX && VFOBTX))
				{
					txtVFOAFreq_LostFocus(this, EventArgs.Empty);
					txtVFOBFreq_LostFocus(this, EventArgs.Empty);
				}
				else if (VFOATX && !VFOBTX)
				{
					txtVFOAFreq_LostFocus(this, EventArgs.Empty);
				}
			}
			else
			{
				txtVFOAFreq_LostFocus(this, EventArgs.Empty);
				txtVFOBFreq_LostFocus(this, EventArgs.Empty);
			}
		}
		else if (PSState)
		{
			txtVFOAFreq_LostFocus(this, EventArgs.Empty);
			txtVFOBFreq_LostFocus(this, EventArgs.Empty);
		}
		else if (tx)
		{
			if (!VFOATX && VFOBTX)
			{
				txtVFOBFreq_LostFocus(this, EventArgs.Empty);
			}
			else if (VFOATX && !VFOBTX)
			{
				txtVFOAFreq_LostFocus(this, EventArgs.Empty);
			}
		}
	}

	private async void chkTUN_CheckedChanged(object sender, EventArgs e)
	{
		bool oldTune = _tuning;
		if (chkTUN.Checked)
		{
			if (!PowerOn)
			{
				MessageBox.Show("Power must be on to turn on the Tune function.", "Power is off", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
				chkTUN.Checked = false;
				return;
			}
			if (SetupForm.TestIMD || chk2TONE.Checked)
			{
				chk2TONE.CheckedChanged -= chk2TONE_CheckedChanged;
				chk2TONE.Checked = false;
				chk2TONE_CheckedChanged(this, EventArgs.Empty);
				chk2TONE.CheckedChanged += chk2TONE_CheckedChanged;
				await Task.Delay(300);
			}
			_tuning = true;
			chkTUN.BackColor = button_selected_color;
			old_meter_tx_mode_before_tune = current_meter_tx_mode;
			if (current_meter_tx_mode != tune_meter_tx_mode)
			{
				CurrentMeterTXMode = tune_meter_tx_mode;
				comboMeterTXMode_SelectedIndexChanged(this, EventArgs.Empty);
			}
			if (_tune_pulse_enabled)
			{
				_tune_pulse_on = true;
				SetupTunePulse();
			}
			else
			{
				_tune_pulse_on = false;
				DSPMode tXDSPMode = Audio.TXDSPMode;
				if (tXDSPMode == DSPMode.LSB || tXDSPMode == DSPMode.CWL || tXDSPMode == DSPMode.DIGL)
				{
					radio.GetDSPTX(0).TXPostGenToneFreq = -cw_pitch;
				}
				else
				{
					radio.GetDSPTX(0).TXPostGenToneFreq = cw_pitch;
				}
				radio.GetDSPTX(0).TXPostGenMode = 0;
				radio.GetDSPTX(0).TXPostGenToneMag = 0.9999899864196777;
				radio.GetDSPTX(0).TXPostGenRun = 1;
			}
			if (_tuneDrivePowerSource == DrivePowerSource.FIXED)
			{
				PreviousPWR = ptbPWR.Value;
			}
			int pWR = SetPowerUsingTargetDBM(out var _, out var _, bSetPower: true, bFromTune: true, bTwoTone: false);
			if (_tuneDrivePowerSource == DrivePowerSource.FIXED)
			{
				PWRSliderLimitEnabled = false;
				PWR = pWR;
			}
			old_dsp_mode = radio.GetDSPTX(0).CurrentDSPMode;
			switch (old_dsp_mode)
			{
			case DSPMode.CWL:
				CWFWKeyer = false;
				Audio.CurrentAudioState1 = Audio.AudioState.DTTSP;
				Audio.TXDSPMode = DSPMode.LSB;
				radio.GetDSPTX(0).CurrentDSPMode = DSPMode.LSB;
				break;
			case DSPMode.CWU:
				CWFWKeyer = false;
				Audio.CurrentAudioState1 = Audio.AudioState.DTTSP;
				Audio.TXDSPMode = DSPMode.USB;
				radio.GetDSPTX(0).CurrentDSPMode = DSPMode.USB;
				break;
			}
			if (andromeda_cat_enabled && aries_cat_enabled && (aries_ant1_enabled || aries_ant2_enabled || aries_ant3_enabled))
			{
				ATUTunetokenSource = new CancellationTokenSource();
				ATUTunetoken = ATUTunetokenSource.Token;
				await Task.Run(delegate
				{
					ATUTune(ATUTunetoken);
				}, ATUTunetoken);
			}
			chkMOX.Checked = true;
			await Task.Delay(100);
			if (!_mox)
			{
				chkTUN.Checked = false;
				return;
			}
			updateVFOFreqs(chkTUN.Checked, isTune: true);
			_current_ptt_mode = PTTMode.MANUAL;
			_manual_mox = true;
			NetworkIO.SetUserOut0(1);
			NetworkIO.SetUserOut2(1);
			if (apollopresent && apollo_tuner_enabled)
			{
				NetworkIO.EnableApolloAutoTune(1);
			}
		}
		else
		{
			_tune_pulse_on = false;
			chkMOX.Checked = false;
			await Task.Delay(100);
			radio.GetDSPTX(0).TXPostGenRun = 0;
			chkTUN.BackColor = SystemColors.Control;
			DSPMode tXDSPMode = old_dsp_mode;
			if ((uint)(tXDSPMode - 3) <= 1u)
			{
				radio.GetDSPTX(0).CurrentDSPMode = old_dsp_mode;
				Audio.TXDSPMode = old_dsp_mode;
				CWFWKeyer = true;
			}
			_tuning = false;
			updateVFOFreqs(chkTUN.Checked, isTune: true);
			if (apollopresent)
			{
				NetworkIO.EnableApolloAutoTune(0);
			}
			if (_tuneDrivePowerSource == DrivePowerSource.FIXED)
			{
				PWRSliderLimitEnabled = true;
				PWR = PreviousPWR;
			}
			if (current_meter_tx_mode != old_meter_tx_mode_before_tune)
			{
				CurrentMeterTXMode = old_meter_tx_mode_before_tune;
			}
			NetworkIO.SetUserOut0(0);
			NetworkIO.SetUserOut2(0);
			_manual_mox = false;
			if (ATUTunetokenSource != null && !ATUTunetokenSource.IsCancellationRequested)
			{
				ATUTunetokenSource.Cancel();
			}
		}
		AndromedaIndicatorCheck(EIndicatorActions.eINTune, IsRX1: false, chkTUN.Checked);
		if (AriesCATEnabled)
		{
			SetAriesTuneState(chkTUN.Checked);
		}
		setupTuneDriveSlider();
		if (oldTune != _tuning)
		{
			TuneChangedHandlers?.Invoke((!RX2Enabled || !VFOBTX) ? 1 : 2, oldTune, _tuning);
		}
	}

	public void SetupTunePulse()
	{
		if (_tune_pulse_on)
		{
			radio.GetDSPTX(0).TXPostGenRun = 0;
			DSPMode tXDSPMode = Audio.TXDSPMode;
			if (tXDSPMode == DSPMode.LSB || tXDSPMode == DSPMode.CWL || tXDSPMode == DSPMode.DIGL)
			{
				radio.GetDSPTX(0).TXPostGenPulseToneFreq = -cw_pitch;
			}
			else
			{
				radio.GetDSPTX(0).TXPostGenPulseToneFreq = cw_pitch;
			}
			radio.GetDSPTX(0).TXPostGenMode = 6;
			radio.GetDSPTX(0).TXPostGenPulseIQOut = true;
			radio.GetDSPTX(0).TXPostGenPulseMag = 0.9999899864196777;
			radio.GetDSPTX(0).TXPostGenPulseFreq = _tune_pulse_count;
			radio.GetDSPTX(0).TXPostGenPulseDutyCycle = _tune_pulse_duty;
			radio.GetDSPTX(0).TXPostGenPulseTransition = (float)_tune_pulse_ramp / 1000f;
			radio.GetDSPTX(0).TXPostGenRun = 1;
		}
	}

	private async void ATUTune(CancellationToken t)
	{
		using (await _mutex.LockAsync())
		{
			if (t.IsCancellationRequested)
			{
				NetworkIO.ATU_Tune(1);
				return;
			}
			try
			{
				NetworkIO.ATU_Tune(0);
				await Task.Delay(1000, t);
				NetworkIO.ATU_Tune(1);
			}
			catch (OperationCanceledException)
			{
				NetworkIO.ATU_Tune(1);
			}
		}
	}

