	public void LoadedTXProfile()
	{
		if (!IsSetupFormNull)
		{
			if (_rx1_dsp_mode == DSPMode.DIGL || _rx1_dsp_mode == DSPMode.DIGU)
			{
				SetDigiMode(1, DigiMode.DigiModeSettingState.dmssStore, bFromTXProfile: true);
				SetDigiMode(1, DigiMode.DigiModeSettingState.dmssTurnOffSettings, bFromTXProfile: true);
			}
			else if (rx1dm != null && (rx1dm.Mode == DigiMode.DigiModeSettingState.dmssTurnOffSettings || rx1dm.Mode == DigiMode.DigiModeSettingState.dmssStore))
			{
				SetDigiMode(1, DigiMode.DigiModeSettingState.dmssRecall, bFromTXProfile: true);
			}
			if (_rx2_dsp_mode == DSPMode.DIGL || _rx2_dsp_mode == DSPMode.DIGU)
			{
				SetDigiMode(2, DigiMode.DigiModeSettingState.dmssStore, bFromTXProfile: true);
				SetDigiMode(2, DigiMode.DigiModeSettingState.dmssTurnOffSettings, bFromTXProfile: true);
			}
			else if (rx2dm != null && (rx2dm.Mode == DigiMode.DigiModeSettingState.dmssTurnOffSettings || rx2dm.Mode == DigiMode.DigiModeSettingState.dmssStore))
			{
				SetDigiMode(2, DigiMode.DigiModeSettingState.dmssRecall, bFromTXProfile: true);
			}
		}
	}

