	private TuneLocation TuneHitTest(int x, int y)
	{
		int num = grpVFOA.Left + txtVFOAFreq.Left;
		int num2 = num + txtVFOAFreq.Width;
		int num3 = grpVFOA.Top + txtVFOAFreq.Top;
		int num4 = num3 + txtVFOAFreq.Height;
		if ((!collapsedDisplay && x > num && x < num2 && y > num3 && y < num4) || (collapsedDisplay && show_rx1 && x > num && x < num2 && y > num3 && y < num4))
		{
			return TuneLocation.VFOA;
		}
		num = grpVFOB.Left + txtVFOBFreq.Left;
		num2 = num + txtVFOBFreq.Width;
		num3 = grpVFOB.Top + txtVFOBFreq.Top;
		num4 = num3 + txtVFOBFreq.Height;
		if (x > num && x < num2 && y > num3 && y < num4)
		{
			return TuneLocation.VFOB;
		}
		num = grpVFOA.Left + txtVFOABand.Left;
		num2 = num + txtVFOABand.Width;
		num3 = grpVFOA.Top + txtVFOABand.Top;
		num4 = num3 + txtVFOABand.Height;
		if (x > num && x < num2 && y > num3 && y < num4)
		{
			return TuneLocation.VFOASub;
		}
		num = panelDisplay.Left + pnlDisplay.Left;
		num2 = num + pnlDisplay.Width;
		num3 = panelDisplay.Top + pnlDisplay.Top + pnlDisplay.Height / 2;
		num4 = num3 + pnlDisplay.Height / 2;
		if (x > num && x < num2 && y > num3 && y < num4)
		{
			return TuneLocation.DisplayBottom;
		}
		num = panelDisplay.Left + pnlDisplay.Left;
		num2 = num + pnlDisplay.Width;
		num3 = panelDisplay.Top + pnlDisplay.Top;
		num4 = num3 + pnlDisplay.Height;
		if (x > num && x < num2 && y > num3 && y < num4)
		{
			return TuneLocation.DisplayTop;
		}
		return TuneLocation.Other;
	}

	private void Console_MouseWheel(object sender, MouseEventArgs e)
	{
		if (base.ActiveControl is PrettyTrackBar)
		{
			btnHidden.Focus();
			return;
		}
		if (base.ActiveControl is TextBoxTS || base.ActiveControl is NumericUpDownTS || base.ActiveControl is TrackBarTS || base.ActiveControl is PrettyTrackBar)
		{
			btnHidden.Focus();
			return;
		}
		if (base.ClientRectangle.Contains(Control.MousePosition.X - base.Location.X, Control.MousePosition.Y - base.Location.Y))
		{
			ToggleFocusMasterTimer();
		}
		if (e.Delta == 0)
		{
			return;
		}
		int num = 0;
		num = ((!WheelReverse) ? ((e.Delta > 0) ? 1 : (-1)) : ((e.Delta <= 0) ? 1 : (-1)));
		if (SelectedNotch != null && num != 0)
		{
			notchMouseWheel(num);
			return;
		}
		if (vfo_char_width == 0)
		{
			GetVFOCharWidth();
		}
		if (num == 0)
		{
			return;
		}
		int num2 = CurrentTuneStepHz;
		if (Common.ShiftKeyDown && num2 >= 10)
		{
			num2 /= 10;
		}
		switch (TuneHitTest(e.X, e.Y))
		{
		case TuneLocation.VFOA:
		{
			if (_mox)
			{
				break;
			}
			double vFOBFreq = VFOAFreq;
			double num3 = 1000.0;
			int num4 = grpVFOA.Left + txtVFOAFreq.Left + txtVFOAFreq.Width;
			if (vfoa_hover_digit < 0)
			{
				int num6 = num4 + 2 - (vfo_pixel_offset - 5);
				while (num6 < e.X && num3 > 1.1E-06)
				{
					num3 /= 10.0;
					num6 += vfo_char_width;
					num6 = ((num3 != 1.0) ? (num6 + vfo_char_space) : (num6 + vfo_decimal_space));
				}
			}
			else
			{
				num3 = Math.Pow(10.0, -vfoa_hover_digit) * 1000.0;
			}
			if (num3 <= 1.0)
			{
				vFOBFreq += num3 * (double)num;
				VFOAFreq = vFOBFreq;
			}
			break;
		}
		case TuneLocation.VFOB:
		{
			if (_mox && VFOBTX)
			{
				break;
			}
			double vFOBFreq = VFOBFreq;
			double num3 = 1000.0;
			int num4 = grpVFOB.Left + txtVFOBFreq.Left + txtVFOBFreq.Width;
			if (vfob_hover_digit < 0)
			{
				int num5 = num4 + 2 - (vfo_pixel_offset - 5);
				while (num5 < e.X && num3 > 1.1E-06)
				{
					num3 /= 10.0;
					num5 += vfo_char_width;
					num5 = ((num3 != 1.0) ? (num5 + vfo_char_space) : (num5 + vfo_decimal_space));
				}
			}
			else
			{
				num3 = Math.Pow(10.0, -vfob_hover_digit) * 1000.0;
			}
			if (num3 <= 1.0)
			{
				vFOBFreq += num3 * (double)num;
				VFOBFreq = vFOBFreq;
			}
			break;
		}
		case TuneLocation.VFOASub:
			if (rx2_enabled && (chkEnableMultiRX.Checked || chkVFOSplit.Checked))
			{
				double vFOBFreq = VFOASubFreq;
				double num3 = 1000.0;
				int num4 = grpVFOA.Left + txtVFOABand.Left + txtVFOABand.Width;
				if (vfoa_sub_hover_digit < 0)
				{
					int num7 = num4 + 2 - (vfo_sub_pixel_offset - 5);
					while (num7 < e.X && num3 > 1.1E-06)
					{
						num3 /= 10.0;
						num7 += vfo_sub_char_width;
						num7 = ((num3 != 1.0) ? (num7 + vfo_sub_char_space) : (num7 + vfo_sub_decimal_space));
					}
				}
				else
				{
					num3 = Math.Pow(10.0, -vfoa_sub_hover_digit) * 1000.0;
				}
				if (num3 <= 1.0)
				{
					vFOBFreq += num3 * (double)num;
					VFOASubFreq = vFOBFreq;
				}
			}
			else
			{
				VFOAFreq = SnapTune(VFOAFreq, num2, num);
			}
			break;
		case TuneLocation.DisplayBottom:
			if (rx2_enabled && chkVFOSplit.Checked && current_click_tune_mode == ClickTuneMode.VFOB && wheel_tunes_vfob)
			{
				VFOASubFreq = SnapTune(VFOASubFreq, num2, num);
			}
			else if (rx2_enabled || (current_click_tune_mode == ClickTuneMode.VFOB && wheel_tunes_vfob))
			{
				VFOBFreq = SnapTune(VFOBFreq, num2, num);
			}
			else
			{
				VFOAFreq = SnapTune(VFOAFreq, num2, num);
			}
			break;
		case TuneLocation.Other:
			if (!m_bWheelTunesOutsideSpectral)
			{
				break;
			}
			goto case TuneLocation.DisplayTop;
		case TuneLocation.DisplayTop:
			if (current_click_tune_mode == ClickTuneMode.VFOB && wheel_tunes_vfob)
			{
				if (rx2_enabled && chkVFOSplit.Checked)
				{
					VFOASubFreq = SnapTune(VFOASubFreq, num2, num);
				}
				else
				{
					VFOBFreq = SnapTune(VFOBFreq, num2, num);
				}
			}
			else if (!_mox)
			{
				VFOAFreq = SnapTune(VFOAFreq, num2, num);
			}
			break;
		}
	}

	public double SnapTune(double freq_mhz, int step_size_hz, int num_steps)
	{
		long num = (long)Math.Round(freq_mhz * 1000000.0);
		long num2 = num / step_size_hz;
		if (num_steps < 0 && num % step_size_hz != 0L)
		{
			num_steps++;
		}
		num = (num2 + num_steps) * step_size_hz;
		return Math.Round((double)num * 1E-06, 6);
	}

	private void txtVFOAFreq_LostFocus(object sender, EventArgs e)
	{
		if (initializing)
		{
			return;
		}
		double value = Math.Round(saved_vfoa_freq, 6);
		Band rX1Band = RX1Band;
		DSPMode rX1DSPMode = RX1DSPMode;
		Filter rX1Filter = RX1Filter;
		double centreFrequency = CentreFrequency;
		bool clickTuneDisplay = ClickTuneDisplay;
		int value2 = ptbDisplayZoom.Value;
		if (!double.TryParse(txtVFOAFreq.Text, out var result))
		{
			VFOAFreq = saved_vfoa_freq;
			return;
		}
		if (m_bVFOAChangedByKeys)
		{
			m_dVFOAFreq = result;
			m_bVFOAChangedByKeys = false;
		}
		if (HardwareSpecific.Model == HPSDRModel.ANAN200D || HardwareSpecific.Model == HPSDRModel.ORIONMKII || HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ANAN_G2E || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.REDPITAYA)
		{
			UpdateDDCs(rx2_enabled);
		}
		double num = m_dVFOAFreq;
		bool flag = true;
		if (chkVFOSplit.Checked && _mox)
		{
			if (VFOATX && !VFOBTX)
			{
				num = VFOASubFreq;
				flag = false;
			}
			else if (!VFOATX && VFOBTX)
			{
				num = VFOBFreq;
				flag = false;
			}
		}
		if (!_click_tune_display || _update_centerfreq)
		{
			CentreFrequency = num;
			_update_centerfreq = false;
		}
		double num2 = Convert.ToDouble(Display.RX1FilterHigh) - Convert.ToDouble(Display.RX1FilterLow);
		double num3 = Convert.ToDouble(Display.RXDisplayHigh) - Convert.ToDouble(Display.RXDisplayLow);
		double num4 = 0.05;
		bool flag2 = num2 < num3 * (1.0 - 2.0 * num4);
		bool flag3 = m_bLimitCTToSpectralArea && ((m_bLimitCTMouseOnly && rx1_click_tune_drag) || !m_bLimitCTMouseOnly);
		bool flag4 = !_mox || (_mox && VFOBTX && RX2Enabled);
		if ((_click_tune_display & flag2) && ((_mox && VFOBTX && RX2Enabled) || !_mox || _display_duplex))
		{
			double num5 = Math.Round((0.0 - (num - CentreFrequency)) * 1000000.0);
			double num6 = Convert.ToDouble(-Display.RX1FilterLow);
			double num7 = Convert.ToDouble(Display.RX1FilterHigh);
			if (num6 < 0.0)
			{
				num6 = 0.0;
			}
			if (num7 < 0.0)
			{
				num7 = 0.0;
			}
			double num8 = Convert.ToDouble(Display.RXDisplayLow) + num3 * num4;
			double num9 = Convert.ToDouble(Display.RXDisplayHigh) - num3 * num4;
			double num10 = 500000.0;
			if (!m_bIgnoreLimitsForZTB)
			{
				if (!ClickTuneDrag)
				{
					if (0.0 - num5 - num6 < num8 || 0.0 - num5 + num7 > num9)
					{
						CentreFrequency = num;
						num5 = 0.0;
					}
				}
				else if (!rx1_spectrum_tune_drag)
				{
					if (0.0 - num5 - num6 < num8 - num10 || 0.0 - num5 + num7 > num9 + num10)
					{
						CentreFrequency = num;
						num5 = 0.0;
					}
					else if (!flag3 && 0.0 - num5 - num6 < num8)
					{
						double num11 = num8 - (0.0 - num5 - num6);
						CentreFrequency -= num11 * 1E-06;
						num5 -= num11;
					}
					else if (!flag3 && 0.0 - num5 + num7 > num9)
					{
						double num12 = 0.0 - num5 + num7 - num9;
						CentreFrequency += num12 * 1E-06;
						num5 += num12;
					}
				}
			}
			if (chkRIT.Checked & flag4)
			{
				num5 -= (double)(int)udRIT.Value;
			}
			bool num13 = 0.0 - num5 < (0.0 - (double)sample_rate_rx1 * 0.92) / 2.0 + num6;
			bool flag5 = 0.0 - num5 > (double)sample_rate_rx1 * 0.92 / 2.0 - num7;
			if (num13 | flag5)
			{
				double num14 = (double)sample_rate_rx1 * 0.92 / 2.0 - Math.Abs(num5);
				num14 = ((0.0 - num5 >= 0.0) ? (0.0 - num14 + num7) : (num14 - num6));
				num -= num14 * 1E-06;
				num5 += num14;
			}
			if (!m_bIgnoreLimitsForZTB && (!rx1_spectrum_tune_drag & flag3))
			{
				bool flag6 = 0.0 - num5 < (double)Display.RXDisplayLow + num6;
				bool flag7 = 0.0 - num5 > (double)Display.RXDisplayHigh - num7;
				if (flag6 | flag7)
				{
					double num15 = ((!flag6) ? ((double)Display.RXDisplayHigh - Math.Abs(num5)) : (0.0 - (double)Display.RXDisplayLow - Math.Abs(num5)));
					num15 = ((0.0 - num5 >= 0.0) ? (0.0 - num15 + num7) : (num15 - num6));
					num -= num15 * 1E-06;
					num5 += num15;
				}
			}
			radio.GetDSPRX(0, 0).RXOsc = num5;
			Display.FreqDiff = (int)radio.GetDSPRX(0, 0).RXOsc;
		}
		else
		{
			if (!flag2 && _click_tune_display && !rx1_spectrum_tune_drag)
			{
				CentreFrequency = num;
			}
			radio.GetDSPRX(0, 0).RXOsc = 0.0;
			if (_rx1_dsp_mode == DSPMode.DRM)
			{
				Display.FreqDiff = -12000;
			}
			else
			{
				Display.FreqDiff = (int)radio.GetDSPRX(0, 0).RXOsc;
			}
		}
		if (_click_tune_display && ((_mox && VFOBTX && RX2Enabled) || !_mox || _display_duplex))
		{
			Display.VFOA = (long)(CentreFrequency * 1000000.0);
		}
		else if (_rx1_dsp_mode == DSPMode.DRM)
		{
			Display.VFOA = (long)(num * 1000000.0) - 12000;
		}
		else
		{
			Display.VFOA = (long)(num * 1000000.0);
		}
		if (flag)
		{
			UpdateVFOAFreq(num.ToString("f6"));
		}
		long num16 = 0L;
		if (chkTUN.Checked && chkVFOATX.Checked && !_display_duplex)
		{
			switch (radio.GetDSPTX(0).CurrentDSPMode)
			{
			case DSPMode.LSB:
			case DSPMode.CWL:
			case DSPMode.DIGL:
				num16 = cw_pitch;
				break;
			case DSPMode.USB:
			case DSPMode.DSB:
			case DSPMode.CWU:
			case DSPMode.FM:
			case DSPMode.AM:
			case DSPMode.DIGU:
			case DSPMode.SAM:
				num16 = ((!RX1IsOn60mChannel() || current_region != FRSRegion.US) ? (-cw_pitch) : (-(long)(ModeFreqOffset(_rx1_dsp_mode) * 1000000.0 + (double)cw_pitch)));
