			if ((uint)(currentDSPMode - 3) <= 1u)
			{
				MessageBox.Show("The frequency " + num20.ToString("f6") + "MHz is not within the\nBand specifications for your region (" + current_region.ToString() + ").", "Transmit Error: Out Of Band", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			}
			else if (!chkTUN.Checked)
			{
				MessageBox.Show("The frequency " + num20.ToString("f6") + "MHz in combination with your TX filter\nsettings [" + Display.TXFilterLow + ", " + Display.TXFilterHigh + "] are not within the Band specifications for your region (" + current_region.ToString() + ").", "Transmit Error: Out Of Band", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			}
			else
