				MessageBox.Show("The frequency " + num20.ToString("f6") + "MHz is not within the\nBand specifications for your region (" + current_region.ToString() + ").", "Transmit Error: Out Of Band", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
