		else if (_rx1_dsp_mode == DSPMode.CWU)
		{
			num19 -= (double)cw_pitch * 1E-06;
			if (!cw_fw_keyer || (cw_fw_keyer && chkTUN.Checked))
			{
				num20 -= (double)cw_pitch * 1E-06;
