			break;
		case DSPMode.USB:
		case DSPMode.DSB:
		case DSPMode.DIGU:
			if (chkTUN.Checked)
			{
				num20 = ((!RX1IsOn60mChannel() || current_region != FRSRegion.US) ? (num20 - (double)cw_pitch * 1E-06) : (num20 - (ModeFreqOffset(_rx1_dsp_mode) + (double)cw_pitch * 1E-06)));
