			num19 = min_freq;
		}
		else if (num19 > max_freq)
		{
			num19 = max_freq;
		}
		if (num20 < min_freq)
		{
			num20 = min_freq;
		}
		else if (num20 > max_freq)
		{
			num20 = max_freq;
		}
		if (chkPower.Checked)
		{
			if (getWavePlayback(0) && !MOX)
			{
