				}
				if (!_click_tune_display)
				{
					RX1DDSFreq = num19;
				}
				if (_click_tune_display)
				{
					double num22 = ((rx1_xvtr_index >= 0) ? XVTRForm.TranslateFreq(CentreFrequency) : CentreFrequency);
					switch (RX1DSPMode)
					{
					case DSPMode.CWL:
						num22 += (double)CWPitch * 1E-06;
						break;
					case DSPMode.CWU:
						num22 -= (double)CWPitch * 1E-06;
						break;
					}
					RX1DDSFreq = num22;
				}
				if (chkEnableMultiRX.Checked && !_mox)
				{
					int num23 = ((!rx2_enabled) ? ((int)((VFOBFreq - VFOAFreq) * 1000000.0)) : ((int)((VFOASubFreq - VFOAFreq) * 1000000.0)));
					if ((chkRIT.Checked && !_mox) & flag4)
					{
						num23 -= (int)udRIT.Value;
					}
					int num24 = (int)(radio.GetDSPRX(0, 0).RXOsc - (double)num23);
					if (num24 > -sample_rate_rx1 / 2 && num24 < sample_rate_rx1 / 2)
					{
						radio.GetDSPRX(0, 1).RXOsc = num24;
					}
					else
					{
						chkEnableMultiRX.Checked = false;
					}
				}
			}
		}
		else if (rx1_xvtr_index >= 0)
		{
			RX1DDSFreq = XVTRForm.TranslateFreq(CentreFrequency);
		}
		else
		{
			RX1DDSFreq = CentreFrequency;
		}
		if (small_lsd)
		{
			txtVFOAMSD.Visible = true;
			txtVFOALSD.Visible = true;
		}
		WDSP.RXANBPSetTuneFrequency(WDSP.id(0u, 0u), (RX1DDSFreq + num18) * 1000000.0);
		WDSP.RXANBPSetTuneFrequency(WDSP.id(0u, 1u), (RX1DDSFreq + num18) * 1000000.0);
		Display.CentreFreqRX1 = rx1_dds_freq_mhz;
		UpdatePreamps();
		double num25 = Math.Round(value, 6);
		if (num25 != VFOAFreq)
		{
			VFOAFrequencyChangeHandlers?.Invoke(rX1Band, RX1Band, rX1DSPMode, RX1DSPMode, rX1Filter, RX1Filter, num25, VFOAFreq, centreFrequency, CentreFrequency, clickTuneDisplay, ClickTuneDisplay, value2, ptbDisplayZoom.Value, radio.GetDSPRX(0, 0).RXOsc, 1);
		}
		double num26 = Math.Round(_old_tx_freq, 6);
		if (num26 != TXFreq || tx_band != TXBand)
		{
			psform?.OnPSContextChanged();
			double centre_freq = ((RX2Enabled && VFOBTX) ? CentreRX2Frequency : CentreFrequency);
			TXFrequncyChangedHandlers?.Invoke(num26, TXFreq, _old_tx_band, TXBand, RX2Enabled, VFOBTX, centre_freq);
			_old_tx_freq = TXFreq;
			_old_tx_band = TXBand;
		}
	}

	private void setupModifyXVTRantennaArray()
	{
		_band_used_for_xvtr_modify = new Band[2];
		_ant_before_xvtr_modify = new int[2];
		for (int i = 0; i < 2; i++)
		{
			_band_used_for_xvtr_modify[i] = Band.LAST;
			_ant_before_xvtr_modify[i] = -1;
		}
	}

	private void modifyXVTRantenna(int rx, double freq, int rx_xvtr_index)
	{
		if (rx < 0 || rx > 1 || rx_xvtr_index < 0 || rx_xvtr_index > 15 || IsSetupFormNull)
		{
			return;
		}
		int rXAntenna = XVTRForm.GetRXAntenna(rx_xvtr_index);
		if (rXAntenna >= 1 && rXAntenna <= 3)
		{
			Band band = BandByFreq(XVTRForm.TranslateFreq(freq), -1, current_region);
			int rXAntenna2 = SetupForm.GetRXAntenna(band);
			if (rXAntenna != rXAntenna2)
			{
				undoXVTRantennaModify(rx);
				rXAntenna2 = SetupForm.GetRXAntenna(band);
				_ant_before_xvtr_modify[rx] = rXAntenna2;
				_band_used_for_xvtr_modify[rx] = band;
				SetupForm.SetRXAntenna(rXAntenna, band);
			}
		}
		else
		{
			undoXVTRantennaModify(rx);
		}
	}

	private void undoXVTRantennaModify(int rx)
	{
		if (rx >= 0 && rx <= 1 && _band_used_for_xvtr_modify[rx] != Band.LAST)
		{
			if (!IsSetupFormNull)
			{
				SetupForm.SetRXAntenna(_ant_before_xvtr_modify[rx], _band_used_for_xvtr_modify[rx]);
			}
			_ant_before_xvtr_modify[rx] = -1;
			_band_used_for_xvtr_modify[rx] = Band.LAST;
		}
	}

	private Band getTXBandWhenExtended(Band b, double frequency = -1.0)
	{
		if (!extended)
		{
			return b;
		}
		Band band = b;
		if (Band.BLMF == b)
		{
			band = Band.B160M;
		}
		else if (Band.B120M == b)
		{
			band = Band.B160M;
		}
		else if (Band.B90M == b)
		{
			band = Band.B80M;
		}
		else if (Band.B61M == b)
		{
			band = Band.B80M;
		}
		else if (Band.B49M == b)
		{
			band = Band.B60M;
		}
		else if (Band.B41M == b)
		{
			band = Band.B40M;
		}
		else if (Band.B31M == b)
		{
			band = Band.B30M;
		}
		else if (Band.B25M == b)
		{
			band = Band.B20M;
		}
		else if (Band.B22M == b)
		{
			band = Band.B20M;
		}
		else if (Band.B19M == b)
		{
			band = Band.B17M;
		}
		else if (Band.B16M == b)
		{
			band = Band.B17M;
		}
		else if (Band.B14M == b)
		{
			band = Band.B15M;
		}
		else if (Band.B13M == b)
		{
			band = Band.B12M;
		}
		else if (Band.B11M == b)
		{
			band = Band.B10M;
		}
		if (band != b)
		{
			return band;
		}
		if (b >= Band.B160M && b <= Band.B6M)
		{
			return b;
		}
		if (b >= Band.VHF0 && b <= Band.VHF13)
		{
			return b;
		}
		if (frequency != -1.0)
		{
			Band nearestBandForFrequency = BandStackManager.GetNearestBandForFrequency(frequency, ignoreGen: true, ignoreWWV: true);
			if (nearestBandForFrequency != Band.FIRST)
			{
				b = nearestBandForFrequency;
			}
		}
		return b;
	}

	private void txtVFOAFreq_KeyPress(object sender, KeyPressEventArgs e)
	{
		string numberDecimalSeparator = CultureInfo.CurrentCulture.NumberFormat.NumberDecimalSeparator;
		int keyChar = e.KeyChar;
		if ((keyChar < 48 || keyChar > 57) && keyChar != 8 && !e.KeyChar.ToString().Equals(numberDecimalSeparator) && keyChar != 27)
		{
			e.Handled = true;
		}
		else if (e.KeyChar.ToString().Equals(numberDecimalSeparator))
		{
			e.Handled = ((TextBoxTS)sender).Text.IndexOf(numberDecimalSeparator) >= 0;
		}
		else if (keyChar == 27)
		{
			m_bVFOAChangedByKeys = false;
			btnHidden.Focus();
		}
		if (e.KeyChar == '\r')
		{
			m_bVFOAChangedByKeys = true;
			btnHidden.Focus();
		}
	}

	private void txtVFOAFreq_MouseMove(object sender, MouseEventArgs e)
	{
		if (!base.ContainsFocus)
		{
			return;
		}
		int num = vfoa_hover_digit;
		int num2 = 0;
		if (vfo_char_width == 0)
		{
			GetVFOCharWidth();
		}
		int num3 = txtVFOAFreq.Width - (vfo_pixel_offset - 5);
		while (num3 < e.X)
		{
			num2++;
			if (small_lsd && txtVFOALSD.Visible)
			{
				num3 = ((num2 >= 6) ? (num3 + (vfo_small_char_width + vfo_small_char_space)) : (num3 + (vfo_char_width + vfo_char_space)));
				if (num2 == 3)
