	private void txtVFOABand_LostFocus(object sender, EventArgs e)
	{
		if (!rx2_enabled || (!chkEnableMultiRX.Checked && !chkVFOSplit.Checked))
		{
			return;
		}
		if (txtVFOABand.Text == "." || string.IsNullOrEmpty(txtVFOABand.Text))
		{
			VFOASubFreq = VFOAFreq;
			return;
		}
		double vFOAFreq = VFOAFreq;
		double num;
		if (m_bVFOABandChangedByKeys)
		{
			num = (m_dVFOASubFreq = VFOASubFreq);
			m_bVFOABandChangedByKeys = false;
		}
		else
		{
			num = VFOASubFreq;
		}
		Display.VFOASub = (long)(num * 1000000.0);
		if (chkTUN.Checked && chkVFOATX.Checked && chkVFOSplit.Checked)
		{
			switch (radio.GetDSPTX(0).CurrentDSPMode)
			{
			case DSPMode.LSB:
			case DSPMode.CWL:
			case DSPMode.DIGL:
				Display.VFOASub += cw_pitch;
				break;
			case DSPMode.USB:
			case DSPMode.DSB:
			case DSPMode.CWU:
			case DSPMode.FM:
			case DSPMode.AM:
			case DSPMode.DIGU:
			case DSPMode.SAM:
				Display.VFOASub -= cw_pitch;
				break;
			}
		}
		saved_vfoa_sub_freq = num;
		if (!CheckValidTXFreq(current_region, num, radio.GetDSPTX(0).CurrentDSPMode, chkTUN.Checked) && chkVFOSplit.Checked && _mox && !extended)
		{
			chkMOX.Checked = false;
		}
		if (chkEnableMultiRX.Checked)
		{
			int num2 = (int)((num - vFOAFreq) * 1000000.0);
			double num3 = radio.GetDSPRX(0, 0).RXOsc - (double)num2;
			if (num3 < (double)(-sample_rate_rx1 / 2))
			{
				VFOASubFreq = vFOAFreq + ((double)(sample_rate_rx1 / 2) + radio.GetDSPRX(0, 0).RXOsc - 1.0) * 1E-06;
				return;
			}
			if (num3 > (double)(sample_rate_rx1 / 2))
			{
				VFOASubFreq = vFOAFreq + ((double)(-sample_rate_rx1 / 2) + radio.GetDSPRX(0, 0).RXOsc + 1.0) * 1E-06;
				return;
			}
			if (num3 > (double)(-sample_rate_rx1 / 2) && num3 < (double)(sample_rate_rx1 / 2))
			{
				radio.GetDSPRX(0, 1).RXOsc = num3;
			}
		}
		if (!chkVFOSplit.Checked)
		{
			return;
		}
		tx_xvtr_index = XVTRForm.XVTRFreq(num);
		Band tx_band = _tx_band;
		Band band = BandByFreq(num, tx_xvtr_index, current_region);
		Band tXBandWhenExtended = getTXBandWhenExtended(band, num);
		if (chkVFOSplit.Checked && tx_band != tXBandWhenExtended)
		{
			SetTXBand(tXBandWhenExtended, band != tXBandWhenExtended);
		}
		if (last_tx_xvtr_index != tx_xvtr_index && tx_xvtr_index >= 0)
		{
			SetupForm.RXOnly = XVTRForm.GetRXOnly(tx_xvtr_index);
		}
		if (tx_xvtr_index >= 0)
		{
			num = XVTRForm.TranslateFreq(num);
		}
		if (tx_band != _tx_band)
		{
			if (_tx_band == Band.B60M)
			{
				chkXIT.Enabled = false;
				chkXIT.Checked = false;
			}
			else
			{
				chkXIT.Enabled = true;
			}
		}
		if (chkXIT.Checked)
		{
			num += (double)(int)udXIT.Value * 1E-06;
		}
		if (num < min_freq)
		{
			num = min_freq;
		}
		else if (num > max_freq)
		{
			num = max_freq;
		}
		switch (radio.GetDSPTX(0).CurrentDSPMode)
		{
		case DSPMode.USB:
		case DSPMode.FM:
		case DSPMode.AM:
		case DSPMode.DIGU:
		case DSPMode.SAM:
			if (chkTUN.Checked)
			{
				num -= (double)cw_pitch * 1E-06;
			}
			break;
		case DSPMode.LSB:
		case DSPMode.DIGL:
			if (chkTUN.Checked)
			{
				num += (double)cw_pitch * 1E-06;
			}
			break;
		case DSPMode.CWL:
			num += (double)cw_pitch * 1E-06;
			break;
		case DSPMode.CWU:
			num -= (double)cw_pitch * 1E-06;
			break;
		}
		if (!rx1_sub_drag)
		{
			tx_dds_freq_mhz = num;
			UpdateTXDDSFreq();
		}
		last_tx_xvtr_index = tx_xvtr_index;
	}

	private void txtVFOABand_KeyPress(object sender, KeyPressEventArgs e)
	{
		if (!rx2_enabled || (!chkEnableMultiRX.Checked && !chkVFOSplit.Checked))
		{
			e.Handled = true;
			return;
		}
		string numberDecimalSeparator = CultureInfo.CurrentCulture.NumberFormat.NumberDecimalSeparator;
		int keyChar = e.KeyChar;
		if ((keyChar < 48 || keyChar > 57) && keyChar != 8 && !e.KeyChar.ToString().Equals(numberDecimalSeparator) && keyChar != 27)
		{
			e.Handled = true;
		}
		else if (e.KeyChar.ToString().Equals(numberDecimalSeparator))
		{
			e.Handled = ((TextBoxTS)sender).Text.IndexOf(numberDecimalSeparator) >= 0;
		}
		else if (keyChar == 27)
		{
			VFOASubFreq = saved_vfoa_sub_freq;
			btnHidden.Focus();
		}
		if (e.KeyChar == '\r')
		{
			m_bVFOABandChangedByKeys = true;
			btnHidden.Focus();
		}
	}

