	private void txtVFOBFreq_KeyPress(object sender, KeyPressEventArgs e)
	{
		string numberDecimalSeparator = CultureInfo.CurrentCulture.NumberFormat.NumberDecimalSeparator;
		int keyChar = e.KeyChar;
		if ((keyChar < 48 || keyChar > 57) && keyChar != 8 && !e.KeyChar.ToString().Equals(numberDecimalSeparator) && keyChar != 27)
		{
			e.Handled = true;
		}
		else if (e.KeyChar.ToString().Equals(numberDecimalSeparator))
		{
			e.Handled = ((TextBoxTS)sender).Text.IndexOf(numberDecimalSeparator) >= 0;
		}
		else if (keyChar == 27)
		{
			m_bVFOBChangedByKeys = false;
			btnHidden.Focus();
		}
		if (e.KeyChar == '\r')
		{
			m_bVFOBChangedByKeys = true;
			btnHidden.Focus();
		}
	}

	private void txtVFOBFreq_MouseMove(object sender, MouseEventArgs e)
	{
		if (!base.ContainsFocus)
		{
			return;
		}
		int num = vfob_hover_digit;
		int num2 = 0;
		if (vfo_char_width == 0)
		{
			GetVFOCharWidth();
		}
		int num3 = txtVFOBFreq.Width - (vfo_pixel_offset - 5);
		while (num3 < e.X)
		{
			num2++;
			if (small_lsd && txtVFOBLSD.Visible)
			{
				num3 = ((num2 >= 6) ? (num3 + (vfo_small_char_width + vfo_small_char_space)) : (num3 + (vfo_char_width + vfo_char_space)));
				if (num2 == 3)
				{
					num3 += vfo_decimal_space - vfo_char_space;
				}
				if (num2 == 6)
				{
					num3 += vfo_small_char_width;
				}
			}
			else
			{
				num3 += vfo_char_width;
				num3 = ((num2 != 3) ? (num3 + vfo_char_space) : (num3 + vfo_decimal_space));
			}
		}
		if (num2 < 3)
		{
			num2 = -1;
		}
		if (num2 > 9)
		{
			num2 = 9;
		}
		vfob_hover_digit = num2;
		if (vfob_hover_digit != num)
		{
			panelVFOBHover.Invalidate();
		}
	}

