	private bool overRX(int x, int y, int rx, bool bIgnorePanafallWaterfall = true)
	{
		int num = 0;
		int num2 = pnlDisplay.Height;
		int num3 = pnlDisplay.Height / 2;
		int num4 = pnlDisplay.Height;
		if (rx2_enabled)
		{
			num2 = pnlDisplay.Height / 2;
			if ((Display.CurrentDisplayModeBottom == DisplayMode.PANAFALL) & bIgnorePanafallWaterfall)
			{
				num4 = pnlDisplay.Height / 4 * 3;
			}
		}
		if ((Display.CurrentDisplayMode == DisplayMode.PANAFALL) & bIgnorePanafallWaterfall)
		{
			num2 = (rx2_enabled ? (pnlDisplay.Height / 4) : Display.PanafallSplitBarPosLogical);
		}
		if (rx1_enabled && rx == 1)
		{
			DisplayMode currentDisplayMode = Display.CurrentDisplayMode;
			if (((uint)currentDisplayMode <= 1u || (uint)(currentDisplayMode - 6) <= 4u) && x >= 0 && x < pnlDisplay.Width && y < num2 && y >= num)
			{
				return true;
			}
		}
		else if (rx2_enabled && rx == 2)
		{
			DisplayMode currentDisplayMode = Display.CurrentDisplayModeBottom;
			if (((uint)currentDisplayMode <= 1u || (uint)(currentDisplayMode - 6) <= 4u) && x >= 0 && x < pnlDisplay.Width && y < num4 && y >= num3)
			{
				return true;
			}
		}
		return false;
	}

	private void notchMouseWheel(int wheelDelta)
	{
		if (SelectedNotch != null)
		{
			double fWidth = SelectedNotch.FWidth;
			fWidth = ((!Common.ShiftKeyDown) ? (fWidth + (double)(wheelDelta * 10)) : (fWidth + (double)wheelDelta));
			if (fWidth < 0.0)
			{
				fWidth = 0.0;
			}
			if (fWidth > (double)_max_filter_width)
			{
				fWidth = _max_filter_width;
			}
			bool flag = true;
			if (SelectedNotch.FCenter - fWidth / 2.0 < 0.0)
			{
				flag = false;
			}
			if (SelectedNotch.FCenter + fWidth / 2.0 > max_freq * 1000000.0)
			{
				flag = false;
			}
			if (flag)
			{
				ChangeNotchBW(SelectedNotch, fWidth);
			}
		}
	}

	public bool CurrentDSPhasTwoSidebands(int rx, bool tx = false)
	{
		DSPMode dSPMode = (tx ? ((!RX2Enabled || !VFOBTX) ? RX1DSPMode : RX2DSPMode) : ((rx != 1) ? _rx2_dsp_mode : _rx1_dsp_mode));
		if (dSPMode != DSPMode.AM && dSPMode != DSPMode.DSB && dSPMode != DSPMode.FM && dSPMode != DSPMode.SAM && dSPMode != DSPMode.SPEC)
		{
			return dSPMode == DSPMode.DRM;
		}
		return true;
	}

	private float agcCalOffset(int rx)
	{
		if (rx == 1)
		{
			if (RX1AGCMode == AGCMode.FIXD)
			{
				return 0f;
			}
			return 2f + (Display.RX1DisplayCalOffset + (Display.RX1PreampOffset - Display.AlexPreampOffset) - Display.RX1FFTSizeOffset);
		}
		if (RX2AGCMode == AGCMode.FIXD)
		{
			return 0f;
		}
		return 2f + (Display.RX2DisplayCalOffset + (Display.RX2PreampOffset - Display.AlexPreampOffset) - Display.RX2FFTSizeOffset);
	}

	private void getFilterEdgesInPixels(MouseEventArgs e, ref int low_x, ref int high_x, ref int vfoa_sub_x, ref int vfoa_sub_low_x, ref int vfoa_sub_high_x)
	{
		if (rx2_enabled && e.Y > pnlDisplay.Height / 2)
		{
			if (_mox)
			{
				if (VFOBTX)
				{
					low_x = HzToPixel(radio.GetDSPTX(0).TXFilterLow, 2);
					high_x = HzToPixel(radio.GetDSPTX(0).TXFilterHigh, 2);
				}
				else
				{
					int num = HzToPixel((float)((VFOBFreq - CentreRX2Frequency) * 1000000.0), 2);
					low_x = num + HzToPixel(radio.GetDSPRX(1, 0).RXFilterLow, 2) - HzToPixel(0f, 2);
					high_x = num + HzToPixel(radio.GetDSPRX(1, 0).RXFilterHigh, 2) - HzToPixel(0f, 2);
				}
			}
			else if (_rx2_dsp_mode != DSPMode.DRM)
			{
				int num2 = HzToPixel((float)((VFOBFreq - CentreRX2Frequency) * 1000000.0), 2);
				low_x = num2 + HzToPixel(radio.GetDSPRX(1, 0).RXFilterLow, 2) - HzToPixel(0f, 2);
				high_x = num2 + HzToPixel(radio.GetDSPRX(1, 0).RXFilterHigh, 2) - HzToPixel(0f, 2);
			}
			return;
		}
		if (_mox)
		{
			low_x = HzToPixel(radio.GetDSPTX(0).TXFilterLow);
			high_x = HzToPixel(radio.GetDSPTX(0).TXFilterHigh);
		}
		else if (_rx1_dsp_mode != DSPMode.DRM)
		{
			int num3 = HzToPixel((float)((VFOAFreq - CentreFrequency) * 1000000.0));
			low_x = num3 + HzToPixel(radio.GetDSPRX(0, 0).RXFilterLow) - HzToPixel(0f);
			high_x = num3 + HzToPixel(radio.GetDSPRX(0, 0).RXFilterHigh) - HzToPixel(0f);
		}
		if (chkEnableMultiRX.Checked && !_mox)
		{
			if (!rx2_enabled)
			{
				vfoa_sub_x = HzToPixel((float)((VFOBFreq - VFOAFreq) * 1000000.0));
				vfoa_sub_low_x = vfoa_sub_x + (HzToPixel((int)udFilterLow.Value) - HzToPixel(0f));
				vfoa_sub_high_x = vfoa_sub_x + (HzToPixel((int)udFilterHigh.Value) - HzToPixel(0f));
			}
			else
			{
				vfoa_sub_x = HzToPixel((float)((VFOASubFreq - VFOAFreq) * 1000000.0));
				vfoa_sub_low_x = vfoa_sub_x + (HzToPixel((int)udFilterLow.Value) - HzToPixel(0f));
				vfoa_sub_high_x = vfoa_sub_x + (HzToPixel((int)udFilterHigh.Value) - HzToPixel(0f));
			}
		}
	}

	private void dragWholeFilter(MouseEventArgs e)
	{
		whole_filter_start_x = e.X;
		if (rx2_enabled && e.Y > pnlDisplay.Height / 2)
		{
			if (_mox && chkVFOBTX.Checked)
			{
				tx_whole_filter_drag = true;
				whole_filter_start_low = SetupForm.TXFilterLow;
				whole_filter_start_high = SetupForm.TXFilterHigh;
			}
			else
			{
				rx2_whole_filter_drag = true;
				whole_filter_start_low = radio.GetDSPRX(1, 0).RXFilterLow;
				whole_filter_start_high = radio.GetDSPRX(1, 0).RXFilterHigh;
			}
		}
		else if (!_mox)
		{
			rx1_whole_filter_drag = true;
			whole_filter_start_low = radio.GetDSPRX(0, 0).RXFilterLow;
			whole_filter_start_high = radio.GetDSPRX(0, 0).RXFilterHigh;
		}
		else
		{
			tx_whole_filter_drag = true;
			whole_filter_start_low = SetupForm.TXFilterLow;
			whole_filter_start_high = SetupForm.TXFilterHigh;
		}
	}

	private double adjustForSnapClickTuning(int rx, double freq)
	{
		DSPMode dSPMode = ((rx != 1) ? RX2DSPMode : RX1DSPMode);
		if (dSPMode == DSPMode.FIRST || dSPMode == DSPMode.LAST)
		{
			return freq;
		}
		if (snap_to_click_tuning && (current_click_tune_mode != ClickTuneMode.Off || click_tune_drag) && dSPMode != DSPMode.CWL && dSPMode != DSPMode.CWU && dSPMode != DSPMode.DIGL && dSPMode != DSPMode.DIGU && !getWavePlayback((rx != 1) ? 1 : 0))
		{
			long num = (long)(freq * 1000000.0);
			int currentTuneStepHz = CurrentTuneStepHz;
			num = ((num % currentTuneStepHz <= currentTuneStepHz / 2) ? (num - num % currentTuneStepHz) : (num + (currentTuneStepHz - num % currentTuneStepHz)));
			freq = (double)num * 1E-06;
		}
		return freq;
	}

	private double getFrequencyAtPixel(int x, int nRX)
	{
		double num = 0.0;
		if (nRX == 2)
		{
			num = ((!_click_tune_rx2_display) ? ((double)PixelToHz(x, 2) + VFOBFreq * 1000000.0) : ((double)PixelToHz(x, 2) + CentreRX2Frequency * 1000000.0));
			switch (_rx2_dsp_mode)
			{
			case DSPMode.CWU:
				num -= (double)cw_pitch;
				break;
			case DSPMode.CWL:
				num += (double)cw_pitch;
				break;
			}
		}
		else
		{
			num = ((!_click_tune_display) ? ((double)PixelToHz(x, 1) + VFOAFreq * 1000000.0) : ((double)PixelToHz(x, 1) + CentreFrequency * 1000000.0));
			switch (_rx1_dsp_mode)
			{
			case DSPMode.CWU:
				num -= (double)cw_pitch;
				break;
			case DSPMode.CWL:
				num += (double)cw_pitch;
				break;
			}
		}
		return num;
	}

	public void ShowNotchPopup(int x, int y, MNotch notch, int min_width, int max_width, bool on_top, int notch_index = -1)
	{
		if (m_frmNotchPopup != null)
		{
			if (notch_index != -1)
			{
				notch = MNotchDB.NotchFromIndex(notch_index);
			}
			m_frmNotchPopup.Location = new Point(x, y);
			Common.ForceFormOnScreen(m_frmNotchPopup, shrink_to_fit: true, keep_on_screen: true);
			if (!m_frmNotchPopup.Visible && notch != null)
			{
				m_frmNotchPopup.Show(notch, min_width, max_width, on_top, notch_index);
			}
		}
	}

