	private void btnDisplayPanCenter_Click(object sender, EventArgs e)
	{
		double num = 200000000.0 / Math.Pow(2.0, 16.0);
		int num2 = Display.RXDisplayHigh - Display.RXDisplayLow;
		int num3 = (int)((double)sample_rate_rx1 - 2.0 * num - (double)num2);
		if (num3 == 0)
		{
			ptbDisplayPan.Value = (ptbDisplayPan.Maximum - ptbDisplayPan.Minimum) / 2;
			ptbDisplayPan_Scroll(btnDisplayPanCenter, EventArgs.Empty);
			return;
		}
		int num4 = -num2 / 2;
		int num5 = (int)((0.0 - (double)sample_rate_rx1) * 0.5 + num);
		int val = (int)((double)(num4 - num5) * (double)ptbDisplayPan.Maximum / (double)num3);
		Pan = Math.Min(Math.Max(ptbDisplayPan.Minimum, val), ptbDisplayPan.Maximum);
	}

	private bool zoomToBandBandwidth(Band b, int rx)
	{
		if (rx == 1 && (!ClickTuneDisplay || b != RX1Band))
		{
			return false;
		}
		if (rx == 2 && (!ClickTuneRX2Display || b != RX2Band))
		{
			return false;
		}
		List<BandFrequencyData> frequencyRangesForBand = BandStackManager.GetFrequencyRangesForBand(b, Extended, CurrentRegion);
		if (frequencyRangesForBand.Count != 1)
		{
			return false;
		}
		BandFrequencyData bandFrequencyData = frequencyRangesForBand.First();
		if (bandFrequencyData.lowOnly)
		{
			return false;
		}
		double low = bandFrequencyData.low;
		double num = bandFrequencyData.high - low;
		double num2 = low + num / 2.0;
		int num3 = 0;
		switch (rx)
		{
		case 1:
			num3 = cmaster.inid(0, 0);
			break;
		case 2:
			num3 = cmaster.inid(0, 1);
			break;
		default:
			return false;
		}
		SpecHPSDR specHPSDR = specRX.GetSpecRX(num3);
		if ((int)(num * 1000000.0) > specHPSDR.SampleRate)
		{
			Zoom = ptbDisplayZoom.Minimum;
		}
		else
		{
			double num4 = (double)specHPSDR.SampleRate / (double)specHPSDR.FFTSize;
			int num5 = specHPSDR.FFTSize - 2 * specHPSDR.Clip;
			int num6 = specHPSDR.Stitches * num5;
			int val = (int)(num * 1000000.0 / num4);
			val = Math.Min(val, num6);
			double num7 = 1.0 - (double)val / (double)num6;
			double num8 = Math.Pow(10.0, num7) - 1.0;
			num8 /= 9.0;
			m_bIgnoreZoomCentre = true;
			PanCentre();
			Zoom = (int)(num8 * 230.0 + 10.0);
			m_bIgnoreZoomCentre = false;
			m_bIgnoreLimitsForZTB = true;
			switch (rx)
			{
			case 1:
				if (_rx1_dsp_mode == DSPMode.CWL)
				{
					num2 -= (double)cw_pitch * 1E-06;
				}
				else if (_rx1_dsp_mode == DSPMode.CWU)
				{
					num2 += (double)cw_pitch * 1E-06;
				}
				CentreFrequency = num2;
				txtVFOAFreq_LostFocus(this, EventArgs.Empty);
				break;
			case 2:
				if (_rx2_dsp_mode == DSPMode.CWL)
				{
					num2 -= (double)cw_pitch * 1E-06;
				}
				else if (_rx2_dsp_mode == DSPMode.CWU)
				{
					num2 += (double)cw_pitch * 1E-06;
				}
				CentreRX2Frequency = num2;
				txtVFOBFreq_LostFocus(this, EventArgs.Empty);
				break;
			}
			m_bIgnoreLimitsForZTB = false;
		}
		return true;
	}

	private void ptbDisplayZoom_Scroll(object sender, EventArgs e)
	{
		double num = lastZoomFactor;
		specRX.GetSpecRX(0).ZoomSlider = ((double)ptbDisplayZoom.Value - 10.0) / 230.0;
		specRX.GetSpecRX(1).ZoomSlider = ((double)ptbDisplayZoom.Value - 10.0) / 230.0;
		specRX.GetSpecRX(cmaster.inid(1, 0)).ZoomSlider = ((double)ptbDisplayZoom.Value - 10.0) / 230.0;
		double num2 = 1.0 / ((double)(ptbDisplayZoom.Maximum + ptbDisplayZoom.Minimum - ptbDisplayZoom.Value) * 0.01);
		DisplayZoomButton dzb;
		if (num2 == 0.5)
		{
			radDisplayZoom05.Checked = true;
			dzb = DisplayZoomButton.B05;
		}
		else if (num2 == 1.0)
		{
			radDisplayZoom1x.Checked = true;
			dzb = DisplayZoomButton.B1;
		}
		else if (num2 == 2.0)
		{
			radDisplayZoom2x.Checked = true;
			dzb = DisplayZoomButton.B2;
		}
		else if (num2 == 4.0)
		{
			radDisplayZoom4x.Checked = true;
			dzb = DisplayZoomButton.B4;
		}
		else
		{
			radDisplayZoom05.Checked = false;
			radDisplayZoom1x.Checked = false;
			radDisplayZoom2x.Checked = false;
			radDisplayZoom4x.Checked = false;
			dzb = DisplayZoomButton.NONE;
		}
		CalcDisplayFreq();
		CalcRX2DisplayFreq();
		CalcTXDisplayFreq();
		if (initializing)
		{
			lastZoomFactor = num2;
		}
		bool flag = num2 > lastZoomFactor;
		if (!m_bIgnoreZoomCentre)
		{
			bool flag2 = !m_bZoomShiftModifier || (m_bZoomShiftModifier && ((!Common.ShiftKeyDown && !m_bZoomShiftModifierReverse) || (Common.ShiftKeyDown && m_bZoomShiftModifierReverse)));
			if (ClickTuneDisplay & flag & flag2)
			{
				CentreFrequency = VFOAFreq;
				txtVFOAFreq_LostFocus(this, EventArgs.Empty);
			}
			if ((rx2_enabled && (ClickTuneRX2Display & flag)) & flag2)
			{
				CentreRX2Frequency = VFOBFreq;
				txtVFOBFreq_LostFocus(this, EventArgs.Empty);
			}
		}
		lastZoomFactor = num2;
		if (sender.GetType() == typeof(PrettyTrackBar))
		{
			ptbDisplayZoom.Focus();
		}
		if (num != num2)
		{
			ZoomFactorChangedHandlers?.Invoke(num, num2, ptbDisplayZoom.Value);
		}
		SetDisplayZoomGeneralSettings(0, dzb);
	}

