	private void initControlBackColours(Control c)
	{
		foreach (Control control in c.Controls)
		{
			Type type = control.GetType();
			if (type == typeof(ButtonTS) || type == typeof(RadioButtonTS))
			{
				if (control.Name != "radRX1Show" && control.Name != "radRX2Show" && control.Name != "chkVACStereo")
				{
					control.BackColor = SystemColors.Control;
				}
			}
			else if (type == typeof(PanelTS))
			{
				initControlBackColours(control);
			}
			else if (type == typeof(GroupBoxTS))
			{
				initControlBackColours(control);
			}
		}
	}

	private void SetRX1Mode(DSPMode new_mode)
	{
		if (new_mode == DSPMode.FIRST || new_mode == DSPMode.LAST)
		{
			return;
		}
		Band rX1Band = RX1Band;
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		DSPMode rx1_dsp_mode = _rx1_dsp_mode;
		WDSP.SetChannelState(WDSP.id(0u, 1u), 0, 0);
		WDSP.SetChannelState(WDSP.id(0u, 0u), 0, 1);
		Thread.Sleep(1);
		if (new_mode == DSPMode.FM)
		{
			WDSP.SetDSPSamplerate(WDSP.id(0u, 0u), 192000);
			WDSP.SetDSPSamplerate(WDSP.id(0u, 1u), 192000);
		}
		else
		{
			WDSP.SetDSPSamplerate(WDSP.id(0u, 0u), 48000);
			WDSP.SetDSPSamplerate(WDSP.id(0u, 1u), 48000);
		}
		radio.GetDSPRX(0, 0).DSPMode = new_mode;
		radio.GetDSPRX(0, 1).DSPMode = new_mode;
		if (chkVFOATX.Checked || !rx2_enabled)
		{
			Audio.TXDSPMode = new_mode;
			radio.GetDSPTX(0).CurrentDSPMode = new_mode;
		}
		Display.RX1DSPMode = new_mode;
		RadioDSP.RX1DSPMode = new_mode;
		if (new_mode == DSPMode.CWL || new_mode == DSPMode.CWU)
		{
			WDSP.SetChannelTDelayUp(WDSP.id(0u, 0u), 0.005);
			WDSP.SetChannelTDelayUp(WDSP.id(0u, 1u), 0.005);
			WDSP.SetChannelTSlewUp(WDSP.id(0u, 0u), 0.01);
			WDSP.SetChannelTSlewUp(WDSP.id(0u, 1u), 0.01);
			WDSP.SetChannelTDelayDown(WDSP.id(0u, 0u), 0.0);
			WDSP.SetChannelTDelayDown(WDSP.id(0u, 1u), 0.0);
			WDSP.SetChannelTSlewDown(WDSP.id(0u, 0u), 0.005);
			WDSP.SetChannelTSlewDown(WDSP.id(0u, 1u), 0.005);
		}
		else
		{
			WDSP.SetChannelTDelayUp(WDSP.id(0u, 0u), 0.0);
			WDSP.SetChannelTDelayUp(WDSP.id(0u, 1u), 0.0);
			WDSP.SetChannelTSlewUp(WDSP.id(0u, 0u), 0.01);
			WDSP.SetChannelTSlewUp(WDSP.id(0u, 1u), 0.01);
			WDSP.SetChannelTDelayDown(WDSP.id(0u, 0u), 0.0);
			WDSP.SetChannelTDelayDown(WDSP.id(0u, 1u), 0.0);
			WDSP.SetChannelTSlewDown(WDSP.id(0u, 0u), 0.01);
			WDSP.SetChannelTSlewDown(WDSP.id(0u, 1u), 0.01);
		}
		double num = VFOAFreq;
		ptbFilterShift.Value = 0;
		btnFilterShiftReset.BackColor = SystemColors.Control;
		switch (rx1_dsp_mode)
		{
		case DSPMode.LSB:
			radModeLSB.BackColor = SystemColors.Control;
			break;
		case DSPMode.USB:
			radModeUSB.BackColor = SystemColors.Control;
			break;
		case DSPMode.DSB:
			radModeDSB.BackColor = SystemColors.Control;
			break;
		case DSPMode.CWL:
			radModeCWL.BackColor = SystemColors.Control;
			if ((chkVFOATX.Checked || !rx2_enabled) && new_mode != DSPMode.CWU && new_mode != DSPMode.CWL)
			{
				_ignore_sidetone_change = true;
				chkMON.Checked = mon_recall;
				_ignore_sidetone_change = false;
			}
			radio.GetDSPRX(0, 0).RXAPFRun = false;
			radio.GetDSPRX(0, 1).RXAPFRun = false;
			SetupForm.EnableRX1APFControl = false;
			lblRX1APF.Hide();
			chkANF.Enabled = true;
			chkANF_CheckedChanged(this, EventArgs.Empty);
			if (!RX1IsIn60mChannel())
			{
				switch (new_mode)
				{
				case DSPMode.USB:
					num -= (double)cw_pitch * 1E-06;
					break;
				default:
					num += (double)cw_pitch * 1E-06;
					break;
				case DSPMode.CWU:
					break;
				}
				setVFOAFreqNoUpdate(num);
			}
			break;
		case DSPMode.CWU:
			radModeCWU.BackColor = SystemColors.Control;
			if ((chkVFOATX.Checked || !rx2_enabled) && new_mode != DSPMode.CWL && new_mode != DSPMode.CWU)
			{
				_ignore_sidetone_change = true;
				chkMON.Checked = mon_recall;
				_ignore_sidetone_change = false;
			}
			radio.GetDSPRX(0, 0).RXAPFRun = false;
			radio.GetDSPRX(0, 1).RXAPFRun = false;
			SetupForm.EnableRX1APFControl = false;
			lblRX1APF.Hide();
			chkANF.Enabled = true;
			chkANF_CheckedChanged(this, EventArgs.Empty);
			if (!RX1IsIn60mChannel())
			{
				switch (new_mode)
				{
				case DSPMode.LSB:
					num += (double)cw_pitch * 1E-06;
					break;
				default:
					num -= (double)cw_pitch * 1E-06;
					break;
				case DSPMode.CWL:
					break;
				}
				setVFOAFreqNoUpdate(num);
			}
			break;
		case DSPMode.FM:
			radModeFMN.BackColor = SystemColors.Control;
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				if (new_mode != DSPMode.AM && new_mode != DSPMode.SAM)
				{
					chkBIN.Enabled = true;
				}
				chkMON.Enabled = true;
				ptbMic_Scroll(this, EventArgs.Empty);
			}
			if (new_mode != DSPMode.SPEC && new_mode != DSPMode.DRM)
			{
				EnableAllFilters();
			}
			handleSqlFM(1, bFM: false);
			break;
		case DSPMode.AM:
			radModeAM.BackColor = SystemColors.Control;
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				if (new_mode != DSPMode.AM && new_mode != DSPMode.SAM)
				{
					chkBIN.Enabled = true;
				}
				chkMON.Enabled = true;
			}
			break;
		case DSPMode.SAM:
			radModeSAM.BackColor = SystemColors.Control;
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				if (new_mode != DSPMode.AM && new_mode != DSPMode.SAM)
				{
					chkBIN.Enabled = true;
				}
				chkMON.Enabled = true;
			}
			break;
		case DSPMode.SPEC:
		{
			radModeSPEC.BackColor = SystemColors.Control;
			comboDisplayMode.Items.Insert(1, "Panadapter");
			comboDisplayMode.Items.Insert(5, "Waterfall");
			ptbFilterShift.Enabled = true;
			btnFilterShiftReset.Enabled = true;
			if (new_mode != DSPMode.DRM && new_mode != DSPMode.FM)
			{
				EnableAllFilters();
			}
			RX1Filter = rx1_filter;
			if (was_panadapter)
			{
				comboDisplayMode.Text = "Panadapter";
			}
			else if (was_waterfall)
			{
				comboDisplayMode.Text = "Waterfall";
			}
			DisplayMode currentDisplayMode = Display.CurrentDisplayMode;
			if (currentDisplayMode == DisplayMode.PANADAPTER || currentDisplayMode == DisplayMode.WATERFALL || (uint)(currentDisplayMode - 8) <= 1u)
			{
				radio.GetDSPRX(0, 0).SpectrumPreFilter = true;
			}
			else
			{
				radio.GetDSPRX(0, 0).SpectrumPreFilter = false;
			}
			break;
		}
		case DSPMode.DIGL:
			radModeDIGL.BackColor = SystemColors.Control;
			if (vac_auto_enable && new_mode != DSPMode.DIGU && new_mode != DSPMode.DRM)
			{
				SetupForm.VACEnable = false;
			}
			if (new_mode != DSPMode.DIGU)
			{
				flag2 = true;
			}
			break;
		case DSPMode.DIGU:
			radModeDIGU.BackColor = SystemColors.Control;
			if (vac_auto_enable && new_mode != DSPMode.DIGL && new_mode != DSPMode.DRM)
			{
				SetupForm.VACEnable = false;
			}
			if (new_mode != DSPMode.DIGL)
			{
				flag2 = true;
			}
			break;
		case DSPMode.DRM:
			radModeDRM.BackColor = SystemColors.Control;
			_rx1_vfo_offset = 0.0;
			if (vac_auto_enable && new_mode != DSPMode.DIGL && new_mode != DSPMode.DIGU)
			{
				SetupForm.VACEnable = false;
			}
			ptbFilterShift.Enabled = true;
			btnFilterShiftReset.Enabled = true;
			if (new_mode != DSPMode.SPEC && new_mode != DSPMode.FM)
			{
				EnableAllFilters();
			}
			chkTNF.Enabled = true;
			btnTNFAdd.Enabled = true;
			break;
		}
		switch (new_mode)
		{
		case DSPMode.LSB:
			_rx1_vfo_offset = 0.0;
			radModeLSB.BackColor = button_selected_color;
			if (!_rx_only && PowerOn)
			{
				chkMOX.Enabled = true;
			}
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			break;
		case DSPMode.USB:
			radModeUSB.BackColor = button_selected_color;
			if (!_rx_only && chkPower.Checked)
			{
				chkMOX.Enabled = true;
			}
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			break;
		case DSPMode.DSB:
			radModeDSB.BackColor = button_selected_color;
			if (!_rx_only && chkPower.Checked)
			{
				chkMOX.Enabled = true;
			}
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			break;
		case DSPMode.CWL:
			radModeCWL.BackColor = button_selected_color;
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				CWPitch = cw_pitch;
				radio.GetDSPTX(0).TXOsc = 0.0;
				if (!_rx_only && chkPower.Checked)
				{
					chkMOX.Enabled = true;
				}
				if (rx1_dsp_mode != DSPMode.CWL && rx1_dsp_mode != DSPMode.CWU)
				{
					if (!initializing)
					{
						mon_recall = chkMON.Checked;
					}
					chkMON.Checked = _cw_sidetones && (_cw_hw_sidetone || _cw_sidetones);
				}
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
			}
			if (!RX1IsIn60mChannel())
			{
				switch (_rx1_dsp_mode)
				{
				case DSPMode.USB:
					num += (double)cw_pitch * 1E-06;
					break;
				default:
					num -= (double)cw_pitch * 1E-06;
					break;
				case DSPMode.CWU:
					break;
				}
				setVFOAFreqNoUpdate(num);
			}
			SetupForm.EnableRX1APFControl = true;
			lblRX1APF.Show();
			radio.GetDSPRX(0, 0).AutoNotchFilter = false;
			radio.GetDSPRX(0, 1).AutoNotchFilter = false;
			chkANF.Enabled = false;
			break;
		case DSPMode.CWU:
			radModeCWU.BackColor = button_selected_color;
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				CWPitch = cw_pitch;
				radio.GetDSPTX(0).TXOsc = 0.0;
				if (!_rx_only && chkPower.Checked)
				{
					chkMOX.Enabled = true;
				}
				if (rx1_dsp_mode != DSPMode.CWL && rx1_dsp_mode != DSPMode.CWU)
				{
					if (!initializing)
					{
						mon_recall = chkMON.Checked;
					}
					chkMON.Checked = _cw_sidetones && (_cw_hw_sidetone || _cw_sw_sidetone);
				}
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
			}
			if (!RX1IsIn60mChannel())
			{
				switch (_rx1_dsp_mode)
				{
				case DSPMode.LSB:
					num -= (double)cw_pitch * 1E-06;
					break;
				default:
					num += (double)cw_pitch * 1E-06;
					break;
				case DSPMode.CWL:
					break;
				}
				setVFOAFreqNoUpdate(num);
			}
			SetupForm.EnableRX1APFControl = true;
			chkANF.Enabled = false;
			lblRX1APF.Show();
			radio.GetDSPRX(0, 0).AutoNotchFilter = false;
			radio.GetDSPRX(0, 1).AutoNotchFilter = false;
			break;
		case DSPMode.FM:
			radModeFMN.BackColor = button_selected_color;
			DisableAllFilters();
			if (_nr_selected[0] > 0)
			{
				SelectNR(1, incude_sub: true, 0);
			}
			handleSqlFM(1, bFM: true);
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				if (!_rx_only && chkPower.Checked)
				{
					chkMOX.Enabled = true;
				}
				chkMON.Checked = false;
				chkMON.Enabled = false;
				chkBIN.Checked = false;
				chkBIN.Enabled = false;
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				ptbFMMic_Scroll(this, EventArgs.Empty);
			}
			break;
		case DSPMode.AM:
			radModeAM.BackColor = button_selected_color;
			if (!_rx_only && chkPower.Checked)
			{
				chkMOX.Enabled = true;
			}
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				chkBIN.Checked = false;
				chkBIN.Enabled = false;
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
			}
			break;
		case DSPMode.SAM:
			radModeSAM.BackColor = button_selected_color;
			if (!_rx_only && chkPower.Checked)
			{
				chkMOX.Enabled = true;
			}
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				chkBIN.Checked = false;
				chkBIN.Enabled = false;
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
			}
			break;
		case DSPMode.SPEC:
		{
			radModeSPEC.BackColor = button_selected_color;
			if_shift = false;
			radio.GetDSPRX(0, 0).RXOsc = 0.0;
			DisableAllFilters();
			ptbFilterShift.Enabled = false;
			btnFilterShiftReset.Enabled = false;
			bool flag4 = Display.CurrentDisplayMode == DisplayMode.PANADAPTER;
			bool flag5 = Display.CurrentDisplayMode == DisplayMode.WATERFALL;
			if (flag4 | flag5)
			{
				comboDisplayMode.Text = "Spectrum";
			}
			comboDisplayMode.Items.Remove("Panadapter");
			comboDisplayMode.Items.Remove("Waterfall");
			was_panadapter = flag4;
			was_waterfall = flag5;
			radio.GetDSPRX(0, 0).SpectrumPreFilter = true;
			Display.RXDisplayLow = -sample_rate_rx1 / 2;
			Display.RXDisplayHigh = sample_rate_rx1 / 2;
			break;
		}
		case DSPMode.DIGL:
			radModeDIGL.BackColor = button_selected_color;
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			if (vac_auto_enable)
			{
				SetupForm.VACEnable = true;
			}
			if (rx1_dsp_mode != DSPMode.DIGU)
			{
				flag = true;
				flag3 = true;
			}
			break;
		case DSPMode.DIGU:
			radModeDIGU.BackColor = button_selected_color;
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			if (vac_auto_enable)
			{
				SetupForm.VACEnable = true;
			}
			if (rx1_dsp_mode != DSPMode.DIGL)
			{
				flag = true;
				flag3 = true;
			}
			break;
		case DSPMode.DRM:
			if_shift = false;
			_rx1_vfo_offset = -0.012;
			radModeDRM.BackColor = button_selected_color;
			if (vac_auto_enable)
			{
				SetupForm.VACEnable = true;
			}
			if (chkVFOATX.Checked || !rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			DisableAllFilters();
			ptbFilterShift.Enabled = false;
			btnFilterShiftReset.Enabled = false;
			radio.GetDSPRX(0, 0).SetRXFilter(7000, 17000);
			btnTNFAdd.Enabled = false;
			chkTNF.Enabled = false;
			chkTNF.Checked = false;
			break;
		}
		if (RX1IsOn60mChannel() && current_region == FRSRegion.US)
		{
			num += 0.0 - ModeFreqOffset(rx1_dsp_mode) + ModeFreqOffset(new_mode);
			setVFOAFreqNoUpdate(num);
		}
		ToolStripMenuItem filterToolStripMenuItem = FilterToolStripMenuItem1;
		string text = (radFilter1.Text = rx1_filters[(int)new_mode].GetName(Filter.F1));
		filterToolStripMenuItem.Text = text;
		ToolStripMenuItem filterToolStripMenuItem2 = FilterToolStripMenuItem2;
		text = (radFilter2.Text = rx1_filters[(int)new_mode].GetName(Filter.F2));
		filterToolStripMenuItem2.Text = text;
		ToolStripMenuItem filterToolStripMenuItem3 = FilterToolStripMenuItem3;
		text = (radFilter3.Text = rx1_filters[(int)new_mode].GetName(Filter.F3));
		filterToolStripMenuItem3.Text = text;
		ToolStripMenuItem filterToolStripMenuItem4 = FilterToolStripMenuItem4;
		text = (radFilter4.Text = rx1_filters[(int)new_mode].GetName(Filter.F4));
		filterToolStripMenuItem4.Text = text;
		ToolStripMenuItem filterToolStripMenuItem5 = FilterToolStripMenuItem5;
		text = (radFilter5.Text = rx1_filters[(int)new_mode].GetName(Filter.F5));
		filterToolStripMenuItem5.Text = text;
		ToolStripMenuItem filterToolStripMenuItem6 = FilterToolStripMenuItem6;
		text = (radFilter6.Text = rx1_filters[(int)new_mode].GetName(Filter.F6));
		filterToolStripMenuItem6.Text = text;
		ToolStripMenuItem filterToolStripMenuItem7 = FilterToolStripMenuItem7;
		text = (radFilter7.Text = rx1_filters[(int)new_mode].GetName(Filter.F7));
		filterToolStripMenuItem7.Text = text;
		ToolStripMenuItem filterToolStripMenuItem8 = FilterToolStripMenuItem8;
		text = (radFilter8.Text = rx1_filters[(int)new_mode].GetName(Filter.F8));
		filterToolStripMenuItem8.Text = text;
		ToolStripMenuItem filterToolStripMenuItem9 = FilterToolStripMenuItem9;
		text = (radFilter9.Text = rx1_filters[(int)new_mode].GetName(Filter.F9));
		filterToolStripMenuItem9.Text = text;
		ToolStripMenuItem filterToolStripMenuItem10 = FilterToolStripMenuItem10;
		text = (radFilter10.Text = rx1_filters[(int)new_mode].GetName(Filter.F10));
		filterToolStripMenuItem10.Text = text;
		radFilterVar1.Text = rx1_filters[(int)new_mode].GetName(Filter.VAR1);
		radFilterVar2.Text = rx1_filters[(int)new_mode].GetName(Filter.VAR2);
		_rx1_dsp_mode = new_mode;
		SelectModeDependentPanel();
		if (_rx1_dsp_mode != DSPMode.SPEC && _rx1_dsp_mode != DSPMode.FM && _rx1_dsp_mode != DSPMode.DRM)
		{
			RX1Filter = rx1_filters[(int)new_mode].LastFilter;
		}
		else
		{
			RX1Filter = Filter.NONE;
			if (_rx1_dsp_mode == DSPMode.FM)
			{
				int num2 = (int)(radio.GetDSPRX(0, 0).RXFMDeviation + radio.GetDSPRX(0, 0).RXFMHighCut);
				UpdateRX1Filters(-num2, num2);
			}
		}
		BINToolStripMenuItem.Enabled = chkBIN.Enabled;
		tbFilterWidthScroll_newMode();
		UpdateDSP();
		txtVFOAFreq_LostFocus(this, EventArgs.Empty);
		ptbPWR_Scroll(this, EventArgs.Empty);
		if (chkVFOSplit.Checked || full_duplex || PSState)
		{
			txtVFOBFreq_LostFocus(this, EventArgs.Empty);
		}
		chkSquelch_CheckStateChanged(this, EventArgs.Empty);
		CalcDisplayFreq();
		if (new_mode == DSPMode.CWL || new_mode == DSPMode.CWU)
		{
			chkCWAPFEnabled_CheckedChanged(this, EventArgs.Empty);
		}
		if (rx1_dsp_mode == DSPMode.FM || new_mode == DSPMode.FM)
		{
			SetupForm.ForceAudioReset();
		}
		WDSP.SetChannelState(WDSP.id(0u, 0u), 1, 0);
		if (radio.GetDSPRX(0, 1).Active)
		{
			WDSP.SetChannelState(WDSP.id(0u, 1u), 1, 0);
		}
		if (new_mode != DSPMode.CWL && new_mode != DSPMode.CWU)
		{
			CWFWKeyer = false;
			if (BreakInEnabledState == CheckState.Indeterminate)
			{
				NonCWModeBreakInDisabled = true;
			}
		}
		else
		{
			CWFWKeyer = true;
			NonCWModeBreakInDisabled = false;
		}
		if (new_mode != DSPMode.CWL && new_mode != DSPMode.CWU && (rx1_dsp_mode == DSPMode.CWL || rx1_dsp_mode == DSPMode.CWU))
		{
			if (QSKEnabled)
			{
				chkQSK.Checked = false;
				qsk_in_CW = true;
			}
			else
			{
				qsk_in_CW = false;
			}
		}
		if ((new_mode == DSPMode.CWL || new_mode == DSPMode.CWU) && rx1_dsp_mode != DSPMode.CWL && rx1_dsp_mode != DSPMode.CWU && qsk_in_CW)
		{
			chkQSK.CheckState = CheckState.Indeterminate;
		}
		if (flag2)
		{
			SetDigiMode(1, DigiMode.DigiModeSettingState.dmssRecall);
		}
		switch (_rx1_dsp_mode)
		{
		case DSPMode.DIGU:
		case DSPMode.DIGL:
			comboDigTXProfile_SelectedIndexChanged(this, EventArgs.Empty);
			break;
		case DSPMode.FM:
			comboFMTXProfile_SelectedIndexChanged(this, EventArgs.Empty);
			break;
		case DSPMode.AM:
		case DSPMode.SAM:
			comboAMTXProfile.BringToFront();
			comboAMTXProfile_SelectedIndexChanged(this, EventArgs.Empty);
			break;
		default:
			comboTXProfile.BringToFront();
			comboTXProfile_SelectedIndexChanged(this, EventArgs.Empty);
			break;
		}
		if (flag)
		{
			SetDigiMode(1, DigiMode.DigiModeSettingState.dmssStore);
		}
		if (flag3)
		{
			SetDigiMode(1, DigiMode.DigiModeSettingState.dmssTurnOffSettings);
		}
		if (rx1_dsp_mode != new_mode)
		{
			ModeChangeHandlers?.Invoke(1, rx1_dsp_mode, new_mode, rX1Band, RX1Band);
		}
	}

	private void radModeButton_CheckedChanged(object sender, EventArgs e)
	{
		if (sender != null && !(sender.GetType() != typeof(RadioButtonTS)) && ((RadioButtonTS)sender).Checked)
		{
			string text = ((RadioButtonTS)sender).Text;
			DSPMode dSPMode = text switch
			{
				"LSB" => DSPMode.LSB, 
				"USB" => DSPMode.USB, 
				"DSB" => DSPMode.DSB, 
				"CWL" => DSPMode.CWL, 
				"CWU" => DSPMode.CWU, 
				"FM" => DSPMode.FM, 
				"AM" => DSPMode.AM, 
				"SAM" => DSPMode.SAM, 
				"SPEC" => DSPMode.SPEC, 
				"DIGL" => DSPMode.DIGL, 
				"DIGU" => DSPMode.DIGU, 
				"DRM" => DSPMode.DRM, 
				_ => DSPMode.FIRST, 
			};
			if (dSPMode != DSPMode.FIRST)
			{
				SetRX1Mode(dSPMode);
				lblModeLabel.Text = text;
				lblModeBigLabel.Text = text;
			}
			lSBToolStripMenuItem.Checked = radModeLSB.Checked;
			uSBToolStripMenuItem.Checked = radModeUSB.Checked;
			dSBToolStripMenuItem.Checked = radModeDSB.Checked;
			cWLToolStripMenuItem.Checked = radModeCWL.Checked;
			cWUToolStripMenuItem.Checked = radModeCWU.Checked;
			fMToolStripMenuItem.Checked = radModeFMN.Checked;
			aMToolStripMenuItem.Checked = radModeAM.Checked;
			sAMToolStripMenuItem.Checked = radModeSAM.Checked;
			sPECToolStripMenuItem.Checked = radModeSPEC.Checked;
			dIGLToolStripMenuItem.Checked = radModeDIGL.Checked;
			dIGUToolStripMenuItem.Checked = radModeDIGU.Checked;
			dRMToolStripMenuItem.Checked = radModeDRM.Checked;
			if (modePopupForm != null)
			{
				modePopupForm.RepopulateForm();
			}
			if (filterPopupForm != null)
			{
				filterPopupForm.RepopulateForm();
			}
			setSmallRX2ModeFilterLabels();
		}
	}

	public void SetRX1Filter(Filter new_filter)
	{
		if (_rx1_dsp_mode == DSPMode.FIRST || _rx1_dsp_mode == DSPMode.LAST)
		{
			return;
		}
		Filter filter = rx1_filter;
		if (filter != Filter.FIRST && filter != Filter.LAST)
		{
			rx1_filters[(int)_rx1_dsp_mode].GetLow(filter);
			rx1_filters[(int)_rx1_dsp_mode].GetHigh(filter);
		}
		int num = 0;
		int num2 = 0;
		switch (rx1_filter)
		{
		case Filter.F1:
			radFilter1.BackColor = SystemColors.Control;
			break;
		case Filter.F2:
			radFilter2.BackColor = SystemColors.Control;
			break;
		case Filter.F3:
			radFilter3.BackColor = SystemColors.Control;
			break;
		case Filter.F4:
			radFilter4.BackColor = SystemColors.Control;
			break;
		case Filter.F5:
			radFilter5.BackColor = SystemColors.Control;
			break;
		case Filter.F6:
			radFilter6.BackColor = SystemColors.Control;
			break;
		case Filter.F7:
			radFilter7.BackColor = SystemColors.Control;
			break;
		case Filter.F8:
			radFilter8.BackColor = SystemColors.Control;
			break;
		case Filter.F9:
			radFilter9.BackColor = SystemColors.Control;
			break;
		case Filter.F10:
			radFilter10.BackColor = SystemColors.Control;
			break;
		case Filter.VAR1:
			radFilterVar1.BackColor = SystemColors.Control;
			udFilterLow.Enabled = false;
			udFilterHigh.Enabled = false;
			break;
		case Filter.VAR2:
			radFilterVar2.BackColor = SystemColors.Control;
			udFilterLow.Enabled = false;
			udFilterHigh.Enabled = false;
			break;
		}
		rx1_filter = new_filter;
		num = rx1_filters[(int)_rx1_dsp_mode].GetLow(new_filter);
		num2 = rx1_filters[(int)_rx1_dsp_mode].GetHigh(new_filter);
		rx1_filters[(int)_rx1_dsp_mode].LastFilter = new_filter;
		switch (new_filter)
		{
		case Filter.F1:
			radFilter1.BackColor = button_selected_color;
			break;
		case Filter.F2:
			radFilter2.BackColor = button_selected_color;
			break;
		case Filter.F3:
			radFilter3.BackColor = button_selected_color;
			break;
		case Filter.F4:
			radFilter4.BackColor = button_selected_color;
			break;
		case Filter.F5:
			radFilter5.BackColor = button_selected_color;
			break;
		case Filter.F6:
			radFilter6.BackColor = button_selected_color;
			break;
		case Filter.F7:
			radFilter7.BackColor = button_selected_color;
			break;
		case Filter.F8:
			radFilter8.BackColor = button_selected_color;
			break;
		case Filter.F9:
			radFilter9.BackColor = button_selected_color;
			break;
		case Filter.F10:
			radFilter10.BackColor = button_selected_color;
			break;
		case Filter.VAR1:
			radFilterVar1.BackColor = button_selected_color;
			udFilterLow.Enabled = true;
			udFilterHigh.Enabled = true;
			break;
		case Filter.VAR2:
			radFilterVar2.BackColor = button_selected_color;
			udFilterLow.Enabled = true;
			udFilterHigh.Enabled = true;
			break;
		case Filter.NONE:
		{
			foreach (Control control in panelFilter.Controls)
			{
				if (control.GetType() == typeof(RadioButtonTS))
				{
					((RadioButtonTS)control).Checked = false;
					if (control.BackColor != SystemColors.Control)
					{
						((RadioButtonTS)control).BackColor = SystemColors.Control;
					}
				}
			}
			return;
		}
		}
		UpdateRX1Filters(num, num2, force: true);
		if (filterAndDspModeValid(1) && filter != rx1_filter)
		{
			FilterChangedHandlers?.Invoke(1, filter, rx1_filter, RX1Band, rx1_filters[(int)_rx1_dsp_mode].GetLow(rx1_filter), rx1_filters[(int)_rx1_dsp_mode].GetHigh(rx1_filter), rx1_filters[(int)_rx1_dsp_mode].GetName(rx1_filter));
		}
	}

	private bool filterAndDspModeValid(int rx)
	{
		switch (rx)
		{
		case 1:
			if (rx1_filter != Filter.FIRST && rx1_filter != Filter.LAST)
			{
				if (_rx1_dsp_mode != DSPMode.FIRST)
				{
					return _rx1_dsp_mode != DSPMode.LAST;
				}
				return false;
			}
			return false;
		case 2:
			if (rx2_filter != Filter.FIRST && rx2_filter != Filter.LAST)
			{
				if (_rx2_dsp_mode != DSPMode.FIRST)
				{
					return _rx2_dsp_mode != DSPMode.LAST;
				}
				return false;
			}
			return false;
		default:
			return false;
		}
	}

	private void radRX2Filter_CheckedChanged(object sender, EventArgs e)
	{
		if (sender == null || sender.GetType() != typeof(RadioButtonTS))
		{
			return;
		}
		RadioButtonTS radioButtonTS = (RadioButtonTS)sender;
		if (radioButtonTS.Checked)
		{
			switch (((RadioButtonTS)sender).Name)
			{
			case "radRX2Filter1":
				SetRX2Filter(Filter.F1);
				kToolStripMenuItem.Text = radRX2Filter1.Text;
				break;
			case "radRX2Filter2":
				SetRX2Filter(Filter.F2);
				kToolStripMenuItem1.Text = radRX2Filter2.Text;
				break;
			case "radRX2Filter3":
				SetRX2Filter(Filter.F3);
				kToolStripMenuItem2.Text = radRX2Filter3.Text;
				break;
			case "radRX2Filter4":
				SetRX2Filter(Filter.F4);
				kToolStripMenuItem3.Text = radRX2Filter4.Text;
				break;
			case "radRX2Filter5":
				SetRX2Filter(Filter.F5);
				kToolStripMenuItem4.Text = radRX2Filter5.Text;
				break;
			case "radRX2Filter6":
				SetRX2Filter(Filter.F6);
				toolStripMenuItem13.Text = radRX2Filter6.Text;
				break;
			case "radRX2Filter7":
				SetRX2Filter(Filter.F7);
				toolStripMenuItem14.Text = radRX2Filter7.Text;
				break;
			case "radRX2FilterVar1":
				SetRX2Filter(Filter.VAR1);
				break;
			case "radRX2FilterVar2":
				SetRX2Filter(Filter.VAR2);
				break;
			}
			lblRX2FilterLabel.Text = radioButtonTS.Text;
			kToolStripMenuItem.Checked = radRX2Filter1.Checked;
			kToolStripMenuItem1.Checked = radRX2Filter2.Checked;
			kToolStripMenuItem2.Checked = radRX2Filter3.Checked;
			kToolStripMenuItem3.Checked = radRX2Filter4.Checked;
			kToolStripMenuItem4.Checked = radRX2Filter5.Checked;
			toolStripMenuItem13.Checked = radRX2Filter6.Checked;
			toolStripMenuItem14.Checked = radRX2Filter7.Checked;
			if (filterPopupForm != null)
			{
				filterPopupForm.RepopulateForm();
			}
			if (e == EventArgs.Empty)
			{
				MatchTXFilterToRXFilter();
			}
		}
	}

	public void MatchTXFilterToRXFilter()
	{
		if (Common.ShiftKeyDown)
		{
			Filter tXFilter;
			switch ((!RX2Enabled || !VFOBTX) ? 1 : 2)
			{
			default:
				return;
			case 1:
				tXFilter = rx1_filter;
				break;
			case 2:
				tXFilter = rx2_filter;
				break;
			}
			SetTXFilter(tXFilter);
		}
	}

	private void radFilter_CheckedChanged(object sender, EventArgs e)
