			case "radFilter7":
				SetRX1Filter(Filter.F7);
				FilterToolStripMenuItem7.Text = radFilter7.Text;
				break;
			case "radFilter8":
				SetRX1Filter(Filter.F8);
				FilterToolStripMenuItem8.Text = radFilter8.Text;
				break;
			case "radFilter9":
				SetRX1Filter(Filter.F9);
				FilterToolStripMenuItem9.Text = radFilter9.Text;
				break;
			case "radFilter10":
				SetRX1Filter(Filter.F10);
				FilterToolStripMenuItem10.Text = radFilter10.Text;
				break;
			case "radFilterVar1":
				SetRX1Filter(Filter.VAR1);
				break;
			case "radFilterVar2":
				SetRX1Filter(Filter.VAR2);
				break;
			}
			lblFilterLabel.Text = radioButtonTS.Text;
			FilterToolStripMenuItem1.Checked = radFilter1.Checked;
			FilterToolStripMenuItem2.Checked = radFilter2.Checked;
			FilterToolStripMenuItem3.Checked = radFilter3.Checked;
			FilterToolStripMenuItem4.Checked = radFilter4.Checked;
			FilterToolStripMenuItem5.Checked = radFilter5.Checked;
			FilterToolStripMenuItem6.Checked = radFilter6.Checked;
			FilterToolStripMenuItem7.Checked = radFilter7.Checked;
			FilterToolStripMenuItem8.Checked = radFilter8.Checked;
			FilterToolStripMenuItem9.Checked = radFilter9.Checked;
			FilterToolStripMenuItem10.Checked = radFilter10.Checked;
			if (filterPopupForm != null)
			{
				filterPopupForm.RepopulateForm();
			}
			setSmallRX2ModeFilterLabels();
			if (e == EventArgs.Empty)
			{
				MatchTXFilterToRXFilter();
			}
		}
	}

	private void udFilterLow_ValueChanged(object sender, EventArgs e)
	{
		if (_filter_console_controls_force_update || udFilterLow.Focused || udFilterLow.ClientRectangle.Contains(udFilterLow.PointToClient(Control.MousePosition)))
		{
			if (udFilterLow.Value >= udFilterHigh.Value - 10m)
			{
				udFilterLow.Value = udFilterHigh.Value - 10m;
				return;
			}
			UpdateRX1Filters((int)udFilterLow.Value, (int)udFilterHigh.Value, force: false, from_change_event: true);
			if (!save_filter_changes)
			{
				rx1_filters[(int)_rx1_dsp_mode].SetLow(rx1_filter, (int)udFilterLow.Value);
			}
		}
		if (save_filter_changes && rx1_filter >= Filter.F1 && rx1_filter <= Filter.VAR2)
		{
			rx1_filters[(int)_rx1_dsp_mode].SetLow(rx1_filter, (int)udFilterLow.Value);
		}
	}

	private void udFilterHigh_ValueChanged(object sender, EventArgs e)
	{
		if (_filter_console_controls_force_update || udFilterHigh.Focused || udFilterHigh.ClientRectangle.Contains(udFilterHigh.PointToClient(Control.MousePosition)))
		{
			if (udFilterHigh.Value <= udFilterLow.Value + 10m)
			{
				udFilterHigh.Value = udFilterLow.Value + 10m;
				return;
			}
			UpdateRX1Filters((int)udFilterLow.Value, (int)udFilterHigh.Value, force: false, from_change_event: true);
			if (!save_filter_changes)
			{
				rx1_filters[(int)_rx1_dsp_mode].SetHigh(rx1_filter, (int)udFilterHigh.Value);
			}
		}
		if (save_filter_changes && rx1_filter >= Filter.F1 && rx1_filter <= Filter.VAR2)
		{
			rx1_filters[(int)_rx1_dsp_mode].SetHigh(rx1_filter, (int)udFilterHigh.Value);
		}
	}

	public bool ConstrainFilter(ref int nNewLow, ref int nNewHigh, int rx, bool filterShift = false)
	{
		DSPMode dSPMode = ((rx == 1) ? _rx1_dsp_mode : _rx2_dsp_mode);
		int num = nNewLow;
		int num2 = nNewHigh;
		switch (dSPMode)
		{
		case DSPMode.LSB:
		case DSPMode.CWL:
		case DSPMode.DIGL:
			if (nNewHigh > 0 && m_bLimitFiltersToSidebands)
			{
				if (filterShift)
				{
					nNewLow -= nNewHigh;
				}
				nNewHigh = 0;
			}
			if (nNewLow < -_max_filter_shift)
			{
				int num7 = -_max_filter_shift - nNewLow;
				nNewLow += num7;
				if (filterShift)
				{
					nNewHigh += num7;
				}
			}
			if (nNewHigh > _max_filter_shift)
			{
				int num8 = nNewHigh - _max_filter_shift;
				nNewHigh -= num8;
				if (filterShift)
				{
					nNewLow -= num8;
				}
			}
			break;
		case DSPMode.USB:
		case DSPMode.CWU:
		case DSPMode.DIGU:
			if (nNewLow < 0 && m_bLimitFiltersToSidebands)
			{
				if (filterShift)
				{
					nNewHigh += nNewLow * -1;
				}
				nNewLow = 0;
			}
			if (nNewLow < -_max_filter_shift)
			{
				int num5 = -_max_filter_shift - nNewLow;
				nNewLow += num5;
				if (filterShift)
				{
					nNewHigh += num5;
				}
			}
			if (nNewHigh > _max_filter_shift)
			{
				int num6 = nNewHigh - _max_filter_shift;
				nNewHigh -= num6;
				if (filterShift)
				{
					nNewLow -= num6;
				}
			}
			break;
		case DSPMode.DSB:
		case DSPMode.AM:
		case DSPMode.SPEC:
		case DSPMode.SAM:
			if (nNewLow > 0 && m_bLimitFiltersToSidebands)
			{
				if (filterShift)
				{
					nNewHigh -= nNewLow;
				}
				nNewLow = 0;
			}
			if (nNewHigh < 0 && m_bLimitFiltersToSidebands)
			{
				if (filterShift)
				{
					nNewLow += nNewHigh * -1;
				}
				nNewHigh = 0;
			}
			if (nNewLow < -_max_filter_shift)
			{
				int num3 = -_max_filter_shift - nNewLow;
				nNewLow += num3;
				if (filterShift)
				{
					nNewHigh += num3;
				}
			}
			if (nNewHigh > _max_filter_shift)
			{
				int num4 = nNewHigh - _max_filter_shift;
				nNewHigh -= num4;
				if (filterShift)
				{
					nNewLow -= num4;
				}
			}
			break;
		}
		if (dSPMode != DSPMode.FM)
		{
			if (nNewLow < -_max_filter_width)
			{
				nNewLow = -_max_filter_width;
			}
			if (nNewLow > _max_filter_width)
			{
				nNewLow = _max_filter_width;
			}
			if (nNewHigh > _max_filter_width)
			{
				nNewHigh = _max_filter_width;
			}
			if (nNewHigh < -_max_filter_width)
			{
				nNewHigh = -_max_filter_width;
			}
		}
		if (nNewLow == num)
		{
			return nNewHigh != num2;
		}
		return true;
	}

	private void ptbFilterShift_Scroll(object sender, EventArgs e)
	{
		if (_rx1_dsp_mode == DSPMode.DRM || _rx1_dsp_mode == DSPMode.SPEC || _rx1_dsp_mode == DSPMode.FM)
		{
			return;
		}
		_ignore_filter_shift_update = true;
		SelectRX1VarFilter();
		int num = (int)udFilterHigh.Value - (int)udFilterLow.Value;
		int num2 = 0;
		switch (_rx1_dsp_mode)
		{
		case DSPMode.USB:
			num2 = default_low_cut + num / 2;
			break;
		case DSPMode.LSB:
			num2 = -default_low_cut - num / 2;
			break;
		case DSPMode.CWU:
			num2 = cw_pitch;
			break;
		case DSPMode.CWL:
			num2 = -cw_pitch;
			break;
		case DSPMode.DIGU:
			num2 = digu_click_tune_offset;
			break;
		case DSPMode.DIGL:
			num2 = -digl_click_tune_offset;
			break;
		}
		int num3 = _max_filter_shift;
		if (num2 > 0)
		{
			if (ptbFilterShift.Value > 0)
			{
				num3 = Math.Min(_max_filter_shift, _max_filter_shift - (Math.Abs(num2) + num / 2));
			}
		}
		else if (num2 < 0)
		{
			if (ptbFilterShift.Value < 0)
			{
				num3 = Math.Min(_max_filter_shift, _max_filter_shift - (Math.Abs(num2) + num / 2));
			}
		}
		else
		{
			num3 = Math.Min(_max_filter_shift, _max_filter_shift - num / 2);
		}
		int num4 = ptbFilterShift.Maximum - ptbFilterShift.Minimum;
		int num5 = num2 + (int)((float)ptbFilterShift.Value / (float)(num4 / 2) * (float)num3);
		if (num5 == _oldFilterShiftCentre)
		{
			_ignore_filter_shift_update = false;
			return;
		}
		_oldFilterShiftCentre = num5;
		int nNewLow = num5 - num / 2;
		int nNewHigh = num5 + num / 2;
		ConstrainFilter(ref nNewLow, ref nNewHigh, 1, filterShift: true);
		UpdateRX1Filters(nNewLow, nNewHigh);
		btnFilterShiftReset.BackColor = button_selected_color;
		if (sender.GetType() == typeof(PrettyTrackBar))
		{
			ptbFilterShift.Focus();
		}
		_ignore_filter_shift_update = false;
	}

	private void ptbFilterShift_Update(int low, int high)
	{
		if (_ignore_filter_shift_update)
		{
			return;
		}
		int num = (int)udFilterHigh.Value - (int)udFilterLow.Value;
		int num2 = 0;
		int num3 = (low + high) / 2;
		switch (_rx1_dsp_mode)
		{
		case DSPMode.USB:
			num2 = default_low_cut + num / 2;
			break;
		case DSPMode.LSB:
			num2 = -default_low_cut - num / 2;
			break;
		case DSPMode.CWU:
			num2 = cw_pitch;
			break;
		case DSPMode.CWL:
			num2 = -cw_pitch;
			break;
		case DSPMode.DIGU:
			num2 = digu_click_tune_offset;
			break;
		case DSPMode.DIGL:
			num2 = -digl_click_tune_offset;
			break;
		}
		int num4 = _max_filter_shift;
		if (num2 > 0)
		{
			if (num3 > num2)
			{
				num4 = Math.Min(_max_filter_shift, _max_filter_shift - (Math.Abs(num2) + num / 2));
			}
		}
		else if (num2 < 0)
		{
			if (num3 < num2)
			{
				num4 = Math.Min(_max_filter_shift, _max_filter_shift - (Math.Abs(num2) + num / 2));
			}
		}
		else
		{
			num4 = Math.Min(_max_filter_shift, _max_filter_shift - num / 2);
		}
		int num5 = ptbFilterShift.Maximum - ptbFilterShift.Minimum;
		int num6 = (int)((float)(num3 - num2) / (float)num4 * (float)(num5 / 2));
		if (num6 > ptbFilterShift.Maximum)
		{
			num6 = ptbFilterShift.Maximum;
		}
		if (num6 < ptbFilterShift.Minimum)
		{
			num6 = ptbFilterShift.Minimum;
		}
		ptbFilterShift.Value = num6;
	}

	private void btnFilterShiftReset_Click(object sender, EventArgs e)
	{
		if (_rx1_dsp_mode != DSPMode.DRM && _rx1_dsp_mode != DSPMode.SPEC && _rx1_dsp_mode != DSPMode.FM)
		{
			ptbFilterShift.Value = 0;
			ptbFilterShift_Scroll(this, EventArgs.Empty);
			btnFilterShiftReset.BackColor = SystemColors.Control;
		}
	}

	private void ptbFilterWidth_Update(int low, int high)
	{
		int num = high - low;
		DSPMode rx1_dsp_mode = _rx1_dsp_mode;
		if (rx1_dsp_mode == DSPMode.DSB || (uint)(rx1_dsp_mode - 5) <= 1u || rx1_dsp_mode == DSPMode.SAM)
		{
			num /= 2;
		}
		int num2 = ptbFilterWidth.Maximum - ptbFilterWidth.Minimum;
		int num3 = 0;
		switch (current_filter_width_mode)
		{
		case FilterWidthMode.Linear:
			num3 = ptbFilterWidth.Minimum + (int)((float)num / (float)_max_filter_width * (float)num2);
			break;
		case FilterWidthMode.Log:
		{
			double num4 = Math.Log(ptbFilterWidth.Maximum);
			double num5 = num4 - (double)((float)num / (float)_max_filter_width) * num4;
			num3 = ptbFilterWidth.Maximum - (int)Math.Pow(Math.E, num5);
			break;
		}
		case FilterWidthMode.Log10:
		{
			double num4 = Math.Log10(ptbFilterWidth.Maximum);
			double num5 = num4 - (double)((float)num / (float)_max_filter_width) * num4;
			num3 = ptbFilterWidth.Maximum - (int)Math.Pow(10.0, num5);
			break;
		}
		}
		if (num3 > ptbFilterWidth.Maximum)
		{
			num3 = ptbFilterWidth.Maximum;
		}
		if (num3 < ptbFilterWidth.Minimum)
		{
			num3 = ptbFilterWidth.Minimum;
		}
		ptbFilterWidth.Value = num3;
	}

	private void ptbFilterWidth_Scroll(object sender, EventArgs e)
	{
		if (_rx1_dsp_mode == DSPMode.DRM || _rx1_dsp_mode == DSPMode.SPEC || _rx1_dsp_mode == DSPMode.FM)
		{
			return;
		}
		bool flag = e is MouseEventArgs e2 && e2.Delta >= 0;
		SelectRX1VarFilter(update: false, _filter_width_update_from_cat);
		int num = ptbFilterWidth.Maximum - ptbFilterWidth.Minimum;
		double num2 = 0.0;
		switch (current_filter_width_mode)
		{
		case FilterWidthMode.Linear:
			num2 = (float)(ptbFilterWidth.Value - ptbFilterWidth.Minimum) / (float)num * (float)_max_filter_width;
			break;
		case FilterWidthMode.Log:
		{
			double num3 = Math.Log(ptbFilterWidth.Maximum);
			double num4 = Math.Log(Math.Max(ptbFilterWidth.Maximum - ptbFilterWidth.Value, 1.0));
			num4 = num3 - num4;
			num2 = (float)(num4 / num3 * (double)_max_filter_width);
			break;
		}
		case FilterWidthMode.Log10:
		{
			double num3 = Math.Log10(ptbFilterWidth.Maximum);
			double num4 = Math.Log10(Math.Max(ptbFilterWidth.Maximum - ptbFilterWidth.Value, 1.0));
			num4 = num3 - num4;
			num2 = (float)(num4 / num3 * (double)_max_filter_width);
			break;
		}
		}
		num2 = (flag ? Math.Ceiling(num2 + 0.5) : Math.Ceiling(num2 - 0.5));
		int val = (int)num2;
		val = Math.Max(val, 10);
		int num5 = rx1_filters[(int)_rx1_dsp_mode].GetBW(rx1_filter);
		switch (_rx1_dsp_mode)
		{
		case DSPMode.DSB:
		case DSPMode.FM:
		case DSPMode.AM:
		case DSPMode.SPEC:
		case DSPMode.SAM:
		case DSPMode.DRM:
			num5 /= 2;
			break;
		}
		if (val == num5)
		{
			SelectRX1VarFilter(update: true, _filter_width_update_from_cat);
			return;
		}
		int num6 = ((int)udFilterLow.Value + (int)udFilterHigh.Value) / 2;
		int nNewLow = 0;
		int nNewHigh = 0;
		switch (_rx1_dsp_mode)
		{
		case DSPMode.DSB:
		case DSPMode.FM:
		case DSPMode.AM:
		case DSPMode.SAM:
			nNewLow = num6 - val;
			nNewHigh = num6 + val;
			break;
		case DSPMode.LSB:
			nNewHigh = -default_low_cut;
			nNewLow = nNewHigh - val;
			break;
		case DSPMode.CWL:
		case DSPMode.DIGL:
			nNewLow = num6 - val / 2;
			nNewHigh = num6 + val / 2;
			break;
		case DSPMode.USB:
			nNewLow = default_low_cut;
			nNewHigh = nNewLow + val;
			break;
		case DSPMode.CWU:
		case DSPMode.DIGU:
			nNewLow = num6 - val / 2;
			nNewHigh = num6 + val / 2;
			break;
		}
		ConstrainFilter(ref nNewLow, ref nNewHigh, 1, filterShift: true);
		UpdateRX1Filters(nNewLow, nNewHigh);
		if (sender.GetType() == typeof(PrettyTrackBar))
		{
			ptbFilterWidth.Focus();
		}
	}

