	private void btnVFOAtoB_Click(object sender, EventArgs e)
	{
		if (rx2_enabled)
		{
			RX2DSPMode = _rx1_dsp_mode;
			VFOBFreq = VFOAFreq;
			switch (rx1_filter)
			{
			case Filter.F8:
			case Filter.F9:
			case Filter.F10:
				RX2Filter = Filter.F1;
				break;
			case Filter.VAR1:
			case Filter.VAR2:
				RX2Filter = RX1Filter;
				RX2FilterLow = RX1FilterLow;
				RX2FilterHigh = RX2FilterHigh;
				break;
			default:
				RX2Filter = rx1_filter;
				break;
			}
			vfob_dsp_mode = _rx1_dsp_mode;
			vfob_filter = rx1_filter;
			comboRX2AGC.Text = comboAGC.Text;
		}
		else
		{
			VFOBFreq = VFOAFreq;
			vfob_dsp_mode = _rx1_dsp_mode;
			vfob_filter = rx1_filter;
		}
	}

