	{
		btnVFOBtoA_Click(this, EventArgs.Empty);
	}

	private void btnVFOBtoA_Click(object sender, EventArgs e)
	{
		if (!rx2_enabled)
		{
			if (!chkEnableMultiRX.Checked)
			{
				RX1DSPMode = vfob_dsp_mode;
				RX1Filter = vfob_filter;
			}
			VFOAFreq = VFOBFreq;
			return;
		}
		RX1DSPMode = _rx2_dsp_mode;
		VFOAFreq = VFOBFreq;
		Filter filter = rx2_filter;
		if ((uint)(filter - 10) <= 1u)
		{
			RX1Filter = RX2Filter;
			RX1FilterLow = RX2FilterLow;
			RX1FilterHigh = RX2FilterHigh;
		}
		else
		{
			RX1Filter = RX2Filter;
		}
		comboAGC.Text = comboRX2AGC.Text;
	}

	public void VFOSwap()
	{
		btnVFOSwap_Click(this, EventArgs.Empty);
	}

	private void btnVFOSwap_Click(object sender, EventArgs e)
	{
		if (!rx2_enabled)
		{
			double vFOAFreq = VFOAFreq;
			if (!chkEnableMultiRX.Checked)
			{
				DSPMode rx1_dsp_mode = _rx1_dsp_mode;
				Filter filter = rx1_filter;
				RX1DSPMode = vfob_dsp_mode;
				RX1Filter = vfob_filter;
				vfob_dsp_mode = rx1_dsp_mode;
				vfob_filter = filter;
			}
			VFOAFreq = VFOBFreq;
			VFOBFreq = vFOAFreq;
			return;
		}
		double vFOAFreq2 = VFOAFreq;
		DSPMode rx1_dsp_mode2 = _rx1_dsp_mode;
		Filter filter2 = rx1_filter;
		int rX2FilterLow = 0;
		int rX2FilterHigh = 0;
		if (filter2 == Filter.VAR1 || filter2 == Filter.VAR2)
		{
			rX2FilterLow = RX1FilterLow;
			rX2FilterHigh = RX1FilterHigh;
		}
		RX1DSPMode = _rx2_dsp_mode;
		VFOAFreq = VFOBFreq;
		RX1Filter = rx2_filter;
		RX2DSPMode = rx1_dsp_mode2;
		VFOBFreq = vFOAFreq2;
		switch (filter2)
		{
		case Filter.F8:
		case Filter.F9:
		case Filter.F10:
			RX2Filter = Filter.F1;
			break;
		case Filter.VAR1:
		case Filter.VAR2:
			RX2Filter = filter2;
			RX2FilterLow = rX2FilterLow;
			RX2FilterHigh = rX2FilterHigh;
			break;
		default:
			RX2Filter = filter2;
			break;
		}
		string text = comboAGC.Text;
		comboAGC.Text = comboRX2AGC.Text;
		comboRX2AGC.Text = text;
	}

	private void UpdateVFOASub()
	{
		bool flag = false;
		double vFOASubFreq = VFOASubFreq;
		if (rx2_enabled)
		{
			if (chkVFOSplit.Checked)
			{
				txtVFOABand.Font = new Font("Microsoft Sans Sarif", 14f, FontStyle.Regular);
				VFOASubFreq = saved_vfoa_sub_freq;
				tx_xvtr_index = XVTRForm.XVTRFreq(VFOASubFreq);
				TXBand = BandByFreq(VFOASubFreq, tx_xvtr_index, current_region);
				if (chkPower.Checked)
				{
					txtVFOABand.ForeColor = Color.Red;
				}
				else
				{
					txtVFOABand.ForeColor = Color.DarkRed;
				}
				txtVFOABand.TextAlign = HorizontalAlignment.Right;
				txtVFOABand.ReadOnly = false;
				txtVFOABand_LostFocus(this, EventArgs.Empty);
				panelVFOASubHover.Visible = true;
				flag = true;
			}
			else if (chkEnableMultiRX.Checked)
			{
				txtVFOABand.Font = new Font("Microsoft Sans Sarif", 14f, FontStyle.Regular);
				VFOASubFreq = saved_vfoa_sub_freq;
				if (chkPower.Checked)
				{
					txtVFOABand.ForeColor = vfo_text_light_color;
				}
				else
				{
					txtVFOABand.ForeColor = vfo_text_dark_color;
				}
				txtVFOABand.TextAlign = HorizontalAlignment.Right;
				txtVFOABand.ReadOnly = false;
				txtVFOABand_LostFocus(this, EventArgs.Empty);
				panelVFOASubHover.Visible = true;
				flag = true;
			}
		}
		if (!flag)
		{
			if (chkPower.Checked)
			{
				txtVFOABand.Font = new Font("Microsoft Sans Sarif", 12f, FontStyle.Regular);
				txtVFOABand.ForeColor = band_text_light_color;
				txtVFOABand.TextAlign = HorizontalAlignment.Center;
				txtVFOAFreq_LostFocus(this, EventArgs.Empty);
				panelVFOASubHover.Visible = false;
			}
			else
			{
				txtVFOABand.Font = new Font("Microsoft Sans Sarif", 12f, FontStyle.Regular);
				txtVFOABand.ForeColor = band_text_dark_color;
				txtVFOABand.TextAlign = HorizontalAlignment.Center;
				txtVFOAFreq_LostFocus(this, EventArgs.Empty);
				panelVFOASubHover.Visible = false;
			}
		}
		double num = Math.Round(vFOASubFreq, 6);
		if (num != VFOASubFreq)
		{
			Band oldBand = BandByFreq(XVTRForm.TranslateFreq(vFOASubFreq), rx1_xvtr_index, current_region);
			Band newBand = BandByFreq(XVTRForm.TranslateFreq(VFOASubFreq), rx1_xvtr_index, current_region);
			VFOASubFrequencyChangeHandlers?.Invoke(oldBand, newBand, RX1DSPMode, RX1Filter, num, VFOASubFreq, CentreFrequency, ClickTuneDisplay, ptbDisplayZoom.Value, radio.GetDSPRX(0, 1).RXOsc, 1);
		}
	}

