	public void SetQuickSplit()
	{
		if (_ignoreQuickSplitSet)
		{
			return;
		}
		_ignoreQuickSplitSet = true;
		bool quickSplitState = _quickSplitState;
		bool flag = false;
		if (!IsSetupFormNull && SetupForm.QuickSplitEnabled && !RX2Enabled)
		{
			if (chkVFOSplit.Checked)
			{
				if (_oldQuickSplitSettings == null)
				{
					_oldQuickSplitSettings = new Dictionary<string, object>();
					_oldQuickSplitSettings.Add("zoom", Zoom);
					_oldQuickSplitSettings.Add("multirx", chkEnableMultiRX.Checked);
					_oldQuickSplitSettings.Add("txfl", chkShowTXFilter.Checked);
					_oldQuickSplitSettings.Add("swapwheels", Midi2Cat.SwapVFOWheelsProperty);
					if (RX2Enabled)
					{
						_oldQuickSplitSettings.Add("VFOASubFreq", VFOASubFreq);
					}
					else
					{
						_oldQuickSplitSettings.Add("VFOBFreq", VFOBFreq);
					}
					_oldQuickSplitSettings.Add("panmain", PanMainRX);
					_oldQuickSplitSettings.Add("pansub", PanSubRX);
					_oldQuickSplitSettings.Add("vfosync", VFOSync);
				}
				double num = (double)SetupForm.QuickSplitShiftHz * 1E-06;
				if (VFOSync)
				{
					VFOSync = false;
				}
				VFOBFreq = VFOAFreq + num;
				if (SetupForm.QuickSplitZoom && Zoom != 190)
				{
					Zoom = 190;
				}
				if (SetupForm.QuickSplitMultiRX && !chkEnableMultiRX.Checked)
				{
					chkEnableMultiRX.Checked = true;
				}
				if (SetupForm.QuickSplitFL && !chkShowTXFilter.Checked)
				{
					chkShowTXFilter.Checked = true;
				}
				if (SetupForm.QuickSplitSwapVFOWheels && !Midi2Cat.SwapVFOWheelsProperty)
				{
					Midi2Cat.SwapVFOWheelsProperty = true;
				}
				if (SetupForm.QuickSplitPanAudio)
				{
					if (!SetupForm.QuickSplitPanAudioFlip)
					{
						PanMainRX = 0;
						PanSubRX = 100;
					}
					else
					{
						PanMainRX = 100;
						PanSubRX = 0;
					}
				}
			}
			else
			{
				flag = true;
			}
			_quickSplitState = true;
			chkVFOSplit.Text = "QPLT";
		}
		else
		{
			_quickSplitState = false;
			flag = true;
			chkVFOSplit.Text = "SPLT";
		}
		if (flag && _oldQuickSplitSettings != null)
		{
			if (_oldQuickSplitSettings.ContainsKey("zoom"))
			{
				Zoom = (int)_oldQuickSplitSettings["zoom"];
			}
			if (_oldQuickSplitSettings.ContainsKey("multirx"))
			{
				chkEnableMultiRX.Checked = (bool)_oldQuickSplitSettings["multirx"];
			}
			if (_oldQuickSplitSettings.ContainsKey("txfl"))
			{
				chkShowTXFilter.Checked = (bool)_oldQuickSplitSettings["txfl"];
			}
			if (_oldQuickSplitSettings.ContainsKey("swapwheels"))
			{
				Midi2Cat.SwapVFOWheelsProperty = (bool)_oldQuickSplitSettings["swapwheels"];
			}
			if (_oldQuickSplitSettings.ContainsKey("VFOASubFreq"))
			{
				VFOASubFreq = (double)_oldQuickSplitSettings["VFOASubFreq"];
			}
			if (_oldQuickSplitSettings.ContainsKey("VFOBFreq"))
			{
				VFOBFreq = (double)_oldQuickSplitSettings["VFOBFreq"];
			}
			if (_oldQuickSplitSettings.ContainsKey("panmain"))
			{
				PanMainRX = (int)_oldQuickSplitSettings["panmain"];
			}
			if (_oldQuickSplitSettings.ContainsKey("pansub"))
			{
				PanSubRX = (int)_oldQuickSplitSettings["pansub"];
			}
			if (_oldQuickSplitSettings.ContainsKey("vfosync"))
			{
				VFOSync = (bool)_oldQuickSplitSettings["vfosync"];
			}
			_oldQuickSplitSettings.Clear();
			_oldQuickSplitSettings = null;
		}
		if (quickSplitState != _quickSplitState)
		{
			QuickSplitChangedHandlers?.Invoke(quickSplitState, _quickSplitState);
		}
		_ignoreQuickSplitSet = false;
	}

