	private void setRIT_LEDs()
	{
		int num = -2000;
		int num2 = 2000;
		double num3 = 1.0 / 14.0;
		double num4 = 0.5 - num3;
		double num5 = 0.5 + num3;
		double num6 = Convert.ToDouble(udRIT.Value - (decimal)num) / Convert.ToDouble(num2 - num);
		if (udRIT.Value < 0m && num6 >= num4)
		{
			num6 = num4;
		}
		else if (udRIT.Value > 0m && num6 <= num5)
		{
			num6 = num5;
		}
		if (udRIT.Value <= (decimal)num + Convert.ToDecimal(num3 * (double)num2))
		{
			num6 = num3;
		}
		Midi2Cat.SendUpdateToMidi(CatCmd.RIT_inc, num6);
	}

	private void setXIT_LEDs()
	{
		int num = -2000;
		int num2 = 2000;
		double num3 = 1.0 / 14.0;
		double num4 = 0.5 - num3;
		double num5 = 0.5 + num3;
		double num6 = Convert.ToDouble(udXIT.Value - (decimal)num) / Convert.ToDouble(num2 - num);
		if (udXIT.Value < 0m && num6 >= num4)
		{
			num6 = num4;
		}
		else if (udXIT.Value > 0m && num6 <= num5)
		{
			num6 = num5;
		}
		if (udXIT.Value <= (decimal)num + Convert.ToDecimal(num3 * (double)num2))
		{
			num6 = num3;
		}
		Midi2Cat.SendUpdateToMidi(CatCmd.XIT_inc, num6);
	}

	private void btnZeroBeat_Click(object sender, EventArgs e)
	{
		if (!PowerOn)
		{
			return;
		}
		int num = FindPeakFreqInPassband();
		if (num == -1)
		{
			return;
		}
		int num2 = 0;
		switch (_rx1_dsp_mode)
		{
		case DSPMode.LSB:
		case DSPMode.USB:
		case DSPMode.CWL:
		case DSPMode.CWU:
		{
			int num3 = CWPitch;
			if (_rx1_dsp_mode == DSPMode.CWL || _rx1_dsp_mode == DSPMode.LSB)
			{
				num3 = -num3;
			}
			if ((decimal)num3 >= udFilterLow.Value && (decimal)num3 <= udFilterHigh.Value)
			{
				num2 = num - num3;
				break;
			}
			int num6 = ((int)udFilterHigh.Value + (int)udFilterLow.Value) / 2;
			num2 = num - num6;
			break;
		}
		case DSPMode.DIGL:
		{
			int num3 = -digl_click_tune_offset;
			if ((decimal)num3 >= udFilterLow.Value && (decimal)num3 <= udFilterHigh.Value)
			{
				num2 = num - num3;
				break;
			}
			int num5 = ((int)udFilterHigh.Value + (int)udFilterLow.Value) / 2;
			num2 = num - num5;
			break;
		}
		case DSPMode.DIGU:
		{
			int num3 = digu_click_tune_offset;
			if ((decimal)num3 >= udFilterLow.Value && (decimal)num3 <= udFilterHigh.Value)
			{
				num2 = num - num3;
				break;
			}
			int num4 = ((int)udFilterHigh.Value + (int)udFilterLow.Value) / 2;
			num2 = num - num4;
			break;
		}
		case DSPMode.FM:
		case DSPMode.AM:
		case DSPMode.SAM:
			num2 = num;
			break;
		}
		if (zero_beat_rit)
		{
			udRIT.Value += (decimal)num2;
			chkRIT.Checked = true;
		}
		else
		{
			VFOAFreq += (double)num2 * 1E-06;
		}
	}

	private unsafe int FindPeakFreqInPassband()
	{
		lock (_findPeakLock)
		{
			int num = (int)udFilterLow.Value;
			int num2 = (int)udFilterHigh.Value;
			double num3 = (double)sample_rate_rx1 / (double)specRX.GetSpecRX(0).FFTSize;
			int num4 = specRX.GetSpecRX(0).FFTSize / 2;
			if (_click_tune_display)
			{
				double num5 = (VFOAFreq - CentreFrequency) * 1000000.0 / num3;
				num4 += (int)num5;
			}
			int num6 = (int)((double)num / num3) + num4;
			int num7 = (int)((double)num2 / num3) + num4;
			if (num6 < 0 || num7 > specRX.GetSpecRX(0).FFTSize - 1)
			{
				return -1;
			}
			double num8 = double.MinValue;
			double num9 = double.MaxValue;
			int num10 = 0;
			int ss = 0;
			double[,] array = new double[specRX.GetSpecRX(0).FFTSize, 2];
			if (array == null)
			{
				_spectrum_mutex.ReleaseMutex();
				return -1;
			}
			int flag = 0;
			_spectrum_mutex.WaitOne();
			fixed (double* snap_buff = &array[0, 0])
			{
				SpecHPSDRDLL.SnapSpectrumTimeout(0, ss, 0, snap_buff, (uint)(1000f / (float)_display_fps * 10f), ref flag);
			}
			_spectrum_mutex.ReleaseMutex();
			if (flag == 0)
			{
				return -1;
			}
			int fFTSize = specRX.GetSpecRX(0).FFTSize;
			double[] array2 = new double[num7 - num6 + 1];
			for (int i = num6; i <= num7; i++)
			{
				double num11 = array[i, 0] * array[i, 0] + array[i, 1] * array[i, 1];
				if (num11 > num8)
				{
					num10 = i;
					num8 = num11;
				}
				if (num11 < num9)
				{
					num9 = num11;
				}
				array2[i - num6] = 10.0 * Math.Log10(num11 / Math.Pow(fFTSize, 2.0));
			}
			return (int)((double)(num10 - num4) * num3);
		}
	}

	private void btnIFtoVFO_Click(object sender, EventArgs e)
	{
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		if (ptbFilterShift.Value == 0)
		{
			return;
		}
		switch (RX1DSPMode)
		{
		default:
			return;
		case DSPMode.DIGU:
		case DSPMode.SPEC:
		case DSPMode.DIGL:
		case DSPMode.DRM:
			return;
		case DSPMode.DSB:
		case DSPMode.FM:
		case DSPMode.AM:
		case DSPMode.SAM:
			flag = true;
			break;
		case DSPMode.CWL:
			flag2 = true;
			flag3 = true;
			break;
		case DSPMode.CWU:
			flag2 = true;
			break;
		case DSPMode.LSB:
			flag3 = true;
			break;
		case DSPMode.USB:
			break;
		}
		int num = (int)udFilterHigh.Value - (int)udFilterLow.Value;
		int num2 = (int)udFilterLow.Value + num / 2;
		double num3 = 0.0;
		int num4 = 0;
		int num5 = 0;
		if (flag)
		{
			num3 = VFOAFreq + (double)num2 / 1000000.0;
			num4 = -(num / 2);
			num5 = num / 2;
		}
		else
		{
			int num6 = ((!flag2) ? (default_low_cut + num / 2) : cw_pitch);
			if (flag3)
			{
				num6 = -num6;
			}
			num3 = VFOAFreq + (double)(num2 - num6) / 1000000.0;
			num4 = num6 - num / 2;
			num5 = num6 + num / 2;
		}
		if (VFOAFreq > num3)
		{
			udFilterHigh.Value = num5;
			udFilterLow.Value = num4;
		}
		else
		{
			udFilterLow.Value = num4;
			udFilterHigh.Value = num5;
		}
		VFOAFreq = num3;
		btnFilterShiftReset_Click(this, EventArgs.Empty);
	}

