	private void ptbRX0Gain_Scroll(object sender, EventArgs e)
	{
		lblRX1Vol.Text = "Vol";
		if (!initializing && e != EventArgs.Empty && m_bRXAFSlidersWillUnmute && chkMUT.Checked)
		{
			chkMUT.Checked = false;
		}
		if (chkMUT.Checked && m_bMuteWillMuteVAC1)
		{
			radio.GetDSPRX(0, 0).RXOutputGain = 0.0;
		}
		else
		{
			radio.GetDSPRX(0, 0).RXOutputGain = (double)ptbRX0Gain.Value / (double)ptbRX0Gain.Maximum;
		}
		ptbRX1AF.Value = ptbRX0Gain.Value;
		lblRX1AF.Text = "RX1 AF:  " + ptbRX0Gain.Value;
		setLinkedAF(1, ptbRX1AF.Value);
		if (sender.GetType() == typeof(PrettyTrackBar))
		{
			ptbRX0Gain.Focus();
		}
		double pct = Convert.ToDouble(ptbRX1AF.Value - ptbRX1AF.Minimum) / Convert.ToDouble(ptbRX1AF.Maximum - ptbRX1AF.Minimum);
		Midi2Cat.SendUpdateToMidi(CatCmd.VolumeVfoA_inc, pct);
		if (sliderForm != null)
		{
			sliderForm.RX1Gain = ptbRX0Gain.Value;
		}
		int value = ptbRX0Gain.Value;
		if (value != _old_rx1_gain)
		{
			RXGainChangedHandlers?.Invoke(1, is_subrx: false, _old_rx1_gain, value);
			_old_rx1_gain = value;
		}
	}

	private void ptbRX1Gain_Scroll(object sender, EventArgs e)
	{
		if (!initializing && e != EventArgs.Empty && m_bRXAFSlidersWillUnmute && chkMUT.Checked)
		{
			chkMUT.Checked = false;
		}
		if (chkMUT.Checked && m_bMuteWillMuteVAC1)
		{
			radio.GetDSPRX(0, 1).RXOutputGain = 0.0;
		}
		else
		{
			radio.GetDSPRX(0, 1).RXOutputGain = (double)ptbRX1Gain.Value / (double)ptbRX1Gain.Maximum;
		}
		setLinkedAF(2, ptbRX1Gain.Value);
		ptbRX1Gain.Focus();
		if (sliderForm != null)
		{
			sliderForm.SubRXGain = ptbRX1Gain.Value;
		}
		int value = ptbRX1Gain.Value;
		if (value != _old_rx1sub_gain)
		{
			RXGainChangedHandlers?.Invoke(1, is_subrx: true, _old_rx1sub_gain, value);
			_old_rx1sub_gain = value;
		}
	}

