	private void chkRX2_CheckedChanged(object sender, EventArgs e)
	{
		_pause_DisplayThread = true;
		bool old_rx2_checked = _old_rx2_checked;
		if (old_rx2_checked != chkRX2.Checked)
		{
			NetworkIO.NotifyRxReconfig();
		}
		if (old_rx2_checked != chkRX2.Checked)
		{
			RX2EnabledPreChangedHandlers?.Invoke(chkRX2.Checked);
		}
		RX2Enabled = chkRX2.Checked;
		if (RX2Enabled && !IsSetupFormNull && old_rx2_checked != chkRX2.Checked)
		{
			bool flag = (SetupForm.GetVACEnabledBitfield() & 2) != 0;
			chkVAC2.Checked = flag;
		}
		if (chkVFOBTX.Checked && chkVAC2.Checked && chkRX2.Checked)
		{
			ptbVACRXGain.Value = vac2_rx_gain;
			ptbVACRXGain_Scroll(this, EventArgs.Empty);
			ptbVACTXGain.Value = vac2_tx_gain;
			ptbVACTXGain_Scroll(this, EventArgs.Empty);
			comboVACSampleRate.Text = vac2_sample_rate;
			chkVACStereo.Checked = vac2_stereo;
		}
		else
		{
			ptbVACRXGain.Value = vac_rx_gain;
			ptbVACRXGain_Scroll(this, EventArgs.Empty);
			ptbVACTXGain.Value = vac_tx_gain;
			ptbVACTXGain_Scroll(this, EventArgs.Empty);
			comboVACSampleRate.Text = vac_sample_rate;
			chkVACStereo.Checked = vac_stereo;
		}
		if (chkRX2.Checked)
		{
			chkRX2.BackColor = button_selected_color;
			chkRX2DisplayAVG_CheckedChanged(this, EventArgs.Empty);
		}
		else
		{
			chkRX2.BackColor = SystemColors.Control;
			if (chkVAC2.Checked)
			{
				chkVAC2.Checked = false;
			}
		}
		if (update_rx2_display)
		{
			if (chkRX2.Checked)
			{
				if (base.Height <= MinimumSize.Height + panelRX2Filter.Height + 8)
				{
					base.Height += panelRX2Filter.Height + 8;
				}
				console_basis_size.Height += panelRX2Filter.Height + 8;
			}
			else
			{
				if (base.Height <= MinimumSize.Height + panelRX2Filter.Height + 8)
				{
					base.Height -= panelRX2Filter.Height + 8;
				}
				console_basis_size.Height -= panelRX2Filter.Height + 8;
			}
			Console_Resize(this, EventArgs.Empty);
		}
		update_rx2_display = true;
		Display.RebuildLinearGradientBrushRX = true;
		if (RX2Enabled)
		{
			Display.FastAttackNoiseFloorRX2 = true;
		}
		if (rx2_enabled)
		{
			txtVFOBFreq_LostFocus(this, EventArgs.Empty);
		}
		setSmallRX2ModeFilterLabels();
		setupZTBButton();
		SetupInfoBarButton(ucInfoBar.ActionTypes.ActivePeaks, Display.SpectralPeakHoldRX1 || (RX2Enabled && Display.SpectralPeakHoldRX2));
		if (!m_bResizeDX2Display && old_rx2_checked != RX2Enabled)
		{
			m_bResizeDX2Display = true;
		}
		_pause_DisplayThread = false;
		if (old_rx2_checked != RX2Enabled)
		{
			SetQuickSplit();
			RX2EnabledChangedHandlers?.Invoke(RX2Enabled);
			_old_rx2_checked = chkRX2.Checked;
		}
	}

	private void setSmallRX2ModeFilterLabels()
	{
		if ((chkEnableMultiRX.Checked && !rx2_enabled) || !rx2_enabled)
		{
			if (_rx1_dsp_mode != DSPMode.FIRST && _rx1_dsp_mode != DSPMode.LAST && rx1_filter != Filter.FIRST && rx1_filter != Filter.LAST)
			{
				string text = _rx1_dsp_mode.ToString().ToUpper();
				string name = rx1_filters[(int)_rx1_dsp_mode].GetName(rx1_filter);
				lblRX2ModeLabel.Text = text;
				lblRX2ModeBigLabel.Text = text;
				lblRX2FilterLabel.Text = name;
			}
		}
		else if (_rx2_dsp_mode != DSPMode.FIRST && _rx2_dsp_mode != DSPMode.LAST && rx2_filter != Filter.FIRST && rx2_filter != Filter.LAST)
		{
			string text2 = _rx2_dsp_mode.ToString().ToUpper();
			string name2 = rx2_filters[(int)_rx2_dsp_mode].GetName(rx2_filter);
			lblRX2ModeLabel.Text = text2;
			lblRX2ModeBigLabel.Text = text2;
			lblRX2FilterLabel.Text = name2;
		}
	}

	private void chkRX2SR_CheckedChanged(object sender, EventArgs e)
	{
		if (chkRX2SR.Checked)
		{
			chkRX2SR.BackColor = button_selected_color;
		}
		else
		{
			chkRX2SR.BackColor = SystemColors.Control;
		}
		DisplayDuplex = chkRX2SR.Checked;
		Display.DisplayDuplex = chkRX2SR.Checked;
		if (path_Illustrator != null)
		{
			path_Illustrator.pi_Changed();
		}
		updateVFOFreqs(_mox);
		if (_old_duplex_state != chkRX2SR.Checked)
		{
			DuplexChangedHandlers?.Invoke(1, _old_duplex_state, chkRX2SR.Checked);
			_old_duplex_state = chkRX2SR.Checked;
		}
	}

	private void panelVFOASubHover_Paint(object sender, PaintEventArgs e)
	{
		if (rx2_enabled && (chkEnableMultiRX.Checked || chkVFOSplit.Checked) && vfoa_sub_hover_digit >= 0)
		{
			int num = 0;
			int num2 = 0;
			num += (vfo_sub_char_width + vfo_sub_char_space) * vfoa_sub_hover_digit;
			if (vfoa_sub_hover_digit > 3)
			{
				num += vfo_sub_decimal_space - vfo_sub_char_space;
			}
			num2 = num + vfo_sub_char_width;
			e.Graphics.DrawLine(new Pen(txtVFOABand.ForeColor, 2f), num, 1, num2, 1);
		}
	}

	private void panelVFOASubHover_MouseMove(object sender, MouseEventArgs e)
	{
		if (rx2_enabled && (chkEnableMultiRX.Checked || chkVFOSplit.Checked))
		{
			Control control = (Control)sender;
			Control control2 = txtVFOABand;
			int num = control.Size.Width - control.ClientSize.Width + (control2.Size.Width - control2.ClientSize.Width);
			int num2 = control.Size.Height - control.ClientSize.Height + (control2.Size.Height - control2.ClientSize.Height);
			int num3 = control.Left - control2.Left - num / 2;
			int num4 = control.Top - control2.Top - num2 / 2;
			txtVFOABand_MouseMove(sender, new MouseEventArgs(e.Button, e.Clicks, e.X + num3, e.Y + num4, e.Delta));
		}
	}

	private void txtVFOABand_MouseMove(object sender, MouseEventArgs e)
	{
		if (!rx2_enabled || (!chkEnableMultiRX.Checked && !chkVFOSplit.Checked) || !chkPower.Checked)
		{
			return;
		}
		panelVFOASubHover.Visible = true;
		if (base.ContainsFocus)
		{
			int num = vfoa_sub_hover_digit;
			int num2 = 0;
			if (vfo_sub_char_width == 0)
			{
				GetVFOSubCharWidth();
			}
			int num3;
			for (num3 = txtVFOABand.Width - (vfo_sub_pixel_offset - 5); num3 < e.X; num3 = ((num2 != 3) ? (num3 + vfo_sub_char_space) : (num3 + vfo_sub_decimal_space)))
			{
				num2++;
				num3 += vfo_sub_char_width;
			}
			if (num2 < 3)
			{
				num2 = -1;
			}
			if (num2 > 9)
			{
				num2 = 9;
			}
			vfoa_sub_hover_digit = num2;
			if (vfoa_sub_hover_digit != num)
			{
				panelVFOASubHover.Invalidate();
			}
		}
	}

	private void txtVFOABand_MouseLeave(object sender, EventArgs e)
	{
		vfoa_sub_hover_digit = -1;
		panelVFOASubHover.Invalidate();
	}

	private void SetRX2Mode(DSPMode new_mode)
	{
		if (new_mode == DSPMode.FIRST || new_mode == DSPMode.LAST)
		{
			return;
		}
		Band rX2Band = RX2Band;
		DSPMode rx2_dsp_mode = _rx2_dsp_mode;
		WDSP.SetChannelState(WDSP.id(2u, 0u), 0, 1);
		if (new_mode == DSPMode.FM)
		{
			WDSP.SetDSPSamplerate(WDSP.id(2u, 0u), 192000);
		}
		else
		{
			WDSP.SetDSPSamplerate(WDSP.id(2u, 0u), 48000);
		}
		radio.GetDSPRX(1, 0).DSPMode = new_mode;
		if (rx2_enabled && chkVFOBTX.Checked)
		{
			Audio.TXDSPMode = new_mode;
			radio.GetDSPTX(0).CurrentDSPMode = new_mode;
		}
		Display.RX2DSPMode = new_mode;
		RadioDSP.RX2DSPMode = new_mode;
		if (new_mode == DSPMode.CWL || new_mode == DSPMode.CWU)
		{
			WDSP.SetChannelTDelayUp(WDSP.id(2u, 0u), 0.005);
			WDSP.SetChannelTDelayUp(WDSP.id(2u, 1u), 0.005);
			WDSP.SetChannelTSlewUp(WDSP.id(2u, 0u), 0.01);
			WDSP.SetChannelTSlewUp(WDSP.id(2u, 1u), 0.01);
			WDSP.SetChannelTDelayDown(WDSP.id(2u, 0u), 0.0);
			WDSP.SetChannelTDelayDown(WDSP.id(2u, 1u), 0.0);
			WDSP.SetChannelTSlewDown(WDSP.id(2u, 0u), 0.005);
			WDSP.SetChannelTSlewDown(WDSP.id(2u, 1u), 0.005);
		}
		else
		{
			WDSP.SetChannelTDelayUp(WDSP.id(2u, 0u), 0.0);
			WDSP.SetChannelTDelayUp(WDSP.id(2u, 1u), 0.0);
			WDSP.SetChannelTSlewUp(WDSP.id(2u, 0u), 0.01);
			WDSP.SetChannelTSlewUp(WDSP.id(2u, 1u), 0.01);
			WDSP.SetChannelTDelayDown(WDSP.id(2u, 0u), 0.0);
			WDSP.SetChannelTDelayDown(WDSP.id(2u, 1u), 0.0);
			WDSP.SetChannelTSlewDown(WDSP.id(2u, 0u), 0.01);
			WDSP.SetChannelTSlewDown(WDSP.id(2u, 1u), 0.01);
		}
		double num = VFOBFreq;
		_ = radio.GetDSPTX(0).TXOsc;
		switch (rx2_dsp_mode)
		{
		case DSPMode.LSB:
			radRX2ModeLSB.BackColor = SystemColors.Control;
			break;
		case DSPMode.USB:
			radRX2ModeUSB.BackColor = SystemColors.Control;
			break;
		case DSPMode.DSB:
			radRX2ModeDSB.BackColor = SystemColors.Control;
			break;
		case DSPMode.CWL:
			radRX2ModeCWL.BackColor = SystemColors.Control;
			if (!RX2IsIn60mChannel())
			{
				switch (new_mode)
				{
				case DSPMode.USB:
					num -= (double)cw_pitch * 1E-06;
					break;
				default:
					num += (double)cw_pitch * 1E-06;
					break;
				case DSPMode.CWU:
					break;
				}
				setVFOBFreqNoUpdate(num);
			}
			radio.GetDSPRX(1, 0).RXAPFRun = false;
			SetupForm.EnableRX2APFControl = false;
			lblRX2APF.Hide();
			break;
		case DSPMode.CWU:
			radRX2ModeCWU.BackColor = SystemColors.Control;
			if (!RX2IsIn60mChannel())
			{
				switch (new_mode)
				{
				case DSPMode.LSB:
					num += (double)cw_pitch * 1E-06;
					break;
				default:
					num -= (double)cw_pitch * 1E-06;
					break;
				case DSPMode.CWL:
					break;
				}
				setVFOBFreqNoUpdate(num);
			}
			radio.GetDSPRX(1, 0).RXAPFRun = false;
			SetupForm.EnableRX2APFControl = false;
			lblRX2APF.Hide();
			break;
		case DSPMode.FM:
			radRX2ModeFMN.BackColor = SystemColors.Control;
			if (rx2_enabled)
			{
				if (new_mode != DSPMode.AM && new_mode != DSPMode.SAM && new_mode != DSPMode.FM)
				{
					if (chkVFOBTX.Checked)
					{
						chkMON.Enabled = true;
					}
					chkRX2BIN.Enabled = true;
				}
				if (chkVFOBTX.Checked)
				{
					ptbMic_Scroll(this, EventArgs.Empty);
				}
			}
			if (new_mode != DSPMode.DRM)
			{
				EnableAllRX2Filters();
			}
			handleSqlFM(2, bFM: false);
			break;
		case DSPMode.AM:
			radRX2ModeAM.BackColor = SystemColors.Control;
			if (rx2_enabled)
			{
				if (new_mode != DSPMode.AM && new_mode != DSPMode.SAM && new_mode != DSPMode.FM)
				{
					if (chkVFOBTX.Checked)
					{
						chkMON.Enabled = true;
					}
					chkRX2BIN.Enabled = true;
				}
				if (chkVFOBTX.Checked)
				{
					ptbMic_Scroll(this, EventArgs.Empty);
				}
			}
			if (new_mode != DSPMode.DRM)
			{
				EnableAllRX2Filters();
			}
			break;
		case DSPMode.SAM:
			radRX2ModeSAM.BackColor = SystemColors.Control;
			if (!rx2_enabled)
			{
				break;
			}
			if (new_mode != DSPMode.AM && new_mode != DSPMode.SAM && new_mode != DSPMode.FM)
			{
				if (chkVFOBTX.Checked)
				{
					chkMON.Enabled = true;
				}
				chkRX2BIN.Enabled = true;
			}
			if (chkVFOBTX.Checked)
			{
				ptbMic_Scroll(this, EventArgs.Empty);
			}
			break;
		case DSPMode.DIGL:
			radRX2ModeDIGL.BackColor = SystemColors.Control;
			if (rx2_enabled && vac2_auto_enable && new_mode != DSPMode.DIGU && new_mode != DSPMode.DRM)
			{
				SetupForm.VAC2Enable = false;
			}
			if (new_mode != DSPMode.DIGU)
			{
				SetDigiMode(2, DigiMode.DigiModeSettingState.dmssRecall);
			}
			break;
		case DSPMode.DIGU:
			radRX2ModeDIGU.BackColor = SystemColors.Control;
			if (rx2_enabled && vac2_auto_enable && new_mode != DSPMode.DIGL && new_mode != DSPMode.DRM)
			{
				SetupForm.VAC2Enable = false;
			}
			if (new_mode != DSPMode.DIGL)
			{
				SetDigiMode(2, DigiMode.DigiModeSettingState.dmssRecall);
			}
			break;
		case DSPMode.DRM:
			radRX2ModeDRM.BackColor = SystemColors.Control;
			rx2_vfo_offset = 0.0;
			if (rx2_enabled && vac_auto_enable && new_mode != DSPMode.DIGL && new_mode != DSPMode.DIGU)
			{
				SetupForm.VAC2Enable = false;
			}
			if (new_mode != DSPMode.FM)
			{
				EnableAllRX2Filters();
			}
			CalcDisplayFreq();
			break;
		}
		switch (new_mode)
		{
		case DSPMode.LSB:
			radRX2ModeLSB.BackColor = button_selected_color;
			if (chkVFOBTX.Checked && rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			break;
		case DSPMode.USB:
			radRX2ModeUSB.BackColor = button_selected_color;
			if (chkVFOBTX.Checked && rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			break;
		case DSPMode.DSB:
			radRX2ModeDSB.BackColor = button_selected_color;
			if (chkVFOBTX.Checked && rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			break;
		case DSPMode.CWL:
			radRX2ModeCWL.BackColor = button_selected_color;
			if (chkVFOBTX.Checked && rx2_enabled)
			{
				radio.GetDSPTX(0).TXOsc = 0.0;
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				CWPitch = cw_pitch;
			}
			if (!RX2IsIn60mChannel())
			{
				switch (_rx2_dsp_mode)
				{
				case DSPMode.USB:
					num += (double)cw_pitch * 1E-06;
					break;
				default:
					num -= (double)cw_pitch * 1E-06;
					break;
				case DSPMode.CWU:
					break;
				}
				setVFOBFreqNoUpdate(num);
			}
			SetupForm.EnableRX2APFControl = true;
			lblRX2APF.Show();
			break;
		case DSPMode.CWU:
			radRX2ModeCWU.BackColor = button_selected_color;
			if (chkVFOBTX.Checked && rx2_enabled)
			{
				radio.GetDSPTX(0).TXOsc = 0.0;
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				CWPitch = cw_pitch;
			}
			if (!RX2IsIn60mChannel())
			{
				switch (_rx2_dsp_mode)
				{
				case DSPMode.LSB:
					num -= (double)cw_pitch * 1E-06;
					break;
				default:
					num += (double)cw_pitch * 1E-06;
					break;
				case DSPMode.CWL:
					break;
				}
				setVFOBFreqNoUpdate(num);
			}
			SetupForm.EnableRX2APFControl = true;
			lblRX2APF.Show();
			break;
		case DSPMode.FM:
			radRX2ModeFMN.BackColor = button_selected_color;
			DisableAllRX2Filters();
			if (chkRX2NR.CheckState == CheckState.Indeterminate)
			{
				chkRX2NR.CheckState = CheckState.Unchecked;
			}
			handleSqlFM(2, bFM: true);
			if (!rx2_enabled)
			{
				break;
			}
			if (chkVFOBTX.Checked)
			{
				if (!_rx_only && chkPower.Checked)
				{
					chkMOX.Enabled = true;
				}
				chkMON.Checked = false;
				chkMON.Enabled = false;
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				ptbFMMic_Scroll(this, EventArgs.Empty);
			}
			chkRX2BIN.Checked = false;
			chkRX2BIN.Enabled = false;
			break;
		case DSPMode.AM:
			radRX2ModeAM.BackColor = button_selected_color;
			if (chkVFOBTX.Checked && rx2_enabled)
			{
				if (!_rx_only && chkPower.Checked)
				{
					chkMOX.Enabled = true;
				}
				chkMON.Checked = false;
				chkMON.Enabled = false;
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				ptbFMMic_Scroll(this, EventArgs.Empty);
			}
			chkRX2BIN.Checked = false;
			chkRX2BIN.Enabled = false;
			break;
		case DSPMode.SAM:
			radRX2ModeSAM.BackColor = button_selected_color;
			if (chkVFOBTX.Checked && rx2_enabled)
			{
				if (!_rx_only && chkPower.Checked)
				{
					chkMOX.Enabled = true;
				}
				chkMON.Checked = false;
				chkMON.Enabled = false;
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				ptbFMMic_Scroll(this, EventArgs.Empty);
			}
			chkRX2BIN.Checked = false;
			chkRX2BIN.Enabled = false;
			break;
		case DSPMode.DIGL:
			radRX2ModeDIGL.BackColor = button_selected_color;
			if (chkVFOBTX.Checked && rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			if (rx2_enabled && vac2_auto_enable)
			{
				SetupForm.VAC2Enable = true;
			}
			if (rx2_dsp_mode != DSPMode.DIGU)
			{
				SetDigiMode(2, DigiMode.DigiModeSettingState.dmssStore);
				SetDigiMode(2, DigiMode.DigiModeSettingState.dmssTurnOffSettings);
			}
			break;
		case DSPMode.DIGU:
			radRX2ModeDIGU.BackColor = button_selected_color;
			if (chkVFOBTX.Checked && rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			if (rx2_enabled && vac2_auto_enable)
			{
				SetupForm.VAC2Enable = true;
			}
			if (rx2_dsp_mode != DSPMode.DIGL)
			{
				SetDigiMode(2, DigiMode.DigiModeSettingState.dmssStore);
				SetDigiMode(2, DigiMode.DigiModeSettingState.dmssTurnOffSettings);
			}
			break;
		case DSPMode.DRM:
			rx2_vfo_offset = -0.012;
			radRX2ModeDRM.BackColor = button_selected_color;
			if (rx2_enabled && vac2_auto_enable)
			{
				SetupForm.VAC2Enable = true;
			}
			if (chkVFOBTX.Checked && rx2_enabled)
			{
				SetTXFilters(new_mode, tx_filter_low, tx_filter_high);
				radio.GetDSPTX(0).TXOsc = 0.0;
			}
			radio.GetDSPRX(1, 0).SetRXFilter(7000, 17000);
			break;
		}
		if (RX2IsOn60mChannel() && current_region == FRSRegion.US)
		{
			num += 0.0 - ModeFreqOffset(rx2_dsp_mode) + ModeFreqOffset(new_mode);
			setVFOBFreqNoUpdate(num);
		}
		ToolStripMenuItem toolStripMenuItem = kToolStripMenuItem;
		string text = (radRX2Filter1.Text = rx2_filters[(int)new_mode].GetName(Filter.F1));
		toolStripMenuItem.Text = text;
		ToolStripMenuItem toolStripMenuItem2 = kToolStripMenuItem1;
		text = (radRX2Filter2.Text = rx2_filters[(int)new_mode].GetName(Filter.F2));
		toolStripMenuItem2.Text = text;
		ToolStripMenuItem toolStripMenuItem3 = kToolStripMenuItem2;
		text = (radRX2Filter3.Text = rx2_filters[(int)new_mode].GetName(Filter.F3));
		toolStripMenuItem3.Text = text;
		ToolStripMenuItem toolStripMenuItem4 = kToolStripMenuItem3;
		text = (radRX2Filter4.Text = rx2_filters[(int)new_mode].GetName(Filter.F4));
		toolStripMenuItem4.Text = text;
		ToolStripMenuItem toolStripMenuItem5 = kToolStripMenuItem4;
		text = (radRX2Filter5.Text = rx2_filters[(int)new_mode].GetName(Filter.F5));
		toolStripMenuItem5.Text = text;
		ToolStripMenuItem toolStripMenuItem6 = toolStripMenuItem13;
		text = (radRX2Filter6.Text = rx2_filters[(int)new_mode].GetName(Filter.F6));
		toolStripMenuItem6.Text = text;
		ToolStripMenuItem toolStripMenuItem7 = toolStripMenuItem14;
		text = (radRX2Filter7.Text = rx2_filters[(int)new_mode].GetName(Filter.F7));
		toolStripMenuItem7.Text = text;
		radRX2FilterVar1.Text = rx2_filters[(int)new_mode].GetName(Filter.VAR1);
		radRX2FilterVar2.Text = rx2_filters[(int)new_mode].GetName(Filter.VAR2);
		_rx2_dsp_mode = new_mode;
		if (_rx2_dsp_mode != DSPMode.FM && _rx2_dsp_mode != DSPMode.DRM)
		{
			RX2Filter = rx2_filters[(int)new_mode].LastFilter;
		}
		else
		{
			RX2Filter = Filter.NONE;
			if (_rx2_dsp_mode == DSPMode.FM)
			{
				int num2 = (int)(radio.GetDSPRX(1, 0).RXFMDeviation + radio.GetDSPRX(1, 0).RXFMHighCut);
				UpdateRX2Filters(-num2, num2);
			}
		}
		if (_rx2_dsp_mode != DSPMode.FM && _rx2_dsp_mode != DSPMode.DRM)
		{
			RX2Filter = rx2_filters[(int)new_mode].LastFilter;
		}
		else
		{
			RX2Filter = Filter.NONE;
		}
		tbFilterWidthScroll_newMode();
		if (new_mode == DSPMode.CWL || new_mode == DSPMode.CWU)
		{
			chkCWAPFEnabled_CheckedChanged(this, EventArgs.Empty);
		}
		UpdateDSP();
		txtVFOBFreq_LostFocus(this, EventArgs.Empty);
		chkRX2Squelch_CheckStateChanged(this, EventArgs.Empty);
		ptbPWR_Scroll(this, EventArgs.Empty);
		if (rx2_dsp_mode == DSPMode.FM || new_mode == DSPMode.FM)
		{
			SetupForm.ForceAudioReset();
		}
		if (rx2_enabled)
		{
			WDSP.SetChannelState(WDSP.id(2u, 0u), 1, 0);
		}
		if (rx2_dsp_mode != new_mode)
		{
			ModeChangeHandlers?.Invoke(2, rx2_dsp_mode, new_mode, rX2Band, RX2Band);
		}
	}

	private void radRX2ModeButton_CheckedChanged(object sender, EventArgs e)
	{
		if (sender != null && !(sender.GetType() != typeof(RadioButtonTS)) && ((RadioButtonTS)sender).Checked)
		{
			switch (((RadioButtonTS)sender).Text)
			{
			case "LSB":
				SetRX2Mode(DSPMode.LSB);
				break;
			case "USB":
				SetRX2Mode(DSPMode.USB);
				break;
			case "DSB":
				SetRX2Mode(DSPMode.DSB);
				break;
			case "CWL":
				SetRX2Mode(DSPMode.CWL);
				break;
			case "CWU":
				SetRX2Mode(DSPMode.CWU);
				break;
			case "FM":
				SetRX2Mode(DSPMode.FM);
				break;
			case "AM":
				SetRX2Mode(DSPMode.AM);
				break;
			case "SAM":
				SetRX2Mode(DSPMode.SAM);
				break;
			case "DIGL":
				SetRX2Mode(DSPMode.DIGL);
				break;
			case "DIGU":
				SetRX2Mode(DSPMode.DIGU);
				break;
			case "DRM":
				SetRX2Mode(DSPMode.DRM);
				break;
			}
			setSmallRX2ModeFilterLabels();
			lSBToolStripMenuItem1.Checked = radRX2ModeLSB.Checked;
			uSBToolStripMenuItem1.Checked = radRX2ModeUSB.Checked;
			dSBToolStripMenuItem1.Checked = radRX2ModeDSB.Checked;
			cWLToolStripMenuItem1.Checked = radRX2ModeCWL.Checked;
			cWUToolStripMenuItem1.Checked = radRX2ModeCWU.Checked;
			fMToolStripMenuItem1.Checked = radRX2ModeFMN.Checked;
			aMToolStripMenuItem1.Checked = radRX2ModeAM.Checked;
			sAMToolStripMenuItem1.Checked = radRX2ModeSAM.Checked;
			dIGLToolStripMenuItem1.Checked = radRX2ModeDIGL.Checked;
			dIGUToolStripMenuItem1.Checked = radRX2ModeDIGU.Checked;
			dRMToolStripMenuItem1.Checked = radRX2ModeDRM.Checked;
			if (filterPopupForm != null)
			{
				filterPopupForm.RepopulateForm();
			}
			if (modePopupForm != null)
			{
				modePopupForm.RepopulateForm();
			}
		}
	}

