	public void SetRX2Filter(Filter new_filter, bool update = true)
	{
		if (_rx2_dsp_mode == DSPMode.FIRST || _rx2_dsp_mode == DSPMode.LAST)
		{
			return;
		}
		Filter filter = rx2_filter;
		int num = 0;
		int num2 = 0;
		switch (rx2_filter)
		{
		case Filter.F1:
			radRX2Filter1.BackColor = SystemColors.Control;
			break;
		case Filter.F2:
			radRX2Filter2.BackColor = SystemColors.Control;
			break;
		case Filter.F3:
			radRX2Filter3.BackColor = SystemColors.Control;
			break;
		case Filter.F4:
			radRX2Filter4.BackColor = SystemColors.Control;
			break;
		case Filter.F5:
			radRX2Filter5.BackColor = SystemColors.Control;
			break;
		case Filter.F6:
			radRX2Filter6.BackColor = SystemColors.Control;
			break;
		case Filter.F7:
			radRX2Filter7.BackColor = SystemColors.Control;
			break;
		case Filter.VAR1:
			udRX2FilterLow.Enabled = false;
			udRX2FilterHigh.Enabled = false;
			break;
		case Filter.VAR2:
			udRX2FilterLow.Enabled = false;
			udRX2FilterHigh.Enabled = false;
			break;
		}
		rx2_filter = new_filter;
		num = rx2_filters[(int)_rx2_dsp_mode].GetLow(new_filter);
		num2 = rx2_filters[(int)_rx2_dsp_mode].GetHigh(new_filter);
		rx2_filters[(int)_rx2_dsp_mode].LastFilter = new_filter;
		panelRX2Filter.Text = "RX2 Filter - " + rx2_filters[(int)_rx2_dsp_mode].GetName(new_filter);
		switch (new_filter)
		{
		case Filter.F1:
			radRX2Filter1.BackColor = button_selected_color;
			break;
		case Filter.F2:
			radRX2Filter2.BackColor = button_selected_color;
			break;
		case Filter.F3:
			radRX2Filter3.BackColor = button_selected_color;
			break;
		case Filter.F4:
			radRX2Filter4.BackColor = button_selected_color;
			break;
		case Filter.F5:
			radRX2Filter5.BackColor = button_selected_color;
			break;
		case Filter.F6:
			radRX2Filter6.BackColor = button_selected_color;
			break;
		case Filter.F7:
			radRX2Filter7.BackColor = button_selected_color;
			break;
		case Filter.VAR1:
			udRX2FilterLow.Enabled = true;
			udRX2FilterHigh.Enabled = true;
			break;
		case Filter.VAR2:
			udRX2FilterLow.Enabled = true;
			udRX2FilterHigh.Enabled = true;
			break;
		case Filter.NONE:
		{
			foreach (Control control in panelRX2Filter.Controls)
			{
				if (control.GetType() == typeof(RadioButtonTS))
				{
					((RadioButtonTS)control).Checked = false;
					if (control.BackColor != SystemColors.Control)
					{
						((RadioButtonTS)control).BackColor = SystemColors.Control;
					}
				}
			}
			return;
		}
		}
		if (update)
		{
			UpdateRX2Filters(num, num2, force: true);
		}
		if (filterAndDspModeValid(2) && filter != rx2_filter)
		{
			FilterChangedHandlers?.Invoke(2, filter, rx2_filter, RX2Band, rx2_filters[(int)_rx2_dsp_mode].GetLow(rx2_filter), rx2_filters[(int)_rx2_dsp_mode].GetHigh(rx2_filter), rx2_filters[(int)_rx2_dsp_mode].GetName(rx2_filter));
		}
	}

