	private void udRX2FilterLow_ValueChanged(object sender, EventArgs e)
	{
		if (_filter_console_controls_force_update || udRX2FilterLow.Focused || udRX2FilterLow.ClientRectangle.Contains(udRX2FilterLow.PointToClient(Control.MousePosition)))
		{
			if (udRX2FilterLow.Value >= udRX2FilterHigh.Value - 10m)
			{
				udRX2FilterLow.Value = udRX2FilterHigh.Value - 10m;
				return;
			}
			UpdateRX2Filters((int)udRX2FilterLow.Value, (int)udRX2FilterHigh.Value, force: false, from_change_event: true);
			if (!save_filter_changes)
			{
				rx2_filters[(int)_rx2_dsp_mode].SetLow(rx2_filter, (int)udRX2FilterLow.Value);
			}
		}
		if (save_filter_changes && rx2_filter >= Filter.F1 && rx2_filter <= Filter.VAR2)
		{
			rx2_filters[(int)_rx2_dsp_mode].SetLow(rx2_filter, (int)udRX2FilterLow.Value);
		}
	}

	private void udRX2FilterHigh_ValueChanged(object sender, EventArgs e)
	{
		if (_filter_console_controls_force_update || udRX2FilterHigh.Focused || udRX2FilterHigh.ClientRectangle.Contains(udRX2FilterHigh.PointToClient(Control.MousePosition)))
		{
			if (udRX2FilterHigh.Value <= udRX2FilterLow.Value + 10m)
			{
				udRX2FilterHigh.Value = udRX2FilterLow.Value + 10m;
				return;
			}
			UpdateRX2Filters((int)udRX2FilterLow.Value, (int)udRX2FilterHigh.Value, force: false, from_change_event: true);
			if (!save_filter_changes)
			{
				rx2_filters[(int)_rx2_dsp_mode].SetHigh(rx2_filter, (int)udRX2FilterHigh.Value);
			}
		}
		if (save_filter_changes && rx2_filter >= Filter.F1 && rx2_filter <= Filter.VAR2)
		{
			rx2_filters[(int)_rx2_dsp_mode].SetHigh(rx2_filter, (int)udRX2FilterHigh.Value);
		}
	}

