	private void ptbRX2RF_Scroll(object sender, EventArgs e)
	{
		if (RX2AGCMode == AGCMode.FIXD)
		{
			lblRX2RF.Text = "Fixed Gain:  " + ptbRX2RF.Value;
			if (!IsSetupFormNull)
			{
				SetupForm.AGCRX2FixedGain = ptbRX2RF.Value;
			}
		}
		else
		{
			lblRX2RF.Text = "AGC Gain:  " + ptbRX2RF.Value;
			if (!IsSetupFormNull)
			{
				SetupForm.AGCRX2MaxGain = ptbRX2RF.Value;
			}
		}
		rx2_agct_by_band[(int)rx2_band] = ptbRX2RF.Value;
		if (sender.GetType() == typeof(PrettyTrackBar))
		{
			ptbRX2RF.Focus();
		}
		double pct = Convert.ToDouble(ptbRX2RF.Value - ptbRX2RF.Minimum) / Convert.ToDouble(ptbRX2RF.Maximum - ptbRX2RF.Minimum);
		Midi2Cat.SendUpdateToMidi(CatCmd.RX2AGCLevel_inc, pct);
		if (sliderForm != null)
		{
			sliderForm.RX2RFGainAGC = ptbRX2RF.Value;
		}
		if (_old_rx2_agc_gain != -999 && _old_rx2_agc_gain != ptbRX2RF.Value)
		{
			AGCGainChangedHandlers?.Invoke(2, _old_rx2_agc_gain, ptbRX2RF.Value);
		}
		_old_rx2_agc_gain = ptbRX2RF.Value;
	}

	private void picRX2Squelch_Paint(object sender, PaintEventArgs e)
	{
		int num = (int)(((double)rx2_sql_data + 160.0) * (double)(picRX2Squelch.Width - 1) / 160.0);
		int num2 = (int)(((double)(float)ptbRX2Squelch.Value + 160.0) * (double)(picRX2Squelch.Width - 1) / 160.0);
		e.Graphics.FillRectangle(Brushes.LimeGreen, 0, 0, num, picRX2Squelch.Height);
		if (num2 < num)
		{
			e.Graphics.FillRectangle(Brushes.Red, num2 + 1, 0, num - num2 - 1, picRX2Squelch.Height);
		}
	}

