	private void ptbRX2Gain_Scroll(object sender, EventArgs e)
	{
		if (!initializing && e != EventArgs.Empty && m_bRXAFSlidersWillUnmute && chkRX2Mute.Checked)
		{
			chkRX2Mute.Checked = false;
		}
		if (chkRX2Mute.Checked && m_bMuteWillMuteVAC2)
		{
			radio.GetDSPRX(1, 0).RXOutputGain = 0.0;
		}
		else
		{
			radio.GetDSPRX(1, 0).RXOutputGain = (double)ptbRX2Gain.Value / (double)ptbRX2Gain.Maximum;
		}
		ptbRX2AF.Value = ptbRX2Gain.Value;
		lblRX2AF.Text = "RX2 AF:  " + ptbRX2Gain.Value;
		setLinkedAF(3, ptbRX2Gain.Value);
		if (sender.GetType() == typeof(PrettyTrackBar))
		{
			ptbRX2Gain.Focus();
		}
		double pct = Convert.ToDouble(ptbRX2AF.Value - ptbRX2AF.Minimum) / Convert.ToDouble(ptbRX2AF.Maximum - ptbRX2AF.Minimum);
		Midi2Cat.SendUpdateToMidi(CatCmd.VolumeVfoB_inc, pct);
		if (sliderForm != null)
		{
			sliderForm.RX2Gain = ptbRX2Gain.Value;
		}
		int value = ptbRX2Gain.Value;
		if (value != _old_rx2_gain)
		{
			RXGainChangedHandlers?.Invoke(2, is_subrx: false, _old_rx2_gain, value);
			RXGainChangedHandlers?.Invoke(2, is_subrx: true, _old_rx2_gain, value);
			_old_rx2_gain = value;
		}
	}

	private void chkRX2Mute_CheckedChanged(object sender, EventArgs e)
	{
		bool muteRX = Audio.MuteRX2;
		if (chkRX2Mute.Checked)
		{
			Audio.MuteRX2 = true;
			if (m_bMuteWillMuteVAC2)
			{
				radio.GetDSPRX(1, 0).RXOutputGain = 0.0;
			}
			lblRX2MuteVFOB.Text = "MUTE";
			lblRX2MuteVFOB.Show();
		}
		else
		{
			Audio.MuteRX2 = false;
			radio.GetDSPRX(1, 0).RXOutputGain = (double)ptbRX2Gain.Value / (double)ptbRX2Gain.Maximum;
			ptbRX2Gain_Scroll(this, EventArgs.Empty);
			lblRX2MuteVFOB.Text = "";
			lblRX2MuteVFOB.Hide();
		}
		if (sliderForm != null)
		{
			sliderForm.RX2MuteOnOff = chkRX2Mute.Checked;
		}
		if (chkRX2Mute.Focused)
		{
			btnHidden.Focus();
		}
		if (path_Illustrator != null)
		{
			path_Illustrator.pi_Changed();
		}
		if (muteRX != Audio.MuteRX2)
		{
			MuteChangedHandlers?.Invoke(2, muteRX, Audio.MuteRX2);
		}
		setMuteAllGeneralSettings();
	}

	private void comboRX2DisplayMode_SelectedIndexChanged(object sender, EventArgs e)
	{
		DisplayMode currentDisplayModeBottom = Display.CurrentDisplayModeBottom;
		switch (comboRX2DisplayMode.Text)
		{
		case "Spectrum":
			Display.CurrentDisplayModeBottom = DisplayMode.SPECTRUM;
			if (chkSplitDisplay.Checked)
			{
				UpdateRXDisplayVars((int)udFilterLow.Value, (int)udFilterHigh.Value);
			}
			break;
		case "Panadapter":
			Display.CurrentDisplayModeBottom = DisplayMode.PANADAPTER;
			if (chkSplitDisplay.Checked)
			{
				CalcDisplayFreq();
			}
			break;
		case "Scope":
			Display.CurrentDisplayModeBottom = DisplayMode.SCOPE;
			break;
		case "Phase":
			Display.CurrentDisplayModeBottom = DisplayMode.PHASE;
			break;
		case "Phase2":
			Display.CurrentDisplayModeBottom = DisplayMode.PHASE2;
			break;
		case "Waterfall":
			Display.CurrentDisplayModeBottom = DisplayMode.WATERFALL;
			if (chkSplitDisplay.Checked)
			{
				CalcDisplayFreq();
			}
			break;
		case "Histogram":
			Display.CurrentDisplayModeBottom = DisplayMode.HISTOGRAM;
			break;
		case "Panafall":
			Display.CurrentDisplayModeBottom = DisplayMode.PANAFALL;
			if (chkSplitDisplay.Checked)
			{
				CalcDisplayFreq();
			}
			break;
		case "Off":
			Display.CurrentDisplayModeBottom = DisplayMode.OFF;
			break;
		}
		if (comboRX2DisplayMode.Focused)
		{
			btnHidden.Focus();
		}
		if (currentDisplayModeBottom != Display.CurrentDisplayModeBottom)
		{
			DisplayModeChangedHandlers?.Invoke(2, currentDisplayModeBottom, Display.CurrentDisplayModeBottom);
		}
	}

