	private void UpdateDSP()
	{
		if (m_bDeferUpdateDSP)
		{
			return;
		}
		Stopwatch stopwatch = new Stopwatch();
		stopwatch.Start();
		int num = 64;
		int num2 = 64;
		int num3 = 128;
		int num4 = 4096;
		int num5 = 4096;
		int num6 = 4096;
		DSPFilterType dSPFilterType = DSPFilterType.Low_Latency;
		DSPFilterType dSPFilterType2 = DSPFilterType.Low_Latency;
		DSPFilterType dSPFilterType3 = DSPFilterType.Low_Latency;
		bool bufferSizeDifferentRX = dsp_buf_phone_rx != dsp_buf_fm_rx || dsp_buf_fm_rx != dsp_buf_cw_rx || dsp_buf_cw_rx != dsp_buf_dig_rx;
		bool filterSizeDifferentRX = dsp_filt_size_phone_rx != dsp_filt_size_fm_rx || dsp_filt_size_fm_rx != dsp_filt_size_cw_rx || dsp_filt_size_cw_rx != dsp_filt_size_dig_rx;
		bool filterTypeDifferentRX = dsp_filt_type_phone_rx != dsp_filt_type_fm_rx || dsp_filt_type_fm_rx != dsp_filt_type_cw_rx || dsp_filt_type_cw_rx != dsp_filt_type_dig_rx;
		bool bufferSizeDifferentTX = dsp_buf_phone_tx != dsp_buf_fm_tx || dsp_buf_fm_tx != dsp_buf_dig_tx;
		bool filterSizeDifferentTX = dsp_filt_size_phone_tx != dsp_filt_size_fm_tx || dsp_filt_size_fm_tx != dsp_filt_size_dig_tx;
		bool filterTypeDifferentTX = dsp_filt_type_phone_tx != dsp_filt_type_fm_tx || dsp_filt_type_fm_tx != dsp_filt_type_dig_tx;
		if (!IsSetupFormNull)
		{
			SetupForm.SetupDSPWarnings(bufferSizeDifferentRX, filterSizeDifferentRX, filterTypeDifferentRX, bufferSizeDifferentTX, filterSizeDifferentTX, filterTypeDifferentTX);
		}
		switch (_rx1_dsp_mode)
		{
		case DSPMode.LSB:
		case DSPMode.USB:
		case DSPMode.DSB:
		case DSPMode.AM:
		case DSPMode.SAM:
			num = dsp_buf_phone_rx;
			num4 = dsp_filt_size_phone_rx;
			dSPFilterType = dsp_filt_type_phone_rx;
			break;
		case DSPMode.FM:
			num = dsp_buf_fm_rx;
			num4 = dsp_filt_size_fm_rx;
			dSPFilterType = dsp_filt_type_fm_rx;
			break;
		case DSPMode.CWL:
		case DSPMode.CWU:
			num = dsp_buf_cw_rx;
			num4 = dsp_filt_size_cw_rx;
			dSPFilterType = dsp_filt_type_cw_rx;
			break;
		case DSPMode.DIGU:
		case DSPMode.DIGL:
		case DSPMode.DRM:
			num = dsp_buf_dig_rx;
			num4 = dsp_filt_size_dig_rx;
			dSPFilterType = dsp_filt_type_dig_rx;
			break;
		}
		switch (_rx2_dsp_mode)
		{
		case DSPMode.LSB:
		case DSPMode.USB:
		case DSPMode.DSB:
		case DSPMode.AM:
		case DSPMode.SAM:
			num2 = dsp_buf_phone_rx;
			num5 = dsp_filt_size_phone_rx;
			dSPFilterType2 = dsp_filt_type_phone_rx;
			break;
		case DSPMode.FM:
			num2 = dsp_buf_fm_rx;
			num5 = dsp_filt_size_fm_rx;
			dSPFilterType2 = dsp_filt_type_fm_rx;
			break;
		case DSPMode.CWL:
		case DSPMode.CWU:
			num2 = dsp_buf_cw_rx;
			num5 = dsp_filt_size_cw_rx;
			dSPFilterType2 = dsp_filt_type_cw_rx;
			break;
		case DSPMode.DIGU:
		case DSPMode.DIGL:
		case DSPMode.DRM:
			num2 = dsp_buf_dig_rx;
			num5 = dsp_filt_size_dig_rx;
			dSPFilterType2 = dsp_filt_type_dig_rx;
			break;
		}
		DSPMode dSPMode = _rx1_dsp_mode;
		if (chkVFOBTX.Checked)
		{
			dSPMode = _rx2_dsp_mode;
		}
		switch (dSPMode)
		{
		case DSPMode.LSB:
		case DSPMode.USB:
		case DSPMode.DSB:
		case DSPMode.AM:
		case DSPMode.SAM:
			num3 = dsp_buf_phone_tx;
			num6 = dsp_filt_size_phone_tx;
			dSPFilterType3 = dsp_filt_type_phone_tx;
			break;
		case DSPMode.FM:
			num3 = dsp_buf_fm_tx;
			num6 = dsp_filt_size_fm_tx;
			dSPFilterType3 = dsp_filt_type_fm_tx;
			break;
		case DSPMode.CWL:
		case DSPMode.CWU:
			num3 = radio.GetDSPTX(0).BufferSize;
			num6 = radio.GetDSPTX(0).FilterSize;
			dSPFilterType3 = radio.GetDSPTX(0).FilterType;
			break;
		case DSPMode.DIGU:
		case DSPMode.DIGL:
		case DSPMode.DRM:
			num3 = dsp_buf_dig_tx;
			num6 = dsp_filt_size_dig_tx;
			dSPFilterType3 = dsp_filt_type_dig_tx;
			break;
		}
		if (num4 < num)
		{
			num = num4;
		}
		if (num5 < num2)
		{
			num2 = num5;
		}
		if (num6 < num3)
		{
			num3 = num6;
		}
		Cursor current = Cursor.Current;
		Cursor.Current = Cursors.WaitCursor;
		bool flag = false;
		if (radio.GetDSPRX(0, 0).BufferSize != num || radio.GetDSPRX(0, 1).BufferSize != num)
		{
			radio.GetDSPRX(0, 0).BufferSize = num;
			radio.GetDSPRX(0, 1).BufferSize = num;
			flag = true;
		}
		if (radio.GetDSPRX(1, 0).BufferSize != num2 || radio.GetDSPRX(1, 1).BufferSize != num2)
		{
			radio.GetDSPRX(1, 0).BufferSize = num2;
			radio.GetDSPRX(1, 1).BufferSize = num2;
			flag = true;
		}
		if (radio.GetDSPTX(0).BufferSize != num3)
		{
			radio.GetDSPTX(0).BufferSize = num3;
			flag = true;
		}
		if (radio.GetDSPRX(0, 0).FilterSize != num4 || radio.GetDSPRX(0, 1).FilterSize != num4)
		{
			radio.GetDSPRX(0, 0).FilterSize = num4;
			radio.GetDSPRX(0, 1).FilterSize = num4;
			flag = true;
		}
		if (radio.GetDSPRX(1, 0).FilterSize != num5 || radio.GetDSPRX(1, 1).FilterSize != num5)
		{
			radio.GetDSPRX(1, 0).FilterSize = num5;
			radio.GetDSPRX(1, 1).FilterSize = num5;
			flag = true;
		}
		if (radio.GetDSPTX(0).FilterSize != num6)
		{
			radio.GetDSPTX(0).FilterSize = num6;
			flag = true;
		}
		if (radio.GetDSPRX(0, 0).FilterType != dSPFilterType || radio.GetDSPRX(0, 1).FilterType != dSPFilterType)
		{
			radio.GetDSPRX(0, 0).FilterType = dSPFilterType;
			radio.GetDSPRX(0, 1).FilterType = dSPFilterType;
			flag = true;
		}
		if (radio.GetDSPRX(1, 0).FilterType != dSPFilterType2 || radio.GetDSPRX(1, 1).FilterType != dSPFilterType2)
		{
			radio.GetDSPRX(1, 0).FilterType = dSPFilterType2;
			radio.GetDSPRX(1, 1).FilterType = dSPFilterType2;
			flag = true;
		}
		if (radio.GetDSPTX(0).FilterType != dSPFilterType3)
		{
			radio.GetDSPTX(0).FilterType = dSPFilterType3;
			flag = true;
		}
		UpdateRXSpectrumDisplayVars();
		UpdateTXSpectrumDisplayVars();
		Cursor.Current = current;
		stopwatch.Stop();
		if (flag && !IsSetupFormNull)
		{
			SetupForm.DSPChangeDuration = stopwatch.ElapsedMilliseconds;
		}
		UpdateMinimumNotchWidthRX(1);
		UpdateMinimumNotchWidthRX(2);
		UpdateMinimumNotchWidthTX();
		if (flag)
		{
			BuildFilterCharacteristics();
			if (EQForm != null && !EQForm.Disposing)
			{
				EQForm.DSPOptionsChanged();
			}
		}
	}

	public void BuildFilterCharacteristics()
	{
		double corner_freq = 1000.0;
		double[] segments;
		int index_low;
		int index_upper;
		(segments, index_low, index_upper) = calcFilterCharacteristics(0, 48000.0, radio.GetDSPRX(0, 0).FilterSize, radio.GetDSPRX(0, 0).RXBandpassWindow, corner_freq, _hi_resolution_filter_characteristics);
		MiniSpec.UpdateRXFilterCharacteristics(DSPMode.FIRST, segments, index_low, index_upper, corner_freq);
		(segments, index_low, index_upper) = calcFilterCharacteristics(1, 192000.0, radio.GetDSPRX(0, 0).FilterSize, radio.GetDSPRX(0, 0).RXBandpassWindow, corner_freq, _hi_resolution_filter_characteristics);
		MiniSpec.UpdateRXFilterCharacteristics(DSPMode.FM, segments, index_low, index_upper, corner_freq);
		(segments, index_low, index_upper) = calcFilterCharacteristics(2, 96000.0, radio.GetDSPTX(0).FilterSize, radio.GetDSPTX(0).TXBandpassWindow, corner_freq, _hi_resolution_filter_characteristics);
		MiniSpec.UpdateTXFilterCharacteristics(segments, index_low, index_upper, corner_freq);
		WDSP.destroy_bfcu(0);
		WDSP.destroy_bfcu(1);
		WDSP.destroy_bfcu(2);
	}

	private unsafe (double[], int, int) calcFilterCharacteristics(int id, double rate, int filter_size, int w_type, double corner_freq, bool hi_res)
	{
		try
		{
			int num = Math.Max(512, filter_size);
			int num2 = Math.Max(num, hi_res ? 8192 : 1024);
			WDSP.create_bfcu(id, num, num, rate, corner_freq, num2);
			int num3 = default(int);
			int num4 = default(int);
			WDSP.getFilterCorners(id, &num3, &num4);
			int num5 = num3 + (num4 - num3) / 2;
			double[] array = new double[num2 + 1];
			fixed (double* segment = &array[0])
			{
				WDSP.getFilterCurve(id, filter_size, w_type, num5 - num2 / 2, num5 + num2 / 2, segment);
			}
			return (array, num3, num4);
		}
		catch
		{
			return (null, -1, -1);
		}
	}

	public void SetupRX2Band(Band b, bool is_for_rx1_vfo_b = false)
	{
		string sBand = BandToString(b);
		SetupRX2Band(sBand, is_for_rx1_vfo_b);
	}

	public void SetupRX2Band(string sBand, bool is_for_rx1_vfo_b = false)
	{
		if (((MOX & is_for_rx1_vfo_b) && VFOBTX && !rx2_enabled) || (MOX && VFOBTX && rx2_enabled))
		{
			return;
		}
		BandStackFilter filter = BandStackManager.GetFilter(BandStackManager.StringToBand(sBand));
		if (filter == null)
		{
			return;
		}
		BandStackEntry bandStackEntry = filter.First();
		if (bandStackEntry == null)
		{
			bandStackEntry = filter.LastVisited.Copy();
			bandStackEntry.Band = BandStackManager.StringToBand(sBand);
		}
		if (bandStackEntry != null)
		{
			if (!is_for_rx1_vfo_b)
			{
				RX2DSPMode = bandStackEntry.Mode;
				RX2Filter = bandStackEntry.Filter;
			}
			VFOBFreq = bandStackEntry.Frequency;
		}
	}

