	private void updateResolutionStatusBarText()
	{
		if (m_bIncludeWindowBorders)
		{
			Size size = base.Size - DropShadowSize;
			toolStripDropDownButton_ScreenSize.Text = size.Width + " x " + size.Height;
		}
		else
