	private void Console_Resize(object sender, EventArgs e)
	{
		resizeBackgroundImage();
		if (base.WindowState != _old_window_state)
		{
			WindowStateChangedHandlers?.Invoke(base.WindowState);
			_old_window_state = base.WindowState;
		}
		updateResolutionStatusBarText();
		if (base.WindowState == FormWindowState.Minimized)
		{
			return;
		}
		if (dpi == 0)
		{
			dpi = (int)pnlDisplay.CreateGraphics().DpiX;
		}
		if (dpi > 96 && !dpi_resize_done)
		{
			if (base_size.Width == 0f)
			{
				base_size = base.AutoScaleDimensions;
			}
			if (!(base.AutoScaleDimensions != base_size))
			{
				return;
			}
			dpi_resize_done = true;
		}
		if (base.Width < console_basis_size.Width && !collapsedDisplay)
		{
			base.Width = console_basis_size.Width;
			return;
		}
		if (!collapsedDisplay && base.Height < console_basis_size.Height)
		{
			base.Height = console_basis_size.Height;
			return;
		}
		h_delta = base.Width - console_basis_size.Width;
		v_delta = Math.Max(base.Height - console_basis_size.Height, 0);
		if (!IsSetupFormNull)
		{
			if (collapsedDisplay)
			{
				SetupForm.CollapsedWidth = base.Width;
				SetupForm.CollapsedHeight = base.Height;
			}
			else
			{
				if (SetupForm.CollapsedWidth == 0)
				{
					SetupForm.CollapsedWidth = console_basis_size.Width;
				}
				if (SetupForm.CollapsedHeight == 0)
				{
					SetupForm.CollapsedHeight = ((HardwareSpecific.Model == HPSDRModel.HPSDR || HardwareSpecific.Model == HPSDRModel.HERMES) ? (console_basis_size.Height - (panelRX2Filter.Height + 8)) : console_basis_size.Height);
				}
			}
		}
		ResizeConsole(h_delta, v_delta);
	}

	private void comboRX2AGC_SelectedIndexChanged(object sender, EventArgs e)
	{
		if (!IsSetupFormNull)
		{
			AGCMode rXAGCMode = radio.GetDSPRX(1, 0).RXAGCMode;
			radio.GetDSPRX(1, 0).RXAGCMode = (AGCMode)comboRX2AGC.SelectedIndex;
			lblRX2AGCLabel.Text = "AGC: " + comboRX2AGC.Text;
			m_RX2agcMode = (AGCMode)comboRX2AGC.SelectedIndex;
			switch ((AGCMode)comboRX2AGC.SelectedIndex)
			{
			case AGCMode.LONG:
				SetupForm.CustomRX2AGCEnabled = false;
				SetupForm.tbDSPAGCRX2HangThreshold.Enabled = true;
				radio.GetDSPRX(1, 0).RXAGCHang = 2000;
				radio.GetDSPRX(1, 0).RXAGCDecay = 2000;
				SetupForm.AGCRX2HangThreshold = SetupForm.tbDSPAGCRX2HangThreshold.Value;
				toolTip1.SetToolTip(comboRX2AGC, "Automatic Gain Control Mode Setting:\nLong (Attack 2ms, Hang 2000ms, Decay 2000ms)");
				break;
			case AGCMode.SLOW:
				SetupForm.CustomRX2AGCEnabled = false;
				SetupForm.tbDSPAGCRX2HangThreshold.Enabled = true;
				radio.GetDSPRX(1, 0).RXAGCHang = 1000;
				radio.GetDSPRX(1, 0).RXAGCDecay = 500;
				SetupForm.AGCRX2HangThreshold = SetupForm.tbDSPAGCRX2HangThreshold.Value;
				toolTip1.SetToolTip(comboRX2AGC, "Automatic Gain Control Mode Setting:\nSlow (Attack 2ms, Hang 1000ms, Decay 500ms)");
				break;
			case AGCMode.MED:
				SetupForm.CustomRX2AGCEnabled = false;
				SetupForm.tbDSPAGCRX2HangThreshold.Enabled = false;
				radio.GetDSPRX(1, 0).RXAGCHang = 0;
				radio.GetDSPRX(1, 0).RXAGCDecay = 250;
				toolTip1.SetToolTip(comboRX2AGC, "Automatic Gain Control Mode Setting:\nMedium (Attack 2ms, Hang OFF, Decay 250ms)");
				break;
			case AGCMode.FAST:
				SetupForm.CustomRX2AGCEnabled = false;
				SetupForm.tbDSPAGCRX2HangThreshold.Enabled = false;
				radio.GetDSPRX(1, 0).RXAGCHang = 0;
				radio.GetDSPRX(1, 0).RXAGCDecay = 50;
				toolTip1.SetToolTip(comboRX2AGC, "Automatic Gain Control Mode Setting:\nFast (Attack 2ms, Hang OFF, Decay 50ms)");
				break;
			case AGCMode.CUSTOM:
				SetupForm.CustomRX2AGCEnabled = true;
				SetupForm.tbDSPAGCRX2HangThreshold.Enabled = true;
				SetupForm.AGCRX2HangThreshold = SetupForm.tbDSPAGCRX2HangThreshold.Value;
				toolTip1.SetToolTip(comboRX2AGC, "Automatic Gain Control Mode Setting:\nCustom - Set specifics in Setup Form -> DSP -> AGC/ALC");
				break;
			case AGCMode.FIXD:
				SetupForm.CustomRX2AGCEnabled = false;
				toolTip1.SetToolTip(comboAGC, "Automatic Gain Control Mode Setting:\nFixed - Set gain with AGC-T control above");
				break;
			}
			if (comboRX2AGC.SelectedIndex == 0)
			{
				RX2RF = SetupForm.AGCRX2FixedGain;
			}
			else
			{
				RX2RF = SetupForm.AGCRX2MaxGain;
			}
			if (rXAGCMode != radio.GetDSPRX(1, 0).RXAGCMode)
			{
				AGCModeChangedHandlers?.Invoke(2, rXAGCMode, radio.GetDSPRX(1, 0).RXAGCMode);
			}
		}
	}

