	public void DetachPanafall(bool enable)
	{
		if (enable)
		{
			if (detachedPanafallForm == null || detachedPanafallForm.IsDisposed)
			{
				detachedPanafallForm = new DetachedPanafallForm();
			}
			Display.SetDetachPanafall(enable: true);
			detachedPanafallForm.Owner = null;
			if (!detachedPanafallForm.Visible)
			{
				detachedPanafallForm.Show();
			}
			detachedPanafallForm.Focus();
		}
		else
		{
			Display.SetDetachPanafall(enable: false);
			if (detachedPanafallForm != null && !detachedPanafallForm.IsDisposed && detachedPanafallForm.Visible)
			{
				detachedPanafallForm.Close();
			}
		}
	}

	public void DetachedPanafallClosing()
	{
		if (Display.DetachPanafallEnabled)
		{
			Display.SetDetachPanafall(enable: false);
		}
		if (!IsSetupFormNull)
		{
			try
			{
				SetupForm.DetachPanafall = false;
			}
			catch
			{
			}
		}
		try
		{
			if (comboDisplayMode != null && !comboDisplayMode.IsDisposed && comboDisplayMode.Text == "Detach Panafall")
			{
				string text = Display.CurrentDisplayMode.ToString();
				text = text.Substring(0, 1).ToUpper() + text.Substring(1).ToLower();
				if (comboDisplayMode.Items.Contains(text))
				{
					comboDisplayMode.Text = text;
				}
			}
		}
		catch
		{
		}
	}

