	public unsafe bool ChangeNotchCentreFrequency(MNotch notch, double newCentreFrequencyHz, int sourceRX, int notch_index = -1)
	{
		double num = min_freq;
		double num2 = max_freq;
		if (sourceRX == 1 && rx1_xvtr_index >= 0)
		{
			int num3 = XVTRForm.XVTRFreq(newCentreFrequencyHz * 1E-06);
			if (num3 == rx1_xvtr_index)
			{
				num = XVTRForm.GetBegin(num3);
				num2 = XVTRForm.GetEnd(num3);
			}
		}
		else if (sourceRX == 2 && rx2_xvtr_index >= 0)
		{
			int num4 = XVTRForm.XVTRFreq(newCentreFrequencyHz * 1E-06);
			if (num4 == rx2_xvtr_index)
			{
				num = XVTRForm.GetBegin(num4);
				num2 = XVTRForm.GetEnd(num4);
			}
		}
		if (newCentreFrequencyHz < num * 1000000.0 || newCentreFrequencyHz > num2 * 1000000.0)
		{
			return false;
		}
		if (SetupForm.NotchAdminBusy)
		{
			return false;
		}
		newCentreFrequencyHz = Math.Round(newCentreFrequencyHz);
		bool result = false;
		int num5 = ((notch_index != -1) ? notch_index : MNotchDB.IndexOf(notch));
		if (num5 >= 0)
		{
			double num6 = default(double);
			double fwidth = default(double);
			int value = default(int);
			WDSP.RXANBPGetNotch(WDSP.id(0u, 0u), num5, &num6, &fwidth, &value);
			bool flag = Convert.ToBoolean(value);
			WDSP.RXANBPEditNotch(WDSP.id(0u, 0u), num5, newCentreFrequencyHz, fwidth, flag);
			WDSP.RXANBPEditNotch(WDSP.id(0u, 1u), num5, newCentreFrequencyHz, fwidth, flag);
			WDSP.RXANBPEditNotch(WDSP.id(2u, 0u), num5, newCentreFrequencyHz, fwidth, flag);
			bool num7 = SelectedNotch != null;
			SetupForm.SaveNotchesToDatabase();
			SetupForm.UpdateNotchDisplay();
			if (num7)
			{
				SelectedNotch = MNotchDB.GetFirstNotchThatMatches(newCentreFrequencyHz, fwidth, flag);
			}
			if (num6 != newCentreFrequencyHz)
			{
				NotchChangedHandlers?.Invoke(num5, -1.0, -1.0, flag, num6, newCentreFrequencyHz, added: false, removed: false);
			}
			result = true;
		}
		return result;
	}

