	public unsafe void AddNotch(double fFreqHZ, int sourceRX)
	{
		if (SetupForm.NotchAdminBusy || sourceRX < 1 || sourceRX > 2)
		{
			return;
		}
		fFreqHZ += (double)GetDSPcwPitchShiftToZero(sourceRX);
		fFreqHZ = Math.Round(fFreqHZ);
		double num = min_freq;
		double num2 = max_freq;
		if (sourceRX == 1 && rx1_xvtr_index >= 0)
		{
			int num3 = XVTRForm.XVTRFreq(fFreqHZ * 1E-06);
			if (num3 == rx1_xvtr_index)
			{
				num = XVTRForm.GetBegin(num3);
				num2 = XVTRForm.GetEnd(num3);
			}
		}
		else if (sourceRX == 2 && rx2_xvtr_index >= 0)
		{
			int num4 = XVTRForm.XVTRFreq(fFreqHZ * 1E-06);
			if (num4 == rx2_xvtr_index)
			{
				num = XVTRForm.GetBegin(num4);
				num2 = XVTRForm.GetEnd(num4);
			}
		}
		if (!(fFreqHZ < num * 1000000.0) && !(fFreqHZ > num2 * 1000000.0) && !MNotchDB.NotchNearFreq(fFreqHZ, 10))
		{
			int num5 = default(int);
			WDSP.RXANBPGetNumNotches(WDSP.id(0u, 0u), &num5);
			double num6 = 200.0;
			if (Common.ShiftKeyDown)
			{
				num6 = 100.0;
			}
			WDSP.RXANBPAddNotch(WDSP.id(0u, 0u), num5, fFreqHZ, num6, active: true);
			WDSP.RXANBPAddNotch(WDSP.id(0u, 1u), num5, fFreqHZ, num6, active: true);
			WDSP.RXANBPAddNotch(WDSP.id(2u, 0u), num5, fFreqHZ, num6, active: true);
			SetupForm.SaveNotchesToDatabase();
			SetupForm.UpdateNotchDisplay();
			NotchChangedHandlers?.Invoke(num5, num6, num6, active: true, fFreqHZ, fFreqHZ, added: true, removed: false);
		}
	}

	private int notchSidebandShift(int rx)
	{
		int num = 0;
		switch (rx)
		{
		case 1:
		{
			int rXFilterLow = radio.GetDSPRX(0, 0).RXFilterLow;
			int rXFilterHigh = radio.GetDSPRX(0, 0).RXFilterHigh;
			num = rXFilterLow + (rXFilterHigh - rXFilterLow) / 2;
			if (num == 0)
			{
				num = rXFilterHigh / 2;
			}
			break;
		}
		case 2:
		{
			int rXFilterLow = radio.GetDSPRX(1, 0).RXFilterLow;
			int rXFilterHigh = radio.GetDSPRX(1, 0).RXFilterHigh;
			num = rXFilterLow + (rXFilterHigh - rXFilterLow) / 2;
			if (num == 0)
			{
				num = rXFilterHigh / 2;
			}
			break;
		}
		}
		return num;
	}

	private void btnTNFAdd_Click(object sender, EventArgs e)
