	public void TNFAdd(int rx)
	{
		if (SetupForm.NotchAdminBusy)
		{
			return;
		}
		double num;
		if (rx == 1)
		{
			num = VFOAFreq * 1000000.0;
			if (RITOn)
			{
				num += (double)RITValue * 1E-06;
			}
		}
		else
		{
			num = VFOBFreq * 1000000.0;
		}
		num += (double)notchSidebandShift(rx);
		AddNotch(num, rx);
	}

