	private void fmDeviation2k(bool force)
	{
		if (radFMDeviation2kHz.Checked)
		{
			int fm_deviation_hz = _fm_deviation_hz;
			_fm_deviation_hz = 2500;
			radio.GetDSPTX(0).TXFMDeviation = 2500.0;
			radio.GetDSPRX(0, 0).RXFMDeviation = 2500.0;
			radio.GetDSPRX(1, 0).RXFMDeviation = 2500.0;
			if (RX1DSPMode == DSPMode.FM)
			{
				int num = (int)(radio.GetDSPRX(0, 0).RXFMDeviation + radio.GetDSPRX(0, 0).RXFMHighCut);
				UpdateRX1Filters(-num, num, force);
			}
			if (RX2DSPMode == DSPMode.FM)
			{
				int num2 = (int)(radio.GetDSPRX(1, 0).RXFMDeviation + radio.GetDSPRX(1, 0).RXFMHighCut);
				UpdateRX2Filters(-num2, num2, force);
			}
			if (radio.GetDSPTX(0).CurrentDSPMode == DSPMode.FM)
			{
				int num3 = (int)(radio.GetDSPTX(0).TXFMDeviation + radio.GetDSPTX(0).TXFMHighCut);
				SetTXFilters(DSPMode.FM, -num3, num3, force);
			}
			if (!m_bUpdatingFMDeviation && fm_deviation_hz != _fm_deviation_hz)
			{
				FMDeviationChangedHandlers?.Invoke(1, fm_deviation_hz, _fm_deviation_hz);
				FMDeviationChangedHandlers?.Invoke(2, fm_deviation_hz, _fm_deviation_hz);
			}
		}
	}

