	public void changeComboFMMemory(int index)
	{
		if (comboFMMemory.Items.Count != 0 && index >= 0 && index <= comboFMMemory.Items.Count - 1)
		{
			if (comboFMMemory.SelectedIndex != index)
			{
				comboFMMemory.SelectedIndex = index;
