	private void cWXToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (CWXForm.ForceToCWmode)
		{
			if (_rx1_dsp_mode == DSPMode.LSB)
			{
				RX1DSPMode = DSPMode.CWL;
			}
			else if (_rx1_dsp_mode == DSPMode.USB)
			{
				RX1DSPMode = DSPMode.CWU;
			}
			if (_rx1_dsp_mode != DSPMode.CWL && _rx1_dsp_mode != DSPMode.CWU)
			{
				MessageBox.Show("The radio must be in CWL or CWU mode in order to open the CWX Control Form.", "CWX Error: Wrong Mode", MessageBoxButtons.OK, MessageBoxIcon.Hand, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
				return;
			}
		}
		else if (_rx1_dsp_mode != DSPMode.CWL && _rx1_dsp_mode != DSPMode.CWU)
		{
			MessageBox.Show("Ideally the radio should be in CWL or CWU mode.", "CWX : Mode warning", MessageBoxButtons.OK, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
		}
		if (CWXForm.InvokeRequired)
		{
			CWXForm.Invoke((MethodInvoker)delegate
			{
				CWXForm.Show();
				CWXForm.Focus();
			});
		}
		else
		{
			CWXForm.Show();
			CWXForm.Focus();
		}
	}

	public void SetComboPreampForHPSDR()
	{
		comboPreamp.Items.Clear();
		switch (HardwareSpecific.Model)
		{
		case HPSDRModel.HPSDR:
		{
			ComboBox.ObjectCollection items9 = comboPreamp.Items;
			object[] items2 = on_off_preamp_settings;
			items9.AddRange(items2);
			if (alexpresent)
			{
				ComboBox.ObjectCollection items10 = comboPreamp.Items;
				items2 = alex_preamp_settings;
				items10.AddRange(items2);
			}
			break;
		}
		case HPSDRModel.HERMES:
			if (alexpresent)
			{
				ComboBox.ObjectCollection items6 = comboPreamp.Items;
				object[] items2 = on_off_preamp_settings;
				items6.AddRange(items2);
				ComboBox.ObjectCollection items7 = comboPreamp.Items;
				items2 = alex_preamp_settings;
				items7.AddRange(items2);
			}
			else
			{
				ComboBox.ObjectCollection items8 = comboPreamp.Items;
				object[] items2 = anan100d_preamp_settings;
				items8.AddRange(items2);
			}
			break;
		case HPSDRModel.ANAN10:
		case HPSDRModel.ANAN10E:
		{
			ComboBox.ObjectCollection items13 = comboPreamp.Items;
			object[] items2 = anan100d_preamp_settings;
			items13.AddRange(items2);
			break;
		}
		case HPSDRModel.ANAN100:
		case HPSDRModel.ANAN100B:
		{
			ComboBox.ObjectCollection items11 = comboPreamp.Items;
			object[] items2 = on_off_preamp_settings;
			items11.AddRange(items2);
			ComboBox.ObjectCollection items12 = comboPreamp.Items;
			items2 = alex_preamp_settings;
			items12.AddRange(items2);
			break;
		}
		case HPSDRModel.ANAN100D:
		case HPSDRModel.ANAN200D:
		case HPSDRModel.REDPITAYA:
			if (alexpresent)
			{
				ComboBox.ObjectCollection items3 = comboPreamp.Items;
				object[] items2 = on_off_preamp_settings;
				items3.AddRange(items2);
				ComboBox.ObjectCollection items4 = comboPreamp.Items;
				items2 = alex_preamp_settings;
				items4.AddRange(items2);
			}
			else
			{
				ComboBox.ObjectCollection items5 = comboPreamp.Items;
				object[] items2 = anan100d_preamp_settings;
				items5.AddRange(items2);
			}
			break;
		case HPSDRModel.ORIONMKII:
		case HPSDRModel.ANAN7000D:
		case HPSDRModel.ANAN8000D:
		case HPSDRModel.ANAN_G2:
		case HPSDRModel.ANAN_G2_1K:
		case HPSDRModel.ANVELINAPRO3:
		case HPSDRModel.ANAN_G2E:
		{
			ComboBox.ObjectCollection items = comboPreamp.Items;
			object[] items2 = anan100d_preamp_settings;
			items.AddRange(items2);
			break;
		}
		}
		comboRX2Preamp.Items.Clear();
		if (HardwareSpecific.Model == HPSDRModel.ANAN100D || HardwareSpecific.Model == HPSDRModel.ANAN200D || HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ORIONMKII || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.REDPITAYA)
		{
			ComboBox.ObjectCollection items14 = comboRX2Preamp.Items;
			object[] items2 = anan100d_preamp_settings;
			items14.AddRange(items2);
		}
		else
		{
			ComboBox.ObjectCollection items15 = comboRX2Preamp.Items;
			object[] items2 = on_off_preamp_settings;
			items15.AddRange(items2);
		}
		RX2PreampMode = rx2_preamp_by_band[(int)rx2_band];
		comboRX2Preamp_SelectedIndexChanged(this, EventArgs.Empty);
		RX2AttenuatorData = getRX2stepAttenuatorForBand(rx2_band);
		RX1PreampMode = rx1_preamp_by_band[(int)rx1_band];
		comboPreamp_SelectedIndexChanged(this, EventArgs.Empty);
		RX1AttenuatorData = getRX1stepAttenuatorForBand(rx1_band);
	}

	private void MakeLineInList()
	{
		int num = 0;
		for (double num2 = -34.5; num2 <= 12.0; num2 += 1.5)
		{
			string text = num2.ToString();
			lineinboost[num] = text;
			num++;
		}
		lineinarrayfill = true;
	}

	public void SetMicXlr()
	{
		NetworkIO.SetMicXlr(mic_xlr ? 1 : 0);
	}

	public void SetMicGain()
	{
		NetworkIO.SetMicBoost(mic_boost ? 1 : 0);
		NetworkIO.SetLineIn(line_in ? 1 : 0);
		if (!lineinarrayfill)
		{
			MakeLineInList();
		}
		NetworkIO.SetLineBoost(Array.IndexOf(lineinboost, line_in_boost.ToString()));
	}

