			{
				modeDependentSettingsForm.Close();
				_modeDependentSettingsFormAutoClosedWhenExpanded = true;
			}
			else
			{
				_modeDependentSettingsFormAutoClosedWhenExpanded = false;
			}
			_isexpanded = true;
			_iscollapsed = false;
			updateAttNudsCombos();
			updateLegacyMeterControls(expanded: true);
			SelectModeDependentPanel();
			setPAProfileLabelPos();
			LegacyItemController.Update();
			if (bSuspendDraw)
			{
				ResumeDrawing(this);
			}
			Text = BasicTitleBar;
		}
	}

	private void setPAProfileLabelPos()
	{
		int num = -1;
		int num2 = -1;
		if (!_iscollapsed && _isexpanded)
		{
			num = panelModeSpecificPhone.Left + 4;
			num2 = panelModeSpecificPhone.Bottom - lblPAProfile.Height - 6;
		}
		else if (_iscollapsed && !_isexpanded && (_showAndromedaTopControls || m_bShowTopControls))
		{
			PictureBox obj = (show_rx1 ? picMultiMeterDigital : picRX2Meter);
			num = obj.Left;
			num2 = obj.Bottom + ((!m_bShowTopControls) ? 4 : 0);
		}
		if (num > -1 && num2 > -1)
		{
			lblPAProfile.Location = new Point(num, num2);
			lblPAProfile.Visible = true;
		}
		else
		{
			lblPAProfile.Visible = false;
		}
	}

