	private void mnuDSP_Click(object sender, EventArgs e)
	{
		if (sender == null || sender.GetType() != typeof(ToolStripMenuItem))
		{
			return;
		}
		string text = ((ToolStripMenuItem)sender).Text;
		if (text == null)
		{
			return;
		}
		switch (text.Length)
		{
		case 2:
			switch (text[1])
			{
			case 'R':
				if (text == "NR")
				{
					bool flag4 = _nr_selected[0] == 1;
					SelectNR(1, incude_sub: true, (!flag4) ? 1 : 0);
				}
				break;
			case 'B':
				if (text == "NB")
				{
					if (chkNB.CheckState == CheckState.Unchecked || chkNB.CheckState == CheckState.Indeterminate)
					{
						chkNB.CheckState = CheckState.Checked;
					}
					else if (chkNB.CheckState == CheckState.Checked)
					{
						chkNB.CheckState = CheckState.Unchecked;
					}
				}
				break;
			}
			break;
		case 3:
			switch (text[2])
			{
			case '2':
				if (!(text == "NR2"))
				{
					if (text == "NB2")
					{
						if (chkNB.CheckState == CheckState.Unchecked || chkNB.CheckState == CheckState.Checked)
						{
							chkNB.CheckState = CheckState.Indeterminate;
						}
						else if (chkNB.CheckState == CheckState.Indeterminate)
						{
							chkNB.CheckState = CheckState.Unchecked;
						}
					}
				}
				else
				{
					bool flag3 = _nr_selected[0] == 2;
					SelectNR(1, incude_sub: true, (!flag3) ? 2 : 0);
				}
				break;
			case '3':
				if (text == "NR3")
				{
					bool flag = _nr_selected[0] == 3;
					SelectNR(1, incude_sub: true, (!flag) ? 3 : 0);
				}
				break;
			case '4':
				if (text == "NR4")
				{
					bool flag2 = _nr_selected[0] == 4;
					SelectNR(1, incude_sub: true, (!flag2) ? 4 : 0);
				}
				break;
			case 'F':
				if (text == "ANF")
				{
					chkANF.Checked = !chkANF.Checked;
				}
				break;
			case 'B':
				if (text == "SNB")
				{
					chkDSPNB2.Checked = !chkDSPNB2.Checked;
				}
				break;
			case 'N':
				if (text == "BIN")
				{
					chkBIN.Checked = !chkBIN.Checked;
				}
				break;
			case 'G':
				if (text == "AVG")
				{
					chkDisplayAVG.Checked = !chkDisplayAVG.Checked;
				}
				break;
			}
			break;
		case 8:
			if (text == "Multi-RX")
			{
				chkEnableMultiRX.Checked = !chkEnableMultiRX.Checked;
			}
			break;
		case 4:
			if (text == "Peak")
			{
				chkDisplayPeak.Checked = !chkDisplayPeak.Checked;
			}
			break;
		case 5:
		case 6:
		case 7:
			break;
		}
	}

	private void mnuDSPRX2_Click(object sender, EventArgs e)
	{
		if (sender == null || sender.GetType() != typeof(ToolStripMenuItem))
		{
			return;
		}
		string text = ((ToolStripMenuItem)sender).Text;
		if (text == null)
		{
			return;
		}
		switch (text.Length)
		{
		case 2:
			switch (text[1])
			{
			case 'R':
				if (text == "NR")
				{
					bool flag = _nr_selected[1] == 1;
					SelectNR(2, incude_sub: true, (!flag) ? 1 : 0);
				}
				break;
			case 'B':
				if (text == "NB")
				{
					if (chkRX2NB.CheckState == CheckState.Unchecked || chkRX2NB.CheckState == CheckState.Indeterminate)
					{
						chkRX2NB.CheckState = CheckState.Checked;
					}
					else if (chkRX2NB.CheckState == CheckState.Checked)
					{
						chkRX2NB.CheckState = CheckState.Unchecked;
					}
				}
				break;
			}
			break;
		case 3:
			switch (text[2])
			{
			case '2':
				if (!(text == "NR2"))
				{
					if (text == "NB2")
					{
						if (chkRX2NB.CheckState == CheckState.Unchecked || chkRX2NB.CheckState == CheckState.Checked)
						{
							chkRX2NB.CheckState = CheckState.Indeterminate;
						}
						else if (chkRX2NB.CheckState == CheckState.Indeterminate)
						{
							chkRX2NB.CheckState = CheckState.Unchecked;
						}
					}
				}
				else
				{
					bool flag4 = _nr_selected[1] == 2;
					SelectNR(2, incude_sub: true, (!flag4) ? 2 : 0);
				}
				break;
			case '3':
				if (text == "NR3")
				{
					bool flag2 = _nr_selected[1] == 3;
					SelectNR(2, incude_sub: true, (!flag2) ? 3 : 0);
				}
				break;
			case '4':
				if (text == "NR4")
				{
					bool flag3 = _nr_selected[1] == 4;
					SelectNR(2, incude_sub: true, (!flag3) ? 4 : 0);
				}
				break;
			case 'F':
				if (text == "ANF")
				{
					chkRX2ANF.Checked = !chkRX2ANF.Checked;
				}
				break;
			case 'N':
				if (text == "BIN")
				{
					chkRX2BIN.Checked = !chkRX2BIN.Checked;
				}
				break;
			case 'B':
				if (text == "SNB")
				{
					chkRX2NB2.Checked = !chkRX2NB2.Checked;
				}
				break;
			case 'G':
				if (text == "AVG")
				{
					chkRX2DisplayAVG.Checked = !chkRX2DisplayAVG.Checked;
				}
				break;
			}
			break;
		case 4:
			if (text == "Peak")
			{
				chkRX2DisplayPeak.Checked = !chkRX2DisplayPeak.Checked;
			}
			break;
		}
	}

