	private void showHideDiversity(bool show, bool starting_up = false)
	{
		if (!RX2PreampPresent)
		{
			return;
		}
		if (diversityForm == null || diversityForm.IsDisposed)
		{
			diversityForm = new DiversityForm(this);
		}
		if (diversityForm.InvokeRequired)
		{
			diversityForm.Invoke((MethodInvoker)delegate
			{
				if (show)
				{
					if (starting_up)
					{
						diversityForm.Opacity = 0.0;
						Common.FadeIn(diversityForm);
					}
					else
					{
						diversityForm.Opacity = 100.0;
					}
					diversityForm.Show();
					diversityForm.Focus();
					UpdateDiversityValues();
					UpdateDiversityMenuItem();
				}
				else
				{
					diversityForm.Close();
				}
			});
		}
		else if (show)
		{
			if (starting_up)
			{
				diversityForm.Opacity = 0.0;
				Common.FadeIn(diversityForm);
			}
			else
			{
				diversityForm.Opacity = 100.0;
			}
			diversityForm.Show();
			diversityForm.Focus();
			UpdateDiversityValues();
			UpdateDiversityMenuItem();
		}
		else
		{
			diversityForm.Close();
		}
	}

