	public void SetFocusMaster(bool state)
	{
		if (n1mm_delay == null)
		{
			return;
		}
		if (state)
		{
			if (n1mm_state == 1)
			{
				n1mm_state = 3;
				ToggleFocusMasterTimer();
			}
		}
		else if (n1mm_state == 0)
		{
			n1mm_state = 1;
		}
		else if (n1mm_state == 3)
		{
			n1mm_state = 1;
			n1mm_delay.Enabled = false;
		}
	}

