	private void nr_selected_from_text(string text)
	{
		if (string.IsNullOrEmpty(text))
		{
			return;
		}
		string[] array = text.Split('|');
		int num = Math.Min(array.Length, _nr_selected.Length);
		for (int i = 0; i < num; i++)
		{
			_nr_selected[i] = 0;
		}
		for (int j = 0; j < num; j++)
		{
			if (int.TryParse(array[j], out var result))
			{
				_nr_selected[j] = result;
			}
		}
		for (int k = 0; k < _nr_selected.Length; k++)
		{
			setupNR(k + 1, sub: false);
			setupNR(k + 1, sub: true);
		}
	}

	private string nr_selected_to_text()
	{
		string text = "";
		for (int i = 0; i < _nr_selected.Length; i++)
		{
			text = text + _nr_selected[i] + "|";
		}
		if (text.EndsWith("|"))
		{
			text = text.Substring(0, text.Length - 1);
		}
		return text;
	}

	private void incrementNR(int rx)
	{
		if (rx >= 1 && rx <= 2)
		{
			int num = _nr_selected[rx - 1];
			_nr_selected[rx - 1]++;
			if (_nr_selected[rx - 1] > 4)
			{
				_nr_selected[rx - 1] = 0;
			}
			setupNR(rx, sub: false);
			setupNR(rx, sub: true);
			if (_nr_selected[rx - 1] != num)
			{
				NRChangedHandlers?.Invoke(rx, num, _nr_selected[rx - 1]);
			}
		}
	}

	public void SelectNR(int rx, bool incude_sub, int nr)
	{
		if (rx >= 1 && rx <= 2 && nr >= 0 && nr <= 4)
		{
			int num = _nr_selected[rx - 1];
			_nr_selected[rx - 1] = nr;
			setupNR(rx, sub: false);
			if (incude_sub)
			{
				setupNR(rx, sub: true);
			}
			if (_nr_selected[rx - 1] != num)
			{
				NRChangedHandlers?.Invoke(rx, num, _nr_selected[rx - 1]);
			}
		}
	}

	public int GetSelectedNR(int rx)
	{
		if (rx < 1 || rx > 2)
		{
			return -1;
		}
		return _nr_selected[rx - 1];
	}

	private void setupNR(int rx, bool sub)
	{
		if (rx < 1 || rx > 2)
		{
			return;
		}
		RadioDSPRX dSPRX = radio.GetDSPRX(rx - 1, sub ? 1 : 0);
		nR2ToolStripMenuItem.Checked = false;
		NR2StripMenuItem2.Checked = false;
		cat_rx2_nr_status = 0;
		cat_rx2_nr2_status = 0;
		int num = _nr_selected[rx - 1];
		if (num < 0)
		{
			num = 0;
		}
		if (num > 4)
		{
			num = 4;
		}
		switch (num)
		{
		case 0:
			dSPRX.RXANR4Run = 0;
			dSPRX.RXANR3Run = 0;
			dSPRX.RXANR2Run = 0;
			dSPRX.RXANR1Run = 0;
			switch (rx)
			{
			case 1:
				cat_nr_status = 0;
				cat_nr2_status = 0;
				NRToolStripMenuItem.Checked = false;
				NR2ToolStripMenuItem1.Checked = false;
				NR3ToolStripMenuItem.Checked = false;
				NR4ToolStripMenuItem.Checked = false;
				chkNR.Text = "NR";
				lblNRLabel.Text = "---";
				chkNR.Checked = false;
				break;
			case 2:
				cat_rx2_nr_status = 0;
				cat_rx2_nr2_status = 0;
				nR2ToolStripMenuItem.Checked = false;
				NR2StripMenuItem2.Checked = false;
				NR3ToolStripMenuItem_rx2.Checked = false;
				NR4ToolStripMenuItem_rx2.Checked = false;
				chkRX2NR.Text = "NR";
				lblRX2NRLabel.Text = "---";
				chkRX2NR.Checked = false;
				break;
			}
			break;
		case 1:
			dSPRX.RXANR4Run = 0;
			dSPRX.RXANR3Run = 0;
			dSPRX.RXANR2Run = 0;
			dSPRX.RXANR1Run = 1;
			switch (rx)
			{
			case 1:
				cat_nr_status = 1;
				cat_nr2_status = 0;
				NRToolStripMenuItem.Checked = true;
				NR2ToolStripMenuItem1.Checked = false;
				NR3ToolStripMenuItem.Checked = false;
				NR4ToolStripMenuItem.Checked = false;
				chkNR.Text = "NR";
				lblNRLabel.Text = "NR";
				chkNR.Checked = true;
				break;
			case 2:
				cat_rx2_nr_status = 1;
				cat_rx2_nr2_status = 0;
				nR2ToolStripMenuItem.Checked = true;
				NR2StripMenuItem2.Checked = false;
				NR3ToolStripMenuItem_rx2.Checked = false;
				NR4ToolStripMenuItem_rx2.Checked = false;
				chkRX2NR.Text = "NR";
				lblRX2NRLabel.Text = "NR";
				chkRX2NR.Checked = true;
				break;
			}
			break;
		case 2:
			dSPRX.RXANR4Run = 0;
			dSPRX.RXANR3Run = 0;
			dSPRX.RXANR1Run = 0;
			dSPRX.RXANR2Run = 1;
			switch (rx)
			{
			case 1:
				cat_nr_status = 0;
				cat_nr2_status = 1;
				NRToolStripMenuItem.Checked = false;
				NR2ToolStripMenuItem1.Checked = true;
				NR3ToolStripMenuItem.Checked = false;
				NR4ToolStripMenuItem.Checked = false;
				chkNR.Text = "NR2";
				lblNRLabel.Text = "NR2";
				chkNR.Checked = true;
				break;
			case 2:
				cat_rx2_nr_status = 0;
				cat_rx2_nr2_status = 1;
				nR2ToolStripMenuItem.Checked = false;
				NR2StripMenuItem2.Checked = true;
				NR3ToolStripMenuItem_rx2.Checked = false;
				NR4ToolStripMenuItem_rx2.Checked = false;
				chkRX2NR.Text = "NR2";
				lblRX2NRLabel.Text = "NR2";
				chkRX2NR.Checked = true;
				break;
			}
			break;
		case 3:
			dSPRX.RXANR4Run = 0;
			dSPRX.RXANR2Run = 0;
			dSPRX.RXANR1Run = 0;
			dSPRX.RXANR3Run = 1;
			switch (rx)
			{
			case 1:
				cat_nr_status = 0;
				cat_nr2_status = 0;
				NRToolStripMenuItem.Checked = false;
				NR2ToolStripMenuItem1.Checked = false;
				NR3ToolStripMenuItem.Checked = true;
				NR4ToolStripMenuItem.Checked = false;
				chkNR.Text = "NR3";
				lblNRLabel.Text = "NR3";
				chkNR.Checked = true;
				break;
			case 2:
				cat_rx2_nr_status = 0;
				cat_rx2_nr2_status = 0;
				nR2ToolStripMenuItem.Checked = false;
				NR2StripMenuItem2.Checked = false;
				NR3ToolStripMenuItem_rx2.Checked = true;
				NR4ToolStripMenuItem_rx2.Checked = false;
				chkRX2NR.Text = "NR3";
				lblRX2NRLabel.Text = "NR3";
				chkRX2NR.Checked = true;
				break;
			}
			break;
		case 4:
			dSPRX.RXANR3Run = 0;
			dSPRX.RXANR2Run = 0;
			dSPRX.RXANR1Run = 0;
			dSPRX.RXANR4Run = 1;
			switch (rx)
			{
			case 1:
				cat_nr_status = 0;
				cat_nr2_status = 0;
				NRToolStripMenuItem.Checked = false;
				NR2ToolStripMenuItem1.Checked = false;
				NR3ToolStripMenuItem.Checked = false;
				NR4ToolStripMenuItem.Checked = true;
				chkNR.Text = "NR4";
				lblNRLabel.Text = "NR4";
				chkNR.Checked = true;
				break;
			case 2:
				cat_rx2_nr_status = 0;
				cat_rx2_nr2_status = 0;
				nR2ToolStripMenuItem.Checked = false;
				NR2StripMenuItem2.Checked = false;
				NR3ToolStripMenuItem_rx2.Checked = false;
				NR4ToolStripMenuItem_rx2.Checked = true;
				chkRX2NR.Text = "NR4";
				lblRX2NRLabel.Text = "NR4";
				chkRX2NR.Checked = true;
				break;
			}
			break;
		}
		AndromedaIndicatorCheck(EIndicatorActions.eINNR, rx == 1, _nr_selected[rx - 1] > 0);
	}

