	private void chkNB_CheckStateChanged(object sender, EventArgs e)
	{
		switch (chkNB.CheckState)
		{
		case CheckState.Checked:
			specRX.GetSpecRX(0).NB2On = false;
			specRX.GetSpecRX(0).NBOn = true;
			NB2ToolStripMenuItem.Checked = false;
			NBToolStripMenuItem.Checked = true;
			cat_nb1_status = 1;
			cat_nb2_status = 0;
			chkNB.Text = "NB";
			lblNBLabel.Text = "NB";
			break;
		case CheckState.Indeterminate:
			specRX.GetSpecRX(0).NBOn = false;
			specRX.GetSpecRX(0).NB2On = true;
			NBToolStripMenuItem.Checked = false;
			NB2ToolStripMenuItem.Checked = true;
			cat_nb1_status = 0;
			cat_nb2_status = 1;
			chkNB.Text = "NB2";
			lblNBLabel.Text = "NB2";
			break;
		case CheckState.Unchecked:
			specRX.GetSpecRX(0).NBOn = false;
			specRX.GetSpecRX(0).NB2On = false;
			NB2ToolStripMenuItem.Checked = false;
			NBToolStripMenuItem.Checked = false;
			cat_nb1_status = 0;
			cat_nb2_status = 0;
			chkNB.Text = "NB";
			lblNBLabel.Text = "--";
			break;
		}
		cmaster.CMSetFRXNBRun(0);
		cmaster.CMSetFRXNB2Run(0);
		AndromedaIndicatorCheck(EIndicatorActions.eINNB, IsRX1: true, chkNB.CheckState != CheckState.Unchecked);
		if (_old_nb_state_changed[0] != chkNB.CheckState)
		{
			int old_nb = ((_old_nb_state_changed[0] == CheckState.Checked) ? 1 : ((_old_nb_state_changed[0] == CheckState.Indeterminate) ? 2 : 0));
			int new_nb = ((chkNB.CheckState == CheckState.Checked) ? 1 : ((chkNB.CheckState == CheckState.Indeterminate) ? 2 : 0));
			NBChangedHandlers?.Invoke(1, old_nb, new_nb);
			_old_nb_state_changed[0] = chkNB.CheckState;
		}
	}

	private void chkRX2NB_CheckStateChanged(object sender, EventArgs e)
	{
		switch (chkRX2NB.CheckState)
		{
		case CheckState.Checked:
			specRX.GetSpecRX(1).NB2On = false;
			specRX.GetSpecRX(1).NBOn = true;
			nB2ToolStripMenuItem1.Checked = true;
			nBRX2ToolStripMenuItem.Checked = false;
			cat_rx2nb1_status = 1;
			cat_rx2nb2_status = 0;
			chkRX2NB.Text = "NB";
			lblRX2NBLabel.Text = "NB";
			break;
		case CheckState.Indeterminate:
			specRX.GetSpecRX(1).NBOn = false;
			specRX.GetSpecRX(1).NB2On = true;
			nBRX2ToolStripMenuItem.Checked = true;
			nB2ToolStripMenuItem1.Checked = false;
			cat_rx2nb1_status = 0;
			cat_rx2nb2_status = 1;
			chkRX2NB.Text = "NB2";
			lblRX2NBLabel.Text = "NB2";
			break;
		case CheckState.Unchecked:
			specRX.GetSpecRX(1).NBOn = false;
			specRX.GetSpecRX(1).NB2On = false;
			nB2ToolStripMenuItem1.Checked = false;
			nBRX2ToolStripMenuItem.Checked = false;
			cat_rx2nb1_status = 0;
			cat_rx2nb2_status = 0;
			chkRX2NB.Text = "NB";
			lblRX2NBLabel.Text = "--";
			break;
		}
		cmaster.CMSetFRXNBRun(1);
		cmaster.CMSetFRXNB2Run(1);
		AndromedaIndicatorCheck(EIndicatorActions.eINNB, IsRX1: false, chkRX2NB.CheckState != CheckState.Unchecked);
		if (_old_nb_state_changed[1] != chkRX2NB.CheckState)
		{
			int old_nb = ((_old_nb_state_changed[1] == CheckState.Checked) ? 1 : ((_old_nb_state_changed[1] == CheckState.Indeterminate) ? 2 : 0));
			int new_nb = ((chkRX2NB.CheckState == CheckState.Checked) ? 1 : ((chkRX2NB.CheckState == CheckState.Indeterminate) ? 2 : 0));
			NBChangedHandlers?.Invoke(2, old_nb, new_nb);
			_old_nb_state_changed[1] = chkRX2NB.CheckState;
		}
	}

