	[DllImport("gdi32.dll", ExactSpelling = true)]
	private static extern IntPtr AddFontMemResourceEx(byte[] pbFont, int cbFont, IntPtr pdv, out uint pcFonts);

	public static Font GetCustomFont(byte[] fontData, float size, FontStyle style)
	{
		if (_fontCollections == null)
		{
			_fontCollections = new List<PrivateFontCollection>();
		}
		PrivateFontCollection privateFontCollection = new PrivateFontCollection();
		IntPtr intPtr = Marshal.AllocCoTaskMem(fontData.Length);
		AddFontMemResourceEx(fontData, fontData.Length, IntPtr.Zero, out var _);
		Marshal.Copy(fontData, 0, intPtr, fontData.Length);
		privateFontCollection.AddMemoryFont(intPtr, fontData.Length);
		Marshal.FreeCoTaskMem(intPtr);
		_fontCollections.Add(privateFontCollection);
		return new Font(privateFontCollection.Families[0], size, style);
	}

	public static Font GetCustomFont(string fontFile, float size, FontStyle style)
	{
		if (_fontCollections == null)
		{
			_fontCollections = new List<PrivateFontCollection>();
		}
		PrivateFontCollection privateFontCollection = new PrivateFontCollection();
		privateFontCollection.AddFontFile(fontFile);
		_fontCollections.Add(privateFontCollection);
		return new Font(privateFontCollection.Families[0], size, style);
	}

