	private void OnKeyPressedRaw(object sender, RawInputEventArg e)
	{
		bool keyPressState = e.KeyPressEvent.KeyPressState;
		Keys vKey = (Keys)e.KeyPressEvent.VKey;
		if (keyPressState)
		{
			bool flag = _keyPressed.TryGetValue(vKey, out var value);
			if (!value)
			{
				GlobalKeyPressDownHandlers?.Invoke(vKey);
				if (!flag)
				{
					_keyPressed.TryAdd(vKey, value: true);
				}
			}
		}
		else
		{
			_keyPressed.TryRemove(vKey, out var value2);
			if (value2)
			{
				GlobalKeyPressUpHandlers?.Invoke(vKey);
			}
		}
	}

	private void OnMouseWheelChanged(object sender, RawInputEventArg e)
	{
		if (m_bAlsoUseSpecificMouseWheel && e.MouseEvent.DeviceName == m_sSpecificMouseDeviceID)
		{
			m_objRawinput.IgnoreNextWheelEvent = m_bWheelOnlyAdjustsVFO;
			if (!IsSetupFormNull && SetupForm.Visible)
			{
				SetupForm.WheelChangeNotify();
			}
			enableOutsideSpectral();
			Console_MouseWheel(this, new MouseEventArgs(MouseButtons.None, 0, 0, 0, e.MouseEvent.buttonData));
			restoreOutsideSpectral();
		}
	}

