	public void SetResolution(string resolutionString)
	{
		if (resolutionString.Length < 1)
		{
			return;
		}
		int result = 0;
		int result2 = 0;
		bool flag = false;
		if (resolutionString[resolutionString.Length - 1] == 'p')
		{
			switch (resolutionString)
			{
			case "720p":
				result = 1280;
				result2 = 720;
				break;
			case "1080p":
				result = 1920;
				result2 = 1080;
				break;
			case "1440p":
				result = 2560;
				result2 = 1440;
				break;
			case "2160p":
				result = 3840;
				result2 = 2160;
				break;
			default:
				result = 1280;
				result2 = 720;
				break;
			}
			flag = true;
		}
		else if (resolutionString.Contains(" x "))
		{
			int num = resolutionString.IndexOf("x");
			flag = int.TryParse(resolutionString.Substring(0, num - 1), out result);
			if (flag)
			{
				flag = int.TryParse(resolutionString.Substring(num + 2), out result2);
			}
		}
		if (flag)
		{
			Rectangle bounds = Screen.FromControl(this).Bounds;
			result = Math.Min(result, bounds.Width);
			result2 = Math.Min(result2, bounds.Height);
			if (base.WindowState == FormWindowState.Maximized)
			{
				base.WindowState = FormWindowState.Normal;
			}
			Size size = new Size(result, result2);
			if (m_bIncludeWindowBorders)
			{
				base.Size = size + DropShadowSize;
			}
			else
			{
				base.ClientSize = size;
			}
		}
	}

