	private bool checkVersions()
	{
		int num = -1;
		int num2 = -1;
		int num3 = -1;
		int num4 = -1;
		try
		{
			num = cmaster.GetCMVersion();
			if (num != 1040)
			{
				MessageBox.Show("Incorrect version of channelmaster.dll installed.", "Version error", MessageBoxButtons.OK, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			}
		}
		catch
		{
			MessageBox.Show("Could not find GetCMVersion() in channelmaster.dll .\nEnsure correct version installed.", "Version function error", MessageBoxButtons.OK, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
		}
		try
		{
			num2 = cmaster.GetCMasioVersion();
			if (num2 != 1020)
			{
				MessageBox.Show("Incorrect version of cmASIO.dll installed.", "Version error", MessageBoxButtons.OK, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
			}
		}
		catch
		{
			MessageBox.Show("Could not find GetCMasioVersion() in cmASIO.dll .\nEnsure correct version installed.", "Version function error", MessageBoxButtons.OK, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button1, (MessageBoxOptions)262144);
		}
		try
		{
			num3 = WDSP.GetWDSPVersion() * 10;
			if (num3 != 2000)
			{
				MessageBox.Show("Incorrect version of wdsp.dll installed.", "Version error", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
		}
		catch
		{
			MessageBox.Show("Could not find GetWDSPVersion() in wdsp.dll .\nEnsure correct version installed.", "Version function error", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
		}
		try
		{
			num4 = PA19.PA_GetVersion();
			int num5 = (num4 >> 16) & 0xFF;
			int num6 = (num4 >> 8) & 0xFF;
			int num7 = num4 & 0xFF;
			num4 = num5 * 100 + num6 * 10 + num7;
			if (num4 != 1970)
			{
				MessageBox.Show("Incorrect version of portaudio.dll installed.", "Version error", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
		}
		catch
		{
			MessageBox.Show("Could not find PA_GetVersion() in portaudio.dll .\nEnsure correct version installed.", "Version function error", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
		}
		if (num == 1040 && num2 == 1020 && num3 == 2000)
		{
			return num4 == 1970;
		}
		return false;
	}

