	private void getControl(Control cc, Point p, string sub)
	{
		Control childAtPoint = cc.GetChildAtPoint(p);
		if (childAtPoint == null)
		{
			m_sOverControlName = "";
		}
		else if (childAtPoint.GetType() == typeof(PanelTS) || childAtPoint.GetType() == typeof(GroupBoxTS) || childAtPoint.GetType() == typeof(ucQuickRecall))
		{
			if (!string.IsNullOrEmpty(sub))
			{
				getControl(childAtPoint, new Point(p.X - childAtPoint.Location.X, p.Y - childAtPoint.Location.Y), sub + " > " + childAtPoint.Name + " (" + childAtPoint.Size.Width + " x " + childAtPoint.Size.Height + ")");
			}
			else
			{
				getControl(childAtPoint, new Point(p.X - childAtPoint.Location.X, p.Y - childAtPoint.Location.Y), childAtPoint.Name + " (" + childAtPoint.Size.Width + " x " + childAtPoint.Size.Height + ")");
			}
		}
		else if (!string.IsNullOrEmpty(sub))
		{
			m_sOverControlName = sub + " > " + childAtPoint.Name + " (" + childAtPoint.Size.Width + " x " + childAtPoint.Size.Height + ")";
		}
		else
		{
			m_sOverControlName = childAtPoint.Name + " (" + childAtPoint.Size.Width + " x " + childAtPoint.Size.Height + ")";
		}
	}

	private void gmh_MouseMove(object sender, MouseEventArgs e)
	{
		if (EnableControlDebug)
		{
			string sOverControlName = m_sOverControlName;
			getControl(this, PointToClient(e.Location), "");
			if (m_sOverControlName != sOverControlName)
			{
				Display.DebugText = m_sOverControlName;
			}
		}
	}

	private void addDelegates()
	{
		m_frmNotchPopup.NotchDeleteEvent += onNotchDelete;
		m_frmNotchPopup.NotchBWChangedEvent += onBWChanged;
		m_frmNotchPopup.NotchActiveChangedEvent += onActiveChanged;
		m_frmSeqLog.ClearButtonEvent += onClearButton;
		BandPreChangeHandlers = (BandPreChange)Delegate.Combine(BandPreChangeHandlers, new BandPreChange(OnBandBeforeChangeHandler));
		BandChangeHandlers = (BandChanged)Delegate.Combine(BandChangeHandlers, new BandChanged(OnBandChangeHandler));
		ModeChangeHandlers = (ModeChanged)Delegate.Combine(ModeChangeHandlers, new ModeChanged(OnModeChangeHandler));
		VFOAFrequencyChangeHandlers = (VFOAFrequencyChanged)Delegate.Combine(VFOAFrequencyChangeHandlers, new VFOAFrequencyChanged(OnVFOAFrequencyChangeHandler));
		VFOBFrequencyChangeHandlers = (VFOBFrequencyChanged)Delegate.Combine(VFOBFrequencyChangeHandlers, new VFOBFrequencyChanged(OnVFOBFrequencyChangeHandler));
		MoxChangeHandlers = (MoxChanged)Delegate.Combine(MoxChangeHandlers, new MoxChanged(OnMoxChangeHandler));
		SetBandChangeHanders = (SetBandChanged)Delegate.Combine(SetBandChangeHanders, new SetBandChanged(OnSetBandChangeHander));
		PowerChangeHanders = (PowerChanged)Delegate.Combine(PowerChangeHanders, new PowerChanged(OnPowerChangeHander));
		CentreFrequencyHandlers = (CentreFrequencyChanged)Delegate.Combine(CentreFrequencyHandlers, new CentreFrequencyChanged(OnCentreFrequencyChanged));
		CTUNChangedHandlers = (CTUNChanged)Delegate.Combine(CTUNChangedHandlers, new CTUNChanged(OnCTUNChanged));
		FilterChangedHandlers = (FilterChanged)Delegate.Combine(FilterChangedHandlers, new FilterChanged(OnFilterChanged));
		ZoomFactorChangedHandlers = (ZoomFactorChanged)Delegate.Combine(ZoomFactorChangedHandlers, new ZoomFactorChanged(OnZoomChanged));
		VFOTXChangedHandlers = (VFOTXChanged)Delegate.Combine(VFOTXChangedHandlers, new VFOTXChanged(OnVFOTXChanged));
		TXInhibitChangedHandlers = (TXInhibitChanged)Delegate.Combine(TXInhibitChangedHandlers, new TXInhibitChanged(OnTXInhibitChanged));
		FilterEdgesChangedHandlers = (FilterEdgesChanged)Delegate.Combine(FilterEdgesChangedHandlers, new FilterEdgesChanged(OnFilterEdgesChanged));
		SampleRateChangedHandlers = (SampleRateChanged)Delegate.Combine(SampleRateChangedHandlers, new SampleRateChanged(OnSampleRateChanged));
		FSPChangedHandlers = (FSPChanged)Delegate.Combine(FSPChangedHandlers, new FSPChanged(OnFSPChanged));
		Display.SetupDelegates();
		TimeOutTimerManager.SetCallback(timeOutTimer);
		MessageFloodControl.SendMessage += on_send_floodcontrol_message;
	}

	private void removeDelegates()
	{
		m_frmNotchPopup.NotchDeleteEvent -= onNotchDelete;
		m_frmNotchPopup.NotchBWChangedEvent -= onBWChanged;
		m_frmNotchPopup.NotchActiveChangedEvent -= onActiveChanged;
		m_frmSeqLog.ClearButtonEvent -= onClearButton;
		BandPreChangeHandlers = (BandPreChange)Delegate.Remove(BandPreChangeHandlers, new BandPreChange(OnBandBeforeChangeHandler));
		BandChangeHandlers = (BandChanged)Delegate.Remove(BandChangeHandlers, new BandChanged(OnBandChangeHandler));
		ModeChangeHandlers = (ModeChanged)Delegate.Remove(ModeChangeHandlers, new ModeChanged(OnModeChangeHandler));
		VFOAFrequencyChangeHandlers = (VFOAFrequencyChanged)Delegate.Remove(VFOAFrequencyChangeHandlers, new VFOAFrequencyChanged(OnVFOAFrequencyChangeHandler));
		VFOBFrequencyChangeHandlers = (VFOBFrequencyChanged)Delegate.Remove(VFOBFrequencyChangeHandlers, new VFOBFrequencyChanged(OnVFOBFrequencyChangeHandler));
		MoxChangeHandlers = (MoxChanged)Delegate.Remove(MoxChangeHandlers, new MoxChanged(OnMoxChangeHandler));
		SetBandChangeHanders = (SetBandChanged)Delegate.Remove(SetBandChangeHanders, new SetBandChanged(OnSetBandChangeHander));
		CentreFrequencyHandlers = (CentreFrequencyChanged)Delegate.Remove(CentreFrequencyHandlers, new CentreFrequencyChanged(OnCentreFrequencyChanged));
		CTUNChangedHandlers = (CTUNChanged)Delegate.Remove(CTUNChangedHandlers, new CTUNChanged(OnCTUNChanged));
		FilterChangedHandlers = (FilterChanged)Delegate.Remove(FilterChangedHandlers, new FilterChanged(OnFilterChanged));
		ZoomFactorChangedHandlers = (ZoomFactorChanged)Delegate.Remove(ZoomFactorChangedHandlers, new ZoomFactorChanged(OnZoomChanged));
		PowerChangeHanders = (PowerChanged)Delegate.Remove(PowerChangeHanders, new PowerChanged(OnPowerChangeHander));
		VFOTXChangedHandlers = (VFOTXChanged)Delegate.Remove(VFOTXChangedHandlers, new VFOTXChanged(OnVFOTXChanged));
		TXInhibitChangedHandlers = (TXInhibitChanged)Delegate.Remove(TXInhibitChangedHandlers, new TXInhibitChanged(OnTXInhibitChanged));
		FilterEdgesChangedHandlers = (FilterEdgesChanged)Delegate.Remove(FilterEdgesChangedHandlers, new FilterEdgesChanged(OnFilterEdgesChanged));
		SampleRateChangedHandlers = (SampleRateChanged)Delegate.Remove(SampleRateChangedHandlers, new SampleRateChanged(OnSampleRateChanged));
		FSPChangedHandlers = (FSPChanged)Delegate.Remove(FSPChangedHandlers, new FSPChanged(OnFSPChanged));
		if (m_frmBandStack2 != null)
		{
			frmBandStack2 bandStack2Form = BandStack2Form;
			bandStack2Form.EntrySelectedHandlers = (frmBandStack2.EntrySelected)Delegate.Remove(bandStack2Form.EntrySelectedHandlers, new frmBandStack2.EntrySelected(OnEntryClicked));
			frmBandStack2 bandStack2Form2 = BandStack2Form;
			bandStack2Form2.EntryAddHandlers = (frmBandStack2.EntryAdd)Delegate.Remove(bandStack2Form2.EntryAddHandlers, new frmBandStack2.EntryAdd(OnEntryAdd));
			frmBandStack2 bandStack2Form3 = BandStack2Form;
			bandStack2Form3.EntryDeleteHandlers = (frmBandStack2.EntryDelete)Delegate.Remove(bandStack2Form3.EntryDeleteHandlers, new frmBandStack2.EntryDelete(OnEntryDelete));
			frmBandStack2 bandStack2Form4 = BandStack2Form;
			bandStack2Form4.EntryUpdateHandlers = (frmBandStack2.EntryUpdate)Delegate.Remove(bandStack2Form4.EntryUpdateHandlers, new frmBandStack2.EntryUpdate(OnEntryUpdate));
			frmBandStack2 bandStack2Form5 = BandStack2Form;
			bandStack2Form5.IgnoreDupeHandlers = (frmBandStack2.IgnoreDupes)Delegate.Remove(bandStack2Form5.IgnoreDupeHandlers, new frmBandStack2.IgnoreDupes(OnIgnoreDupes));
			frmBandStack2 bandStack2Form6 = BandStack2Form;
			bandStack2Form6.HideOnSelectHandlers = (frmBandStack2.HideOnSelect)Delegate.Remove(bandStack2Form6.HideOnSelectHandlers, new frmBandStack2.HideOnSelect(OnHideOnSelect));
			frmBandStack2 bandStack2Form7 = BandStack2Form;
			bandStack2Form7.ShowInSpectrumHandlers = (frmBandStack2.HideOnSelect)Delegate.Remove(bandStack2Form7.ShowInSpectrumHandlers, new frmBandStack2.HideOnSelect(OnShowInSpectrum));
			m_frmBandStack2.RemoveDelegates();
		}
		Display.RemoveDelegates();
		TimeOutTimerManager.RemoveCallback(timeOutTimer);
		MessageFloodControl.SendMessage -= on_send_floodcontrol_message;
	}

	public void StopAllTx(string msg = "")
	{
		if (MOX || _manual_mox || chkTUN.Checked || chk2TONE.Checked)
		{
			_stop_all_tx = true;
			MOX = false;
			_manual_mox = false;
			if (chkTUN.Checked)
			{
				chkTUN.Checked = false;
			}
			if (chk2TONE.Checked)
			{
				chk2TONE.Checked = false;
			}
			if (!string.IsNullOrEmpty(msg))
			{
				infoBar.Warning(msg, red_warning: false, 10000);
			}
		}
	}

	private void timeOutTimer(string msg)
	{
		if (MOX || _manual_mox || chkTUN.Checked || chk2TONE.Checked)
		{
			StopAllTx(msg + " Time Out Timer");
		}
	}

	private void OnTXInhibitChanged(bool oldState, bool newState)
	{
		TXInhibit = newState;
	}

	private void OnVFOTXChanged(bool vfoB, bool oldState, bool newState)
	{
		if (KWAutoInformation)
		{
			BroadcastVFOChange(vfoB ? "1" : "0");
		}
	}

	private void OnIgnoreDupes(bool ignore)
	{
		m_bIgnoreFrequencyDupes = ignore;
	}

	private void OnHideOnSelect(bool hideOnSelect)
	{
		m_bHideBandstackWindowOnSelect = hideOnSelect;
	}

	private void OnShowInSpectrum(bool show)
	{
		m_bShowBandStackOverlays = show;
		Display.ShowBandStackOverlays = show;
		updateBandstackOverlay(1);
	}

	private void OnPowerChangeHander(bool oldPower, bool newPower)
	{
		if (newPower)
		{
			clearRXSignalPixels(1);
			if (RX2Enabled)
			{
				clearRXSignalPixels(2);
			}
			Text = BasicTitleBar;
		}
	}

	private void handleBSFChange(Band oldBand, Band newBand, DSPMode oldMode, DSPMode newMode, Filter oldFilter, Filter newFilter, double oldFreq, double newFreq, double oldCentreF, double newCentreF, bool oldCTUN, bool newCTUN, int oldZoomSlider, int newZoomSlider)
	{
		if (m_bSetBandRunning)
		{
			return;
		}
		BandStackFilter filter = BandStackManager.GetFilter(oldBand);
		if (filter != null && oldBand != newBand)
		{
			updateLastVisited(filter, oldBand, oldMode, oldFilter, oldFreq, oldCentreF, oldCTUN, oldZoomSlider);
			filter = BandStackManager.GetFilter(newBand);
			if (filter != null)
			{
				updateLastVisited(filter, newBand, newMode, newFilter, newFreq, newCentreF, newCTUN, newZoomSlider);
			}
		}
		filter = BandStackManager.GetFilter(newBand);
		if (filter != null && oldBand == newBand)
		{
			updateLastVisited(filter, newBand, newMode, newFilter, newFreq, newCentreF, newCTUN, newZoomSlider);
		}
		if (filter != null && newBand != oldBand)
		{
			BandStack2Form.InitBandStackFilter(filter);
			updateStackNumberDisplay(filter);
		}
		if (oldBand != newBand)
		{
			updateBandstackOverlay(1);
		}
	}

	private void updateLastVisited(BandStackFilter bsf, Band band, DSPMode mode, Filter filter, double freq, double centreF, bool cTUN, int zoomSlider)
	{
		if (bsf != null)
		{
			bsf.LastVisited.Band = band;
			bsf.LastVisited.Mode = mode;
			bsf.LastVisited.Filter = filter;
			bsf.LastVisited.Frequency = freq;
			bsf.LastVisited.CentreFrequency = centreF;
			bsf.LastVisited.CTUNEnabled = cTUN;
			bsf.LastVisited.ZoomSlider = zoomSlider;
		}
	}

	private void OnSetBandChangeHander(int rx, Band oldBand, Band newBand, DSPMode oldMode, DSPMode newMode, Filter oldFilter, Filter newFilter, double oldFreq, double newFreq, double oldCentreF, double newCentreF, bool oldCTUN, bool newCTUN, int oldZoomSlider, int newZoomSlider)
	{
		if (rx == 1)
		{
			handleBSFChange(oldBand, newBand, oldMode, newMode, oldFilter, newFilter, oldFreq, newFreq, oldCentreF, newCentreF, oldCTUN, newCTUN, oldZoomSlider, newZoomSlider);
		}
	}

	private void OnEntryAdd(BandStackFilter bsf)
	{
		if (BandStackManager.Ready)
		{
			BandStackEntry bandStackEntry = bsf.LastVisited.Copy(bNewGUID: true);
			if (!m_bIgnoreFrequencyDupes || bsf.FindEntriesForFrequency(bandStackEntry.Frequency).Count <= 0)
			{
				BandStackManager.AddEntry(bandStackEntry);
				bsf.GenerateFilteredList(bMaintainSelected: false);
				bsf.IndexOfCurrent = bsf.IndexFromGUID(bandStackEntry.GUID);
				BandStack2Form.InitBandStackFilter(bsf);
				updateStackNumberDisplay(bsf);
				updateBandstackOverlay(1);
			}
		}
	}

	private void OnEntryUpdate(BandStackFilter bsf, BandStackEntry bse)
	{
		if (BandStackManager.Ready && bsf.UpdateCurrentWithLastVisitedData(m_bIgnoreFrequencyDupes))
		{
			bsf.GenerateFilteredList(bMaintainSelected: false);
			bsf.IndexOfCurrent = bsf.IndexFromGUID(bse.GUID);
			BandStack2Form.InitBandStackFilter(bsf);
			updateStackNumberDisplay(bsf);
			updateBandstackOverlay(1);
		}
	}

	private void OnEntryDelete(BandStackFilter bsf, BandStackEntry bse)
	{
		if (BandStackManager.Ready)
		{
			BandStackManager.DeleteEntry(bse);
			bsf.GenerateFilteredList(bMaintainSelected: true);
			bsf.SelectInitial();
			BandStack2Form.InitBandStackFilter(bsf);
			updateStackNumberDisplay(bsf);
			BandStackEntry bandStackEntry = bsf.Current();
			if (bandStackEntry != null)
			{
				OnEntryClicked(bsf, bandStackEntry, updateLastVisited: true, obeyHide: false);
			}
			updateBandstackOverlay(1);
		}
	}

	private void OnCentreFrequencyChanged(int rx, double oldFreq, double newFreq, Band band, double offset)
	{
		if (rx == 1)
		{
			updateBandstackOverlay(rx);
		}
		if (_display_max_bin_enabled[rx - 1])
		{
			setupDisplayMaxBinDetect(rx, sub_rx: false, enabled: true);
		}
		if (!m_bSetBandRunning && rx == 1 && BandStackManager.Ready)
		{
			BandStackFilter filter = BandStackManager.GetFilter(band, bIncludeUserDefined: false);
			if (filter != null)
			{
				filter.LastVisited.CentreFrequency = newFreq;
			}
		}
	}

	private void OnCTUNChanged(int rx, bool oldCTUN, bool newCTUN, Band band)
	{
		if (_display_max_bin_enabled[rx - 1])
		{
			setupDisplayMaxBinDetect(rx, sub_rx: false, enabled: true);
		}
		if (!m_bSetBandRunning && rx == 1 && BandStackManager.Ready)
		{
			BandStackFilter filter = BandStackManager.GetFilter(band, bIncludeUserDefined: false);
			if (filter != null)
			{
				filter.LastVisited.CTUNEnabled = newCTUN;
			}
		}
	}

	private void OnFilterChanged(int rx, Filter oldFilter, Filter newFilter, Band band, int low, int high, string sName)
	{
		handleVfoSyncFilter(rx, newFilter);
		if (!m_bSetBandRunning && rx == 1 && BandStackManager.Ready)
		{
			BandStackFilter filter = BandStackManager.GetFilter(band, bIncludeUserDefined: false);
			if (filter != null)
			{
				filter.LastVisited.Filter = newFilter;
			}
			updateBandstackOverlay(1);
		}
	}

	private void updateBandstackOverlay(int rx)
	{
		if (!BandStackManager.Ready || rx != 1 || !m_bShowBandStackOverlays)
		{
			return;
		}
		BandStackFilter filter = BandStackManager.GetFilter(RX1Band, bIncludeUserDefined: false);
		if (filter != null)
		{
			double num = ((rx == 1) ? (Display.RXDisplayHigh - Display.RXDisplayLow) : (Display.RX2DisplayHigh - Display.RX2DisplayLow));
			double num2 = ((rx == 1) ? Display.CentreFreqRX1 : Display.CentreFreqRX2);
			double num3 = Math.Round(num2 - num / 2.0 * 1E-06, 6);
			double num4 = Math.Round(num2 + num / 2.0 * 1E-06, 6);
			num3 -= (double)_max_filter_width * 1E-06;
			num4 += (double)_max_filter_width * 1E-06;
			BandStackEntry[] array = filter.FindForFrequencyRange(num3, num4).ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				array[i].LowFilter = rx1_filters[(int)array[i].Mode].GetLow(array[i].Filter);
				array[i].HighFilter = rx1_filters[(int)array[i].Mode].GetHigh(array[i].Filter);
			}
			Display.BandStackOverlays = array;
		}
	}

	private void OnZoomChanged(double oldZoomFactor, double newZoomFactor, int sliderValue)
	{
		updateBandstackOverlay(1);
		if (!m_bSetBandRunning && BandStackManager.Ready)
		{
			BandStackFilter filter = BandStackManager.GetFilter(RX1Band, bIncludeUserDefined: false);
			if (filter != null)
			{
				filter.LastVisited.ZoomFactor = newZoomFactor;
				filter.LastVisited.ZoomSlider = sliderValue;
			}
		}
	}

	private void OnEntryClicked(BandStackFilter bsf, BandStackEntry bse, bool updateLastVisited = true, bool obeyHide = true)
	{
		if (!m_bSetBandRunning && BandStackManager.Ready)
		{
			bool flag = false;
			if (updateLastVisited)
			{
				flag = bsf.UpdateCurrentWithLastVisitedData(m_bIgnoreFrequencyDupes);
			}
			if (flag)
			{
				bsf.GenerateFilteredList(bMaintainSelected: false);
				bsf.IndexOfCurrent = bsf.IndexFromGUID(bse.GUID);
				BandStack2Form.InitBandStackFilter(bsf);
			}
			else
			{
				bsf.IndexOfCurrent = bsf.IndexFromGUID(bse.GUID);
				BandStack2Form.UpdateSelected();
			}
			if (m_bHideBandstackWindowOnSelect & obeyHide)
			{
				Invoke(new MethodInvoker(BandStack2Form.HideClose));
			}
			setRX1BandFromBandStackEntry(in bse);
			updateStackNumberDisplay(bsf);
		}
	}

	private void preBandSelect(int rx, Band band, int dir = 0)
	{
		if ((MOX && rx == 1 && (VFOATX || (!rx2_enabled && VFOBTX))) || (MOX && rx == 2 && VFOBTX) || m_bSetBandRunning || rx != 1 || !BandStackManager.Ready)
		{
			return;
		}
		BandStackFilter filter = BandStackManager.GetFilter(band, bIncludeUserDefined: false);
		if (filter != null)
		{
			BandStackEntry bse;
			if (RX1Band == band)
			{
				if (Common.CtrlKeyDown)
				{
					OnEntryAdd(filter);
					return;
				}
				filter.UpdateCurrentWithLastVisitedData(m_bIgnoreFrequencyDupes);
				bse = ((dir == 0) ? ((!Common.ShiftKeyDown) ? filter.Next() : filter.Previous()) : ((dir <= 0) ? filter.Previous() : filter.Next()));
				filter.GenerateFilteredList(bMaintainSelected: true);
				BandStack2Form.InitBandStackFilter(filter, select: false);
			}
			else
			{
				BandStackFilter filter2 = BandStackManager.GetFilter(RX1Band);
				if (filter2 != null)
				{
					filter2.UpdateCurrentWithLastVisitedData(m_bIgnoreFrequencyDupes);
					filter2.GenerateFilteredList(bMaintainSelected: true);
				}
				BandStack2Form.InitBandStackFilter(filter, select: false);
				bse = filter.SelectInitial();
			}
			if (bse == null)
			{
				bse = filter.LastVisited.Copy();
				bse.Band = band;
				List<BandFrequencyData> frequencyRangesForBand = BandStackManager.GetFrequencyRangesForBand(band, Extended, CurrentRegion);
				if (frequencyRangesForBand.Count > 0)
				{
					bse.CentreFrequency = frequencyRangesForBand.First().low + (frequencyRangesForBand.First().high - frequencyRangesForBand.First().low) / 2.0;
					bse.Frequency = bse.CentreFrequency;
				}
				else if (band >= Band.VHF0 && band <= Band.VHF13)
				{
					int index = (int)(band - 14);
					bse.CentreFrequency = XVTRForm.GetBegin(index) + (XVTRForm.GetEnd(index) - XVTRForm.GetBegin(index)) / 2f;
					bse.Frequency = bse.CentreFrequency;
				}
			}
			BandStack2Form.UpdateSelected();
			setRX1BandFromBandStackEntry(in bse);
		}
		updateStackNumberDisplay(filter);
	}

	private void OnBandBeforeChangeHandler(int rx, Band band)
	{
		preBandSelect(rx, band);
	}

	private void setRX1BandFromBandStackEntry(in BandStackEntry bse)
	{
		if ((!MOX || (!VFOATX && (rx2_enabled || !VFOBTX))) && bse != null)
		{
			NetworkIO.SendHighPriority(0);
			SetBand(bse.Mode.ToString(), bse.Filter.ToString(), bse.Frequency, bse.CTUNEnabled, bse.ZoomSlider, bse.CentreFrequency);
			UpdateWaterfallLevelValues();
			updateDisplayGridLevelValues();
			UpdateDiversityValues();
			NetworkIO.SendHighPriority(1);
		}
	}

	private void OnBandChangeHandler(int rx, Band oldBand, Band newBand)
	{
		if (rx == 1)
		{
			switch (BandStackManager.GetBandTypeForFrequency(VFOAFreq))
			{
			case BandType.GEN:
				setBandPanelVisible(gen: true, hf: false, vhf: false);
				break;
			case BandType.HF:
				setBandPanelVisible(gen: false, hf: true, vhf: false);
				break;
			case BandType.VHF:
				setBandPanelVisible(gen: false, hf: false, vhf: true);
				break;
			}
		}
		clearRXSignalPixels(rx);
		if (!m_bSetBandRunning && BandStackManager.Ready && rx == 1)
		{
			BandStackFilter filter = BandStackManager.GetFilter(oldBand, bIncludeUserDefined: false);
			if (filter != null)
			{
				filter.LastVisited.Band = oldBand;
			}
			filter = BandStackManager.GetFilter(newBand, bIncludeUserDefined: false);
			if (filter != null)
			{
				filter.LastVisited.Band = newBand;
				BandStack2Form.InitBandStackFilter(filter, select: false);
				filter.SelectInitial();
				BandStack2Form.UpdateSelected();
				updateStackNumberDisplay(filter);
			}
		}
	}

	private void OnModeChangeHandler(int rx, DSPMode oldMode, DSPMode newMode, Band oldBand, Band newBand)
	{
		if (newMode != DSPMode.CWL && newMode != DSPMode.CWU)
		{
			_old_cw_auto_mode = DSPMode.FIRST;
		}
		clearRXSignalPixels(rx);
		updateStepIndexForMode(rx, newMode);
		handleVfoSyncMode(rx, newMode);
		if (!m_bSetBandRunning && rx == 1 && BandStackManager.Ready)
		{
			BandStackFilter filter = BandStackManager.GetFilter(oldBand, bIncludeUserDefined: false);
			if (filter != null)
			{
				filter.LastVisited.Mode = oldMode;
			}
			filter = BandStackManager.GetFilter(newBand, bIncludeUserDefined: false);
			if (filter != null)
			{
				filter.LastVisited.Mode = newMode;
			}
		}
	}

	private void OnVFOAFrequencyChangeHandler(Band oldBand, Band newBand, DSPMode oldMode, DSPMode newMode, Filter oldFilter, Filter newFilter, double oldFreq, double newFreq, double oldCentreF, double newCentreF, bool oldCTUN, bool newCTUN, int oldZoomSlider, int newZoomSlider, double offset, int rx)
	{
		if (KWAutoInformation)
		{
			BroadcastFreqChange("A", newFreq);
		}
		handleBSFChange(oldBand, newBand, oldMode, newMode, oldFilter, newFilter, oldFreq, newFreq, oldCentreF, newCentreF, oldCTUN, newCTUN, oldZoomSlider, newZoomSlider);
		if (_display_max_bin_enabled[rx - 1] && rx == 1)
		{
			setupDisplayMaxBinDetect(rx, sub_rx: false, enabled: true);
		}
		handleVfoSyncFrequency(rx, b_to_a: false);
	}

	private void OnVFOBFrequencyChangeHandler(Band oldBand, Band newBand, DSPMode oldMode, DSPMode newMode, Filter oldFilter, Filter newFilter, double oldFreq, double newFreq, double oldCentreF, double newCentreF, bool oldCTUN, bool newCTUN, int oldZoomSlider, int newZoomSlider, double offset, int rx)
	{
		if (KWAutoInformation)
		{
			BroadcastFreqChange("B", newFreq);
		}
		if (_display_max_bin_enabled[rx - 1] && rx == 2)
		{
			setupDisplayMaxBinDetect(rx, sub_rx: false, enabled: true);
		}
		handleVfoSyncFrequency(rx, b_to_a: true);
	}

	private void OnMoxChangeHandler(int rx, bool oldMox, bool newMox)
	{
		if (newMox)
		{
			if (_display_max_bin_enabled[rx - 1])
			{
				setupDisplayMaxBinDetect(rx, sub_rx: false, enabled: false, update_enabled_state: false);
			}
		}
		else if (_display_max_bin_enabled[rx - 1])
		{
			setupDisplayMaxBinDetect(rx, sub_rx: false, enabled: true, update_enabled_state: false);
		}
		if (newMox)
		{
			chkExternalPA.Enabled = m_bHotSwitchOCTXPins;
		}
		else
		{
			chkExternalPA.Enabled = true;
		}
		updateOCTXPins(newMox);
		clearRXSignalPixels(1);
		if (RX2Enabled)
		{
			clearRXSignalPixels(2);
		}
	}

	private void updateStackNumberDisplay(BandStackFilter bsf)
	{
		if (!BandStackManager.Ready)
		{
			return;
		}
		if (bsf != null)
		{
			if (bsf.IndexOfCurrent == -1)
			{
				if (bsf.ReturnMode == BandStackFilter.FilterReturnMode.LastVisited)
				{
					regBandStackCurrentEntry.Text = "L";
				}
				else
				{
					regBandStackCurrentEntry.Text = "-";
				}
			}
			else
			{
				regBandStackCurrentEntry.Text = (bsf.IndexOfCurrent + 1).ToString();
			}
			regBandStackTotalEntries.Text = bsf.NumberOfEntries.ToString();
