	public unsafe void setAGCThresholdPoint(double agc_thresh_point, int rx)
	{
		float num = 0f;
		num = agcCalOffset(rx);
		agc_thresh_point -= (double)num;
		if (agc_thresh_point > 2.0)
		{
			agc_thresh_point = 2.0;
		}
		if (agc_thresh_point < -160.0)
		{
			agc_thresh_point = -160.0;
		}
		double num2 = 0.0;
		switch (rx)
		{
		case 1:
		{
			double size = specRX.GetSpecRX(0).FFTSize;
			WDSP.SetRXAAGCThresh(WDSP.id(0u, 0u), agc_thresh_point, size, sample_rate_rx1);
			WDSP.GetRXAAGCTop(WDSP.id(0u, 0u), &num2);
			break;
		}
		case 2:
		{
			double size = specRX.GetSpecRX(1).FFTSize;
			WDSP.SetRXAAGCThresh(WDSP.id(2u, 0u), agc_thresh_point, size, sample_rate_rx2);
			WDSP.GetRXAAGCTop(WDSP.id(2u, 0u), &num2);
			break;
		}
		}
		num2 = Math.Round(num2);
		if (num2 > 120.0)
		{
			num2 = 120.0;
		}
		if (num2 < -20.0)
		{
			num2 = -20.0;
		}
		if (((rx == 1) ? RX1AGCMode : RX2AGCMode) == AGCMode.FIXD)
		{
			if (!IsSetupFormNull)
			{
				switch (rx)
				{
				case 1:
					SetupForm.AGCFixedGain = (int)num2;
					break;
				case 2:
					SetupForm.AGCRX2FixedGain = (int)num2;
					break;
				}
			}
		}
		else if (!IsSetupFormNull)
		{
			switch (rx)
			{
			case 1:
				SetupForm.AGCMaxGain = (int)num2;
				break;
			case 2:
				SetupForm.AGCRX2MaxGain = (int)num2;
				break;
			}
		}
	}

	private void tmrAutoAGC_Tick(object sender, EventArgs e)
	{
		if (!chkPower.Checked || _mox)
		{
			return;
		}
		_lastRX1NoiseFloorGood = Display.IsNoiseFloorGoodRX1;
		_lastRX2NoiseFloorGood = Display.IsNoiseFloorGoodRX2;
		if (!_lastRX1NoiseFloorGood && !_lastRX2NoiseFloorGood)
		{
			return;
		}
		if (_lastRX1NoiseFloorGood)
		{
			_lastRX1NoiseFloor = Display.NoiseFloorRX1;
		}
		if (_lastRX2NoiseFloorGood)
		{
			_lastRX2NoiseFloor = Display.NoiseFloorRX2;
		}
		if (!IsSetupFormNull)
		{
			if (_lastRX1NoiseFloorGood && GridMinFollowsNFRX1 && (Display.CurrentDisplayMode == DisplayMode.PANADAPTER || Display.CurrentDisplayMode == DisplayMode.SPECTRUM || Display.CurrentDisplayMode == DisplayMode.PANAFALL || Display.CurrentDisplayMode == DisplayMode.PANASCOPE || Display.CurrentDisplayMode == DisplayMode.WATERFALL))
			{
				float num = _lastRX1NoiseFloor - _RX1NFoffsetGridFollow;
				float num2 = Math.Abs(SetupForm.DisplayGridMax - SetupForm.DisplayGridMin);
				if (Math.Abs(SetupForm.DisplayGridMin - num) >= 2f)
				{
					SetupForm.DisplayGridMin = num;
					if (_maintainNFAdjustDeltaRX1)
					{
						SetupForm.DisplayGridMax = num + num2;
					}
				}
			}
			if (_lastRX2NoiseFloorGood && RX2Enabled && GridMinFollowsNFRX2 && (Display.CurrentDisplayModeBottom == DisplayMode.PANADAPTER || Display.CurrentDisplayModeBottom == DisplayMode.SPECTRUM || Display.CurrentDisplayModeBottom == DisplayMode.PANAFALL || Display.CurrentDisplayModeBottom == DisplayMode.PANASCOPE || Display.CurrentDisplayModeBottom == DisplayMode.WATERFALL))
			{
				float num3 = _lastRX2NoiseFloor - _RX2NFoffsetGridFollow;
				float num4 = Math.Abs(SetupForm.RX2DisplayGridMax - SetupForm.RX2DisplayGridMin);
				if (Math.Abs(SetupForm.RX2DisplayGridMin - num3) >= 2f)
				{
					SetupForm.RX2DisplayGridMin = num3;
					if (_maintainNFAdjustDeltaRX2)
					{
						SetupForm.RX2DisplayGridMax = num3 + num4;
					}
				}
			}
		}
		if (m_bAutoAGCRX1 && _lastRX1NoiseFloorGood)
		{
			setAGCThresholdPoint((double)_lastRX1NoiseFloor + m_dAutoAGCOffsetRX1, 1);
		}
		if (m_bAutoAGCRX2 && _lastRX2NoiseFloorGood)
		{
			setAGCThresholdPoint((double)_lastRX2NoiseFloor + m_dAutoAGCOffsetRX2, 2);
		}
	}

