	public void ZoomToBand(bool bStore)
	{
		int num;
		Band band;
		double centreFrequency;
		if (RX2Enabled && Common.ShiftKeyDown)
		{
			num = 1;
			band = RX2Band;
			centreFrequency = CentreRX2Frequency;
		}
		else
		{
			num = 0;
			band = RX1Band;
			centreFrequency = CentreFrequency;
		}
		if (bStore && !m_bZTBstoreLock)
		{
			ztb_data_by_band[num][(int)band].CentreFrequency = centreFrequency;
			ztb_data_by_band[num][(int)band].ZoomSliderPosition = ptbDisplayZoom.Value;
			ztb_data_by_band[num][(int)band].PanSliderPosition = ptbDisplayPan.Value;
			ztb_data_by_band[num][(int)band].Initalised = true;
			return;
		}
		DSPMode dSPMode;
		bool flag;
		if (num == 1)
		{
			if (!chkX2TR.Checked)
			{
				chkX2TR.Checked = true;
			}
			dSPMode = RX2DSPMode;
			flag = chkX2TR.Checked;
		}
		else
		{
			if (!chkFWCATU.Checked)
			{
				chkFWCATU.Checked = true;
			}
			dSPMode = RX1DSPMode;
			flag = chkFWCATU.Checked;
		}
		if (m_bZTBisRecallStore)
		{
			ztb_data ztb_data2 = ztb_data_by_band[num][(int)band];
			if (!(ztb_data2.Initalised & flag))
			{
				return;
			}
			centreFrequency = ztb_data_by_band[num][(int)band].CentreFrequency;
			switch (dSPMode)
			{
			case DSPMode.CWL:
				centreFrequency -= (double)cw_pitch * 1E-06;
				break;
			case DSPMode.CWU:
				centreFrequency += (double)cw_pitch * 1E-06;
				break;
			}
			m_bIgnoreLimitsForZTB = true;
			if (Pan != ztb_data2.PanSliderPosition)
			{
				Pan = ztb_data2.PanSliderPosition;
			}
			if (Zoom != ztb_data2.ZoomSliderPosition)
			{
				Zoom = ztb_data2.ZoomSliderPosition;
			}
			if (num == 0)
			{
				if (CentreFrequency != centreFrequency)
				{
					CentreFrequency = centreFrequency;
					txtVFOAFreq_LostFocus(this, EventArgs.Empty);
				}
			}
			else if (CentreRX2Frequency != centreFrequency)
			{
				CentreRX2Frequency = centreFrequency;
				txtVFOBFreq_LostFocus(this, EventArgs.Empty);
			}
			m_bIgnoreLimitsForZTB = false;
		}
		else if (flag)
		{
			if (num == 0)
			{
				zoomToBandBandwidth(RX1Band, 1);
			}
			else
			{
				zoomToBandBandwidth(RX2Band, 2);
			}
		}
	}

