	public void UpdateTuneLabel(bool bShowLimitValue, EventArgs e)
	{
		if (IsSetupFormNull)
		{
			return;
		}
		string text = "Tu | 2T";
		if (_tuneDrivePowerSource == DrivePowerSource.TUNE_SLIDER && _2ToneDrivePowerSource != DrivePowerSource.TUNE_SLIDER)
		{
			text = "Tune";
		}
		if (_tuneDrivePowerSource != DrivePowerSource.TUNE_SLIDER && _2ToneDrivePowerSource == DrivePowerSource.TUNE_SLIDER)
		{
			text = "2Tone";
		}
		bool pABandUsesMaxPower = SetupForm.GetPABandUsesMaxPower(TXBand);
		int num;
		if (!bShowLimitValue)
		{
			num = ((!ptbTune.IsConstrained) ? ptbTune.Value : ptbTune.ConstrainedValue);
		}
		else
		{
			PrettyTrackBar.LimitConstraint obj = e as PrettyTrackBar.LimitConstraint;
			num = obj.LimitValue;
			if (obj.MouseWheel)
			{
				_bDelayUpdateTuneLabel = true;
				if (_tmrTuneSliderUpdate == null)
				{
					_tmrTuneSliderUpdate = new System.Timers.Timer(500.0);
					_tmrTuneSliderUpdate.Elapsed += OnTuneSliderUpdateTimerTick;
					_tmrTuneSliderUpdate.AutoReset = false;
					_tmrTuneSliderUpdate.Enabled = true;
				}
				else
				{
					_tmrTuneSliderUpdate.Stop();
					_tmrTuneSliderUpdate.Start();
				}
			}
		}
		string text2 = ((!pABandUsesMaxPower) ? num.ToString() : ((int)((float)num / (float)(ptbTune.Maximum - ptbTune.Minimum) * SetupForm.GetPABandMaxPower(TXBand)) + "w"));
		if (!bShowLimitValue)
		{
			if (ptbTune.IsConstrained)
			{
				lblTune.Text = text + ":  (" + text2 + ")";
			}
			else
			{
				lblTune.Text = text + ":  " + text2;
			}
		}
		else
		{
			lblTune.Text = "Limit: " + text2;
		}
	}

	private void ptbTune_Scroll(object sender, EventArgs e)
	{
		if (!IsSetupFormNull)
		{
			PrettyTrackBar.LimitConstraint limitConstraint = e as PrettyTrackBar.LimitConstraint;
			if (limitConstraint != null)
			{
				limitTunePower_by_band[(int)_tx_band] = limitConstraint.LimitValue;
			}
			int num = setPowerFromTuneSlider(out var bConstrain, e != EventArgs.Empty);
			tunePower_by_band[(int)_tx_band] = ptbTune.Value;
			UpdateTuneLabel((limitConstraint != null) & bConstrain, e);
			if (sender.GetType() == typeof(PrettyTrackBar))
			{
				ptbTune.Focus();
			}
			if (m_fTuneDrivePower != (double)num)
			{
				m_fTuneDrivePower = num;
				DrivePowerChangedHandlers?.Invoke(1, num, tune: true);
			}
		}
	}

	private void setupTuneDriveSlider()
	{
		if (_tuneDrivePowerSource != DrivePowerSource.TUNE_SLIDER && _2ToneDrivePowerSource != DrivePowerSource.TUNE_SLIDER)
		{
			ptbTune.Visible = false;
			lblTune.Visible = false;
		}
		else
		{
			ptbTune.Visible = true;
			lblTune.Visible = true;
		}
		if (chkTUN.Checked)
		{
			ptbPWR.Enabled = _tuneDrivePowerSource == DrivePowerSource.DRIVE_SLIDER;
			ptbTune.Enabled = _tuneDrivePowerSource == DrivePowerSource.TUNE_SLIDER;
		}
		else if (chk2TONE.Checked)
		{
			ptbPWR.Enabled = _2ToneDrivePowerSource == DrivePowerSource.DRIVE_SLIDER;
			ptbTune.Enabled = _2ToneDrivePowerSource == DrivePowerSource.TUNE_SLIDER;
		}
		else
		{
			ptbPWR.Enabled = true;
			ptbTune.Enabled = true;
		}
		lblPWR.Enabled = ptbPWR.Enabled;
		lblTune.Enabled = ptbTune.Enabled;
	}

	private int setPowerFromDriveSlider(out bool bConstrain, bool bAdjustedBySliderControl)
	{
		int result = SetPowerUsingTargetDBM(out var bConstrain2, out var _, bSetPower: true, bFromTune: false, bTwoTone: false);
		bConstrain = bConstrain2;
		return result;
	}

	private int setPowerFromTuneSlider(out bool bConstrain, bool bAdjustedBySliderControl)
	{
		int result = SetPowerUsingTargetDBM(out var bConstrain2, out var _, bSetPower: true, bFromTune: true, chk2TONE.Checked);
		bConstrain = bConstrain2;
		return result;
	}

	public int SetPowerUsingTargetDBM(out bool bConstrain, out double targetdBm, bool bSetPower, bool bFromTune, bool bTwoTone)
	{
		PrettyTrackBar prettyTrackBar = ptbPWR;
		bConstrain = true;
		int num = 0;
		int num2 = 0;
		if (!MOX && !chkTUN.Checked && !chk2TONE.Checked)
		{
			if (bFromTune)
			{
				num2 = ((!bTwoTone) ? 1 : 2);
			}
		}
		else if (chkTUN.Checked)
		{
			num2 = 1;
		}
		else if (chk2TONE.Checked)
		{
			num2 = 2;
		}
		switch (num2)
		{
		case 0:
			num = ptbPWR.Value;
			power_by_band[(int)_tx_band] = num;
			break;
		case 1:
			switch (_tuneDrivePowerSource)
			{
			case DrivePowerSource.DRIVE_SLIDER:
				num = ptbPWR.Value;
				break;
			case DrivePowerSource.TUNE_SLIDER:
				prettyTrackBar = ptbTune;
				num = ptbTune.Value;
				break;
			case DrivePowerSource.FIXED:
				num = tune_power;
				bConstrain = false;
				break;
			}
			break;
		case 2:
			switch (_2ToneDrivePowerSource)
			{
			case DrivePowerSource.DRIVE_SLIDER:
				num = ptbPWR.Value;
				break;
			case DrivePowerSource.TUNE_SLIDER:
				prettyTrackBar = ptbTune;
				num = ptbTune.Value;
				break;
			case DrivePowerSource.FIXED:
				num = twotone_tune_power;
				bConstrain = false;
				break;
			}
			break;
		}
		if ((!chkTUN.Checked || xvtr_tune_power) && tx_xvtr_index >= 0)
		{
			if (prettyTrackBar.Focused)
			{
				XVTRForm.SetPower(tx_xvtr_index, prettyTrackBar.Value);
			}
			BandByFreq(XVTRForm.TranslateFreq(VFOAFreq), tx_xvtr_index, current_region);
		}
		if (bConstrain)
		{
			num = prettyTrackBar.ConstrainAValue(num);
		}
		double num3 = 10.0 * Math.Log10((double)num * 1000.0);
		double num4;
		if (tx_xvtr_index >= 0)
		{
			Band b = BandByFreq(XVTRForm.TranslateFreq(VFOAFreq), tx_xvtr_index, current_region);
			num4 = GainByBand(b, num);
		}
		else
		{
			num4 = GainByBand(TXBand, num);
		}
		num3 -= num4;
		double num5 = Math.Sqrt(Math.Pow(10.0, num3 * 0.1) * 0.05);
		targetdBm = num3;
		if (!bSetPower)
		{
			return num;
		}
		if ((float)num != _lastPower && chkFWCATUBypass.Checked && _forceATTwhenPowerChangesWhenPSAon)
		{
			if ((float)num > _lastPower || _forceATTwhenPowerChangesWhenPSAon_anddecreased)
			{
				SetupForm.ATTOnTX = 31;
			}
			_lastPower = num;
		}
		if (num == 0)
		{
			Audio.RadioVolume = 0.0;
			if (chkTUN.Checked)
			{
				radio.GetDSPTX(0).TXPostGenRun = 0;
			}
		}
		else
		{
			if (chkTUN.Checked)
			{
				radio.GetDSPTX(0).TXPostGenRun = 1;
			}
			Audio.RadioVolume = Math.Min(num5 / 0.8, 1.0);
		}
		return num;
	}

