		{
			meterDelay.Reset();
			bool flag = false;
			bool flag2 = false;
			int val = int.MaxValue;
			if (!_mox || (_mox && RX2Enabled && VFOBTX))
			{
				float num = RXOffset(1);
				if (MeterManager.RequiresUpdate(1, Reading.SIGNAL_STRENGTH) || (TCIServer != null && TCIServer.SensorRequiresUpdate(1, Reading.SIGNAL_STRENGTH)))
				{
					_RX1MeterValues[Reading.SIGNAL_STRENGTH] = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.SIGNAL_STRENGTH) + num;
				}
				bool flag3 = true;
				if (MeterManager.RequiresUpdate(1, Reading.AVG_SIGNAL_STRENGTH) || (TCIServer != null && TCIServer.SensorRequiresUpdate(1, Reading.AVG_SIGNAL_STRENGTH)))
				{
					_RX1MeterValues[Reading.AVG_SIGNAL_STRENGTH] = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.AVG_SIGNAL_STRENGTH) + num;
					flag3 = false;
				}
				if (MeterManager.RequiresUpdate(1, Reading.ADC_PK))
				{
					_RX1MeterValues[Reading.ADC_PK] = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.ADC_REAL);
				}
				if (MeterManager.RequiresUpdate(1, Reading.ADC_AV))
				{
					_RX1MeterValues[Reading.ADC_AV] = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.ADC_IMAG);
				}
				if (MeterManager.RequiresUpdate(1, Reading.AGC_PK))
				{
					_RX1MeterValues[Reading.AGC_PK] = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.AGC_PK);
				}
				if (MeterManager.RequiresUpdate(1, Reading.AGC_AV))
				{
					_RX1MeterValues[Reading.AGC_AV] = WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.AGC_AV);
				}
				if (MeterManager.RequiresUpdate(1, Reading.AGC_GAIN))
				{
					_RX1MeterValues[Reading.AGC_GAIN] = 0f - WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.AGC_GAIN);
				}
				if (MeterManager.RequiresUpdate(1, Reading.ESTIMATED_PBSNR))
				{
					if (!Display.FastAttackNoiseFloorRX1 && _lastRX1NoiseFloorGood)
					{
						float num2 = (flag3 ? (WDSP.CalculateRXMeter(0u, 0u, WDSP.MeterType.AVG_SIGNAL_STRENGTH) + num) : _RX1MeterValues[Reading.AVG_SIGNAL_STRENGTH]);
						SpectralResult spectralResult = spectralCalculations(1, num2);
						_RX1MeterValues[Reading.ESTIMATED_PBSNR] = (float)spectralResult.estimated_snr;
					}
					else
					{
						_RX1MeterValues[Reading.ESTIMATED_PBSNR] = 0f;
