				updateMetersReading(Reading.ALC_PK, Math.Max(-195f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.ALC_PK)), 0);
				updateMetersReading(Reading.ALC_G, Math.Max(-195f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.ALC_G)), 0);
				updateMetersReading(Reading.ALC_GROUP, Math.Max(-30f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.ALC_PK)) + Math.Max(0f, 0f - WDSP.CalculateTXMeter(1u, WDSP.MeterType.ALC_G)), 0);
				updateMetersReading(Reading.PWR, ((alexpresent || apollopresent) && HardwareSpecific.Model == HPSDRModel.ANAN8000D && tx_xvtr_index >= 0) ? drivepwr : calfwdpower, 0);
				updateMetersReading(Reading.REVERSE_PWR, (alexpresent || apollopresent) ? alex_rev : (-200f), 0);
				updateMetersReading(Reading.SWR, alex_swr, 0);
				updateMetersReading(Reading.DRIVE_FWD_ADC, average_drvadc, 0);
				updateMetersReading(Reading.FWD_ADC, average_fwdadc, 0);
				updateMetersReading(Reading.REV_ADC, average_revadc, 0);
				updateMetersReading(Reading.DRIVE_PWR, average_drivepwr, 0);
				updateMetersReading(Reading.PA_FWD_PWR, alex_fwd, 0);
				updateMetersReading(Reading.PA_REV_PWR, alex_rev, 0);
				updateMetersReading(Reading.CAL_FWD_PWR, calfwdpower, 0);
				flag2 = true;
				if (TCIServer != null)
				{
					val = TCIServer.MinimumRequiredTxSensorInterval();
				}
			}
			int DDCrx = -1;
			int DDCrx2 = -1;
			int DDCsync = -1;
			int DDCsync2 = -1;
			int DDCpsrx = -1;
			int DDCpstx = -1;
			GetDDC(out DDCrx, out DDCrx2, out DDCsync, out DDCsync2, out DDCpsrx, out DDCpstx);
