			{
				_RX1MeterValues[Reading.ADC_MAX_MAG] = (int)NetworkIO.getADCmaxMagnitude(GetADCInUse(DDCrx));
				flag = true;
			}
			bool flag4 = MeterManager.RequiresUpdate(1, Reading.VOLTS);
			bool flag5 = MeterManager.RequiresUpdate(1, Reading.AMPS);
			if (flag4 | flag5)
			{
				if (flag4)
				{
					_RX1MeterValues[Reading.VOLTS] = _MKIIPAVolts;
