				if (flag5)
				{
					_RX1MeterValues[Reading.AMPS] = _MKIIPAAmps;
				}
				flag = true;
			}
			if (flag)
			{
				MeterReadingsChangedHandlers?.Invoke(1, tx: false, ref _RX1MeterValues);
			}
			if (flag2)
			{
				MeterReadingsChangedHandlers?.Invoke(1, tx: true, ref _RX1MeterValues);
				MeterReadingsChangedHandlers?.Invoke(2, tx: true, ref _RX2MeterValues);
			}
			meterDelay.Stop();
			int val2 = MeterManager.QuickestUpdateInterval(1, _mox) - (int)meterDelay.DurationMsec;
			val2 = Math.Min(val2, val);
			if (val2 < 1)
			{
				val2 = 1;
			}
			await Task.Delay(val2);
		}
