	private void updateMetersReading(Reading reading, float value, int rx)
	{
		if ((rx == 0 || rx == 1) && (MeterManager.RequiresUpdate(1, reading) || (TCIServer != null && TCIServer.SensorRequiresUpdate(1, Reading.MIC))))
		{
			_RX1MeterValues[reading] = value;
		}
		if ((rx == 0 || rx == 2) && (MeterManager.RequiresUpdate(2, reading) || (TCIServer != null && TCIServer.SensorRequiresUpdate(2, Reading.MIC))))
		{
			_RX2MeterValues[reading] = value;
		}
	}

