	private void ptbSquelch_Scroll(object sender, EventArgs e)
	{
		if (_bIgnoreSqlUpdate)
		{
			return;
		}
		int num = ((chkSquelch.CheckState == CheckState.Indeterminate) ? rx1_voice_squelch_threshold_scroll : ((_rx1_dsp_mode == DSPMode.FM) ? rx1_fm_squelch_threshold_scroll : rx1_squelch_threshold_scroll));
		switch (chkSquelch.CheckState)
		{
		case CheckState.Unchecked:
		case CheckState.Checked:
		{
			int num2;
			if (_rx1_dsp_mode == DSPMode.FM)
			{
				num2 = (int)((float)(ptbSquelch.Value + 160) / 160f * 100f);
				rx1_fm_squelch_threshold_scroll = ptbSquelch.Value;
				radio.GetDSPRX(0, 0).FMSquelchThreshold = (float)Math.Pow(10.0, -2.0 * (double)num2 / 100.0);
				radio.GetDSPRX(0, 1).FMSquelchThreshold = (float)Math.Pow(10.0, -2.0 * (double)num2 / 100.0);
			}
			else
			{
				rx1_squelch_threshold_scroll = ptbSquelch.Value;
				num2 = ptbSquelch.Value;
				radio.GetDSPRX(0, 0).RXSquelchThreshold = (float)num2 - RXOffset(1);
				radio.GetDSPRX(0, 1).RXSquelchThreshold = (float)num2 - RXOffset(1);
			}
			chkSquelch.Text = "SQL:  " + num2;
			break;
		}
		case CheckState.Indeterminate:
		{
			int num2 = (int)((float)(ptbSquelch.Value + 160) / 160f * 100f);
			rx1_voice_squelch_threshold_scroll = ptbSquelch.Value;
			radio.GetDSPRX(0, 0).SSqlThreshold = (float)num2 / 100f;
			radio.GetDSPRX(0, 1).SSqlThreshold = (float)num2 / 100f;
			chkSquelch.Text = "VSQL: " + num2;
			break;
		}
		}
		if (sender.GetType() == typeof(PrettyTrackBar))
		{
			ptbSquelch.Focus();
		}
		if (sliderForm != null)
		{
			sliderForm.RX1Squelch = ptbSquelch.Value;
		}
		int num3 = ((chkSquelch.CheckState == CheckState.Indeterminate) ? rx1_voice_squelch_threshold_scroll : ((_rx1_dsp_mode == DSPMode.FM) ? rx1_fm_squelch_threshold_scroll : rx1_squelch_threshold_scroll));
		if (num != num3)
		{
			SQLLevelChangedHandlers?.Invoke(1, num, num3);
		}
