	private void chkSquelch_CheckStateChanged(object sender, EventArgs e)
	{
		if (initializing || _bIgnoreSqlStateChange)
		{
			return;
		}
		bool visible = !collapsedDisplay;
		int value = 0;
		switch (chkSquelch.CheckState)
		{
		case CheckState.Unchecked:
			radio.GetDSPRX(0, 0).RXFMSquelchOn = false;
			radio.GetDSPRX(0, 1).RXFMSquelchOn = false;
			radio.GetDSPRX(0, 0).RXAMSquelchOn = false;
			radio.GetDSPRX(0, 1).RXAMSquelchOn = false;
			radio.GetDSPRX(0, 0).SSqlOn = false;
			radio.GetDSPRX(0, 1).SSqlOn = false;
			if (_rx1_dsp_mode == DSPMode.FM)
			{
				_rx1_fm_squelch_state = SquelchState.OFF;
				visible = false;
				value = rx1_fm_squelch_threshold_scroll;
			}
			else
			{
				_rx1_squelch_state = SquelchState.OFF;
				value = rx1_squelch_threshold_scroll;
			}
			break;
		case CheckState.Checked:
			if (_rx1_dsp_mode == DSPMode.FM)
			{
				radio.GetDSPRX(0, 0).RXAMSquelchOn = false;
				radio.GetDSPRX(0, 1).RXAMSquelchOn = false;
				radio.GetDSPRX(0, 0).SSqlOn = false;
				radio.GetDSPRX(0, 1).SSqlOn = false;
				radio.GetDSPRX(0, 0).RXFMSquelchOn = true;
				radio.GetDSPRX(0, 1).RXFMSquelchOn = true;
				_rx1_fm_squelch_state = SquelchState.SQL;
				visible = false;
				value = rx1_fm_squelch_threshold_scroll;
			}
			else
			{
				radio.GetDSPRX(0, 0).RXFMSquelchOn = false;
				radio.GetDSPRX(0, 1).RXFMSquelchOn = false;
				radio.GetDSPRX(0, 0).SSqlOn = false;
				radio.GetDSPRX(0, 1).SSqlOn = false;
				radio.GetDSPRX(0, 0).RXAMSquelchOn = true;
				radio.GetDSPRX(0, 1).RXAMSquelchOn = true;
				_rx1_squelch_state = SquelchState.SQL;
				value = rx1_squelch_threshold_scroll;
			}
			break;
		case CheckState.Indeterminate:
			radio.GetDSPRX(0, 0).RXFMSquelchOn = false;
			radio.GetDSPRX(0, 1).RXFMSquelchOn = false;
			radio.GetDSPRX(0, 0).RXAMSquelchOn = false;
			radio.GetDSPRX(0, 1).RXAMSquelchOn = false;
			radio.GetDSPRX(0, 0).SSqlOn = true;
			radio.GetDSPRX(0, 1).SSqlOn = true;
			if (_rx1_dsp_mode == DSPMode.FM)
			{
				_rx1_fm_squelch_state = SquelchState.VSQL;
			}
			else
			{
				_rx1_squelch_state = SquelchState.VSQL;
			}
			visible = false;
			value = rx1_voice_squelch_threshold_scroll;
			break;
		}
		if (sliderForm != null)
		{
			sliderForm.RX1SquelchState = chkSquelch.CheckState;
		}
		AndromedaIndicatorCheck(EIndicatorActions.eINSquelch, IsRX1: true, chkSquelch.Checked);
		picSquelch.Visible = visible;
		_bIgnoreSqlUpdate = true;
		ptbSquelch.Value = value;
		_bIgnoreSqlUpdate = false;
		ptbSquelch_Scroll(this, EventArgs.Empty);
		SquelchState squelchState = ((_rx1_dsp_mode == DSPMode.FM) ? _rx1_fm_squelch_state : _rx1_squelch_state);
		if (_old_sql_state[0] != squelchState)
		{
			SQLChangedHandlers?.Invoke(1, _old_sql_state[0], squelchState);
			_old_sql_state[0] = squelchState;
		}
	}

	private void handleSqlFM(int rx, bool bFM, SquelchState force_to_state = SquelchState.LAST)
	{
		_bIgnoreSqlStateChange = true;
		SquelchState squelchState = SquelchState.LAST;
		if (force_to_state == SquelchState.LAST)
		{
			if (bFM)
			{
				switch (rx)
				{
				case 1:
					squelchState = _rx1_fm_squelch_state;
					break;
				case 2:
					squelchState = _rx2_fm_squelch_state;
					break;
				}
			}
			else
			{
				switch (rx)
				{
				case 1:
					squelchState = _rx1_squelch_state;
					break;
				case 2:
					squelchState = _rx2_squelch_state;
					break;
				}
			}
		}
		else
		{
			_bIgnoreSqlStateChange = false;
			squelchState = force_to_state;
		}
		if (squelchState == SquelchState.LAST)
		{
			_bIgnoreSqlStateChange = false;
			return;
		}
		switch (rx)
		{
		case 1:
			switch (squelchState)
			{
			case SquelchState.OFF:
				chkSquelch.CheckState = CheckState.Unchecked;
				break;
			case SquelchState.SQL:
				chkSquelch.CheckState = CheckState.Checked;
				break;
			case SquelchState.VSQL:
				chkSquelch.CheckState = CheckState.Indeterminate;
				break;
			}
			break;
		case 2:
			switch (squelchState)
			{
			case SquelchState.OFF:
				chkRX2Squelch.CheckState = CheckState.Unchecked;
				break;
			case SquelchState.SQL:
				chkRX2Squelch.CheckState = CheckState.Checked;
				break;
			case SquelchState.VSQL:
				chkRX2Squelch.CheckState = CheckState.Indeterminate;
				break;
			}
			break;
		}
		_bIgnoreSqlStateChange = false;
	}

