	private void ptbRX2Squelch_Scroll(object sender, EventArgs e)
	{
		if (_bIgnoreSqlUpdate)
		{
			return;
		}
		int num = ((chkRX2Squelch.CheckState == CheckState.Indeterminate) ? rx2_voice_squelch_threshold_scroll : ((_rx2_dsp_mode == DSPMode.FM) ? rx2_fm_squelch_threshold_scroll : rx2_squelch_threshold_scroll));
		switch (chkRX2Squelch.CheckState)
		{
		case CheckState.Unchecked:
		case CheckState.Checked:
		{
			int num2;
			if (_rx2_dsp_mode == DSPMode.FM)
			{
				num2 = (int)((float)(ptbRX2Squelch.Value + 160) / 160f * 100f);
				rx2_fm_squelch_threshold_scroll = ptbRX2Squelch.Value;
				radio.GetDSPRX(1, 0).FMSquelchThreshold = (float)Math.Pow(10.0, -2.0 * (double)num2 / 100.0);
				radio.GetDSPRX(1, 1).FMSquelchThreshold = (float)Math.Pow(10.0, -2.0 * (double)num2 / 100.0);
			}
			else
			{
				rx2_squelch_threshold_scroll = ptbRX2Squelch.Value;
				num2 = ptbRX2Squelch.Value;
				radio.GetDSPRX(1, 0).RXSquelchThreshold = (float)num2 - RXOffset(2);
				radio.GetDSPRX(1, 1).RXSquelchThreshold = (float)num2 - RXOffset(2);
			}
			chkRX2Squelch.Text = "SQL:  " + num2;
			break;
		}
		case CheckState.Indeterminate:
		{
			int num2 = (int)((float)(ptbRX2Squelch.Value + 160) / 160f * 100f);
			rx2_voice_squelch_threshold_scroll = ptbRX2Squelch.Value;
			radio.GetDSPRX(1, 0).SSqlThreshold = (float)num2 / 100f;
			radio.GetDSPRX(1, 1).SSqlThreshold = (float)num2 / 100f;
			chkRX2Squelch.Text = "VSQL: " + num2;
			break;
		}
		}
		if (sender.GetType() == typeof(PrettyTrackBar))
		{
			ptbRX2Squelch.Focus();
		}
		if (sliderForm != null)
		{
			sliderForm.RX2Squelch = ptbRX2Squelch.Value;
		}
		int num3 = ((chkRX2Squelch.CheckState == CheckState.Indeterminate) ? rx2_voice_squelch_threshold_scroll : ((_rx2_dsp_mode == DSPMode.FM) ? rx2_fm_squelch_threshold_scroll : rx2_squelch_threshold_scroll));
		if (num != num3)
		{
			SQLLevelChangedHandlers?.Invoke(2, num, num3);
		}
	}

