	private void updateLegacyMeterControls(bool expanded)
	{
		bool flag = !_hide_legacy_meters;
		if (expanded)
		{
			grpMultimeter.Visible = flag;
			grpRX2Meter.Visible = flag;
			grpMultimeterMenus.Visible = flag;
			comboMeterRXMode.Visible = flag;
			comboRX2MeterMode.Visible = flag;
			comboMeterTXMode.Visible = flag;
			return;
		}
		grpMultimeter.Visible = false;
		grpRX2Meter.Visible = false;
		grpMultimeterMenus.Visible = false;
		if (m_bShowTopControls || _showAndromedaTopControls)
		{
			picMultiMeterDigital.Visible = flag && ShowRX1;
			txtMultiText.Visible = flag && ShowRX1;
			picRX2Meter.Visible = flag && ShowRX2;
			txtRX2Meter.Visible = flag && ShowRX2;
		}
		if (m_bShowTopControls)
		{
			panelMeterLabels.Visible = false;
			comboMeterRXMode.Visible = flag && ShowRX1;
			comboRX2MeterMode.Visible = flag && ShowRX2;
			comboMeterTXMode.Visible = flag;
			return;
		}
		if (_showAndromedaTopControls)
		{
			panelMeterLabels.Visible = flag;
			comboMeterRXMode.Visible = false;
			comboRX2MeterMode.Visible = false;
			comboMeterTXMode.Visible = false;
			return;
		}
		panelMeterLabels.Visible = false;
		comboMeterRXMode.Visible = false;
		comboRX2MeterMode.Visible = false;
		comboMeterTXMode.Visible = false;
		picMultiMeterDigital.Visible = false;
		txtMultiText.Visible = false;
		picRX2Meter.Visible = false;
		txtRX2Meter.Visible = false;
	}

	public void InitFFTFillTime(int rx)
	{
		int fFTSize;
		int sampleRate;
		switch (rx)
		{
		case 1:
			fFTSize = specRX.GetSpecRX(0).FFTSize;
			sampleRate = specRX.GetSpecRX(0).SampleRate;
			break;
		case 2:
			fFTSize = specRX.GetSpecRX(1).FFTSize;
			sampleRate = specRX.GetSpecRX(1).SampleRate;
			break;
		default:
			return;
		}
		float num = (float)sampleRate / (float)fFTSize;
		float num2 = (float)Common.FindNextPowerOf2((int)(float)Math.Round((float)sampleRate / num)) / (float)sampleRate * 1000f;
		if (rx == 1)
		{
			_fft_fill_timeRX1 = num2;
			Display.RX1FFTFillTime = _fft_fill_timeRX1;
		}
		else
		{
			_fft_fill_timeRX2 = num2;
			Display.RX2FFTFillTime = _fft_fill_timeRX2;
		}
	}

