		}
	}

	private void setupCMasioStatusBar()
	{
		switch (cmaster.GetCMAstate())
		{
		case 0:
			toolStripStatusLabel_CMstatus.Visible = false;
			break;
		case 1:
			toolStripStatusLabel_CMstatus.Image = Resources.cm_green;
			toolStripStatusLabel_CMstatus.ToolTipText = "CM ASIO is in use. The driver being used will not be available to VAC.\nAlso, speaker/microphone jacks on the radio will be inoperable.";
			toolStripStatusLabel_CMstatus.Visible = true;
			break;
		default:
			toolStripStatusLabel_CMstatus.Image = Resources.cm_red;
			toolStripStatusLabel_CMstatus.ToolTipText = "Issue starting CM ASIO. Check driver name in registry.\nAlso check in/out channels.";
			toolStripStatusLabel_CMstatus.Visible = true;
			break;
		}
	}

	private void setupSerialCatStatusBar()
	{
		if (IsSetupFormNull)
		{
			return;
		}
		int[] array = SetupForm.SerialCatState();
		int num = 0;
		for (int i = 0; i < array.Length; i++)
		{
			num += array[i];
		}
		if (num == 0)
		{
			toolStripStatusLabel_CatSerial.Visible = false;
			return;
		}
		Bitmap bitmap = new Bitmap(Resources.cat_serial_status);
		for (int j = 0; j < bitmap.Width; j++)
		{
			for (int k = 0; k < bitmap.Height; k++)
			{
				Color pixel = bitmap.GetPixel(j, k);
				if (pixel.A == byte.MaxValue && pixel.R == byte.MaxValue && pixel.G == 0 && pixel.B == 0)
				{
					Color color = ((array[0] == 0) ? Color.Transparent : ((array[0] == 1) ? Color.FromArgb(255, 255, 0, 0) : Color.FromArgb(255, 0, 255, 0)));
					bitmap.SetPixel(j, k, color);
				}
				else if (pixel.A == byte.MaxValue && pixel.R == 0 && pixel.G == byte.MaxValue && pixel.B == 0)
				{
					Color color2 = ((array[1] == 0) ? Color.Transparent : ((array[1] == 1) ? Color.FromArgb(255, 255, 0, 0) : Color.FromArgb(255, 0, 255, 0)));
					bitmap.SetPixel(j, k, color2);
				}
				else if (pixel.A == byte.MaxValue && pixel.R == 0 && pixel.G == 0 && pixel.B == byte.MaxValue)
				{
					Color color3 = ((array[2] == 0) ? Color.Transparent : ((array[2] == 1) ? Color.FromArgb(255, 255, 0, 0) : Color.FromArgb(255, 0, 255, 0)));
					bitmap.SetPixel(j, k, color3);
				}
				else if (pixel.A == byte.MaxValue && pixel.R == 0 && pixel.G == 0 && pixel.B == 0)
				{
					Color color4 = ((array[3] == 0) ? Color.Transparent : ((array[3] == 1) ? Color.FromArgb(255, 255, 0, 0) : Color.FromArgb(255, 0, 255, 0)));
					bitmap.SetPixel(j, k, color4);
				}
			}
		}
		string text = "Serial : ";
		for (int l = 0; l < array.Length; l++)
		{
			if (array[l] == 1)
			{
				text += $"CAT{l + 1} disabled, ";
			}
			else if (array[l] == 2)
			{
				text += $"CAT{l + 1} enabled, ";
			}
		}
		if (text.Right(2) == ", ")
		{
			text = text.Left(text.Length - 2);
		}
		toolStripStatusLabel_CatSerial.Image = bitmap;
		toolStripStatusLabel_CatSerial.ToolTipText = text;
		toolStripStatusLabel_CatSerial.Visible = true;
	}

	public void UpdateStatusBarStatusIcons(StatusBarIconGroup iconGroup)
	{
		if (iconGroup == StatusBarIconGroup.All || iconGroup == StatusBarIconGroup.CMAsio)
		{
			setupCMasioStatusBar();
		}
		if (iconGroup == StatusBarIconGroup.All || iconGroup == StatusBarIconGroup.N1MM)
		{
			toolStripStatusLabel_N1MM.Visible = N1MM.IsStarted && (N1MM.IsEnabled(1) || N1MM.IsEnabled(2));
		}
		if (iconGroup == StatusBarIconGroup.All || iconGroup == StatusBarIconGroup.TCPIPCat)
		{
			toolStripStatusLabel_CatTCPip.Visible = m_tcpCATServer != null && m_tcpCATServer.IsServerRunning;
		}
		if (iconGroup == StatusBarIconGroup.All || iconGroup == StatusBarIconGroup.SerialCat)
		{
			setupSerialCatStatusBar();
		}
		if (iconGroup == StatusBarIconGroup.All || iconGroup == StatusBarIconGroup.TCI)
		{
			toolStripStatusLabel_TCI.Visible = m_tcpTCIServer != null && m_tcpTCIServer.IsServerRunning;
		}
	}

