	private void toolTipItemMouseHover(object sender, EventArgs e)
	{
		if (m_statusBarToolTip != null)
		{
			m_statusBarToolTip.Hide(statusStripMain);
			m_statusBarToolTip.Dispose();
			m_statusBarToolTip = null;
		}
		string toolTipText;
		int num;
