	public void SetAutoFormStartSetting(string form, bool show)
	{
		string key = form.ToLower();
		if (!_auto_start_form_settings.ContainsKey(key))
		{
			_auto_start_form_settings.Add(key, show);
		}
		else
		{
			_auto_start_form_settings[key] = show;
		}
	}

	public bool GetAutoFormStartSetting(string form)
	{
		string key = form.ToLower();
		if (_auto_start_form_settings.ContainsKey(key))
		{
			return _auto_start_form_settings[key];
		}
		return false;
	}

	private string getAutoStartData()
	{
		string text = "";
		foreach (KeyValuePair<string, bool> auto_start_form_setting in _auto_start_form_settings)
		{
			string key = auto_start_form_setting.Key;
			bool value = auto_start_form_setting.Value;
			text = text + key + "|" + value.ToString().ToLower() + "|";
		}
		if (text.EndsWith("|"))
		{
			text = text.Substring(0, text.Length - 1);
		}
		return text.ToLower();
	}

	private void setAutoStartData(string data)
	{
		string[] array = data.ToLower().Split('|');
		if (array.Length % 2 != 0)
		{
			return;
		}
		for (int i = 0; i < array.Length; i += 2)
		{
			string form = array[i];
			if (bool.TryParse(array[i + 1], out var result))
			{
				SetAutoFormStartSetting(form, result);
			}
		}
		if (!IsSetupFormNull)
		{
			SetupForm.UpdateAutoStartForms();
		}
	}

	private void handleShowOnStartWindowsForms()
	{
		_autoFormLoadingDuplicate.Clear();
		foreach (KeyValuePair<string, bool> auto_start_form_setting in _auto_start_form_settings)
		{
			_autoFormLoadingDuplicate.Add(auto_start_form_setting.Key, auto_start_form_setting.Value);
		}
		if (_autoFormLoadingDuplicate.Count > 0)
		{
			_autoLoadFormTimerFormTimer = new System.Windows.Forms.Timer();
			_autoLoadFormTimerFormTimer.Tick += OnOpenWindowsFormsTimerEvent;
			_autoLoadFormTimerFormTimer.Interval = 250;
			_autoLoadFormTimerFormTimer.Start();
		}
	}

	private void OnOpenWindowsFormsTimerEvent(object source, EventArgs e)
	{
		_autoLoadFormTimerFormTimer.Stop();
		if (_autoFormLoadingDuplicate.Count == 0)
		{
			return;
		}
		KeyValuePair<string, bool> keyValuePair = _autoFormLoadingDuplicate.First();
		string key = keyValuePair.Key;
		bool value = keyValuePair.Value;
		if ((key == "linearity" || key == "ampview") && !base.Visible)
		{
			_autoFormLoadingDuplicate.Remove(key);
			_autoFormLoadingDuplicate.Add(key, value);
			_autoLoadFormTimerFormTimer.Start();
			return;
		}
		_autoFormLoadingDuplicate.Remove(key);
		if (value)
		{
			showOnStartup(key);
		}
		if (_autoFormLoadingDuplicate.Count > 0)
		{
			_autoLoadFormTimerFormTimer.Start();
		}
	}

	private void showOnStartup(string form)
	{
		EventArgs empty = EventArgs.Empty;
		if (form == null)
		{
			return;
		}
		switch (form.Length)
		{
		case 6:
			switch (form[0])
			{
			case 'm':
				if (form == "memory")
				{
					memoryToolStripMenuItem_Click(this, empty);
				}
				break;
			case 'f':
				if (form == "finder")
				{
					finderMenuItem_Click(this, empty);
				}
				break;
			}
			break;
		case 4:
			switch (form[0])
			{
			case 'w':
				if (form == "wave")
				{
					waveToolStripMenuItem_Click(this, empty);
				}
				break;
			case 'x':
				if (form == "xvtr")
				{
					xVTRsToolStripMenuItem_Click(this, empty);
				}
				break;
			}
			break;
		case 9:
			switch (form[0])
			{
			case 'e':
				if (form == "equaliser")
				{
					equalizerToolStripMenuItem_Click(this, empty);
				}
				break;
			case 'l':
				if (!(form == "linearity") || psform == null)
				{
					break;
				}
				if (psform.InvokeRequired)
				{
					psform.Invoke((MethodInvoker)delegate
					{
						psform.ShowAtStartup_LinearityForm();
					});
				}
				else
				{
					psform.ShowAtStartup_LinearityForm();
				}
				break;
			case 'd':
				if (form == "diversity")
				{
					showHideDiversity(show: true);
				}
				break;
			case 'b':
				if (form == "bandstack")
				{
					lblBandStack_Click(this, empty);
				}
				break;
			}
			break;
		case 2:
			switch (form[0])
			{
			case 'r':
				if (form == "ra")
				{
					RAtoolStripMenuItem_Click(this, empty);
				}
				break;
			case 'w':
				if (form == "wb")
				{
					wBToolStripMenuItem_Click(this, empty);
				}
				break;
			}
			break;
		case 5:
			if (form == "setup")
			{
				_eq_form_show_rx = true;
				setupToolStripMenuItem1_Click(this, empty);
			}
			break;
		case 3:
			if (form == "cwx")
			{
				cWXToolStripMenuItem_Click(this, empty);
			}
			break;
		case 7:
			if (!(form == "ampview") || psform == null)
			{
				break;
			}
			if (psform.InvokeRequired)
			{
				psform.Invoke((MethodInvoker)delegate
				{
					psform.ShowAtStartup_AmpViewForm();
				});
			}
			else
			{
				psform.ShowAtStartup_AmpViewForm();
			}
			break;
		case 8:
			break;
		}
	}

	private void handleLaunchOnStartUp()
	{
		if (IsSetupFormNull)
		{
			return;
		}
		string[] autoLaunchFiles = SetupForm.GetAutoLaunchFiles();
		foreach (string text in autoLaunchFiles)
		{
			string obj = text.ToLower();
			int num = obj.IndexOf(".exe");
			int num2 = obj.IndexOf(".cmd");
			int num3 = obj.IndexOf(".bat");
			int[] obj2 = new int[3] { num, num2, num3 };
			int num4 = int.MaxValue;
			int[] array = obj2;
			foreach (int num5 in array)
			{
				if (num5 != -1 && num5 < num4)
				{
					num4 = num5;
				}
			}
			if (num4 == int.MaxValue)
			{
				continue;
			}
			string arguments = text.Substring(num4 + 4).Trim();
			string text2 = text.Substring(0, num4 + 4).Trim();
			if (!File.Exists(text2))
			{
				continue;
			}
			try
			{
				string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(text2);
				if (SetupForm.AutoLaunchNoStartIfRunning && (!SetupForm.AutoLaunchNoStartIfRunning || IsProcessRunning(fileNameWithoutExtension)))
				{
					continue;
				}
				string text3 = Path.GetExtension(text2).ToLower();
				switch (text3)
				{
				case ".exe":
				case ".cmd":
				case ".bat":
				{
					ProcessWindowStyle windowStyle = ((!(text3 == ".exe")) ? ProcessWindowStyle.Hidden : ProcessWindowStyle.Normal);
					Process process = Process.Start(new ProcessStartInfo(text2)
					{
						WindowStyle = windowStyle,
						UseShellExecute = true,
						CreateNoWindow = true,
						Arguments = arguments,
						WorkingDirectory = Path.GetDirectoryName(text2)
					});
					if (process != null)
					{
						_started_processes.Add(process);
					}
					break;
				}
				}
			}
			catch
			{
			}
		}
	}

	private bool IsProcessRunning(string processName)
	{
		return Process.GetProcessesByName(processName).Length != 0;
	}

	private static List<IntPtr> FindAllWindowHandlesByProcessId(int processId)
	{
		List<IntPtr> handles = new List<IntPtr>();
		EnumWindows(delegate(IntPtr hWnd, IntPtr lParam)
		{
			GetWindowThreadProcessId(hWnd, out var lpdwProcessId);
			if (lpdwProcessId == processId)
			{
				handles.Add(hWnd);
			}
			return true;
		}, IntPtr.Zero);
		return handles;
	}

	[DllImport("user32.dll", SetLastError = true)]
	private static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);

	[DllImport("user32.dll", SetLastError = true)]
	private static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);

	[DllImport("user32.dll")]
	private static extern bool PostMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);

	[DllImport("user32.dll", SetLastError = true)]
	private static extern bool PostThreadMessage(uint idThread, uint Msg, IntPtr wParam, IntPtr lParam);

	private void autoLaunchTryToClose()
	{
		if (IsSetupFormNull || !SetupForm.AutoLaunchTryToClose)
		{
			return;
		}
		foreach (Process started_process in _started_processes)
		{
			try
			{
				PostMessage(started_process.MainWindowHandle, 16u, IntPtr.Zero, IntPtr.Zero);
			}
			catch
			{
			}
		}
		if (_started_processes.Count > 0)
		{
			Thread.Sleep(50);
		}
		foreach (Process started_process2 in _started_processes)
		{
			try
			{
				PostMessage(started_process2.MainWindowHandle, 18u, IntPtr.Zero, IntPtr.Zero);
			}
			catch
			{
			}
		}
		if (_started_processes.Count > 0)
		{
			Thread.Sleep(50);
		}
		foreach (Process started_process3 in _started_processes)
		{
			try
			{
				PostThreadMessage((uint)started_process3.Threads[0].Id, 18u, IntPtr.Zero, IntPtr.Zero);
			}
			catch
			{
			}
		}
		if (_started_processes.Count > 0)
		{
			Thread.Sleep(50);
		}
		foreach (Process started_process4 in _started_processes)
		{
			try
			{
				foreach (IntPtr item in FindAllWindowHandlesByProcessId(started_process4.Id))
				{
					try
					{
						PostMessage(item, 16u, IntPtr.Zero, IntPtr.Zero);
					}
					catch
					{
					}
				}
			}
			catch
			{
			}
		}
		if (_started_processes.Count > 0)
		{
			Thread.Sleep(50);
		}
		foreach (Process started_process5 in _started_processes)
		{
			try
			{
				foreach (IntPtr item2 in FindAllWindowHandlesByProcessId(started_process5.Id))
				{
					try
					{
						PostMessage(item2, 18u, IntPtr.Zero, IntPtr.Zero);
					}
					catch
					{
					}
				}
			}
			catch
			{
			}
		}
		if (_started_processes.Count > 0)
		{
			Thread.Sleep(50);
		}
		foreach (Process started_process6 in _started_processes)
		{
			try
			{
				started_process6.CloseMainWindow();
			}
			catch
			{
			}
		}
		if (_started_processes.Count > 0)
		{
			Thread.Sleep(50);
		}
		foreach (Process started_process7 in _started_processes)
		{
			try
			{
				started_process7.Close();
			}
			catch
			{
			}
			finally
			{
				try
				{
					started_process7.Dispose();
				}
				catch
				{
				}
			}
		}
	}

