	private void miAbout_Click(object sender, EventArgs e)
	{
		if (IsSetupFormNull)
		{
			return;
		}
		string radio_model;
		string firmware_version;
		string protocol;
		string supported_protocol;
		if (NetworkIO.getHaveSync() == 1)
		{
			radio_model = HardwareSpecific.Model.ToString();
			if (NetworkIO.CurrentRadioProtocol == RadioProtocol.ETH)
			{
				HPSDRModel model = HardwareSpecific.Model;
				firmware_version = (((uint)(model - 11) > 1u) ? (NetworkIO.FWCodeVersion.ToString("0\\.0") + "." + NetworkIO.BetaVersion) : ((NetworkIO.BetaVersion < 39) ? (NetworkIO.FWCodeVersion.ToString("0\\.0") + "." + NetworkIO.BetaVersion) : ("fpga(v" + NetworkIO.FWCodeVersion + ") p2app(v" + NetworkIO.BetaVersion + ")")));
				protocol = "2";
				supported_protocol = NetworkIO.Protocol2VersionSupported.ToString("0\\.0");
			}
			else
			{
				firmware_version = NetworkIO.FWCodeVersion.ToString("0\\.0");
				protocol = "1";
				supported_protocol = "";
			}
		}
		else
		{
			firmware_version = "? (not connected)";
			protocol = "? (not connected)";
			supported_protocol = "";
			radio_model = HardwareSpecific.Model.ToString() + " (not connected)";
		}
		string verNum = Common.GetVerNum(include_revision: true);
		int num = PA19.PA_GetVersion();
		int num2 = (num >> 16) & 0xFF;
		int num3 = (num >> 8) & 0xFF;
		int num4 = num & 0xFF;
		string portAudio_version = num2 + "." + num3 + "." + num4;
		string andromedaVersionNumber = SetupForm.AndromedaVersionNumber;
		string text = andromedaVersionNumber;
		text = text.Replace("Andromeda: ", "");
		text = text.Replace("G2 panel: ", "");
		text = text.Replace("h/w=", "h=");
		text = text.Replace("  s/w=", " s=");
		if (!string.IsNullOrEmpty(text))
		{
			text = (andromedaVersionNumber.Contains("G2") ? ("G2 Panel Version: " + text) : ("Andromeda Panel Version: " + text));
		}
		int num5 = Display.DXVersion();
		string dx_version = ((num5 == -1) ? "" : ((float)num5 / 10f).ToString("f1"));
		_frmAbout.InitVersions(verNum, "EU2AV", DB.VersionNumber.ToString(), dx_version, radio_model, firmware_version, protocol, supported_protocol, ((float)WDSP.GetWDSPVersion() / 100f).ToString("f2"), ((float)cmaster.GetCMVersion() / 1000f).ToString("f2"), ((float)cmaster.GetCMasioVersion() / 1000f).ToString("f2"), portAudio_version, text);
		_frmAbout.ShowDialog(this);
	}

	private void resizeBackgroundImage()
	{
		if (base.ClientSize == _background_image_size || base.ClientSize.Width == 0 || base.ClientSize.Height == 0)
		{
			return;
		}
		Graphics graphics = null;
		_background_image_size = base.ClientSize;
		if (BackgroundImage != null)
		{
			BackgroundImage.Dispose();
			BackgroundImage = null;
		}
		if (_cached_background_image == null)
		{
			return;
		}
		try
		{
			Image image = new Bitmap(base.ClientSize.Width, base.ClientSize.Height);
			graphics = Graphics.FromImage(image);
			graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
			graphics.DrawImage(_cached_background_image, 0, 0, image.Width, image.Height);
			BackgroundImageLayout = ImageLayout.None;
			BackgroundImage = image;
		}
		catch (Exception)
		{
			if (BackgroundImage == null)
			{
				BackgroundImageLayout = ImageLayout.Stretch;
				BackgroundImage = _cached_background_image;
			}
		}
		finally
		{
			graphics?.Dispose();
		}
	}

