	public double GetMinimumRXNotchWidth(int rx)
	{
		if (rx < 1 || rx > 2)
		{
			return 100.0;
		}
		if (_minimum_rx_notch_width.ContainsKey(rx - 1))
		{
			return _minimum_rx_notch_width[rx - 1];
		}
		return 100.0;
	}

	public double GetMinimumTXNotchWidth()
	{
		return _minimum_tx_notch_width;
	}

	public unsafe void UpdateMinimumNotchWidthRX(int rx)
	{
		int num = -1;
		switch (rx)
		{
		case 1:
			num = WDSP.id(0u, 0u);
			break;
		case 2:
			num = WDSP.id(2u, 0u);
			break;
		}
		if (num != -1)
		{
			double value = 0.0;
			WDSP.RXANBPGetMinNotchWidth(num, &value);
			if (_minimum_rx_notch_width.ContainsKey(rx - 1))
			{
				_minimum_rx_notch_width[rx - 1] = value;
			}
			else
			{
				_minimum_rx_notch_width.Add(rx - 1, value);
			}
			MinimumRXNotchWidthChangedHandlers?.Invoke(rx, value);
		}
	}

	public void UpdateMinimumNotchWidthTX()
	{
		int num = ((radio.GetDSPTX(0).CurrentDSPMode == DSPMode.FM) ? 192000 : 96000);
		double num2 = radio.GetDSPTX(0).TXBandpassWindow switch
		{
			0 => 1600.0 / (double)(radio.GetDSPTX(0).FilterSize / 256) * (double)(num / 48000), 
			1 => 2200.0 / (double)(radio.GetDSPTX(0).FilterSize / 256) * (double)(num / 48000), 
			_ => 100.0, 
		};
		MinimumTXNotchWidthChangedHandlers?.Invoke(num2);
	}

