				getFilterEdgesInPixels(e, ref low_x2, ref high_x2, ref vfoa_sub_x2, ref vfoa_sub_low_x2, ref vfoa_sub_high_x2);
				if (Math.Abs(e.X - low_x2) < 3 && e.X < high_x2)
				{
