					{
						if (_mox && chkVFOBTX.Checked)
						{
							if (!_click_tune_rx2_display)
							{
								switch (radio.GetDSPTX(0).CurrentDSPMode)
								{
								case DSPMode.LSB:
								case DSPMode.DSB:
								case DSPMode.CWL:
								case DSPMode.FM:
								case DSPMode.AM:
								case DSPMode.DIGL:
								case DSPMode.SAM:
