									break;
								default:
									tx_low_filter_drag = true;
									break;
								}
							}
						}
						else
						{
							rx2_low_filter_drag = true;
						}
					}
					else if (_mox && (!chkSplitDisplay.Checked || chkVFOATX.Checked))
					{
						if (!_click_tune_display)
						{
							switch (radio.GetDSPTX(0).CurrentDSPMode)
							{
							case DSPMode.LSB:
							case DSPMode.DSB:
							case DSPMode.CWL:
							case DSPMode.FM:
							case DSPMode.AM:
							case DSPMode.DIGL:
							case DSPMode.SAM:
								tx_high_filter_drag = true;
								break;
							default:
								tx_low_filter_drag = true;
