						{
							if (!_click_tune_rx2_display)
							{
								DSPMode currentDSPMode = radio.GetDSPTX(0).CurrentDSPMode;
								if (currentDSPMode == DSPMode.LSB || currentDSPMode == DSPMode.CWL || currentDSPMode == DSPMode.DIGL)
								{
									tx_low_filter_drag = true;
								}
								else
								{
									tx_high_filter_drag = true;
								}
							}
						}
						else
						{
							rx2_high_filter_drag = true;
						}
					}
					else if (_mox && (!chkSplitDisplay.Checked || (chkSplitDisplay.Checked && chkVFOATX.Checked)))
					{
						if (!_click_tune_display)
						{
							DSPMode currentDSPMode = radio.GetDSPTX(0).CurrentDSPMode;
							if (currentDSPMode == DSPMode.LSB || currentDSPMode == DSPMode.CWL || currentDSPMode == DSPMode.DIGL)
							{
								tx_low_filter_drag = true;
