					{
						sub_drag_start_freq = VFOASubFreq;
					}
					else
					{
						sub_drag_start_freq = VFOBFreq;
					}
					rx1_sub_drag = true;
				}
				else
				{
					spectrum_drag_last_x = e.X;
					if (rx2_enabled && e.Y > pnlDisplay.Height / 2)
					{
						rx2_spectrum_drag = true;
					}
					else
					{
						rx1_spectrum_drag = true;
					}
