			{
				return;
			}
			if (!rx2_enabled && Display.CurrentDisplayMode == DisplayMode.PANAFALL && e.Y >= Display.PanafallSplitBarPosLogical && e.Y < Display.PanafallSplitBarPosLogical + 20)
			{
				Display.PanafallSplitBarPerc = 0.5f;
				return;
			}
			if (Common.CtrlKeyDown)
			{
