					{
						num61 = WaterfallPixelToTime(e.Y, 1);
					}
				}
				DisplayCursorX = e.X;
				DisplayCursorY = e.Y;
				Display.MouseFrequency = num60;
				switch (dSPMode)
				{
				case DSPMode.CWL:
					num63 += (double)cw_pitch * 1E-06;
					break;
				case DSPMode.CWU:
					num63 -= (double)cw_pitch * 1E-06;
					break;
				}
				infoBar.Left1(0, num60.ToString("f1") + "Hz");
				bool flag17 = _mox && ((RX2Enabled && !flag15 && VFOATX) || (flag15 && VFOBTX) || !RX2Enabled);
				if ((flag16 && !flag17) || (flag16 && _display_duplex && !flag15))
				{
					num63 += num65 - num64;
				}
				string obj = num63.ToString("f6") + " MHz";
				int startIndex = obj.IndexOf(separator) + 4;
				string text = obj.Insert(startIndex, " ");
				infoBar.Left3(0, text);
				Display.MHzCursorDisplay = text;
				string otherData1CursorDisplay;
				if (flag13)
				{
					text = num61.ToString("f1") + "dBm";
					otherData1CursorDisplay = text;
				}
				else if (flag14)
				{
					text = (num61 / 1000f).ToString("f1") + "sec";
					otherData1CursorDisplay = text;
				}
				else
				{
					text = "";
					otherData1CursorDisplay = "";
				}
				infoBar.Left2(0, text);
				Display.OtherData1CursorDisplay = otherData1CursorDisplay;
			}
			else
			{
				infoBar.Left1(0, "");
				infoBar.Left2(0, "");
				infoBar.Left3(0, "");
				Display.OtherData1CursorDisplay = "";
			}
			if (rx1_spectrum_tune_drag && (!_mox || (rx2_enabled && chkVFOBTX.Checked)))
			{
				float num67 = PixelToHz(spectrum_drag_last_x);
				float num68 = PixelToHz(e.X);
				spectrum_drag_last_x = e.X;
				float num69 = num68 - num67;
				CentreFrequency -= (double)num69 * 1E-06;
				txtVFOAFreq_LostFocus(this, EventArgs.Empty);
			}
			if (rx2_spectrum_tune_drag && rx2_enabled && (!_mox || chkVFOATX.Checked))
			{
				float num70 = PixelToHz(spectrum_drag_last_x, 2);
				float num71 = PixelToHz(e.X, 2);
				spectrum_drag_last_x = e.X;
				float num72 = num71 - num70;
				CentreRX2Frequency -= (double)num72 * 1E-06;
				txtVFOBFreq_LostFocus(this, EventArgs.Empty);
			}
			if (rx1_spectrum_drag && (!_mox || (rx2_enabled && chkVFOBTX.Checked)))
			{
				float num73 = PixelToHz(spectrum_drag_last_x);
				float num74 = PixelToHz(e.X);
				spectrum_drag_last_x = e.X;
				float num75 = num74 - num73;
				VFOAFreq -= (double)num75 * 1E-06;
			}
			if (rx2_spectrum_drag && rx2_enabled && (!_mox || chkVFOATX.Checked))
			{
				float num76 = PixelToHz(spectrum_drag_last_x, 2);
				float num77 = PixelToHz(e.X, 2);
				spectrum_drag_last_x = e.X;
				float num78 = num77 - num76;
				VFOBFreq -= (double)num78 * 1E-06;
			}
			if (rx1_click_tune_drag && (!_mox || (rx2_enabled && chkVFOBTX.Checked)))
			{
				float num79 = PixelToHz(spectrum_drag_last_x);
				float num80 = PixelToHz(e.X);
				spectrum_drag_last_x = e.X;
				float num81 = num79 - num80;
				VFOAFreq -= (double)num81 * 1E-06;
			}
			if (rx2_click_tune_drag && rx2_enabled && (!_mox || chkVFOATX.Checked))
			{
				float num82 = PixelToHz(spectrum_drag_last_x, 2);
				float num83 = PixelToHz(e.X, 2);
				spectrum_drag_last_x = e.X;
				float num84 = num82 - num83;
				VFOBFreq -= (double)num84 * 1E-06;
			}
			if (flag2 && e.Y < pnlDisplay.Height / 2 + 15)
			{
				cursor = Cursors.SizeWE;
			}
			else if (flag && e.Y < 15)
			{
				cursor = Cursors.SizeWE;
			}
			if (!rx2_enabled && Display.CurrentDisplayMode == DisplayMode.PANAFALL && m_bDraggingPanafallSplit)
			{
				cursor = Cursors.SizeNS;
			}
			if (cursor == Cursors.Cross || cursor == _cross_outlined)
			{
				if (agc_knee_drag || agc_hang_drag)
				{
					cursor = grabbing;
				}
				else if (rx1_spectrum_drag || rx2_spectrum_drag || rx1_spectrum_tune_drag || rx2_spectrum_tune_drag)
				{
					cursor = Cursors.SizeWE;
				}
				else if (rx1_click_tune_drag || rx2_click_tune_drag)
				{
					cursor = grabbing;
				}
				else if (!rx2_enabled && Display.CurrentDisplayMode == DisplayMode.PANAFALL && e.Y >= Display.PanafallSplitBarPosLogical && e.Y < Display.PanafallSplitBarPosLogical + 20)
				{
					cursor = Cursors.SizeNS;
				}
			}
			pnlDisplay.Cursor = cursor;
		}
		catch (Exception)
		{
		}
	}

	private void pnlDisplay_MouseUp(object sender, MouseEventArgs e)
	{
		if (Display.PausedDisplay)
		{
			return;
		}
		if (e.Button == MouseButtons.Left)
		{
			DisplayMode currentDisplayMode = Display.CurrentDisplayMode;
			if ((uint)currentDisplayMode <= 1u || (uint)(currentDisplayMode - 6) <= 4u)
			{
				rx1_low_filter_drag = false;
				rx1_high_filter_drag = false;
				rx1_whole_filter_drag = false;
				rx2_low_filter_drag = false;
				rx2_high_filter_drag = false;
				rx2_whole_filter_drag = false;
				tx_low_filter_drag = false;
				tx_high_filter_drag = false;
				tx_whole_filter_drag = false;
				rx1_click_tune_drag = false;
				rx2_click_tune_drag = false;
				rx1_spectrum_tune_drag = false;
				rx2_spectrum_tune_drag = false;
				agc_knee_drag = false;
				agc_hang_drag = false;
				gridminmaxadjust = false;
				rx1_grid_adjust = false;
				rx2_grid_adjust = false;
				tx1_grid_adjust = false;
				tx2_grid_adjust = false;
				Display.HightlightFilterEdgeRX1 = 0;
				Display.HightlightFilterEdgeRX2 = 0;
			}
			if (rx1_sub_drag)
			{
				rx1_sub_drag = false;
				if (rx2_enabled)
				{
					txtVFOABand_LostFocus(this, EventArgs.Empty);
				}
				else
				{
					txtVFOBFreq_LostFocus(this, EventArgs.Empty);
				}
			}
			if (rx1_spectrum_drag)
			{
				rx1_spectrum_drag = false;
				txtVFOAFreq_LostFocus(this, EventArgs.Empty);
			}
			rx2_spectrum_drag = false;
			if (m_bBandStackOverlayClicked)
			{
				if (Display.HighlightedBandStackEntryIndex != -1 && Display.BandStackOverlays != null && (Display.CurrentDisplayMode == DisplayMode.PANADAPTER || Display.CurrentDisplayMode == DisplayMode.PANAFALL) && Display.HighlightedBandStackEntryIndex < Display.BandStackOverlays.Length)
				{
					BandStackEntry bandStackEntry = Display.BandStackOverlays[Display.HighlightedBandStackEntryIndex];
					if (bandStackEntry != null)
					{
						BandStackFilter filter = BandStackManager.GetFilter(RX1Band, bIncludeUserDefined: false);
						if (filter != null)
						{
							OnEntryClicked(filter, bandStackEntry, updateLastVisited: false);
						}
					}
				}
				m_bBandStackOverlayClicked = false;
			}
			if (m_bDraggingNotch)
			{
				m_bDraggingNotch = false;
				double fCenter = SelectedNotch.FCenter;
				ChangeNotchCentreFrequency(SelectedNotch, fCenter, m_nNotchRX);
			}
			else if (m_bDraggingNotchBW)
			{
				m_bDraggingNotchBW = false;
				double fWidth = SelectedNotch.FWidth;
				ChangeNotchBW(SelectedNotch, fWidth);
			}
			if (m_bDraggingPanafallSplit)
			{
				m_bDraggingPanafallSplit = false;
			}
		}
		if (e.Button == MouseButtons.Right)
		{
			DisplayMode currentDisplayMode = Display.CurrentDisplayMode;
			if ((uint)currentDisplayMode <= 1u || (uint)(currentDisplayMode - 7) <= 3u)
			{
				gridminmaxadjust = false;
				gridmaxadjust = false;
				rx1_grid_adjust = false;
				rx2_grid_adjust = false;
				tx1_grid_adjust = false;
				tx2_grid_adjust = false;
			}
			if (SelectedNotch != null && !Common.CtrlKeyDown)
			{
				Point p = new Point(e.X, e.Y);
				int num = pnlDisplay.PointToScreen(p).X - 16;
				int num2 = pnlDisplay.PointToScreen(p).Y - 16;
				ShowNotchPopup(num, num2, SelectedNotch, 0, 1000, AlwaysOnTop);
			}
		}
	}

	private async void pnlDisplay_Resize(object sender, EventArgs e)
	{
		_pause_DisplayThread = true;
		m_bResizeDX2Display = true;
		while (m_bResizeDX2Display && m_bDisplayLoopRunning)
		{
			await Task.Delay(1);
		}
		if (!initializing)
		{
			updateBandstackOverlay(1);
			UpdateRXSpectrumDisplayVars();
			UpdateTXSpectrumDisplayVars();
		}
		_pause_DisplayThread = false;
	}

	public void ApplyDisplayRenderScale()
	{
		pnlDisplay_Resize(this, EventArgs.Empty);
	}

	public bool SetHiDpiSurfaces(bool on)
	{
		if (on)
		{
			HiDpiSurfaces.Enable(pnlDisplay, OnPnlDisplayDpiChanged);
			float windowScale = HiDpiSurfaces.GetWindowScale(pnlDisplay.Handle);
			Size physicalClientSize = HiDpiSurfaces.GetPhysicalClientSize(pnlDisplay.Handle);
			float num = Math.Max(1, pnlDisplay.Width);
			float num2 = ((physicalClientSize.Width > 0) ? ((float)physicalClientSize.Width / num) : 1f);
			if (windowScale > 1.01f && Math.Abs(num2 - windowScale) > 0.1f)
			{
				LogTool.AddLogEntry($"HiDPI / 2K mode REFUSED: monitor scale {windowScale:F2} but panel phys/logical ratio {num2:F2} (phys={physicalClientSize.Width}, logical={pnlDisplay.Width}) — render would be enlarged", "Display");
				HiDpiSurfaces.Disable(pnlDisplay);
				return false;
			}
			LogTool.AddLogEntry($"HiDPI / 2K mode enabled: monitor scale {windowScale:F2}, panel phys/logical ratio {num2:F2} (phys={physicalClientSize.Width}x{physicalClientSize.Height}, logical={pnlDisplay.Width}x{pnlDisplay.Height})", "Display");
			Display.HiDpiPhysicalRender = true;
			if (detachedPanafallForm != null && detachedPanafallForm.IsHandleCreated)
			{
				detachedPanafallForm.SetHiDpiSurface(on: true);
			}
			if (m_bDisplayLoopRunning)
			{
				ApplyDisplayRenderScale();
			}
			return true;
		}
		Display.HiDpiPhysicalRender = false;
		HiDpiSurfaces.Disable(pnlDisplay);
		if (detachedPanafallForm != null && detachedPanafallForm.IsHandleCreated)
		{
			detachedPanafallForm.SetHiDpiSurface(on: false);
		}
		if (m_bDisplayLoopRunning)
		{
			ApplyDisplayRenderScale();
		}
		return true;
	}

	private void OnPnlDisplayDpiChanged()
	{
		ApplyDisplayRenderScale();
	}

	protected override void OnHandleCreated(EventArgs e)
	{
		base.OnHandleCreated(e);
		if (!Display.HiDpiPhysicalRender)
		{
			return;
		}
		try
		{
			if (!SetHiDpiSurfaces(on: true))
			{
				Display.HiDpiPhysicalRender = false;
			}
		}
		catch (Exception ex)
		{
			Display.HiDpiPhysicalRender = false;
			try
			{
				File.AppendAllText(Path.Combine(Application.StartupPath, "HiDpiFallback.log"), $"{DateTime.UtcNow:u} HiDPI startup fallback: {ex.Message}{Environment.NewLine}");
			}
			catch
			{
			}
		}
	}

	private void setupDisplayMaxBinDetect(int rx, bool sub_rx, bool enabled, bool update_enabled_state = true)
	{
		if (rx >= 1 && rx <= 2)
		{
			int frame_rate = (int)Math.Max(1f, (float)_display_fps * 1.1f);
			int disp;
			float num;
			double fLow;
			double fHigh;
			if (rx == 2)
			{
				disp = 1;
				num = SampleRateRX2;
				double num2 = ((!_click_tune_rx2_display) ? 0.0 : ((VFOBFreq - CentreRX2Frequency) * 1000000.0));
				fLow = (double)radio.GetDSPRX(1, sub_rx ? 1 : 0).RXFilterLow + num2;
				fHigh = (double)radio.GetDSPRX(1, sub_rx ? 1 : 0).RXFilterHigh + num2;
			}
			else
			{
				int num3 = (RITOn ? RITValue : 0);
				disp = 0;
				num = SampleRateRX1;
				double num2 = ((!_click_tune_display) ? 0.0 : ((VFOAFreq - CentreFrequency) * 1000000.0));
				num2 += (double)num3;
				fLow = (double)radio.GetDSPRX(0, sub_rx ? 1 : 0).RXFilterLow + num2;
				fHigh = (double)radio.GetDSPRX(0, sub_rx ? 1 : 0).RXFilterHigh + num2;
			}
			WDSP.SetupDetectMaxBin(enabled ? 1 : 0, disp, 0, 0, num, fLow, fHigh, 0.5, frame_rate);
			if (update_enabled_state)
			{
				_display_max_bin_enabled[rx - 1] = enabled;
			}
		}
	}

	private void OnFilterEdgesChanged(int rx, Filter newFilter, Band band, int low, int high, string sName, int max_width, int max_shift)
	{
		if (_display_max_bin_enabled[rx - 1])
		{
			setupDisplayMaxBinDetect(rx, sub_rx: false, enabled: true);
		}
	}

	private void OnSampleRateChanged(int rx, int oldSampleRate, int newSampleRate)
	{
		if (_display_max_bin_enabled[rx - 1])
		{
			setupDisplayMaxBinDetect(rx, sub_rx: false, enabled: true);
		}
	}

	private void OnFSPChanged(int old_fpr, int new_fps)
	{
		if (_display_max_bin_enabled[0])
		{
			setupDisplayMaxBinDetect(1, sub_rx: false, enabled: true);
		}
		if (_display_max_bin_enabled[1])
		{
			setupDisplayMaxBinDetect(2, sub_rx: false, enabled: true);
		}
	}

