	private bool requires_reposition()
	{
		bool result = false;
		if (Common.AltlKeyDown && Common.ShiftKeyDown && Common.CtrlKeyDown)
		{
			Thread.Sleep(500);
			Application.DoEvents();
			if (Common.AltlKeyDown && Common.ShiftKeyDown && Common.CtrlKeyDown)
			{
				DialogResult dialogResult = MessageBox.Show("CTRL+ALT+SHIFT key combo has been detected.\n\nThe location of the main Thetis console window and Setup will be moved to the primary monitor.\n\nIf other forms are 'missing' you can use Setup->Tools->[Reposition Forms] to recover them.\n\n\nDo you want to do this?\n\n\nNOTE: release the keys", "Resposition detected", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button2, (MessageBoxOptions)262144);
				while (Common.AltlKeyDown || Common.ShiftKeyDown || Common.CtrlKeyDown)
				{
					Thread.Sleep(100);
					Application.DoEvents();
				}
				result = dialogResult == DialogResult.Yes;
			}
		}
		return result;
	}

	private void on_send_floodcontrol_message(string msg, string uid)
	{
		if (base.InvokeRequired)
		{
			Invoke((MethodInvoker)delegate
			{
				on_send_floodcontrol_message(msg, uid);
			});
			return;
		}
		bool flag = false;
		string text = uid;
		if (!(text == "freq_change_broadcast"))
		{
			if (text == "vfo_change_broadcast")
			{
				flag = true;
			}
		}
		else
		{
			flag = true;
		}
		if (flag)
		{
			Dictionary<string, bool> kenwoodAISettings = SetupForm.KenwoodAISettings;
			if (kenwoodAISettings["port1"])
			{
				sioPut(Siolisten, msg);
			}
			if (kenwoodAISettings["port2"])
			{
				sioPut(Sio2listen, msg);
			}
			if (kenwoodAISettings["port3"])
			{
				sioPut(Sio3listen, msg);
			}
			if (kenwoodAISettings["port4"])
			{
				sioPut(Sio4listen, msg);
			}
			if (m_tcpCATServer != null && kenwoodAISettings["tcp"])
			{
				m_tcpCATServer.SendToClients(msg);
			}
		}
	}

	public void DoOtherButtonAction(int rx, OtherButtonId id, MouseButtons button, bool force = false, bool current_state = false)
	{
		if (_busy_doing_otherbutton_action && !force)
		{
			return;
		}
		_busy_doing_otherbutton_action = true;
		if (button == MouseButtons.Right && handleDoOtherButtonActionRightClick(rx, id))
		{
			_busy_doing_otherbutton_action = false;
			return;
		}
		switch (id)
		{
		case OtherButtonId.POWER:
			PowerOn = !PowerOn;
			break;
		case OtherButtonId.RX_2:
			RX2Enabled = !RX2Enabled;
			break;
		case OtherButtonId.MON:
			MON = !MON;
			break;
		case OtherButtonId.TUN:
			TUN = !TUN;
			break;
		case OtherButtonId.MOX:
			MOX = !MOX;
			break;
		case OtherButtonId.TWOTON:
			TwoTone = !TwoTone;
			break;
		case OtherButtonId.DUP:
			chkRX2SR.Checked = !chkRX2SR.Checked;
			break;
		case OtherButtonId.PS_A:
			PSA = !PSA;
			break;
		case OtherButtonId.REC:
			if (ckQuickRec.Enabled)
			{
				ckQuickRec.CheckedChanged -= ckQuickRec_CheckedChanged;
				QuickRec = !QuickRec;
				ckQuickRec.CheckedChanged += ckQuickRec_CheckedChanged;
				ckQuickRec_CheckedChanged(this, EventArgs.Empty);
			}
			break;
		case OtherButtonId.PLAY:
			if (ckQuickPlay.Enabled)
			{
				ckQuickPlay.CheckedChanged -= ckQuickPlay_CheckedChanged;
				QuickPlay = !QuickPlay;
				ckQuickPlay.CheckedChanged += ckQuickPlay_CheckedChanged;
				ckQuickPlay_CheckedChanged(this, EventArgs.Empty);
			}
			break;
		case OtherButtonId.WAVE_RECORD:
			if (!ckQuickPlay.Checked && !ckQuickRec.Checked)
			{
				waveRecord(rx, current_state);
			}
			break;
		case OtherButtonId.NR:
			incrementNR(rx);
			break;
		case OtherButtonId.ANF:
			SetANF(rx, !GetANF(rx));
			break;
		case OtherButtonId.NB:
		{
			int selectedNB = GetSelectedNB(rx);
			selectedNB++;
			if (selectedNB > 2)
			{
				selectedNB = 0;
			}
			SetSelectedNB(rx, selectedNB);
			break;
		}
		case OtherButtonId.SNB:
			SetSNB(rx, !GetSNB(rx));
			break;
		case OtherButtonId.MNF:
			TNFActive = !TNFActive;
			break;
		case OtherButtonId.MNF_PLUS:
			TNFAdd(1);
			break;
		case OtherButtonId.SPLT:
		{
			MouseEventArgs e = new MouseEventArgs(MouseButtons.Left, 1, 0, 0, 0);
			chkVFOSplit_MouseClick(this, e);
			break;
		}
		case OtherButtonId.A_TO_B:
			btnVFOAtoB_Click(this, EventArgs.Empty);
			break;
		case OtherButtonId.ZERO_BEAT:
			btnZeroBeat_Click(this, EventArgs.Empty);
			break;
		case OtherButtonId.B_TO_A:
			btnVFOBtoA_Click(this, EventArgs.Empty);
			break;
		case OtherButtonId.IF_TO_V:
			btnIFtoVFO_Click(this, EventArgs.Empty);
			break;
		case OtherButtonId.SWAP_AB:
			btnVFOSwap_Click(this, EventArgs.Empty);
			break;
		case OtherButtonId.AVG:
			SetAVG(rx, !GetAVG(rx));
			break;
		case OtherButtonId.PEAK_HOLD:
			SetPeak(rx, !GetPeak(rx));
			break;
		case OtherButtonId.CTUN:
			SetCTUN(rx, !GetCTUN(rx));
			break;
		case OtherButtonId.VAC1:
			if (!IsSetupFormNull)
			{
				SetupForm.VACEnable = !SetupForm.VACEnable;
			}
			break;
		case OtherButtonId.VAC2:
			if (!IsSetupFormNull)
			{
				SetupForm.VAC2Enable = !SetupForm.VAC2Enable;
			}
			break;
		case OtherButtonId.MUTE:
			SetMute(rx, !GetMute(rx));
			break;
		case OtherButtonId.MUTE_ALL:
			SetMute(0, !GetMute(0));
			break;
		case OtherButtonId.BIN:
			SetBin(rx, !GetBin(rx));
			break;
		case OtherButtonId.SUBRX:
			SetSubRX(rx, !GetSubRX(rx));
			break;
		case OtherButtonId.PAN_SWAP:
			chkPanSwap.Checked = !chkPanSwap.Checked;
			break;
		case OtherButtonId.NR1:
			if (GetSelectedNR(rx) == 1)
			{
				SelectNR(rx, incude_sub: true, 0);
			}
			else
			{
				SelectNR(rx, incude_sub: true, 1);
			}
			break;
		case OtherButtonId.NR2:
			if (GetSelectedNR(rx) == 2)
			{
				SelectNR(rx, incude_sub: true, 0);
			}
			else
			{
				SelectNR(rx, incude_sub: true, 2);
			}
			break;
		case OtherButtonId.NR3:
			if (GetSelectedNR(rx) == 3)
			{
				SelectNR(rx, incude_sub: true, 0);
			}
			else
			{
				SelectNR(rx, incude_sub: true, 3);
			}
			break;
		case OtherButtonId.NR4:
			if (GetSelectedNR(rx) == 4)
			{
				SelectNR(rx, incude_sub: true, 0);
			}
			else
			{
				SelectNR(rx, incude_sub: true, 4);
			}
			break;
		case OtherButtonId.NB1:
			if (GetSelectedNB(rx) == 1)
			{
				SetSelectedNB(rx, 0);
			}
			else
			{
				SetSelectedNB(rx, 1);
			}
			break;
		case OtherButtonId.NB2:
			if (GetSelectedNB(rx) == 2)
			{
				SetSelectedNB(rx, 0);
			}
			else
			{
				SetSelectedNB(rx, 2);
			}
			break;
