	public bool GetMute(int rx)
	{
		int num;
		switch (rx)
		{
		default:
			return false;
		case 1:
		case 2:
			num = rx;
			break;
		case 0:
			num = 1;
			break;
		}
		int num2 = num;
		int num3 = ((rx == 0) ? 2 : rx);
		bool flag = true;
		for (int i = num2; i <= num3; i++)
		{
			switch (i)
			{
			case 1:
				if (num2 == num3)
				{
					return MUT;
				}
				flag &= MUT;
				break;
			case 2:
				if (num2 == num3)
				{
					return MUT2;
				}
				flag &= MUT2;
				break;
			}
		}
		return flag;
	}

	public int GetSelectedNB(int rx)
	{
		if (rx < 1 || rx > 2)
		{
			return -1;
		}
		int result = 0;
		switch (rx)
		{
		case 1:
			switch (chkNB.CheckState)
			{
			case CheckState.Unchecked:
				result = 0;
				break;
			case CheckState.Checked:
				result = 1;
				break;
			case CheckState.Indeterminate:
				result = 2;
				break;
			}
			break;
		case 2:
			switch (chkRX2NB.CheckState)
			{
			case CheckState.Unchecked:
				result = 0;
				break;
			case CheckState.Checked:
				result = 1;
				break;
			case CheckState.Indeterminate:
				result = 2;
				break;
			}
			break;
		}
		return result;
	}

	public bool SetSelectedNB(int rx, int nb)
	{
		if (rx < 1 || rx > 2)
		{
			return false;
		}
		if (nb < 0 || nb > 2)
		{
			return false;
		}
		CheckState checkState;
		switch (nb)
		{
		case 0:
			checkState = CheckState.Unchecked;
			break;
		case 1:
			checkState = CheckState.Checked;
			break;
		case 2:
			checkState = CheckState.Indeterminate;
			break;
		default:
			return false;
		}
		switch (rx)
		{
		case 1:
			chkNB.CheckState = checkState;
			return true;
		case 2:
			chkRX2NB.CheckState = checkState;
			return true;
		default:
			return false;
		}
	}

