	public void SetGeneralSetting(int rx, OtherButtonId id, bool state)
	{
		int num;
		switch (rx)
		{
		default:
			return;
		case 1:
		case 2:
			num = rx;
			break;
		case 0:
			num = 1;
			break;
		}
		int num2 = ((rx == 0) ? 2 : rx);
		for (int i = num; i <= num2; i++)
		{
			if (_general_settings[i - 1] == null)
			{
				_general_settings[i - 1] = new Dictionary<OtherButtonId, bool>();
			}
			Dictionary<OtherButtonId, bool> dictionary = _general_settings[i - 1];
			bool flag = false;
			if (dictionary.ContainsKey(id))
			{
				flag = dictionary[id];
			}
			dictionary[id] = state;
			if (!_init_general_setting && flag != state)
			{
				Dictionary<OtherButtonId, bool> settings = new Dictionary<OtherButtonId, bool>(_general_settings[i - 1]);
				GeneralSettingsChangedHandlers?.Invoke(i, id, flag, state, settings);
			}
		}
	}

