	public void SetHWSampleRateSetting(int rx, int rate)
	{
		if (rx >= 1 && rx <= 2 && (rate == 48000 || rate == 96000 || rate == 192000 || rate == 384000 || rate == 768000 || rate == 1536000))
		{
			SetGeneralSetting(rx, OtherButtonId.SR_48000, state: false);
			SetGeneralSetting(rx, OtherButtonId.SR_96000, state: false);
			SetGeneralSetting(rx, OtherButtonId.SR_192000, state: false);
			SetGeneralSetting(rx, OtherButtonId.SR_384000, state: false);
			SetGeneralSetting(rx, OtherButtonId.SR_768000, state: false);
			SetGeneralSetting(rx, OtherButtonId.SR_1536000, state: false);
			switch (rate)
			{
			case 48000:
				SetGeneralSetting(rx, OtherButtonId.SR_48000, state: true);
				break;
			case 96000:
				SetGeneralSetting(rx, OtherButtonId.SR_96000, state: true);
				break;
			case 192000:
				SetGeneralSetting(rx, OtherButtonId.SR_192000, state: true);
				break;
			case 384000:
				SetGeneralSetting(rx, OtherButtonId.SR_384000, state: true);
				break;
			case 768000:
				SetGeneralSetting(rx, OtherButtonId.SR_768000, state: true);
				break;
			case 1536000:
				SetGeneralSetting(rx, OtherButtonId.SR_1536000, state: true);
				break;
			}
		}
	}

	public int GetATT(int rx)
	{
		if (rx < 1 || rx > 2)
		{
			return 0;
		}
		PreampMode preampMode = PreampMode.FIRST;
		bool flag = false;
		int result = 0;
		switch (rx)
		{
		case 1:
			flag = _rx1_step_att_enabled;
			preampMode = RX1PreampMode;
			result = RX1AttenuatorData;
			break;
		case 2:
			flag = _rx2_step_att_enabled;
			preampMode = RX2PreampMode;
			result = RX2AttenuatorData;
			break;
		}
		if (flag)
		{
			return result;
		}
		return preampMode switch
		{
			PreampMode.HPSDR_OFF => 20, 
			PreampMode.HPSDR_ON => 0, 
			PreampMode.HPSDR_MINUS10 => 10, 
			PreampMode.HPSDR_MINUS20 => 20, 
			PreampMode.HPSDR_MINUS30 => 30, 
			PreampMode.HPSDR_MINUS40 => 40, 
			PreampMode.HPSDR_MINUS50 => 50, 
			PreampMode.SA_MINUS10 => 10, 
			PreampMode.SA_MINUS20 => 20, 
			PreampMode.SA_MINUS30 => 30, 
			_ => 0, 
		};
	}

	private int maxAtt()
	{
		if (alexpresent && HardwareSpecific.Model != HPSDRModel.ANAN10 && HardwareSpecific.Model != HPSDRModel.ANAN10E && HardwareSpecific.Model != HPSDRModel.ANAN7000D && HardwareSpecific.Model != HPSDRModel.ANAN8000D && HardwareSpecific.Model != HPSDRModel.ORIONMKII && HardwareSpecific.Model != HPSDRModel.ANAN_G2E && HardwareSpecific.Model != HPSDRModel.ANAN_G2 && HardwareSpecific.Model != HPSDRModel.ANAN_G2_1K && HardwareSpecific.Model != HPSDRModel.ANVELINAPRO3 && HardwareSpecific.Model != HPSDRModel.REDPITAYA)
		{
			return 61;
		}
		return 31;
	}

	public bool SetATT(int rx, int att, SetAttMode mode)
	{
		if (rx < 1 || rx > 2)
		{
			return false;
		}
		bool flag = false;
		switch (mode)
		{
		case SetAttMode.CURRENT:
			switch (rx)
			{
			case 1:
				if (!IsSetupFormNull)
				{
					flag = SetupForm.RX1EnableAtt;
				}
				break;
			case 2:
				if (!IsSetupFormNull)
				{
					flag = SetupForm.RX2EnableAtt;
				}
				break;
			}
			break;
		case SetAttMode.PREAMP_MODE:
			flag = false;
			break;
		case SetAttMode.STEP_ATTEN:
			flag = true;
			break;
		default:
			return false;
		}
		if (flag)
		{
			switch (rx)
			{
			case 1:
				RX1AttenuatorData = att;
				break;
			case 2:
				RX2AttenuatorData = att;
				break;
			}
		}
		else
		{
			PreampMode preampMode = PreampMode.FIRST;
			bool flag2 = HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ORIONMKII || HardwareSpecific.Model == HPSDRModel.ANAN_G2E || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.ANAN10 || HardwareSpecific.Model == HPSDRModel.ANAN10E || (!alexpresent && (HardwareSpecific.Model == HPSDRModel.HERMES || HardwareSpecific.Model == HPSDRModel.ANAN100D || HardwareSpecific.Model == HPSDRModel.ANAN200D || HardwareSpecific.Model == HPSDRModel.REDPITAYA));
			int num = maxAtt();
			if (att > num)
			{
				att = num;
			}
			if (att < 5)
			{
				preampMode = PreampMode.HPSDR_ON;
			}
			else if (att >= 5 && att < 15)
			{
				preampMode = (flag2 ? PreampMode.SA_MINUS10 : PreampMode.HPSDR_MINUS10);
			}
			else if (att >= 15 && att < 25)
			{
				preampMode = (flag2 ? PreampMode.SA_MINUS20 : PreampMode.HPSDR_MINUS20);
			}
			else if (att >= 25 && att < 35)
			{
				preampMode = (flag2 ? PreampMode.SA_MINUS30 : PreampMode.HPSDR_MINUS30);
			}
			else if (att >= 35 && att < 45)
			{
				preampMode = PreampMode.HPSDR_MINUS40;
			}
			else if (att >= 45)
			{
				preampMode = PreampMode.HPSDR_MINUS50;
			}
			if (preampMode == PreampMode.FIRST)
			{
				return false;
			}
			switch (rx)
			{
			case 1:
				RX1PreampMode = preampMode;
				break;
			case 2:
				RX2PreampMode = preampMode;
				break;
			}
		}
		return true;
	}

	private void setATTGeneralSetting(int rx)
	{
		if (rx < 1 || rx > 2)
		{
			return;
		}
		SetGeneralSetting(rx, OtherButtonId.ATT_0, state: false);
		SetGeneralSetting(rx, OtherButtonId.ATT_10, state: false);
		SetGeneralSetting(rx, OtherButtonId.ATT_20, state: false);
		SetGeneralSetting(rx, OtherButtonId.ATT_30, state: false);
		SetGeneralSetting(rx, OtherButtonId.ATT_40, state: false);
		SetGeneralSetting(rx, OtherButtonId.ATT_50, state: false);
		PreampMode preampMode = PreampMode.FIRST;
		bool flag = false;
		int num = 0;
		switch (rx)
		{
		case 1:
			flag = _rx1_step_att_enabled;
			preampMode = RX1PreampMode;
			num = RX1AttenuatorData;
			SetGeneralSetting(rx, OtherButtonId.ATT_STEP, flag);
			break;
		case 2:
			flag = _rx2_step_att_enabled;
			preampMode = RX2PreampMode;
			num = RX2AttenuatorData;
			SetGeneralSetting(rx, OtherButtonId.ATT_STEP, flag);
			break;
		}
		if (flag)
		{
			switch (num)
			{
			case 0:
				SetGeneralSetting(rx, OtherButtonId.ATT_0, state: true);
				break;
			case 10:
				SetGeneralSetting(rx, OtherButtonId.ATT_10, state: true);
				break;
			case 20:
				SetGeneralSetting(rx, OtherButtonId.ATT_20, state: true);
				break;
			case 30:
				SetGeneralSetting(rx, OtherButtonId.ATT_30, state: true);
				break;
			case 40:
				SetGeneralSetting(rx, OtherButtonId.ATT_40, state: true);
				break;
			case 50:
				SetGeneralSetting(rx, OtherButtonId.ATT_50, state: true);
				break;
			}
			return;
		}
		switch (preampMode)
		{
		case PreampMode.HPSDR_OFF:
			SetGeneralSetting(rx, OtherButtonId.ATT_0, state: true);
			break;
		case PreampMode.HPSDR_ON:
			SetGeneralSetting(rx, OtherButtonId.ATT_0, state: true);
			break;
		case PreampMode.HPSDR_MINUS10:
		case PreampMode.SA_MINUS10:
			SetGeneralSetting(rx, OtherButtonId.ATT_10, state: true);
			break;
		case PreampMode.HPSDR_MINUS20:
		case PreampMode.SA_MINUS20:
			SetGeneralSetting(rx, OtherButtonId.ATT_20, state: true);
			break;
		case PreampMode.HPSDR_MINUS30:
		case PreampMode.SA_MINUS30:
			SetGeneralSetting(rx, OtherButtonId.ATT_30, state: true);
			break;
		case PreampMode.HPSDR_MINUS40:
			SetGeneralSetting(rx, OtherButtonId.ATT_40, state: true);
			break;
		case PreampMode.HPSDR_MINUS50:
			SetGeneralSetting(rx, OtherButtonId.ATT_50, state: true);
			break;
		}
	}

	public void IncrementATT(int rx)
	{
		if (rx < 1 || rx > 2)
		{
			return;
		}
		PreampMode preampMode = PreampMode.FIRST;
		bool flag = false;
		int num = 0;
		switch (rx)
		{
		case 1:
			flag = _rx1_step_att_enabled;
			preampMode = RX1PreampMode;
			num = RX1AttenuatorData;
			break;
		case 2:
			flag = _rx2_step_att_enabled;
			preampMode = RX2PreampMode;
			num = RX2AttenuatorData;
			break;
		}
		if (flag)
		{
			int num2 = maxAtt();
			num++;
			if (num > num2)
			{
				num = num2;
			}
			switch (rx)
			{
			case 1:
				RX1AttenuatorData = num;
				break;
			case 2:
				RX2AttenuatorData = num;
				break;
			}
			return;
		}
		bool flag2 = HardwareSpecific.Model == HPSDRModel.ANAN7000D || HardwareSpecific.Model == HPSDRModel.ANAN8000D || HardwareSpecific.Model == HPSDRModel.ORIONMKII || HardwareSpecific.Model == HPSDRModel.ANAN_G2E || HardwareSpecific.Model == HPSDRModel.ANAN_G2 || HardwareSpecific.Model == HPSDRModel.ANAN_G2_1K || HardwareSpecific.Model == HPSDRModel.ANVELINAPRO3 || HardwareSpecific.Model == HPSDRModel.ANAN10 || HardwareSpecific.Model == HPSDRModel.ANAN10E || (!alexpresent && (HardwareSpecific.Model == HPSDRModel.HERMES || HardwareSpecific.Model == HPSDRModel.ANAN100D || HardwareSpecific.Model == HPSDRModel.ANAN200D || HardwareSpecific.Model == HPSDRModel.REDPITAYA));
		switch (preampMode)
		{
		case PreampMode.HPSDR_OFF:
			preampMode = (flag2 ? PreampMode.SA_MINUS10 : PreampMode.HPSDR_MINUS10);
			break;
		case PreampMode.HPSDR_ON:
			preampMode = (flag2 ? PreampMode.SA_MINUS10 : PreampMode.HPSDR_MINUS10);
			break;
		case PreampMode.HPSDR_MINUS10:
			preampMode = (flag2 ? PreampMode.SA_MINUS20 : PreampMode.HPSDR_MINUS20);
			break;
		case PreampMode.HPSDR_MINUS20:
			preampMode = (flag2 ? PreampMode.SA_MINUS30 : PreampMode.HPSDR_MINUS30);
			break;
		case PreampMode.HPSDR_MINUS30:
			preampMode = PreampMode.HPSDR_MINUS40;
			break;
		case PreampMode.HPSDR_MINUS40:
			preampMode = PreampMode.HPSDR_MINUS50;
			break;
		case PreampMode.HPSDR_MINUS50:
			return;
		case PreampMode.SA_MINUS10:
			preampMode = PreampMode.SA_MINUS20;
			break;
		case PreampMode.SA_MINUS20:
			preampMode = PreampMode.SA_MINUS30;
			break;
		case PreampMode.SA_MINUS30:
			return;
		}
		switch (rx)
		{
		case 1:
			RX1PreampMode = preampMode;
			break;
		case 2:
			RX2PreampMode = preampMode;
			break;
		}
	}

	public void DecrementATT(int rx)
	{
		if (rx < 1 || rx > 2)
		{
			return;
		}
		PreampMode preampMode = PreampMode.FIRST;
		bool flag = false;
		int num = 0;
		switch (rx)
		{
		case 1:
			flag = _rx1_step_att_enabled;
			preampMode = RX1PreampMode;
			num = RX1AttenuatorData;
			break;
		case 2:
			flag = _rx2_step_att_enabled;
			preampMode = RX2PreampMode;
			num = RX2AttenuatorData;
			break;
		}
		if (flag)
		{
			num--;
			if (num < 0)
			{
				num = 0;
			}
			switch (rx)
			{
			case 1:
				RX1AttenuatorData = num;
				break;
			case 2:
				RX2AttenuatorData = num;
				break;
			}
			return;
		}
		switch (preampMode)
		{
		case PreampMode.HPSDR_OFF:
			return;
		case PreampMode.HPSDR_MINUS10:
			preampMode = PreampMode.HPSDR_ON;
			break;
		case PreampMode.HPSDR_MINUS20:
			preampMode = PreampMode.HPSDR_MINUS10;
			break;
		case PreampMode.HPSDR_MINUS30:
			preampMode = PreampMode.HPSDR_MINUS20;
			break;
		case PreampMode.HPSDR_MINUS40:
			preampMode = PreampMode.HPSDR_MINUS30;
			break;
		case PreampMode.HPSDR_MINUS50:
			preampMode = PreampMode.HPSDR_MINUS40;
			break;
		case PreampMode.SA_MINUS10:
			preampMode = PreampMode.HPSDR_ON;
			break;
		case PreampMode.SA_MINUS20:
			preampMode = PreampMode.SA_MINUS10;
			break;
		case PreampMode.SA_MINUS30:
			preampMode = PreampMode.SA_MINUS20;
			break;
		}
		switch (rx)
		{
		case 1:
			RX1PreampMode = preampMode;
			break;
		case 2:
			RX2PreampMode = preampMode;
			break;
		}
	}

	private void handleVfoSyncInitial()
	{
		if (!VFOSync || _prevent_vsync_updates)
		{
			return;
		}
		_prevent_vsync_updates = true;
		switch (_vfo_sync_initial_action)
		{
		case VFOSYNCinit.VFO_A_to_B:
			if (RX2Enabled)
			{
				if (_vfo_sync_frequency)
				{
					VFOBFreq = VFOAFreq;
				}
				if (_vfo_sync_mode)
				{
					RX2DSPMode = RX1DSPMode;
				}
				if (_vfo_sync_filter)
				{
					RX2Filter = RX1Filter;
				}
			}
			else
			{
				if (_vfo_sync_frequency)
				{
					VFOBFreq = VFOAFreq;
				}
				if (_vfo_sync_mode)
				{
					RX2DSPMode = RX1DSPMode;
				}
				if (_vfo_sync_filter)
				{
					RX2Filter = RX1Filter;
				}
			}
			break;
		case VFOSYNCinit.VFO_B_to_A:
			if (RX2Enabled)
			{
				if (_vfo_sync_frequency)
				{
					VFOAFreq = VFOBFreq;
				}
				if (_vfo_sync_mode)
				{
					RX1DSPMode = RX2DSPMode;
				}
				if (_vfo_sync_filter)
				{
					RX1Filter = RX2Filter;
				}
			}
			else if (_vfo_sync_frequency)
			{
				VFOAFreq = VFOBFreq;
			}
			break;
		}
		_prevent_vsync_updates = false;
	}

	private void handleVfoSyncFrequency(int rx, bool b_to_a)
	{
		if (!VFOSync || !_vfo_sync_frequency || _prevent_vsync_updates)
		{
			return;
		}
		_prevent_vsync_updates = true;
		switch (rx)
		{
		case 1:
			if (b_to_a)
			{
				VFOAFreq = VFOBFreq;
			}
			else
			{
				VFOBFreq = VFOAFreq;
			}
			_prevent_vsync_updates = false;
			handleVfoSyncMode(1, RX1DSPMode);
			break;
		case 2:
			if (b_to_a)
			{
				VFOAFreq = VFOBFreq;
				_prevent_vsync_updates = false;
				handleVfoSyncMode(2, RX2DSPMode);
			}
			break;
		}
		_prevent_vsync_updates = false;
	}

	private void handleVfoSyncMode(int rx, DSPMode mode)
	{
		if (!VFOSync || !_vfo_sync_mode || _prevent_vsync_updates)
		{
			return;
		}
		_prevent_vsync_updates = true;
		_mode_changed_via_vsync = _vfo_sync_filter;
		switch (rx)
		{
		case 1:
			RX2DSPMode = mode;
			if (_mode_changed_via_vsync)
			{
				_mode_changed_via_vsync = false;
				_prevent_vsync_updates = false;
				handleVfoSyncFilter(1, RX1Filter);
			}
			break;
		case 2:
			RX1DSPMode = mode;
			if (_mode_changed_via_vsync)
			{
				_mode_changed_via_vsync = false;
				_prevent_vsync_updates = false;
				handleVfoSyncFilter(2, RX2Filter);
			}
			break;
		}
		_mode_changed_via_vsync = false;
		_prevent_vsync_updates = false;
	}

	private void handleVfoSyncFilter(int rx, Filter newFilter)
	{
		if (!VFOSync || newFilter == Filter.VAR1 || newFilter == Filter.VAR2 || !_vfo_sync_filter || _prevent_vsync_updates)
		{
			return;
		}
		_prevent_vsync_updates = true;
		switch (rx)
		{
		case 1:
			if (newFilter != Filter.F8 && newFilter != Filter.F9 && newFilter != Filter.F10)
			{
				RX2Filter = newFilter;
			}
			break;
		case 2:
			RX1Filter = newFilter;
			break;
		}
		_prevent_vsync_updates = false;
	}

