	private void arp_PowerChanged(bool old_power, bool new_power)
	{
		if (ARP.IsWDSPBusy)
		{
			string error;
			if (ARP.IsPlaying)
			{
				ARP.StopPlayback(out error);
			}
			if (ARP.IsRecording)
			{
				ARP.StopRecord(out error);
			}
		}
	}

	private void arp_PlayingingChanged(bool playing, string id, string filename, bool isWdsp)
	{
		if (base.InvokeRequired)
		{
			BeginInvoke((Action)delegate
			{
				arp_PlayingingChanged(playing, id, filename, isWdsp);
			});
			return;
		}
		if (id == "quick")
		{
			if (playing)
			{
				ckQuickPlay.Enabled = true;
				ckQuickRec.Enabled = false;
			}
			else
			{
				ckQuickPlay.Enabled = true;
				ckQuickRec.Enabled = true;
				if (ckQuickPlay.Checked)
				{
					ckQuickPlay.Checked = false;
				}
			}
			QuickPlayChangedHandlers?.Invoke(1, !playing, playing);
		}
		else
		{
			ckQuickPlay.Enabled = !playing;
			ckQuickRec.Enabled = !playing;
		}
		setPlayRecordStatusBar();
	}

	public bool WaveRecording(int rx)
	{
		if (rx < 1 || rx > 2)
		{
			return false;
		}
		return _wave_recording[rx - 1];
	}

	private void arp_RecordingChanged(bool recording, string id, string filename)
	{
		if (base.InvokeRequired)
		{
			BeginInvoke((Action)delegate
			{
				arp_RecordingChanged(recording, id, filename);
			});
			return;
		}
		if (id == "quick")
		{
			if (recording)
			{
				ckQuickPlay.Enabled = false;
				ckQuickRec.Enabled = true;
			}
			else
			{
				ckQuickPlay.Enabled = true;
				ckQuickRec.Enabled = true;
				if (ckQuickRec.Checked)
				{
					ckQuickRec.Checked = false;
				}
			}
			QuickRecordChangedHandlers?.Invoke(1, !recording, recording);
		}
		else
		{
			ckQuickPlay.Enabled = !recording;
			ckQuickRec.Enabled = !recording;
		}
		if (id == "waverecord_1")
		{
			bool old_state = _wave_recording[0];
			_wave_recording[0] = recording;
			WaveRecordChangedHandlers?.Invoke(1, old_state, recording);
		}
		else if (id == "waverecord_2")
		{
			bool old_state2 = _wave_recording[1];
			_wave_recording[1] = recording;
			WaveRecordChangedHandlers?.Invoke(2, old_state2, recording);
		}
		setPlayRecordStatusBar();
	}

	private void setPlayRecordStatusBar()
	{
		if (ARP.IsRecording)
		{
			toolStripStatusLabel_play_record.Image = Resources.record;
			toolStripStatusLabel_play_record.Visible = true;
		}
		else if (ARP.IsPlaying)
		{
			toolStripStatusLabel_play_record.Image = Resources.play;
			toolStripStatusLabel_play_record.Visible = true;
		}
		else
		{
			toolStripStatusLabel_play_record.Visible = false;
		}
	}

	private void waveRecord(int rx, bool recording)
	{
		ARP.StopRecord(out var error);
		ARP.StopPlayback(out error);
		if (!recording)
		{
			int wfw_id;
			double num;
			DSPMode dSPMode;
			Band b;
			if (rx != 1 && rx == 2)
			{
				wfw_id = 1;
				num = VFOBFreq;
				dSPMode = RX2DSPMode;
				b = RX2Band;
			}
			else
			{
				wfw_id = 0;
				num = VFOAFreq;
				dSPMode = RX1DSPMode;
				b = RX1Band;
			}
			RecordingDetails recordingDetails = new RecordingDetails
			{
				Band = BandStackManager.BandToString(b),
				Frequency = num.ToString("F6", CultureInfo.InvariantCulture),
				Mode = dSPMode.ToString(),
				UtcTime = DateTime.UtcNow
			};
			int num2;
			switch (ARP.BitDepthMode)
			{
			case AudioBitDepthMode.Pcm8:
				num2 = 8;
				break;
			case AudioBitDepthMode.Pcm16:
				num2 = 16;
				break;
			case AudioBitDepthMode.Pcm24:
				num2 = 24;
				break;
			case AudioBitDepthMode.IeeeFloat32:
			case AudioBitDepthMode.Pcm32:
				num2 = 32;
				break;
			default:
				num2 = 0;
				break;
			}
			int sampleRate = ARP.SampleRate;
			string text = DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ss.fffZ");
			string text2 = recordingDetails.Mode + "_" + recordingDetails.Frequency + "MHz_[" + num2 + "bits_" + sampleRate + "Hz]_" + text + ".wav";
			error = new string(Path.GetInvalidFileNameChars());
			foreach (char oldChar in error)
			{
				text2 = text2.Replace(oldChar, '_');
			}
			string full_path = Path.Combine(ARP.AudioFolder, "waverecord", text2);
			ARP.RecordToFileFromWDSP("waverecord_" + rx, full_path, wfw_id, out var _, remove_if_file_exists: true, recordingDetails);
		}
	}
}
